window.PACK={"book":{"id":"diwan-abutammam","title":"ديوان أبو تمام","type":"diwan","author":"أبو تمام (ت ٢٣١هـ)","source":"الموسوعة الشعرية / المكتبة الشاملة عبر مشروع OpenITI","optional":true,"era":"abbasi","packVersion":"5c878d44349b"},"items":[{"id":"diwan-abutammam:1","bookId":"diwan-abutammam","type":"poem","seq":1,"chapter":"البحر: كامل تام","title":"يا موضع الشذنية الوجناء","page":"","text":"يا موضع الشذنية الوجناء … ومصارع الإدلاج والإسراء\nأقري السلام معرفا ومحصبا … من خالد المعروف والهيجاء\nسيل طما لو لم يذده ذائد … لتبطحت أولاه بالبطحاء\nوغدت بطون منى منى من سيبه … وغدت حرى منه ظهور حراء\nوتعرفت عرفات زاخره ولم … يخصص كداء منه بالإكداء\nولطاب مرتبع بطيبة واكتست … بردين : برد ثرى وبرد ثراء\nلا يحرم الحرمان خيرا إنهم … حرموا به نوءا من الأنواء\nيا سائلي عن خالد وفعاله … رد فاغترف علما بغير رشاء\nانظر وإياك الهوى لا تمكنن … سلطانه من مقلة شوساء\nتعلم من افترعت صدور رماحه … وسيوفه من بلدة عذراء\nودعا فأسمع بالأسنة واللهى … صم العدى في صخرة صماء\nبمجامع الثغرين ما ينفك من … جيش أزب وغارة شعواء\nمن كل فرج للعدو كأنه … فرج حمى إلا من الأكفاء\nقد كان خطب عاثر فأقاله … رأي الخليفة كوكب الخلفاء\nفخرجت منه كالشهاب ولم تزل … مذ كنت خراجا من الغماء\nما سرني بخداجها من حجة … ما بين أندلس إلى صنعاء\nأجر ولكن قد نظرت فلم أجد … أجرا يفي بشماتة الأعداء\nلو سرت لالتقت الضلوع على أسى … كلف قليل السلم للأحشاء\nولجف نوار الكلام وقلما … يلفى بقاء الغرس بعد الماء\nفالجو جوي إن أقمت بغبطة … والأرض أرضي والسماء سمائي"},{"id":"diwan-abutammam:2","bookId":"diwan-abutammam","type":"poem","seq":2,"chapter":"البحر: بسيط تام","title":"فحواك عين على نجواك يامذل","page":"","text":"فحواك عين على نجواك يامذل … حتام لايتقضى قولك الخطل ! ؟\nوإن أسمج من تشكو إليه هوى … من كان أحسن شيء عنده العذل\nما أقبلت أوجه اللذات سافرة … مذ أدبرت باللوى أيامنا الأول\nإن شئت ألا ترى صبرا لمصطبر … فانظرعلى أي حال أصبح الطلل\nكأنماجادمغناه ، فغيره … دموعنا ، يوم بانوا ، وهي تنهمل\nولوتراهم وإيانا وموقفنا … في مأتم البين لاستهلالنا زجل\nمن حرقة أطلقتها فرقة أسرت … قلبا ومن غزل في نحره عذل\nوقدطوى الشوق في أحشائنابقر … عين طوتهن في أحشائها الكلل\nفرغن للسحرحتى ظل كل شج … حران في بعضه عن بعضه شغل\nيخزي ركام النقا ما في مآزرها … ويفضح الكحل في أجفانهاالكحل\nتكاد تنتقل الأرواح لوتركت … من الجسوم إليها حيث مكة الهمل\nهانت على كل شيء فهو يسفكها … حتى المنازل والأحداج والإبل\nبالقائم الثامن المستخلف اطأدت … قواعد الملك ممتدا لها الطول\nبيمنمعتصم باللهلاأود … بالملك مذضم قطريه ولاخلل\nيهني الرعية أن الله مقتدرا … أعطاهم بأبي إسحاق ما سألوا\nلو كان في عاجل من آجل بدل … لكان في وعده من رفده بدل\nتغاير الشعر فيه إذ سهرت له … حتى ظننت قوافيه ستقتتل\nلولا قبولي نصح العزم مرتحلا … لراكضاني إليه الرحل والجمل\nله رياض ندى لم يكب زهرتها … خلف ولم تتبختر بينها العلل\nمدى العفاة فلم تحلل به قدم … إذ اخلع الليل النهار رأيتها\nماإن يبالي إذا حلى خلائقه … بجوده أي قطريه حوى العطل\nكأن أمواله والبذل يمحقها … نهب تعسفه التبذير أو نفل\nشرست بل لنت بل قانيت ذاك بذا … فأنت لاشك فيك أنت السهل والجبل\nيدي لمن شاء رهن لم يذق جرعا … من راحتيك درى ماالصاب والعسل\nصلى الإله على العباس وانبجست … على ثرى حلة الوكافة الهطل\nذاك الذي كان لوأن الأنام له … نسل لما راضهم جبن ولا بخل\nأبو النجوم التي ما ضن ثاقبها … أن لم يكن برجه ثور ولاحمل\nمن كل مشتهر في كل معترك … لم يعرف المشتري فيه ولا زحل\nيحميه لألاؤه أولوذعيته … من أن يذال بمن أو ممن الرجل\nومشهد بين حكم الذل منقطع … صاليه أو بحبال الموت متصل\nضنك إذاخرست أبطاله نطقت … فيه الصوارم والخطية الذبل\nلايطمع المرءأن يجتاب غمرته … بالقول ما لم يكن جسرا له العمل\nجليت والموت مبد حر صفحته … وقد تفرعن في أوصاله الأجل\nأبحت أوعاره بالضرب وهو حمى … للحرب يثبت فيه الروع والوهل\nآل النبي إذا ما ظلمة طرقت … كانوا لنا سرجا أنتم لها شعل\nيستعذبون مناياهم كأنهم … لا يبأسون من الدنيا إذا قتلوا\nقوم إذاوعدواأو أوعدوا غمروا … صدقا ذوائب ما قالوا بما فعلوا\nأسد العرين إذا ما الروع صبحها … أوصبحته ، ولكن غابها الاسل\nتناول الفوت أيدي الموت قادرة … إذا تناول سيفا منهم بطل\nليسقم الدهر أو تصحح مودته … فاليوم أول يوم صح لي أمل\nأدنيت رحلي إلى مدن مكارمه … إلي يهتبل اللذ حيث أهتبل\nيحميه حزم لحزم البخل مهتضم … جودا وعرض لعرض المال مبتذل\nفكر ، إذا راضه راض الأمور به … رأي تفنن فيه الريث والعجل\nقد جاء من وصفك التفسير معتذرا … بالعجز ، إن لم يغثني الله والجمل\nلقد لبست أميرالمؤمنين بها … حليا نظاماه بيت سار أومثل\nغريبة تؤنس الآداب وحشتها … فما تحل على قوم ، فترتحل"},{"id":"diwan-abutammam:3","bookId":"diwan-abutammam","type":"poem","seq":3,"chapter":"البحر: رجز تام","title":"ألا ترى ما أصدق الأنواء","page":"","text":"ألا ترى ما أصدق الأنواء … قد أفنت الحجرة والللأواء ؟\nفلو عصرت الصخر صار ماء … من ليلة بتنا بها ليلاء\nان هي عادت ليلة عداء … أصبحت الأرض إذن سماء"},{"id":"diwan-abutammam:4","bookId":"diwan-abutammam","type":"poem","seq":4,"chapter":"البحر: كامل تام","title":"قدك ائئب أربيت في الغلواء","page":"","text":"قدك ائئب أربيت في الغلواء … كم تعذلون وأنتم سجرائي\nلا تسقني ماء الملام فإنني … صب قد استعذبت ماء بكائي\nومعرس للغيث تخفق بينه … رايات كل دجنة وطفاء\nنشرت حدائقه فصرن مآلفا … لطرائف الأنواء والأنداء\nفسقاه مسك الطل كافور الصبا … وانحل فيه خيط كل سماء\nغني الربيع بروضه ، فكأنما … أهدى إليه الوشي من صنعاء\nصبحته بسلافة صبحتها … بسلافة الخلطاء والندماء\nبمدامة تغدو المنى لكؤوسها … خولا على السراء والضراء\nراح إذا ما الراح كن مطيها … كانت مطايا الشوق في الأحشاء\nعنبية ذهبية سكبت لها … ذهب المعاني صاغة الشعراء\nأكل الزمان لطول مكث بقائها … ما كان خامرها من الأقذاء\nصعبت وراض المزج سيء خلقها … فتعلمت من حسن خلق الماء\nخرقاء يلعب بالعقول حبابها … كتلعب الأفعال بالأسماء\nوضعيفة فإذا أصابت فرصة … قتلت ، كذلك قدرة الضعفاء\nجهمية الأوصاف إلا أنهم … قد لقبوها جوهر الأشياء\nوكأن بهجتها وبهجة كأسها … نار ونور قيدا بوعاء\nأو درة بيضاء بكر أطبقت … حبلا على ياقوتة حمراء\nومسافة كمسافة الهجر ارتقى … في صدر باقي الحب والبرحاء\nبيد لنسل العيد في أملودها … ما ارتيد من عيد ومن عدواء\nمزقت ثوب عكوبها بركوبها … والنار تنبع من حصى المعزاء\nوإلى ابن حسان اعتدت بي همة … وقفت عليه خلتي وإخائي\nلما رأيتك قد غذوت مودتي … بالبشر واستحسنت وجه ثنائي\nأنبطت في قلبي لوأيك مشرعا … ظلت تحوم عليه طير رجائي\nفثويت جارا للحضيض وهمتي … قد طوقت بكواكب الجوزاء\nإيه فدتك مغارسي ومنابتي … إطرح غناءك في بحور عنائي\nيسر لقولك مهر فعلك إنه … ينوي افتضاض صنيعة عذراء\nوإلى محمد ابتعثت قصائدي … ورفعت للمستنشدين لوائي\nوإذا تشاجرت الخطوب قريتها … جدلا يقل مضارب الأعداء\nيا غاية الأدباء والظرفاء بل … يا سيد الشعراء والخطباء\nيحيى بن ثابت الذي سن الندى … وحوى المكارم من حيا وحياء"},{"id":"diwan-abutammam:5","bookId":"diwan-abutammam","type":"poem","seq":5,"chapter":"البحر: طويل","title":"أجل أيها الربع الذي خف آهله","page":"","text":"أجل أيها الربع الذي خف آهله … لقد أدركت فيك النوى ما تحاوله\nوقفت وأحشائي منازل للأسى … به ، وهو قفر قد تعفت منازله\nأسائلكم ماباله حكم البلى … عليه ، وإلا فاتركوني أسائله\nلقد أحسن الدمع المحاماة ، بعدما … أساء الأسى إذ جاور القلب داخله\nدعا شوقه يا ناصر الشوق دعوة … فلباه طل الدمع يجري ووابله\nبيوم تريك الموت في صورة النوى … أواخره من حسرة وأوائله\nوقفنا على جمر الوداع ، عشية … ولا قلب ، إلا وهو تغلي مراجله\nوفي الكلة الصفراء جؤذر رملة … غدا مستقلا والفراق معادله\nتيقنت أن البين أول فاتك … به مذ رأيت الهجر ، وهو يغازله\nيعنفني أن ضقت ذرعا بنأيه … ويجزع أن ضاقت عليه خلاخله\nأتتك أمير المؤمنين وقد أتى … عليها الملأ دماثه وجراوله\nوصلن السرى بالوخد في كل صحصح … وبالسهد الموصول والنوم خاذله\nرواحلنا الليل النهار رأيتها … بإرقالها من كل وجه تقابله\nإلى قطب الدنيا الذي لو بفضله … مدحت بني الدنيا كفتهم فضائله\nمن البأس والمعروف والجود والتقى … عيال عليه رزقهن شمائله\nجلا ظلمات الظلم عن وجه أمة … أضاء لها من كوكب الحق آفله\nولاذت بحقويه الخلافة والتقت … على خدرها أرماحه ومناصله\nأتته مغذا قد أتاها كأنها ، … ولا شك ، كانت قبل ذاك تراسله\nبمعتصم بالله قد عصمت به … عرى الدين والتفت عليها وسائله\nرعى الله فيه للرعية رأفة … تزايله الدنيا وليست تزايله\nفأضحوا ، وقد فاضت إليه قلوبهم … ورحمته فيهم تفيض ونائله\nوقام ، فقام العدل في كل بلدة … خطيبا وأضحى الملك قد شق بازله\nوجرد سيف الحق حتى كأنه … من السل مسود غمده وحمائله\nرضينا على رغم الليالي بحكمه … وهل دافع أمرا وذو العرش قائله !\nلقد حان من يهدي سويداء قلبه … لحد سنان في يد الله عامله\nوكم ناكث للعهد قد نكثت به … أمانيه واستخذى لحقك باطله\nفأمكنته من رمة العفو رأفة … ومغفرة إذ أمكنتك مقاتله\nوحاط له الإفرار بالذنب روحه … وجثمانه إذ لم تحطه قبائله\nإذا مارق بالغدر حاول غدرة … فذاك حري أن تئيم حلائله\nفإن باشر الإصحار فالبيض والقنا … قراه وأحواض المنايا مناهله\nوإن يبن حيطانا عليه ، فإنما … أولئك عقالاته لا معاقله\nوإلا فأعلمه بأنك ساخط … ودعه فإن الخوف لا شك قاتله\nبيمن أبي إسحاق طالت يد العلى … وقامت قناة الدين واشتد كاهله\nهو اليم من أي النواحي أتيته … فلجته المعروف والجود ساحله\nتعود بسط الكف حتى لو أنه … ثناها لقبض لم تجبه أنامله\nولو لم يكن في كفه غير روحه … لجاد بها ، فليتق الله سائله\nعطاء لو اسطاع الذي يستميحه … لأصبح من بين الورى وهو عاذله\nإذا آمل ساماه قرطس في المنى … مواهبه حتى يؤمل آمله\nلهى تستثير القلب لولا اتصالها … بحسن دفاع الله وسوس سائله\nإمام الهدى وابن الهدى أي فرحة … تعجلها فيك القريض وقائله !\nرجاؤك للباغي الغنى عاجل الغنى … وأول يوم من لقائك آجله"},{"id":"diwan-abutammam:6","bookId":"diwan-abutammam","type":"poem","seq":6,"chapter":"البحر: بسيط تام","title":"السيف أصدق أنباء من الكتب","page":"","text":"السيف أصدق أنباء من الكتب … في حده الحد بين الجد واللعب\nبيض الصفائح لا سود الصحائف في … متونهن جلاء الشك والريب\nوالعلم في شهب الأرماح لامعة … بين الخميسين لافي السبعة الشهب\nأين الرواية بل أين النجوم وما … صاغوه من زخرف فيها ومن كذب\nتخرصا وأحاديثا ملفقة … ليست بنبع إذا عدت ولاغرب\nعجائبا زعموا الأيام مجفلة … عنهن في صفر الأصفار أو رجب\nوخوفوا الناس من دهياء مظلمة … إذا بدا الكوكب الغربي ذو الذنب\nوصيروا الأبراج العليا مرتبة … ما كان منقلبا أو غير منقلب\nيقضون بالأمر عنها وهي غافلة … ما دار في فلك منها وفي قطب\nلو بينت قط أمرا قبل موقعه … لم تخف ماحل بالأوثان والصلب\nفتح الفتوح تعالى أن يحيط به … نظم من الشعر أو نثر من الخطب\nفتح تفتح أبواب السماء له … وتبرز الأرض في أثوابها القشب\nيا يوم وقعة عمورية انصرفت … منك المنى حفلا معسولة الحلب\nأبقيت جد بني الإسلام في صعد … والمشركين ودار الشرك في صبب\nأم لهم لو رجوا أن تفتدى جعلوا … فداءها كل أم منهم وأب\nوبرزة الوجه قد أعيت رياضتها … كسرى وصدت صدودا عن أبي كرب\nبكر فما افترعتها كف حادثة … ولا ترقت إليها همة النوب\nمن عهد إسكندر أو قبل ذلك قد … شابت نواصي الليالي وهي لم تشب\nحتى إذا مخض الله السنين لها … مخض البخيلة كانت زبدة الحقب\nأتتهم الكربة السوداء سادرة … منها وكان اسمها فراجة الكرب\nجرى لها الفال برحا يوم أنقرة … إذ غودرت وحشة الساحات والرحب\nلما رأت أختها بالأمس قد خربت … كان الخراب لها أعدى من الجرب\nكم بين حيطانها من فارس بطل … قاني الذوائب من آني دم سرب\nبسنة السيف والخطي من دمه … لاسنة الدين والإسلام مختضب\nلقد تركت أمير المؤمنين بها … للنار يوما ذليل الصخر والخشب\nغادرت فيها بهيم الليل وهو ضحى … يشله وسطها صبح من اللهب\nحتى كأن جلابيب الدجى رغبت … عن لونها وكأن الشمس لم تغب\nضوء من النار والظلماء عاكفة … وظلمة من دخان في ضحى شحب\nفالشمس طالعة من ذا وقد أفلت … والشمس واجبة من ذا ولم تجب\nتصرح الدهر تصريح الغمام لها … عن يوم هيجاء منها طاهر جنب\nلم تطلع الشمس فيه يوم ذاك على … بان بأهل ولم تغرب على عزب\nما ربع مية معمورا يطيف به … غيلان أبهى ربى من ربعها الخرب\nولا الخدود وقد أدمين من خجل … أشهى إلى ناظري من خدها الترب\nسماجة غنيت منا العيون بها … عن كل حسن بدا أو منظر عجب\nوحسن منقلب تبقى عواقبه … جاءت بشاشته من سوء منقلب\nلو يعلم الكفر كم من أعصر كمنت … له العواقب بين السمر والقضب\nتدبير معتصم بالله منتقم … لله مرتقب في الله مرتغب\nومطعم النصر لم تكهم أسنته … يوما ولا حجبت عن روح محتجب\nلم يغز قوما ، ولم ينهد إلى بلد … إلا تقدمه جيش من الرعب\nلو لم يقد جحفلا ، يوم الوغى ، لغدا … من نفسه ، وحدها ، في جحفل لجب\nرمى بك الله برجيها فهدمها … ولو رمى بك غير الله لم يصب\nمن بعد ما أشبوها واثقين بها … والله مفتاح باب المعقل الأشب\nوقال ذو أمرهم لا مرتع صدد … للسارحين وليس الورد من كثب\nأمانيا سلبتهم نجح هاجسها … ظبى السيوف وأطراف القنا السلب\nإن الحمامين من بيض ومن سمر … دلوا الحياتين من ماء ومن عشب\nلبيت صوتا زبطريا هرقت له … كأس الكرى ورضاب الخرد العرب\nعداك حر الثغور المستضامة عن … برد الثغور وعن سلسالها الحصب\nأجبته معلنا بالسيف منصلتا … ولو أجبت بغير السيف لم تجب\nحتى تركت عمود الشرك منعفرا … ولم تعرج على الأوتاد والطنب\nلما رأى الحرب رأي العين توفلس … والحرب مشتقة المعنى من الحرب\nغدا يصرف بالأموال جريتها … فعزه\nهيهات ! زعزعت الأرض الوقور به … عن غزو محتسب لا غزو مكتسب\nلم ينفق الذهب المربي بكثرته … على الحصى وبه فقر إلى الذهب\nإن الأسود أسود الغيل همتها … يوم الكريهة في المسلوب لا السلب\nولى ، وقد ألجم الخطي منطقه … بسكتة تحتها الأحشاء في صخب\nأحذى قرابينه صرف الردى ومضى … يحتث أنجى مطاياه من الهرب\nموكلا بيفاع الأرض يشرفه … من خفة الخوف لا من خفة الطرب\nإن يعد من حرها عدو الظليم ، فقد … أوسعت جاحمها من كثرة الحطب\nتسعون ألفا كآساد الشرى نضجت … جلودهم قبل نضج التين والعنب\nيا رب حوباء لما اجتث دابرهم … طابت ولو ضمخت بالمسك لم تطب\nومغضب رجعت بيض السيوف به … حي الرضا من رداهم ميت الغضب\nوالحرب قائمة في مأزق لجج … تجثو القيام به صغرا على الركب\nكم نيل تحت سناها من سنا قمر … وتحت عارضها من عارض شنب\nكم كان في قطع أسباب الرقاب بها … إلى المخدرة العذراء من سبب\nكم أحرزت قضب الهندي مصلتة … تهتز من قضب تهتز في كثب\nبيض ، إذا انتضيت من حجبها ، رجعت … أحق بالبيض أترابا من الحجب\nخليفة الله جازى الله سعيك عن … جرثومة الدين والإسلام والحسب\nبصرت بالراحة الكبرى فلم ترها … تنال إلا على جسر من التعب\nإن كان بين صروف الدهر من رحم … موصولة أو ذمام غير منقضب\nفبين أيامك اللاتي نصرت بها … وبين أيام بدر أقرب النسب\nأبقت بني الأصفر الممراض كاسمهم … صفر الوجوه وجلت أوجه العرب"},{"id":"diwan-abutammam:7","bookId":"diwan-abutammam","type":"poem","seq":7,"chapter":"البحر: كامل تام","title":"بمحمد صار الزمان محمدا","page":"","text":"بمحمد صار الزمان محمدا … عندي وأعتب بعد سوء فعاله\nبمروق الأخلاق لو عاشرته … لرأيت نجحك من جميع خصاله\nمن ودني بلسانه وبقلبه … وأنالني بيمينه وشماله\nأبدا يفيد غرائبا من ظرفه … ورغائبا من جوده ونواله\nوسألت عن أمري ، فسل عن أمره … دوني فحالي قطعة من حاله\nلو كنت شاهد بذله لشهدت لي … بوراثة أو شركة في ماله"},{"id":"diwan-abutammam:8","bookId":"diwan-abutammam","type":"poem","seq":8,"chapter":"البحر: كامل تام","title":"لو أن دهرا رد رجع جواب","page":"","text":"لو أن دهرا رد رجع جواب … أو كف من شأويه طول عتاب\nلعذلته في دمنتين بأمرة … ممحوتين لزينب ورباب\nثنتان كالقمرين حف سناهما … بكواعب مثل الدمى أتراب\nمن كل ريم لم ترم سوءا ولم … تخلط صبى أيامها بتصابي\nأذكت عليه شهاب نار في الحشا … بالعذل وهنا أخت آل شهاب\nعذلا شبيها بالجنون كأنما … قرأت به الورهاء شطر كتاب\nأو ما رأت بردي من نسج الصبى … ورأت خضاب الله ، وهو خضابي ؟\nلاجود في الأقوام يعلم ما خلا … جودا حليفا في بني عتاب\nمتدفقا صقلوا به أحسابهم … إن السماحة صيقل الأحساب\nقوم إذا جلبوا الجياد إلى الوغى … أيقنت أن السوق سوق ضراب\nيا مالك ابن المالكين ولم تزل … تدعى ليومي نائل وعقاب\nلم ترم ذا رحم ببائقة ولا … كلمت قومك من وراء حجاب\nللجود باب في الأنام ولم تزل … يمناك مفتاحا لذاك الباب\nورأيت قومك ، والإساءة منهم … جرحى بظفر للزمان وناب\nهم صيروا تلك البروق صواعقا … فيهم وذاك العفو سوط عذاب\nقأقل أسامة جرمها واصفح لها … عنه وهب ماكان للوهاب\nرفدوك في يوم الكلاب وشققوا … فيه المزاد بجحفل غلاب\nوهم بعين أباغ راشوا للوغى … سهميك عند الحارث الحراب\nوليالي الحشاك والثرثار قد … جلبوا الجياد لواحق الأقراب\nفمضت كهولهم ودبر أمرهم … أحداثهم تدبير غير صواب\nلا رقة الحضر اللطيف غذتهم … وتباعدوا عن فطنة الأعراب\nفإذا كشفتهم وجدت لديهم … كرم النفوس وقلة الآداب\nأسبل عليهم ستر عفوك مفضلا … وانفح لهم من نائل بذناب\nلك في رسول الله أعظم أسوة … وأجلها في سنة وكتاب\nأعطى المؤلفة القلوب رضاهم … كرما ، ورد أخايذ الأحزاب\nوالجعفريون استقلت ظعنهم … عن قومهم وهم نجوم كلاب\nحتى إذا أخذ الفراق بقسطه … منهم وشط بهم عن الأحباب\nورأوا بلاد الله قد لفظتهم … أكنافها رجعوا إلى جواب\nفأتوا كريم الخيم مثلك صافحا … عن ذكر أحقاد مضت وضباب\nليس الغبي بسيد في قومه … لكن سيد قومه المتغابي\nقد ذل شيطان النفاق وأخفتت … بيض السيوف زئير أسد الغاب\nفاضمم أقاصيهم إليك ، فإنه … لايزخر الوادي بغير شعاب\nوالسهم بالريش اللوءام ولن ترى … بيتا بلا عمد ولا أطناب\nمهلا بني غنم بن تغلب إنكم … للصيد من عدنان والصباب\nلولا بنو جشم بن بكر فيكم … رفعت خيامكم بغير قباب\nيا مالك استودعتني لك منة … تبقى ذخائرها على الأحقاب\nيا خاطبا مدحي إليه بجوده … ولقد خطبت قليلة الخطاب\nخذها ابنة الفكر المهذب في الدجى … والليل أسود رقعة الجلباب\nبكرا تورث في الحياة وتنثني … في السلم وهي كثيرة الأسلاب\nويزيدها مر الليالي جدة … وتقادم الأيام حسن شباب"},{"id":"diwan-abutammam:9","bookId":"diwan-abutammam","type":"poem","seq":9,"chapter":"البحر: بسيط تام","title":"قل لابن طوق رحى سعد إذا خبطت","page":"","text":"قل لابن طوق رحى سعد إذا خبطت … نوائب الدهر أعلاها وأسفلها\nأصبحت حاتمها جودا وأحنفها … حلما وكيسها علما ودغفلها\nمالي أرى الحجرة الفيحاء مقفلة … عني وقد طالما استفتحت مقفلها !\nكأنها جنة الفردوس معرضة … وليس لي عمل زاك فأدخلها"},{"id":"diwan-abutammam:10","bookId":"diwan-abutammam","type":"poem","seq":10,"chapter":"البحر: طويل","title":"دنا سفر والدر تنأى وتصقب","page":"","text":"دنا سفر والدر تنأى وتصقب … وينسى سراه من يعافى ويصحب\nوأيامنا خزر العيون عوابس … اذا لم يحصها الحزم المتلبب\nولابد من فرو إذا اجتابه امرؤ … غدا وهو سام في الصنابر اغلب\nامين القوى لم تحصص الحرب رأسه … ولم ينض عمرا ، وهو أشمط أشيب\nيسرك بأسا وهو غير مغمر … ويعند للأيام حين يجرب\nتظل البلاد ترتمي بضريبها … وتشمل من أقطارها وهو يجنب\nاذا البدن المقرور ألبسه غدا … له راشح من تحته بتصبب\nإذا عد ذنبا ثقله منكب امرئ … يقول الحشا : إحسانه حين يذنب\nاتيت اذا استعتبت مصقعة به … تملأت علما أنها سوف تعتب\nيراه الشفيف المرتعن فينثني … حسيرا فتغشاه الصبا فتنكب\nاذا ما اساءت بالثياب فقوله … لها كلما لاقته أهل ومرحب\nإذا اليوم أمسى وهو غضبان لم يكن … طويل مبالاة به حين يغضب\nكأن حواشيه العلى وخصوره … وما انحط منه جمرة تتلهب\nفهل أنت مهديه بمثل شكيره … من الشكر يعلو مصعدا ويصوب ؟\nله زئبر يدفي من الذم كلما … تجلببهث في محفل متجلبب\nفأنت العليم الطب أي وصية … بها كان اوصى في الثياب المهلب"},{"id":"diwan-abutammam:11","bookId":"diwan-abutammam","type":"poem","seq":11,"chapter":"البحر: كامل تام","title":"أحسن بأيام العقيق وأطيب","page":"","text":"أحسن بأيام العقيق وأطيب … والعيش في أظلالهن المعجب\nومصيفهن المستظل بظله … سرب المها وربيعهن الصيب\nأصل كبرد العصب نيط إلى ضحى … عبق بريحان الرياض مطيب\nوظلالهن المشرقات بخرد … بيض كواعب غامضات الأكعب\nوأغن من دعج الظباء مربب … بدلن منه أغن غير مربب\nلله ليلتنا وكانت ليلة … ذخرت لنا بين اللوى فالشربب\nقالت ، وقد أعلقت كفي كفها : … حلا ، وما كل الحلال بطيب\nفنعمت من شمس إذا حجبت بدت … من نورها فكأنها لم تحجب\nوإذا رنت خلت الظباء ولدنها … ربعية واسترضعت في الربرب\nإنسية إن حصلت أنسابها … جنية الأبوين مالم تنسب\nقد قلت للزباء لما أصبحت … في حد ناب للزمان ومخلب\nلمدينة عجماء قد أمسى البلى … فيها خطيبا باللسان المعرب\nفكأنما سكن الفناء عراصها … أو صال فيها الدهر صولة مغضب\nلكن بنو طوق وطوق قبلهم … شادوا المعالى بالثناء الأغلب\nفستخرب الدنيا وأبنية العلى … وقبابها جدد بها لم تخرب\nرفعت بأيام الطعان وغشيت … رقراق لون للسماحة مذهب\nيا طالبا مسعاتهم لينالها … هيهات منك غبار ذاك الموكب !\nأنت المعنى بالغواني تبتغي … أقصى مودتها برأس أشيب\nوطئ الخطوب وكف من غلوائها … عمر بن طوق ، نجم أهل المغرب\nملتف أعراق الوشيج ، إذا انتمى … يوم الفخار ، ثري ترب المنصب\nفي معدن الشرف الذي من حليه … سبكت مكارم تغلب ابنة تغلب\nقد قلت في غلس الدجى لعصابة … طلبت أبا حفص : مناخ الأركب\nالكوكب الجشمي نصب عيونكم … فاستوضحوا إيضاء ذاك الكوكب\nيعطي عطاء المحسن الخضل الندى … عفوا ويعتذر اعتذار المذنب\nومرحب بالزائرين وبشره … يغنيك عن أهل لديه ومرحب\nيغدو مؤمله إذا ما حط في … أكنافه رحل المكل الملغب\nسلس اللبانة والرجاء ببابه … كتب المنى ممتد ظل المطلب\nالجد شيمته وفيه فكاهة … سجع ولاجد لمن لم يلعب\nشرس ، ويتبع ذاك لين خليقة … لا خير في الصهباء ما لم تقطب\nصلب إذا اعوج الزمان ولم يكن … ليلين صلب الخطب من لم يصلب\nالود للقربى ، ولكن عرفه … للأبعد الأوطان دون الأقرب\nوكذاك عتاب بن سعد أصبحوا … وهم زمام زماننا المتقلب\nهم رهط من أمسى بعيدا رهطه … وبنو أبي رجل بغير بني أب\nومنافس عمر بن طوق ما له … من ضغنه غير الحصى والأثلب\nتعب الخلائق والنوال ولم يكن … بالمستريح العرض من لم يتعب\nبشحوبه في المجد أشرق وجهه … لايستنير فعال من لم يشحب\nبحر يطم على العفاة وإن تهج … ريح السؤال بموجه يغلولب\nوالشول ما حلبت تدفق رسلها … وتجف درتها إذا لم تحلب\nيا عقب طوق أي عقب عشيرة … أنتم ، وربت معقب لم يعقب\nقيدت من عمر بن طوق همتي … بالحول الثبت الجنان القلب\nنفق المديح ببابه فكسوته … عقدا من الياقوت غير مثقب\nأولى المديح بأن يكون مهذبا … ماكان منه في أغر مهذب\nغربت خلائقه وأغرب شاعر … فيه فأحسن مغرب في مغرب\nلما كرمت نطقت فيك بمنطق … حق فلم آثم ولم أتحوب\nومتى امتدحت سواك كنت متى يضق … عني له صدق المقالة أكذب"},{"id":"diwan-abutammam:12","bookId":"diwan-abutammam","type":"poem","seq":12,"chapter":"البحر: كامل تام","title":"بوأت رحلي في المراد المقبل","page":"","text":"بوأت رحلي في المراد المقبل … فرتعت في إثر الغمام المسبل\nمن مبلغ أفناء يعرب كلها … إني ابتنيت الجار قبل المنزل\nوأخذت بالطول الذي لم ينصرم … ثنياه والعقد الذي لم يحلل\nهتك الظلام أبو الوليد بغرة … فتحت لنا باب الرجاء المقفل\nبأتم من قمر السماء وإن بدا … بدرا وأحسن في العيون وأجمل\nوأجل من قس إذا استنطقته … رأيا وألطف في الأمور وأجزل\nشرخ من الشرف المنيف يهزه … هز الصفيحة شرخ عمر مقبل\nفاسلم لجدة سؤدد مستقبل … أنف وبرد شبيبة مستقبل\nكم أدت الأيام من حدث كفت … أيامه حدث الزمان المعضل\nللمحمل يكشفه ولم يبعل به … والثقل يحمله وليس بمثقل\nوالخطب أمت منك أم دماغه … بالقلب الماضي الجنان الحول\nومقامة نبل الكلام سلاحها … للقول فيها غمرة لا تنجلي\nقول تظل ميونه منهلة … سمين بين مقشب ومثمل\nفرجت ظلمتها بخطبة فيصل … مثل لها في الروع طعنة فيصل\nجمعت لنا فرق الأماني منكم … بأبر من روح الحياة وأوصل\nفصنيعة في يومها وصنيعة … قد أحولت وصنيعة لم تحول\nكالمزن من ماضي الرباب ومقبل … منتظر ومخيم متهلل\nلي حرمة والت علي سجالكم … والماء رزق جمامه للأول\nإن يعجب الأقوام أني عندكم … والماء دون ذي رحم بها متوسل\nفبنو أمية الفرزدق صنوهم … نسبا وكان ودادهم في الأخطل"},{"id":"diwan-abutammam:13","bookId":"diwan-abutammam","type":"poem","seq":13,"chapter":"البحر: رجز تام","title":"لم أر غير حمة الدؤوب","page":"","text":"لم أر غير حمة الدؤوب … تواصلث الادلاج بالتأويب\nأبعد من أين ومن لغوب … منها غداة الشارق المهضوب\nتجائبا وليس من نجيب … شبابة الأعناق بالعجوب\nكالليل أو كاللوب أو كالنوب … منقادة ص لغادر غربيب\nكالشيعة التفت على النقيب … آخذة بطاعة الجنوب\nناقضة لمرر الخطوب … تكف غرب الزمن العصيب\nمحاءة للأزمة اللزوب … محو استلام الركن للذنوب\nلما بدت للارض من قريب … تشوفت لويلها السكوب\nتشوف المريض للطبيب … وطرب المحب للحبيب\nوفرحة الأديب بالأديب … وخيمت صادقة الشوبوب\nفقام فيها الرعد كالخطيب … وحنت الريح حنين النيب\nوالشمس ذات حاجب محجوب … قد غربت من غير ما غروب\nوالأرض في ردائها القشيب … في زاهر من نبتها رطيب\nبعد اشتهاب الثلج والصريب … كالكهل بعد السن والتحنيب\nتبدل الشباب بالمشيب … كم آنست من جانب غريب\nوغلبت من الثرى المغلوب … ونفست عن بارض مكروب\nوسكنت من نافر الجنوب … وأقنعت من بلد رغيب\nيحفظ عهد الغيث بالمغيب … لذيذة الريق مع الصبيب\nكأنما تهمي على القلوب … "},{"id":"diwan-abutammam:14","bookId":"diwan-abutammam","type":"poem","seq":14,"chapter":"البحر: مجزوء الرجز","title":"الحسن بن وهب","page":"","text":"الحسن بن وهب … كالغيث في انسكابه\nفي الشرخ من حجاه … والشرخ من شبابه\nوالخصب من نداه … والخصب من جنابه\nومنصب نماه … ووالد سما به\nنطنب كيف شينا … فيه ولم نحابه\nوحلة كساها … كالحلي والتهابه\nفاستنبطت مديحا … كالأري في لصابه\nفراح في ثنائي … ورحت في ثيابه"},{"id":"diwan-abutammam:15","bookId":"diwan-abutammam","type":"poem","seq":15,"chapter":"البحر: بسيط تام","title":"لا نالك العثر من دهر ولا زلل","page":"","text":"لا نالك العثر من دهر ولا زلل … ولايكن للعلا في فقدك الثكل\nلاتعتلل إنما بالمكرمات إذا … أنت اعتللت ترى الأوجاع والعلل\nتضاءل الجود مذمدت إليك يد … من بعض أيدي الضنى واستأسد البخل\nلم يبق في صدر راجي حاجة أمل … إلا وقد ذاب سقما ذلك الأمل\nبينا كذلك والدنيا على خطر … والعرف فيك إلى الرحمن يبتهل\nوأعين الخلق تعطي فوق ما سئلت … عليك والصبر يعطي دون ما يسل\nحبا بك الله من لولاك لانبعثت … فيه الليالي ومنها الوخد والرمل\nسقم أتيح له برء فذعذعه … والرمح يناد حينا ثم يعتدل\nوحال لون فرد الله نضرته … والنجم يخمد شيئا ثم يشتعل\nأجر أتاك ولم تعمل له وبلا … فكر المقيم على توحيده عمل"},{"id":"diwan-abutammam:16","bookId":"diwan-abutammam","type":"poem","seq":16,"chapter":"البحر: مجزوء الرمل","title":"اصبري ايتها النفس","page":"","text":"اصبري ايتها النفس … فان الصبر أحجى\nنهنهي الحزن فان … الحزن إن لم ينه لجا\nوالبسي اليأس من النا … فان اليأس ملجا\nربما خاب رجاء … وأتى ما ليس يرجى\nوكتاب كتبته … \nلا ترى عين رقيب … فيه للاقلام ثجا\nلم يبح فيه بسر … لا ولا أدرج درجا\nفأجابته دموع … جعلت للكأس مزجا\nوسقيم الطرف قد … \nزارني والليل قد اق … بل نحوي يتدجى\nحين نال العلج في … \nطلعت شمس علينا … ووإن لم ننو حجا !\nلذة الطعم تمج المس … ك في الأقداح مجا\nكست الشيخ شبابا … فاكتسى شكلا وغنجا"},{"id":"diwan-abutammam:17","bookId":"diwan-abutammam","type":"poem","seq":17,"chapter":"البحر: بسيط تام","title":"أبدت أسى أن رأتني مخلس القصب","page":"","text":"أبدت أسى أن رأتني مخلس القصب … وآل ما كان من عجب إلى عجب\nست وعشرون تدعوني فأتبعها … إلى المشيب ولم تظلم ولم تحب\nيومي من الدهر مثل الدهر مشتهر … عزما وحزما وساعي منه كالحقب\nفأصغري أن شيبا لاح بي حدثا … وأكبري أنني في المهد لم أشب\nولايؤرقك أيماض القتير به … فإن ذاك ابتسام الرأي والأدب\nرأت تشننه فاهتاج هائجها … وقال لاعجها للعبرة : انسكبي\nلا تنكري منه تخديدا تجلله … فالسيف لا يزدرى إن كان ذا شطب\nلا يطرد الهم إلا الهم من رجل … مقلقل لبنات القفرة النعب\nماض ، إذا الكرب التفت رأيت له … بوخدهن استطالات على النوب\nستصبح العيس بي ، والليلأ عند فتى … كثير ذكر الرضا في ساعة الغضب\nصدفت عنه ، فلم تصدف مودته … عني وعاوده ظني ، فلم يخب\nكالغيث إن جئته وافاك ريقه … وإن تحملت عنه كان في الطلب\nخلائق الحسن استوفي البقاء ، فقد … أصبحت قرة عين المجد والحسب\nكأنما هو من أخلاقه أبدا … وإن ثوى وحده في جحفل لجب\nصيغت له شيمة غراء من ذهب … لكنها أهلك الأشياء للذهب\nلما رأى أدبا في غير ذي كرم … قد ضاع أو كرما في غير ذي أدب\nسما إلى السورة العلياء ، فاجتمعا … في فعله كاجتماع النور والعشب\nبلوت منك وأيامي مذممة … مودة وجدت أحلى من النشب\nمن غير ما سبب ماض ، كفى سببا … للحر أن يعتفي حرا بلا سبب"},{"id":"diwan-abutammam:18","bookId":"diwan-abutammam","type":"poem","seq":18,"chapter":"البحر: كامل تام","title":"أما أبو بشر فقد أضحى الورى","page":"","text":"أما أبو بشر فقد أضحى الورى … كلا على نفحاته ونواله\nفمتى تلم به تؤب مستيقنا … أن ليس أولى من سواه بماله\nكرم يزيد على الكرام وتحته … أدب يفك القلب من أغلاله\nحتى لو أنك تستشف ضميره … لو كان يهدي لامرىء ما لا يرى\nأبليت منه مودة عبدية … راشت ببالي كلها بنباله\nأو ما رأيت الورد أتحفنا به … إتحاف من خطر الصديق بباله ؟\nوردا كتوريد الخدود تلونت … خجلا وأبيض في بياض فعاله\nوالقهوة الصهباء ظلت تستقى … من طيبات المجتنى وحلاله\nمشمولة تغني المقل ، وإنما … ذاك الغنى التزبيد في إقلاله\nوملحبا لاقى المنية خاسرا … والموت أحمر واقفا بحياله\nفكبا كما يكبو الكمي تصرفت … أيامه وانبت من أبطاله\nفأتى وقد عرته مرهفة المدى … من روحه جمعا ومن سرباله\nلو كان يهدى لامرئ مالا يرى … يهدى لعظم فراقه وذياله\nلرددت تحفته عليه وإن علت … عن ذاك واستهديت بعض خصاله"},{"id":"diwan-abutammam:19","bookId":"diwan-abutammam","type":"poem","seq":19,"chapter":"البحر: بسيط تام","title":"الغيم من بين مغبوق ومصطبح","page":"","text":"الغيم من بين مغبوق ومصطبح … من ريق مكتفلات بالثرى دلح\nدهم اذا ضحكت في روضة طفقت … عيون نوارها تبكي من الفرح"},{"id":"diwan-abutammam:20","bookId":"diwan-abutammam","type":"poem","seq":20,"chapter":"البحر: خفيف تام","title":"أي مرعى عين ووادي نسيب","page":"","text":"أي مرعى عين ووادي نسيب … لحبته الأيام في ملحوب ؟ !\nملكته الصبا الولوع فأل … فته قعود البلى وسؤر الخطوب\nند عنك العزاء فيه وقاد ال … دمع من مقلتيك قود الجنيب\nصحبت وجدك المدامع فيه … بنجيع بعبرة مصحوب\nبملث على الفراق مرب … ولشأو الهوى البعيد طلوب\nأخلبت بعده بروق من الله … ووجفت غدر من التشبيب\nربما قد أراه ريان مكسو ال … مغاني من كل حسن وطيب\nبسقيم الجفون غير سقيم … ومريب الألحاظ غير مريب\nفي أوان من الربيع كريم … وزمان من الخريف حسيب\nفعليه السلام لا أشرك الأط … لال في لوعتي ولا في نحيبي\nفسواء إجابتي غير داع … ودعائي بالقفر غير مجيب\nفسواء خفض تحت السرى وغناء … من عناء ونضرة من شحوب\nفاسأل العيس ما لديها وألف … بين أشخاصها وبين السهوب\nلا تذيلن صغير همك وانظر … كم بذي الأثل دوحة من قضيب\nما على الوسج الرواتك من عت … ب ، إذا ما آتت أبا أيوب\nحول ، لا فعاله مرتع الذ … م ولا عرضه مراح العيوب\nسرح قوله إذا ما استمرت … عقدة العي في لسان الخطيب\nومصيب شواكل الأمر فيه … مشكلات يلكن لب لبيب\nلامعنى بكل شيء ولا كل … م عجيب في عينه بعجيب\nسدك الكف بالندى عائر السم … ع إلى حيث صرخة المكروب\nليس يعرى من حلة من طراز ال … مدح من تاجر بها مستثيب\nفإذا مر لابس الحمد قال ال … قوم : من صاحب الرداء القشيب\nوإذا كف راغب سلبته … راح طلقا كالكوكب المشبوب\nما مهاة الحجال مسلوبة أظ … رف حسنا من ماجد مسلوب\nواجد بالخليل من برحاء الش … وق وجدان غيره بالحبيب\nآمن الجيب والضلوع ، إذا ما … أصبح الغش وهو درع القلوب\nلا كمصفيهم ، إذا حضروا الود … م ولاح قضبانهم بالمغيب\nيتغطى عنهم ولكنه تن … صل أخلاقه نصول المشيب\nكل شعب كنتم به آل وهب … فهو شعبي وشعب كل أديب\nلم أزل بارد الجوانح مذ خض … خضت دلوي في ماء ذاك القليب\nبنتم بالمكروه دوني وأصبح … ت الشريك المختار في المحبوب\nثم لم أدع من بعيد لدى الإذ … ن ولم أثن عنكم من قريب\nكل يوم تزخرفون فنائي … بحباء فرد وبر غريب\nإن قلبي لكم لكالكبد الحر … ى وقلبي لغيركم كالقلوب\nلست أدلي بحرمة مستزيدا … في وداد منكم ولا في نصيب\nلاتصيب الصديق قارعة التأ … نيب ، إلا من الصديق الرغيب\nغير أن العليل ليس بمذمو … م على شرح ما به للطبيب\nلو رأينا التوكيد خطة عجز … ما شفعنا الآذان بالتثويب"},{"id":"diwan-abutammam:21","bookId":"diwan-abutammam","type":"poem","seq":21,"chapter":"البحر: كامل تام","title":"عجب لعمري أن وجهك معرض","page":"","text":"عجب لعمري أن وجهك معرض … عني ، وأنت بوجه نفعك مقبل\nبر بدأت به ودار بابها … للخلق مفتوح ووجهك مقفل\nأولا ترى أن الطلاقة جنة … من سوء ما تجنى الظنون ومعقل ؟\nحلي الصنيعة أن يكون لربها … لفظ يحسنها وطرف قلقل\nومودة مطوية منش ورة … فيها إلى إنجاحها متعلل\nإن تعط وجها كاسفا من تحته … كرم وحلم خليقة لا تجهل\nفلرب سارية عليك مطيرة … قد جاد عارضها ومايتهلل"},{"id":"diwan-abutammam:22","bookId":"diwan-abutammam","type":"poem","seq":22,"chapter":"البحر: كامل تام","title":"لمكاسر الحسن بن وهب أطيب","page":"","text":"لمكاسر الحسن بن وهب أطيب … وأمر في حنك الحسود وأعذب\nوله إذا خلق التخلق أو نبا … خلق كروض الحزن أو هو أخصب\nضربت به أفق الثناء ضرائب … كالمسك يقتق بالندى ويطيب\nيستنبط الروح اللطيف نسيمها … أرجا وتؤكل بالضمير وتشرب\nذهبت بمذهبه السماحة ، فالتوت … فيه الظنون : أمذهب أم مذهب\nورأيت غرته صبيحة نكبة … جلل فقلت : أبارق أم كوكب\nمتعت كما متع الضحى في حادث … داج كأن الصبح فيه مغرب\nيفديه قوم أحضرت أعراضهم … سوء المعايب ، والنوال مغيب\nمن كل مهراق الحياء كأنما … غطى غديري وجنتيه الطحلب\nمتدسم الثوبين ينظر زاده … نظر يحدقه وخد صلب\nفإذا طلبت لديهم ما لم أنل … أدركت من جدواه ما لا أطلب\nضم الفتاء إلى الفتوة برده … وسقاه وسمي الشباب الصيب\nوصفا كما يصفو الشهاب ، وإنه … في ذاك من صبغ الحياء لمشرب\nتلقى السعود بوجهه وتحبه … وعليك مسحة بغضة ، فتحبب\nإن الإخاء ولادة وأنا امرؤ … ممن أواخي حيث ملت ، فأنجب\nوإذا الرجال تساجلوا في مشهد … فمريح رأي منهم أو معزب\nأحرزت خصليه إليك وأقبلت … آراء قوم خلف رأيك تجنب\nوإذا رأيتك والكلام لآلئ … تؤم فبكر في النظام وثيب\nفكأن قسا في عكاظ يخطب … وكأن ليلى الأخيلية تندب\nوكثير عزة يوم بين ينسب … وابن المقفع في اليتيمة يسهب\nتكسو الوقار وتستخف موقرا … طورا وتبكي سامعين وتطرب\nقد جاءنا الرشأ الذي أهديته … خرقا ولو شئنا لقلنا المركب\nلدن البنان له لسان أعجم … خرس معانيه ووجه معرب\nيرنو فيثلم في القلوب بطرفه … ويعن للنظر الحرون فيصحب\nقد صرف الرانون خمرة خده … وأظنها بالريق منه ستقطب\nحمد حبيت به وأجر حلقت … من دونه عنقاء ليل مغرب\nخذه ، وإن لم يرتجع معروفه … محض إذا مزج الرجال مهذب\nوانفح لنا من طيب خيمك نفحة … إن كانت الأخلاق مما توهب"},{"id":"diwan-abutammam:23","bookId":"diwan-abutammam","type":"poem","seq":23,"chapter":"البحر: كامل تام","title":"إن الأمير بلاك في أحواله","page":"","text":"إن الأمير بلاك في أحواله … فرآك أهزعه غداة نضاله\nآسيته في المكرمات ولم تزل … ركنا لمن هو ممسك بحباله\nفمتى النهوض بحق شكرك إن جنت … بالغيب كفك لي ثمار فعاله !\nفلقيت بين يديك حلو عطائه … ولقيت بين يدي مر سؤاله\nوإذا امرؤ أسدى إليك صنيعة … من جاهه فكأنها من ماله"},{"id":"diwan-abutammam:24","bookId":"diwan-abutammam","type":"poem","seq":24,"chapter":"البحر: كامل تام","title":"لا خير في قربى بغير مودة","page":"","text":"لا خير في قربى بغير مودة … ولرب منتفع بود أباعد\nوإذا القرابة أقبلت بمودة … فاشدد لها كف القبول بساعد"},{"id":"diwan-abutammam:25","bookId":"diwan-abutammam","type":"poem","seq":25,"chapter":"البحر: طويل","title":"أأيامنا ما كنت إلا مواهبا","page":"","text":"أأيامنا ما كنت إلا مواهبا … وكنت يإسعاف الحبيب حبائبا\nسنغرب تجديدا لعهدك في البكا … فما كنت في الأيام إلا غرائبا\nومعترك للشوق أهدى به الهوى … إلى ذي الهوى ، نجل العيون ربائبا\nكواعب زارت في ليال قصيرة … يخيلن لي من حسنهن كواعبا\nسلبنا غطاء الحسن عن حر أوجه … تظل للب السالبيها سوالبا\nوجوه لو أن الأرض فيها كواكب … توقد للساري لكن كواكبا\nسلي هل عمرت القفر ، وهو سباسب … وغادرت ربعي من ركابي سباسبا\nوغربت حتى لم أجد ذكر مشرق … وشرقت حتى قد نسيت المغاربا\nخطوب إذا لاقيتهن رددنني … جريحا كأني قد لقيت الكتائبا\nومن لم يسلم للنوائب أصبحت … خلائقه طرا عليه نوائبا\nوقد يكهم السيف المسمى منية … وقد يرجع المرء المظفر خائبا\nفآفة ذا ألا يصادف مضربا … وآفة ذا ألا يصادف ضاربا\nوملآن من ضغن كواه توقلي … إلى الهمة العليا سناما وغاربا\nشهدت جسيمات العلى وهو غائب … ولو كان أيضا شاهدا كان غائبا\nإلى الحسن اقتدنا ركائب صيرت … لها الحزن من أرض الفلاة ركائبا\nنبذت إليه همتى فكأنما … كدرت به نجما على الدهر ثاقبا\nوكنت امرءا ألقى الزمان مسالما … فآليت لا ألقاه إلا محاربا\nلو اقتسمت أخلاقه الغر لم تجد … معيبا ولا خلقا من الناس عائبا\nإذا شئت أن تحصي فواضل كفه … فكن كاتبا أو فاتخذ لك كاتبا\nعطايا هي الأنواء إلا علامة … دعت تلك أنواء وتلك مواهبا\nهو الغيث لو أفرطت في الوصف عامدا … لأكذب في مدحيه ماكنت كاذبا\nثوى ماله نهب المعالي ، فأوجبت … عليه زكاة الجود ما ليس واجبا\nتحسن في عينيه إن كنت زائرا … وتزداد حسنا كلما جئت طالبا\nخدين العلى أبقى له البذل والتقى … عواقب من عرف كفته العواقبا\nيطول استشارات التجارب رأيه … إذا ما ذوو الرأي استشاروا التجاربا\nبرئت من الآمال وهي كثيرة … لديك وإن جاءتك حدبا لواغبا\nوهل كنت إلا مذنبا يوم أنتحي … سواك بآمال فأقبلت تائبا ! ؟"},{"id":"diwan-abutammam:26","bookId":"diwan-abutammam","type":"poem","seq":26,"chapter":"البحر: كامل تام","title":"يا عصمتي ومعولي وثمالي","page":"","text":"يا عصمتي ومعولي وثمالي … بل يا جنوبي غضة وشمالي\nبل لأمتي ألقى بها حد الوغى … بل يا كوكبي أسري به وهلالي\nشكلت رجاء أخيك فرقتك التي … قد أمسكت بمخنق الآمال\nفوجدتها في همتي ورأيتها … في مطلبي وعرفتها في مالي\nوغدوت تخطوني العيون ضؤولة … من بعد أبهة لديك وخال\nمن شدة الشوق التي قد أفرطت … فكأنها في العين شدة حالي\nفاجل القذى عن مقلتي بأسطر … يكشفن من كربات بال بالي\nسود يبيضن الوجوه بمصطفى … تلك النوادر منك والأمثال\nوآحثث أناملك السوابغ بينها … حتى تجول هناك كل مجال\nما زلن أظآر البلاغة كلها … وحواضن الإحسان والإجمال\nفي بطن قرطاس رخيص ضمنت … أحشاؤه دررالكلام الغالي\nإني أعدك معقلا ما مثله … كهف ولاجبل من الأجبال\nوأرى كتابك بالسلامة مغنيا … عن كتب غيرك باللهى والمال"},{"id":"diwan-abutammam:27","bookId":"diwan-abutammam","type":"poem","seq":27,"chapter":"البحر: رجز تام","title":"حماد من نوء له حماد","page":"","text":"حماد من نوء له حماد … في ناجرات الشهر لا الدآدي\nاطلق من صر ومن نوادي … فجاء يحدوها فنعم الحادي\nسارية مسمحة القياد … سهادة نوامة بالوادي\n … أظفرت الثرى بما يغادي\nنزالة عند رضا العباد … قد جعلت للمحل بالمرصاد\nسيقت ببرق ضارم الزناد … كأنه ضمائر الاغماد\nثم برعد صخب الإرعاد … يسلقها بألسن حداد\nلما سرت في حاجة البلاد … ولحق الاعجاز بالهوادي\nفاختلط السواد بالسواد … اظفرت الثرى بمن تعادي\nفرويت هاماته الصوادي … كم حملت لم قتر من زاد\nومن رواء سنة جماد … وحلبت من روقة العتاد\nمن القلاص الخور والجلاد … والمقربات الصفوة الجياد\nومن حبير اليمنة الأبراد … من أتحميات ومن وراد\nهدية من صمد جواد … ليس بمولود ولا ولاد\nممنوعة من حاضر وباد … حتى تحل في الصعيد الثادي"},{"id":"diwan-abutammam:28","bookId":"diwan-abutammam","type":"poem","seq":28,"chapter":"البحر: طويل","title":"تقي جمحاتي لست طوع مؤنبي","page":"","text":"تقي جمحاتي لست طوع مؤنبي … وليس جنيبي ، إن عذلت ، بمصحبي\nفلم توفدي سخطا إلى متنصل … ولم تنزلي عتبا بساحة معتب\nرضيت الهوى والشوق خدنا وصاحبا … فإن أنت لم ترضي بذلك فاغضبي\nتصرف حالات الفراق مصرفي … على صعب حالات الأسى ومقلبي\nولي بدن يأوي ، إذا الحب ضافه … إلى كبد حرى وقلب معذب\nوخوطية شمسية رشئية … مهفهفة الأعلى رداح المحقب\nتصدع شمل القلب من كل وجهة … وتشعبه بالبث من كل مشعب\nبمختبل ساج من الطرف أحور … ومقتبل صاف من الثغر أشنب\nمن المعطيات الحسن والمؤتياته … مجلببة أو فاضلا لم تجلبب\nلو ان امرأ القيس بن حجر بدت له … لما قال مرا بي على أم جندب\nفتلك شقوري لا ارتيادك بالأذى … محلي إلا تبكري تتأوبي\nأحاولت إرشادي ؟ فعقلي مرشدي … أم استمت تأديبي فدهري مؤدبي\nهما أظلما حالي ثمت أجليا … ظلاميهما عن وجه أمرد أشيب\nشجى في حلوق الحادثات ، مشرق … به عزمه في الترهات مغرب\nكأن له دينا على كل مشرق … من الأرض أو ثأرا لدى كل مغرب\nرأيت لعياش خلائق لم تكن … لتكمل إلا في اللباب المهذب\nله كرم لو كان في الماء لم يغض … وفي البرق ماشام امرؤ برق خلب\nأخو أزمات ، بذله بذل محسن … إلينا ولكن عذره عذر مذنب\nإذا أمه العافون ألفوا حياضه … ملاء وألفوا روضه غير مجدب\nإذا قال أهلا مرحبا نبعت لهم … مياه الندى من تحت أهل ومرحب\nيهولك أن تلقاه صدرا لمحفل … ونحرا لأعداء وقلبا لموكب\nمصاد تلاقت لوذا بريوده … قبائل حيي حضرموت ليعرب\nبأروع مضاء على كل أروع … وأغلب مقدام على كل أغلب\nكلوذهم فيما مضى من جدوده … بذي العرف والإحماد قيل ومرحب\nذوون ، قيول لم تزل كل حلبة … تمزق منهم عن أغر محنب\nهمام كنصل السيف كيف هززته … وجدت المنايا منه في كل مضرب\nتركت حطاما منكب الدهر إذ نوى … زحامي لما أن جعلتك منكبي\nوما ضيق أقطار البلاد أضافني … إليك ولكن مذهبي فيك مذهبي\nوأنت بمصر غايتي وقرابتي … بها وبنو الآباء فيها بنو أبي\nولاغرو أن وطأت أكناف مرتعي … لمهمل أخفاضي ورفهت مشربي\nفقومت لي ما اعوج من قصد همتي … وبيضت لي ما اسود من وجه مطلبي\nوهاتا ثياب المدح فاجرر ذيولها … عليك وهذا مركب الحمد فاركب"},{"id":"diwan-abutammam:29","bookId":"diwan-abutammam","type":"poem","seq":29,"chapter":"البحر: وافر تام","title":"أنا بشر قد استفتحت بابا","page":"","text":"أنا بشر قد استفتحت بابا … وقد أتممته إلا قليلا\nفأصبح وهو جبار وعهدي … به مذ أشهر يدعى فسيلا\nفلا أدري من الأعلى فعالا … ومن يبني العلى عرضا وطولا\nأمعطي الجزيل بلا امتنان … به ، أم من أفدت به الجزيلا !\nرأيتك تعرك الحاجات حتى … تعيد بذاك أصعبها ذلولا\nوتصرخ من دعاك إلى المعالي … بيا عبد الحميد ويا بجيلا\nهو الشكر الجسيم على الأعادي … إذا شكر الرجال غدا ضئيلا\nفإنك لو ترى المعروف وجها … إذا لرأيته حسنا جميلا"},{"id":"diwan-abutammam:30","bookId":"diwan-abutammam","type":"poem","seq":30,"chapter":"البحر: وافر تام","title":"يد الشكوى أتتك على البريد","page":"","text":"يد الشكوى أتتك على البريد … تمد بها القصائد بالنشيد\nتقلب بينها أملا جديدا … تدرع حلتي طمع جديد\nشكوت إلى الزمان نحول جسمي … فارشدني الى عبد الحميد\nفجئتك راكبا أمل القوافي … على ثقة من البلد البعيد"},{"id":"diwan-abutammam:31","bookId":"diwan-abutammam","type":"poem","seq":31,"chapter":"البحر: خفيف تام","title":"من سجايا الطلول ألا تجيبا","page":"","text":"من سجايا الطلول ألا تجيبا … فصواب من مقلة أن تصوبا\nفاسألنها ، واجعل بكاك جوابا … تجد الشوق سائلا ومجيبا\nقد عهدنا الرسوم وهي عكاظ … للصبى تزدهيك حسنا وطيبا\nأكثر الأرض زائرا ومزورا … وصعودا من الهوى وصبوبا\nوكعابا كأنما ألبستها … غفلات الشباب بردا قشيبا\nبين البين فقدها قلما تع … رف فقدا للشمس حتى تغيبا\nلعب الشيب بالمفارق بل ج … د فأبكى تماضرا ولعوبا\nخضبت خدها إلى لؤلؤ العق … د دما أن رأت شواتي خضيبا\nكل داء يرجى الدواء له إلا … الفظيعين : ميتة ومشيبا\nيا نسيب الثغام ذنبك أبقى … حسناتي عند الحسان ذنوبا\nولئن عبن ما رأين لقد أن … كرن مستنكرا وعبن معيبا\nأو تصدعن عن قلى لكفى بالش … يب بيني وبينهن حسيبا\nلو رأى الله أن للشيب فضلا … جاورته الأبرار في الخلد شيبا\nكل يوم تبدي صروف الليالي … خلقا من أبي سعيد رغيبا\nطاب فيه المديح والتذ حتى … فاق وصف الديار والتشبيبا\nلو يفاجا ركن النسيب كثير … بمعانيه خالهن نسيبا\nغربته العلى على كثرة النا … س ، فأضحى في الأقربين جنيبا\nفليطل عمره ، فلو مات في مر … ومقيما بها لمات غريبا\nسبق الدهر بالتلاد ولم ين … تظر النائبات حتى تنوبا\nفإذا ما الخطوب أعفته كانت … راحتاه حوادثا وخطوبا\nوصليب القناة والرأي والإس … لام ، سائل بذاك عنه الصليبا\nوعر الدين بالجلاد ولك … ن وعور العدو صارت سهوبا\nفدروب الإشراك صارت فضاء … وفضاء الإسلام يدعى دروبا\nقد رأوه وهو القريب بعيدا … ورأوه ، وهو البعيد ، قريبا\nسكن الكيد فيهم إن من أع … ظم إرب ألا يسمى أريبا\nمكرهم عنده فصيح وإن هم … خاطبوا مكره رأوه جليبا\nولعمر القنا الشوارع تمري … من تلاع الطلى نجيعا صبيبا\nفي مكر للروع كنت أكيلا … للمنايا في ظله وشريبا\nلقد انصعت والشتاء له وج … ه يراه الكماة جهما قطوبا\nطاعنا منحر الشمال متيحا … لبلاد العدو موتا جنوبا\nفي ليال تكاد تبقي بخد الشم … س من ريحها البليل شحوبا\nسبرات إذا الحروب أبيخت … هاج صنبرها فكانت حروبا\nفضربت الشتاء في أخدعيه … ضربة غادرته عودا ركوبا\nلو أصخنا من بعدها لسمعنا … لقلوب الأيام منك وجيبا\nكل حصن من ذي الكلاع وأكشو … ثاء أطلقت فيه يوما عصيبا\nوصليلا من السيوف مرنا … وشهابا من الحريق ذنوبا\nوأرادوك بالبيات ومن ه … ذا يرادي متالعا وعسيبا\nفرأوا قشعم السياسة قد ثق … ف من جنده القنا والقلوبا\nحية الليل يشمس الحزم منه … إن أرادت شمس النهار الغروبا\nلو تقصوا أمر الأزارق خالوا … قطريا سما لهم أو شبيبا\nثم وجهت فارس الأزد والأو … حد في النصح مشهدا ومغيبا\nفتصلى محمد بن معاذ … جمرة الحرب وامترى الشؤبوبا\nبالعوالي يهتكن عن كل قلب … صدره أو حجابه المحجوبا\nطلبت أنفس الكماة فشقت … من وراء الجيوب منهم جيوبا\nغزوة متبع ولو كان رأي … لم تفزد به لكانت سلوبا\nيوم فتح سقى أسود الضواحي … كثب الموت رائبا وحليبا\nفإذا ما الأيام أصبحن خرسا … كظما في الفخار قام خطيبا\nكان داء الإشراك سيفك واش … تدت شكاة الهدى ، فكنت طبيبا\nأنضرت أيكتي عطاياك حتى … صار ساقا عودي وكان قضيبا\nممطرا لي بالجاه والمال لا أل … قاك إلا مستوهبا أو وهوبا\nفإذا ما أردت كنت رشاء … وإذا ماأردت كنت قليبا\nباسطا بالندى سحائب كف … بنداها أمسى حبيب حبيبا\nفإذا نعمة امرئ فركته … فاهتصرها إليك ولهى عروبا\nوإذا الصنع كان وحشا فمل … يت برغم الزمان صنعا ربيبا\nوبقاء حتى يفوت أبو يع … قوب في سنه أبا يعقوبا"},{"id":"diwan-abutammam:32","bookId":"diwan-abutammam","type":"poem","seq":32,"chapter":"البحر: كامل تام","title":"يوم الفراق لقد خلقت طويلا","page":"","text":"يوم الفراق لقد خلقت طويلا … لم تبق لي جلدا ولا معقولا\nلو حار مرتاد المنية لم يرد … إلا الفراق على النفوس دليلا\nقالوا الرحيل فما شككت بأنها … نفسي عن الدنيا تريد رحيلا\nالصبر أجمل غير أن تلددا … في الحب أحرى أن يكون جميلا\nأتظنني أجد السبيل إلى العزا … وجد الحمام إذا إلي سبيلا !\nرد الجموح الصعب أسهل مطلبا … من رد دمع قد أصاب مسيلا\nذكرتكم الأنواء ذكري بعضكم … فبكت عليكم بكرة وأصيلا\nوبنفسي القمر الذي بمحجر … أمسى مصونا للنوى مبذولا\nإني تأملت النوى فوجدتها … سيفا علي مع الهوى مسلولا\nلا تأخذيني بالزمان ، فليس لي … تبعا ولست على الزمان كفيلا\nمن زاحف الأيام ثم عبا لها … غير القناعة لم يزل مفلولا\nمن كان مرعى عزمه وهمومه … روض الأماني لم يزل مهزولا\nلو جاز سلطان القنوع وحكمه … في الخلق ما كان القليل قليلا\nالززق لا تكمد عليه فإنه … يأتي ولم تبعث إليه رسولا\nلله درك أي معبر قفرة … لا يوحش ابن البيضة الإجفيلا\nبنت الفضاء متى تخد بك لا تدع … في الصدر منك على الفلاة غليلا\nأو ما تراها ، ما تراها ، هزة … تشأى العيون تعجرفا وذميلا !\nلو كان كلفها عبيد حاجة … يوما لأنسي شدقما وجديلا\nبالسكسكي الماتعي تمتعت … همم ثنت طرف الزمان كليلا\nلا تدعون نوح بن عمرو دعوة … للخطب إلا أن يكون جليلا\nيقظ إذاما المشكلات عرونه … ألفينه المتبسم البهلولا\nما زال يبرمهن حتى إنه … ليقال ، ما خلق الإله سحيلا\nثبت المقام يرى القبيلة واحدا … ويرى فيحسبه القبيل قبيلا\nكم وقعة لك في المكارم فخمة … غادرت فيها ما ملكت فتيلا\nأوطأت أرض البخل فيها غارة … تركت حزون الحادثات سهولا\nفرأيت أكثر ماحبوت من اللهى … نزرا وأصغر ما شكرت جزيلا\nلم يترك في المجد من جعل الندى … في ماله للمعتفين وكيلا\nأوليس عمرو بث في الناس الندى … حتى اشتهينا أن نصيب بخيلا\nأشدد يديك بحبل نوح معصما … تلقاه حبلا بالندى موصولا\nذاك الذي إن كان خلك لم تقل … يا ليتني لم أتخذه خليلا"},{"id":"diwan-abutammam:33","bookId":"diwan-abutammam","type":"poem","seq":33,"chapter":"البحر: كامل تام","title":"كشف الغطاء فأوقدي أو أخمدي","page":"","text":"كشف الغطاء فأوقدي أو أخمدي … لم تكمدي فظننت ان لم يكمد\nيكفيكه شوق يطيلث ظماءه … واذا سقاه سقاه سم الأسود\nعذلت غروب دموعه عذاله … بسواكب فندن كل مفند\nأتت النوى دون الهوى ، فأتى الأسى … دون الاسى بحرارة لم تبرد\nجارى إليه البين وصل خريدة … ماشت إليه المطل مشي الأكبد\nعبث الفراق بدمعه بقلبه … عبثا يروح الجد فيه ويغتدي\nيا يوم شرد يوم لهوي لهوه … بصبابتي وأذل عز تجلدي\nما كان أحسن لو غبرت فلم نقل … ما كان أقبح يوم برقة منشد\nيوم أفاض جوى اغاض تعزيا … خاض الهوى بحري حجاه المزيد\nعطفوا الخدور على وشي الخدود صيانة … وشي البرود بمسجف وممهد\nأهلا وسهلا بالإمام ومرحبا … سهلت حزونة كل أمر قردد\nغل المروراة الصحاصح عزمه … بالعيس إن قصدت وإن لم تقصد\nمتجرد ثبت المواطىء حزمه … متجرد للحادث المتجرد\nفانتاش مصر من اللتيا والتي … بتجاوز وتعطف وتغمد\nفي دولة لحظ الزمان شعاعها … فارتد منقلبا بعيني أرمد\nمن كان مولده تقدم قبلها … او بعدها فكأنه لم يولد\nالله يشهد أن هديك للرضا … فينا ويلعن كل من لم يشهد\nأولي أمة أحمد ما أحمد … بمضيع ما أوليت امة أحمد\nأما الهدى فقد اقتدحت بزنده … في العالمين فويل من لم يهتد\nنحن الفداء من الردى لخليفة … برضاه من سخط الليالي نفتدي\nملك إذا ما ذيق مر المبتلى … عند الكريهة عذب ماء المحتذ\nهدمت مساعيه المساعي وابتنت … خطط المكارم في عراض الفرقد\nسبقت خطا الأيام عمرياتها … ومضت فصارت مسندا للمسند\nما زال يمتحن العلى ويروضها … حتى اتقته بكيمياء السؤدد\nفكأنما ظفرت يداه بالمنى … \nسخطت لهاه على جداه سخطة … فاسترفدت أقصى رضا المسترفد\nصدمت مواهبه النوائب صدمة … شغبت على شغب الزمان الأنكد\nوطئت خزون الجود حتى خلتها … فجرت عيونا في متون الجلمد\nوأرى الأمور المشكلات تمزقت … ظلماتها عن رأيك المتوقد\nعن مثل نصل السيف إلا أنه … مذ سل اول سلة لم يغمد\nفبسطت أزهرها بوجه أزهر … وقبضت أربدها بوجه أربد\n … للراغبين زهادة في العسجد\nلو يعلم العافون كم لك في الندى … من فرحة وقريحة لم تخمد\nوكأنما نافست قدرك حظه … وحسدت نفسك حين أن لم تحسد\n … عصفت به أرواح جودك في غد\n … فيها بشأو خلائق لم تجهد\n … وحطمت بالانجاز ظهر الموعد\n … فاقام عنك وأنت سعد الاسعد\n … مرها وتربة ارضه من إثمد\nهذا أمين الله آخر مصدر … شجي الظماء يه وأول مورد\nووسيلتي فيها اليك طريفة … شام يدين بحب آل محمد\nحتى لقد ظن الغواة وباطل … أني تجسم في روح ال . . . . .\nومتى يخيم في الفؤاد عناؤها … فغناؤها يطوي المراحل في اليد"},{"id":"diwan-abutammam:34","bookId":"diwan-abutammam","type":"poem","seq":34,"chapter":"البحر: كامل تام","title":"إني اتتني من لدنك صحيفة","page":"","text":"إني اتتني من لدنك صحيفة … غلبت هموم الصدر ، وهي غوالب\nوطلبت ودي والتنائف بيننا … فنداك مطلوب ومجدك طالب\nفلتلقينك حيث كنت قصائد … فيها لأهل المكرمات مآرب\nفكأنما هي في السماع جنادل … وكأنما هي في العيون كواكب\nوغرائب تأتيك إلا أنها … لصنيعك الحسن الجميل أقارب\nنعم إذا رعيت بشكر لم تزل … نعما ، وإن لم ترع ، فهي مصائب\nكثرت خطايا الدهر في ، وقد يرى … بنداك ، وهو إلي منها تائب\nوتتابعت أيامه وشهوره … عصبا يغرن كأنهن مقانب\nمن نكبة محفوفة بمصيبة … جذ السنام لها وجذ الغارب\nأو لوعة منتوجة من فرقة … حق الدموع علي فيها واجب\nوولهت مذ زمت ركابك للنوى … فكأنني مذ غبت عني غائب"},{"id":"diwan-abutammam:35","bookId":"diwan-abutammam","type":"poem","seq":35,"chapter":"البحر: طويل","title":"تحمل عنه الصبر يوم تحملوا","page":"","text":"تحمل عنه الصبر يوم تحملوا … وعادت صباه في الصبا وهي شمأل\nبيوم كطول الدهر في عرض مثله … ووجدي من هذا وهذاك أطول\nتولوا فولت لوعتي تحشد الأسى … علي وجاءت عبرتي وهي تهمل\nبذلت لهم مكنون دمعي ، فإن ونى … فشوقي على ألا يجف موكل\nألا بكرت معذورة حين تعذل … تعرفني م العيش ما لست أجهل\nأأتبع ضنك الأمر ، والأمر مدبر … وأدفع في صدر الغنى وهو مقبل\nمحمد يا بن المستهل تهللت … عليك سماء من ثنائي تهطل\nوكم مشهد أشهدته الجود ، فانقضى … ومجدك يستحيا ومالك يقتل\nبلوناك أما كعب عرضك في العلى … فعال ولكن خذ مالك أسفل\nتحملت ما لو حمل الدهر شطره … لفكر دهرا أي عبأيه أثقل\nأبوك شقيق لم يزل وهو للندى … شقيق وللملهوف حرز ومعقل\nأفاد من العليا كنوزا لو انها … صوامت مال ما درى أين تجعل\nفحسب امرئ أنت امرو آخر له … وحسبك فخرا أنه لك أول\nوهل للقريض الغض أو من يحوكه … على أحد إلاعليك معول !\nليهن امرأ أثنى عليك بأنه … قول وإن أربى فلا يتقول\nسهلن عليك المكرمات فوصفها … علينا إذا ما استجمعت فيك أسهل\nرأيتك للسفرالمطرد غاية … يؤمونها حتى كأنك منهل\nسألتك ألا تسأل الله حاجة … سوى عفوه مادمت ترجى وتسأل\nوإياك لا إياي أمدح مثلما … عليك يقينا لا علي المعول\nولست ترى أن العلى لك عندما … تقول ولكن العلى حين تفعل\nولا شك أن الخير منك سجية … ولكن خير الخير عندي المعجل"},{"id":"diwan-abutammam:36","bookId":"diwan-abutammam","type":"poem","seq":36,"chapter":"قصائد","title":"أأطلال هند ساء ما اعتضت من هند","page":"","text":"أأطلال هند ساء ما اعتضت من هند … اقايضت حور العين بالعور ا . . . . . .\nاذا شئن بالالوان كن عصابة … من الهند والآذان كن من الصغد\nلعجنا عليك العيس بعد معاجها … على البيض اترابا على النؤي والود\nفلا دمع ما لم يجر في اثره دم … ولا وجد ما لم تعي عن صفة الوجد\nومقدودة رؤد تكاد تقدها … اصابعها بالعين من حسن القد\nتعصفر خديها العيون بحمرة … اذا وردت كانت وبالا على الورد\nاذا زهدتني في الهوى خيفة الردى … جلت لي عن وجه يزهد في الزهد\nوقفت بها اللذات في متنفس … من الغيث يسقي روضة في ثرى جعد\nوصفراء احدقنا بها في حدائق … تجود من الأثمار بالثعد والمعد\nبقاعية تجري علينا كؤوسها … فتبدي الذي نخفي وتخفي الذي نبدي\nبنصر بن منصور بن بسام انفرى … لنا شظف الأيام عن عيشة رغد\nألا لا يمد الدهر كفا بسيئ … إلى مجتدي نصر فتقطع للزند\nبسيب أبي العباس بدل أزلنا … بخفض وصرنا بعد جزر إلى مد\nغنيت به عمن سواه وحولت … عجاف ركابي من سعيد إلى سعد\nله خلق سهل ونفس طباعها … ليان ولكن عزمه من صفا صلد\nرأيت الليالي قد تغير عهدها … فلما تراءى لي رجهن الى العهد\nأسائل نصر لاتسله ، فإنه … احن الى الأرفاد منك إلى الرفد\nفتى ما يبالي حين تجتمع العلى … له أن يكون المال في السحق والبعد\nفتى جوده طبع فليس بحافل … أفي الجور كان الجود منه أو القصد\nإذا طرقته الحادثات بنكبة … مخضن سقاء منه ليس بذي زبد\nونبهن مثل السيف لو لو تسله … يدان لسلته ظباه من الغمد\nسأحمد نصرا ماحييت وإنني … لأعلم أن قد جل نصر عن الحمد\nتجلى به رشدي وأثرت به يدي … وفاض يه ثمدي وأورى يه زندي\nفإن يك أربى عفو شكري على ندى … أناس فقد أربى نداه على جهدي\nومازال منشورا علي نواله … وعندي حتى قد بقيت بلا عندي\nوقصر قولي من بعد ما أرى … أقول فأشجي امة وانا وحدي\nبغيت بشعري فاعتلاه ببذله … فلا يبغ في شعر له أحد بعدي"},{"id":"diwan-abutammam:37","bookId":"diwan-abutammam","type":"poem","seq":37,"chapter":"البحر: طويل","title":"لقد أخذت من دار ماوية الحقب","page":"","text":"لقد أخذت من دار ماوية الحقب … أنحل المغاني للبلى هي أم نهب !\nوعهدي بها إذ ناقض العهد بدرها … مراح الهوى فيها ومسرحه الخصب\nمؤزرة من صنعة الوبل والندى … بوشي زلت وشي ، وعصب ولا عصب\nتحير في آرامها الحسن ، فاغتدت … قرارة من يصبي ونجعة من يصبو\nسواكن في بر كما سكن الدمى … نوافر من سوء كما نفر السرب\nكواعب أتراب لغيداء أصبحت … وليس لها في الحسن شكل ولاترب\nلها منظر قيد النواظر لم يزل … يروح ويغدو في خفارته الحب\nيظل سراة القوم مثنى وموحدا … نشاوى بعينيها كأنهم شرب\nإلى خالد راحت بنا أرحبية … مرافقها من عن كراكرها نكب\nجرى النجد الأحوى عليها فأصبحت … من السير ورقا وهي في نجدها صهب\nإلى ملك لولا سجال نواله … لما كان للمعروف نقي ولا شخب\nمن البيض محجوب عن السوء والخنا … ولا تحجب الأنواء من كفه الحجب\nمصون المعالي لا يزيد أذاله … ولامزيد ولاشريك ولا الصلب\nولا مرتا ذهل ولا الحصن غاله … ولا كف شأويه علي ولا صعب\nوأشباه بكر المجد بكر بن وائل … وقاسط عدنان وأنجبه هنب\nمضوا وهم أوتاد نجد وأرضها … يرون عظاما كلما عظم الخطب\nوما كان بين الهضب فرق وبينهم … سوى أنهم زالوا ولم يزل الهضب\nلهم نسب كالفجر ما فيه مسلك … خفي ولا واد عنود ولا شعب\nهو الإضحيان الطلق ، رفت فروعه … وطاب الثرى من تحته وزكا الترب\nيذم سنيد القوم ضيق محله … على العلم منه أنه الواسع الرحب\nرأى شرفا ممن يريد اختلاسه … بعيد المدى فيه على أهله قرب\nفيا وشل الدنيا بشيبان لاتغض … ويا كوكب الدنيا بشيبان لا تخب\nفما دب إلا في بيوتهم الندى … ولم ترب إلا في جحورهم الحرب\nأولاك بنو الأحساب لولا فعالهم … درجن ، فلم يوجد لمكرمة عقب\nلهم يوم ذي قار مضى وهو مفرد … وحيد من الأشباه ليس له صحب\nبه علمت صهب الأعاجم أنه … به أعربت عن ذات أنفسها العرب\nهو المشهد الفصل الذي ما نجا به … لكسرى بن كسرى لا سنام ولاصلب\nأقول لأهل الثغر قد رئب الثأى … وأسبغت النعماء والتأم الشعب\nفسيحوا بأطراف الفضاء وأرتعوا … قنا خالد من درب لكم درب\nفتى عنده خير الثواب وشره … ومنه الإباء الملح والكرم العذب\nأشم شريكي يسير أمامه … مسيرة شهر في كتائبه الرعب\nولما رأى توفيل راياتك التي … إذا ما اتلأبت لا يقاومها الصلب\nتولى ولم يأل الردى في اتباعه … كأن الردى في قصده هائم صب\nكأن بلاد الروم عمت بصيحة … فضمت حشاها أو رغا وسطها السقب\nبصاغرة القصوى وطمين واقترى … بلاد قرنطاووس وابلك السكب\nغدا خائفا يستنجد الكتب مذعنا … عليك فلا رسل ثنتك ولا كتب\nوما الأسد الضرغام يوما بعاكس … صريمته إن أن بصبص الكلب\nومر ونار الكرب تلفح قلبه … وما الروح إلا أن يخامره الكرب\nمضى مدبرا شطر الدبور ، ونفسه … على نفسه من سوء ظن بها إلب\nجفا الشرق حتى ظن من كان جاهلا … بدين النصارى أن قبلته الغرب\nرددت أديم الدين أملس بعدما … غدا ولياليه وأيامه جرب\nبكل فتى ضرب يعرض للقنا … محيا محلى حليه الطعن والضرب\nكماة ، إذا تدعى نزال لدى الوغى … رأيتهم رجلى ، كأنهم ركب\nمن المطريين الأولى ليس ينجلي … بغيرهم للدهر صرف ولا لزب\nوما اجتليت بكر من الحرب ناهد … ولاثيب إلا ومنهم لها خطب\nجعلت نظام المكرمات ، فلم تدر … رحا سؤدد إلا وأنت لها قطب\nإذا افتخرت يوما ربيعة أقبلت … مجنبتي مجد وأنت لها قلب\nيجف الثرى منها وتربك لين … وينبو بها ماء الغمام وما تنبو\nبجودك تبيض الخطوب إذا دجت … وترجع في ألوانها الحجح الشهب\nهو المركب المدني إلى كل سؤدد … وعلياء إلا أنه المركب الصعب\nإذا سبب أمسى كهاما لدى امرئ … أجاب رجائي عندك السبب العضب\nوسيارة في الأرض ليس بنازح … على وخدها حزن سحيق ولا سهب\nتذر ذرور الشمس في كل بلدة … وتمضي جموحا مايرد لها غرب\nعذارى قواف كنت غير مدافع … أبا عذرها لا ظلم ذاك ولا غصب\nإذا أنشدت في القوم ظلت كأنها … مسرة كبر أو تداخلها عجب\nمفصلة باللؤلو المنتقى لها … من الشعر إلا أنه اللؤلؤ الرطب"},{"id":"diwan-abutammam:38","bookId":"diwan-abutammam","type":"poem","seq":38,"chapter":"البحر: كامل تام","title":"كفي وغاك ، فإنني لك قالي","page":"","text":"كفي وغاك ، فإنني لك قالي … ليست هوادي عزمتي بتوالي\nأنا ذوعرفت فإن عرتك جهالة … فأنا المقيم قيامة العذال\nعطفت ملامتها على ابن ملمة … كالسيف جاب الصبر شخت الآل\nعادت له أيامه مسودة … حتى توهم أنهن ليالي\nلا تنكري عطل الكريم من الغنى … فالسيل حرب للمكان العالي\nوتنظري خبب الركاب ينصها … محيي القريض إلى مميت المال\nلما بلغنا ساحة الحسن انقضى … عنا تعجرف دولة الإمحال\nبسط الرجاء لنا برغم نوائب … كثرت بهن مصارع الآمال\nأغلى عذارى الشعر إن مهورها … عند الكريم وإن رخصن غوالي\nترد الظنون به على تصديقها … ويحكم الآمال في الأموال\nأضحى سمي أبيك فيك مصدقا … بأجل فائدة وأيمن فال\nورأيتني فسألت نفسك سيبها … لي ثم جدت وما انتظرت سؤالي\nكالغيث ليس له ، أريد غمامه … أو لم يرد ، بد من التهطال"},{"id":"diwan-abutammam:39","bookId":"diwan-abutammam","type":"poem","seq":39,"chapter":"البحر: طويل","title":"قفوا جددوا من عهدكم بالمعاهد","page":"","text":"قفوا جددوا من عهدكم بالمعاهد … وإن هي لم تسمع لنشدان ناشد\nلقد أطرق الربع المحيل لفقدهم … وبينهم إطراق ثكلان فاقد\nوابقوا لضيف الحزن مني بعدهم … قرى من جوى سار وطيف معاود\nسقته ذعافا عادة الدهر فيهم … وسم الليالي فوق سم الاساود\nبه علة للبين صماء لم تصخ … لبرء ولم توجب عيادة عائد\nوفي الكلة الوردية اللون جوذر … من العين ورد اللون ورد المجاسد\nرماني بخلف بعد ما عاش حقبة … ولاسمري فيها لأول عاضد\nغدت مغتدى الغضبى وأوصت خيالها … بهجران نضو العيس نضو الخرائد\nوقالت نكاح الحب يفسد شكله … وكم نكحوا حبا وليس بفاسد\nسآوي بهذا القلب من لوعة الهوى … إلى ثغب من نطفة اليأس بارد\nوأروع لا يلقي المقاليد لامرئ … وكل امرئ يلقي له بالمقالد\nله كبرياء المشتري وسعوده … وسورة بهرام وظرف عطارد\nأغر يداه فرضتا كل طالب … وجدواه وقف في سبيل المحامد\nفتى لم يقم فرضا بيوم كريهة … إلى كل أفق وافدا غير وافد\nولااشتدت الأيام الا ألانها … اشم شديد الوطء فوق الشدائد\nبلوناه فيها ماجدا ذا حفيظة … وما كان ريب الدهر فيهابماجد\nغدا قاصدا للمجد حتى أصابه … وكم من مصيب قصده غير قاصد\nهم حسدوه لا ملومين مجده … وماحاسد في المكرمات بحاسد\nقراني اللهى والود حتى كأنما … أفاد الغنى من نائلي وفوائدي\nفأصبح يلقاني الزمان من اجله … بإعظام مولود ورأفة والد\nيصد عن الدنيا اذا عن سؤدد … ولو برزت في زي عذراء ناهد\nإذا المرء لم يزهد وقد صبغت له … بعصفرها الدنيا فليس بزاهد\nفواكبدي الحرى وواكبد الندى … لأيامه لو كن غير بوائد\nوهيهات ما ريب الزمان بمخلد … غريبا ولاريب الزمان بخالد"},{"id":"diwan-abutammam:40","bookId":"diwan-abutammam","type":"poem","seq":40,"chapter":"البحر: طويل","title":"على مثلها من أربع وملاعب","page":"","text":"على مثلها من أربع وملاعب … أذيلت مصونات الدموع السواكب\nأقول لقرحان من البين لم يضف … رسيس الهوى تحت الحشا والترائب\nأعني أفرق شمل دمعي فإنني … أرى الشمل منهم ليس بالمتقارب\nوما صار في ذا اليوم عذلك كله … عدوي حتى صار جهلك صاحبي\nومابك إركابي من الرشد مركبا … ألا إنما حاولت رشد الركائب\nفكلني إلى شوقي وسر يسر الهوى … إلى حرقاتي بالدموع السوارب\nأميدان لهوي من أتاح لك البلى … فأصبحت ميدان الصبا والجنائب ؟ !\nأصابتك أبكار الخطوب فشتتت … هواي بأبكار الظباء الكواعب\nوركب يساقون الركاب زجاجة … من السير لم تقصد لها كف قاطب\nفقد أكلوا منها الغوارب بالسرى … فصارت لها أشباحهم كالغوارب\nيصرف مسراها جذيل مشارق … إذا آبه هم عذيق مغارب\nيرى بالكعاب الرود طلعة ثائر … وبالعرمس الوجناء غرة آيب\nكأن به ضغنا على كل جانب … من الأرض أو شوقا إلى كل جانب\nإذا العيس لاقت بي أبا دلف فقد … تقطع مابيني وبين النوائب\nهنالك تلقى الجود حيث تقطعت … تمائمه والمجد مرخى الذوائب\nتكاد عطاياه يجن جنونها … إذا لم يعوذها بنغمة طالب\nإذا حركته هزة المجد غيرت … عطاياه أسماء الأماني الكواذب\nتكاد مغانيه تهش عراصها … فتركب من شوق إلى كل راكب\nإذا ماغدا أغدى كريمة ماله … هديا ولو زفت لألأم خاطب\nيرى أقبح الأشياء أوبة آيب … كسته يد المأمول حلة خائب\nوأحسن من نور تفتحه الصبا … بياض العطايا في سواد المطالب\nإذا ألجمت يوما لجيم وحولها … بنو الحصن نجل المحصنات النجائب\nفإن المنايا والصوارم والقنا … أقاربهم في الروع دون الأقارب\nجحافل لا يتركن ذا جبرية … سليما ولا يحربن من لم يحارب\nيمدون من أيد عواص عواصم … تصول بأسياف قواض قواضب\nإذا الخيل جابت قسطل الحرب صدعوا … صدور العوالي في صدور الكتائب\nإذا افتخرت يوما تميم بقوسها … وزادت على ما وطدت من مناقب\nفأنتم بذي قار أمالت سيوفكم … عروش الذين استرهنوا قوس حاجب\nمحاسن من مجد متى تقرنوا بها … محاسن أقوام تكن كالمعايب\nمكارم لجت في علو كأنها … تحاول ثأرا عند بعض الكواكب\nوقد علم الأفشين وهو الذي به … يصان رداء الملك عن كل جاذب\nبأنك لما اسحنكك الأمر واكتسى … أهابي تسفي في وجوه التجارب\nتجللته بالرأي حتى أريته … به ملء عينيه مكان العواقب\nبأرشق إذ سالت عليهم غمامة … جرت بالعوالي والعتاق الشوازب\nنضوت له رأيين سيفا ومنصلا … وكل كنجم في الدجنة ثاقب\nوكنت متى تهزز لخطب تغشه … ضرائب أمضى من رقاق المضارب\nفذكرك في قلب الخليفة بعدها … خليفتك المقفى بأعلى المراتب\nفإن تنس يذكر أو يقل فيك حاسد … يفل قوله أو تنأ دار تصاقب\nفأنت لديه حاضر غير حاضر … جميعا وعنه غائب غير غائب\nإليك أرحنا عازب الشعر بعدما … تمهل في روض المعاني العجائب\nغرائب لاقت في فنائك أنسها … من المجد فهي الآن غير غرائب\nولو كان يفنى الشعر أفناه ما قرت … حياضك منه في العصور الذواهب\nولكنه صوب العقول إذا انجلت … سحائب منه أعقبت بسحائب\nأقول لأصحابي هو القاسم الذي … به شرح الجود التباس المذاهب\nوإني لأرجو أن ترد ركائبي … مواهبه بحرا ترجى مواهبي"},{"id":"diwan-abutammam:41","bookId":"diwan-abutammam","type":"poem","seq":41,"chapter":"البحر: طويل","title":"غدا الملك معمو الحرا والمنازل","page":"","text":"غدا الملك معمو الحرا والمنازل … منوروحف الروض عذب المناهل\nبمعتصم بالله أصبح ملجأ … ومعتصما حرزا لكل موائل\nلقد ألبس الله الإمام فضائلا … وتابع فيها باللهى والفواضل\nفأضحت عطاياه نوازع شردا … تسائل في الآفاق عن كل سائل\nمواهب جدن الأرض حتى كأنما … أخذن بآداب السحاب الهواطل\nإذا كان فخرا للممدح وصفه … بيوم عقاب أو ندى منه هامل\nفكم لحظة أهديتها لابن نكبة … فأصبح منها ذا عقاب ونائل\nشهدت أمير المؤمنين شهادة … كثير ذوو تصديقها في المحافل\nلقد لبس الأفشين قسطلة الوغى … محشا بنصل السيف غير مواكل\nوسارت به بين القنابل والقنا … عزائم كانت كالقنا والقنابل\nوجرد من آرائه حين أضرمت … به الحرب حدا مثل حد المناصل\nرأى بابك منه التي لا شوى لها … فترجى سوى نزع الشوى والمفاصل\nتراه إلى الهيجاء أول راكب … وتحت صبير الموت أول نازل\nتسربل سربالا من الصبر وارتدى … عليه بغضب في الكريهة قاصل\nوقد ظللت عقبان أعلامه ضحى … بعقبان طير في الدماء نواهل\nأقامت مع الرايات حتى كأنها … من الجيش إلا أنها لم تقاتل\nفلما رآه الخرميون والقنا … بوبل أغاليه مغيث الأسافل\nرأوا منه ليثا فابذعرت حماتهم … وقد حكمت فيه حماة العوامل\nعشية صد البابكي عن القنا … صدود المقالي لا صدود المجامل\nتحدرمن لهبيه يرجو غنيمة … بساحة لا الواني ولا المتخاذل\nفكان كشاة الرمل قيضه الردى … لقانصه من قبل نصب الحبائل\nوفي سنة قد أنفد الدهر عظمها … فلم يرج منها مفرج دون قابل\nفكانت كناب شارف السن طرقت … بسقب وكانت في مخيلة حائل\nوعاذ بإطراف المعاقل معصما … وأنسي أن الله فوق المعاقل\nفولى وماأبقى الردى من حماته … له غير أسآر الرماح الذوابل\nأما وأبيه وهو من لا أبا له … يعد لقد أمسى مضيء المقاتل\nفتوح أمير المؤمنين تفتحت … لهن أزاهير الربا والخمائل\nوعادات نصر لم تزل تستعيدها … عصابة حق في عصابة باطل\nوما هو إلا الوحي أو حد مرهف … تميل ظباه أخدعي كل مائل\nفهذا دواء الداء من كل عالم … وهذا دواء الداء من كل جاهل\nفيا أيها النوام عن ريق الهدى … وقد جادكم من ديمة بعد وابل\nهو الحق إن تستيقظوا فيه تغنموا … وإن تغفلوا ، فالسيف ليس بغافل"},{"id":"diwan-abutammam:42","bookId":"diwan-abutammam","type":"poem","seq":42,"chapter":"البحر: طويل","title":"طوتني المنايا يوم ألهو بلذة","page":"","text":"طوتني المنايا يوم ألهو بلذة … وقد غاب عني أحمد ومحمد !\nجزى الله أيام الفراق ملامة … كما ليس يوم في التفرق يحمد\nإذا ما انقضى يوم بشوق مبرح … اتى باشتياق فادح بعده غد\nفلم يبق مني طول شوقي اليهم … سوى حسرات في الحشا تتردد\nخليلي ما أرتعت طرفي ببهجة … وما انبسطت مني إلى لذة يد\nولا استحدثت نفسي خليلا مجددا … فيذهلني عنه الخليل المجدد\nولا حلت عن عهدي الذي قد عهدتما … فدوما على العهد الذي كنت اعهد\nفإن تختلوا دوني بأنس ولذة … فإني بطول البث والشوق مفرد"},{"id":"diwan-abutammam:43","bookId":"diwan-abutammam","type":"poem","seq":43,"chapter":"البحر: بسيط تام","title":"مالي بعادية الأيام من قبل","page":"","text":"مالي بعادية الأيام من قبل … لم يثن كيد النوى كيدي ولاحيلي\nلا شيء إلا أباتته على وجل … ولم تبت قط من شيء على وجل\nقد قلقل الدمع دهر من خلائقه … طول الفراق ولا طول من الأجل\nسلني عن الدين والدنيا أجبك ، وعن … أبي سعيد وفقديه فلا تسل\nمن كان حلي الأماني قبل ظعنته … فصرت مذ سار ذا أمنية عطل\nنأي الندى لا تنائي خلة وهوى … والفجع بالمجد غير الفجع بالغزل\nلئن غدا شاحبا تخدي القلاص به … لقد تخلفت عنه شاحب الأمل\nملقى الرجاء وملقى الرحل في نفر … الجود عندهم قول بلا عمل\nأضحوا بمستن سيل الذم وارتفعت … أموالهم في هضاب المطل والعلل\nمن كل أظمى الثرى والأرض قد نهلت … ومقشعر الربا والشمس في الحمل !\nوأخرس الجود تلقى الدهر سائله … كأنه واقف منه على طلل !\nقد كان وعدك لي بحرا فصيرني … يوم الزماع إلى الضحضاح والوشل\nوبين الله هذا من بريته … في قوله ' خلق الإنسان من عجل '\nلله وخد المهاري أي مكرمة … هزت وأي غمام قلقلت خضل !\nخير الأخلاء خير الأرض همته … وأفضل الركب يقرو أفضل السبل\nحطت إلى عمدة الإسلام أرحله … والشمس قد نفضت ورسا على الأصل\nملبيا طالما لبى مناديه … إلى الوغى غير رعديد ولاوكل\nومحرما أحرمت أرض العراق له … من الندى واكتست ثوبا من البخل\nوسافكا لدماء البدن قد سفكت … به دماء ذوي الإلحاد والنحل\nوراميا جمرات الحج في سنة … رمى بها جمرات اليوم ذي الشعل\nيردي ويرقل نحو المروتين كما … يردي ويرقل نحو الفارس البطل\nتقبل الركن ركن البيت نافلة … ظهر كفك معمو من القبل\nلما تركت بيوت الكفر خاوية … بالغزو آثرت بيت الله بالقفل\nوالحج والغزو مقرونان في قرن … فاذهب فأنت زعاف الخيل والإبل\nنفسي فداؤك إن كانت فداءك من … صرف الحوادث والأيام والدول\nلاملبس ماله من دون سائله … سترا ولا ناصب المعروف للعذل\nلاشمسه جمرة تشوى الوجوه بها … يوما ولا ظله عنا بمنتقل\nتحول أمواله عن عهدها أبدا … ولم يزل قط عن عهد ولم يحل\nساري الهموم طموح العزم صادقه … كأن آراءه تنحط من جبل\nأبقى على جولة الأيام من كنفي … رضوى وأسير في الآفاق من مثل\nنبهت نبهان بعد النوم وانسكبت … بك الحياة على الأحياء من ثعل\nكم قد دعت لك بالإخلاص من مرة … فيهم وفداك بالآباء من رجل\nإن حن نجد وأهلوه إليك فقد … مررت فيه مرور العارض الهطل\nوأي أرض به لم تكس زهرتها … وأي واد به ظمآن لم يسل !\nما زال للصارخ المعلي عقيرته … غوث من الغوث تحت الحادث الجلل\nمن كل أبيض يجلو منه سائله … خدا أسيلا به خذ من الأسل"},{"id":"diwan-abutammam:44","bookId":"diwan-abutammam","type":"poem","seq":44,"chapter":"البحر: رجز تام","title":"ياسهم للبرق الذي استطارا","page":"","text":"ياسهم للبرق الذي استطارا … بات على رغم الدجى نهارا\nحتى اذا ما انجد الأبصارا … وبلا جهارا أو ندى سرارا\nآض لنا ماء وكان نارا … أرضى الثرى وأسخط الغبارا"},{"id":"diwan-abutammam:45","bookId":"diwan-abutammam","type":"poem","seq":45,"chapter":"البحر: بسيط تام","title":"قل للأمير قد نال ما طلبا","page":"","text":"قل للأمير قد نال ما طلبا … ورد من سالف المعروف ما ذهبا\nمن نال من سؤدد زاك ومن حسب … ما حسب واصفه من وصفه حسبا\nإذا المكارم عقت واستخف بها … أضحى الندى والسدى أما له وأبا\nترضى السيوف به في الروع منتصرا … ويغضب الدين والدنيا إذا غضبا\nفي مصعبيين ما لاقوا مريد ردى … للملك إلا أصاروا خده تربا\nكأنهم وقلنسي البيض فوقهم ، … يوم الهياج ، بدور قلنست شهبا\nفداء نعلك معطى حظ مكرمة … أصغى إلى المطل حتى باع ما وهبا\nإني وإن كان قوم مالهم سبب … إلا قضاء ، كفاهم دوني السببا\nوكنت أعلم علما لاكفاء له … أن ليس كل قطار ينبت العشبا\nوربما عدلت كف الكريم عن ال … قوم الحضور ونالت معشرا غيبا\nلمضمر غلة تخبو ، فيضرمها … إني سبقت ويعطي غيري القصبا\nونادب رفعة قد كنت آملها … لديك لا فضة أبكي ولا ذهبا\nأدعوك دعوة مظلوم وسيلته … إن لم تكن بي رحيما فارحم الأدبا\nاحفظ وسائل شعر فيك ما ذهبت … خواطف البرق إلا دون ما ذهبا\nيغدون مغتربات في البلاد فما … يزلن يؤنسن في الآفاق مغتربا\nولا تضعها ، فما في الأرض أحسن من … نظم القوافي إذا ماصادفت حسبا"},{"id":"diwan-abutammam:46","bookId":"diwan-abutammam","type":"poem","seq":46,"chapter":"البحر: طويل","title":"لهان علينا أن نقول وتفعلا","page":"","text":"لهان علينا أن نقول وتفعلا … ونذكر بعض الفضل عنك وتفضلا\nأبا جعفر أجريت في كل تلعة … لنا جعفرا من فيض كفيك سلسلا\nفكم قد أثرنا من نوالك معدنا … وكم قد بنينا في ظلالك معقلا !\nرجعت المنى خضرا تثنى غصونها … علينا وأطلقت الرجاء المكبلا\nومايلحظ العافي جداك مؤملا … سوى لحظة حتى يؤوب مؤملا\nلقد زدت أوضاحي امتدادا ولم أكن … بهيما ولا أرضى من الأرض مجهلا\nولكن أياد صادفتني جسامها … أغر فأوفت بي أغر محجلا\nإذا أحسن الأقوام أن يتطاولوا … بلا نعمة أحسنت أن تتطولا\nتعظمت عن ذاك التعظم منهم … وأوصاك نبل القدر ألا تنبلا\nتبيت بعيدا أن توجه حيلة … على نشب السلطان أو تتأولا\nإذا ما أصابوا غرة فتمولوا … بها راح بيت المال منك ممولا\nهززت أمير المؤمنين محمدا … فكان ردينيا وأبيض منصلا\nفما إن تبالي أن تجهز رأيه … إلى ناكث ألا تجهز جحفلا\nترى شخصه وسط الخلاقة هضبة … وخطبته دون الخلافة فيصلا\nوأنك إذ ألبسته العز منعما … وسربلته تلك الخلافة فيصلا\nلتقضي به حق الرعية آخرا … وتقضي به حق الخلافة أولا\nفما هضبتا رضوى ولا ركن معنق … ولا الطود من قدس ولا أنف يذبلا\nبأثقل منه وطأة حين يغتدي … فيلقي وراء الملك نحرا وكلكلا\nمنيع نواحي السر فيه ، حصينها … إذا صارت النجوى المذالة محفلا\nترى الحادث المستعجم الخطب معجما … لديه ومشكولا إذا كان مشكلا\nوجدناك أندى من رجال اناملا … وأحسن في الحاجات وجها وأجملا\nتضيء إذا اسود الزمان وبعضهم … يرى الموت أن ينهل أو يتهللا\nووالله ما آتيك إلا فريضة … وآتي جميع الناس إلا تنفلا\nوليس امرؤ في الناس كنت سلاحه … عشية يلقى الحادثات بأعزلا\nيرى درعه حصداء والسيف قاضيا … وزجيه مسمومين والسوط مغولا\nسأقطع أمطاء المطايا برحلة … إلى البلد الغربي هجرا وموصلا\nإلى الرحم الدنيا التي قد أجفها … عقوقي عسى أسبابها أن تبللا !\nقبيل وأهل لم ألاق مشوقهم … لوشك النوى إلا فواقا كلا ولا\nكأنهم كانوا لخفة وقفتي … معارف لي أو منزلا كان منزلا\nولو شيت لما التاث بري عليهم … ولم يك إجمالا لكان تجملا\nفلم أجد الأخلاق إلا تخلفا … ولم أجدش الأفضال إلا تفضلا\nوأصرف وجهي عن بلاد غدا بها … لساني مشكولا وقلبي مقفلا\nوجد بها قوم سواي ، فصادفوا … بها الصنع أعشى والزمان مغفلا\nكلاب أغارت في فريسة ضيغم … طروقا وهام أطعمت صيد أجدلا\nوإن صريح الرأي والحزم لامرئ … إذا بلغته الشمس أن يتحولا\nوإلا تكن تلك الأماني غضة … ترف فحسبي أن تصادف ذبلا\nفليس الذي قاسى المطالب غدوة … هبيدا كمن قاسى المطالب حنظلا\nلئن هممي أوجدنني في تقلبي … مآلا ، لقد أفقدنني منك موئلا\nوإن رمت أمرا مدبر الوجه إنني … سأترك حظا في فنائك مقبلا\nوإن كنت أخطو ساحة المحل إنني … لأترك روضا من جداك وجدولا\nكذلك لا يلقي المسافر رحله … إلى منقل حتى يخلف منقلا\nولا صاحب التطواف يعمر منهلا … وربعا إذا لم يخل ربعا ومنهلا\nومن ذا يداني أو ينائي وهل فتى … يحل عرى الترحال أو يترحلا !\nفمرني بأمر أحوذي فإنني … رأيت العدا أثروا وأصبحت مرملا\nفسيان عندي صادفوا لي مطمعا … أعاب به أو صادفوا لي مقتلا\nووالله لا أنفك أهدي شواردا … إليك يحملن الثناء المنخلا\nتخال به بردا عليك محبرا … وتحسبه عقدا عليك مفصلا\nألذ من السلوى وأطيب نفحة … من المسك مفتوقا وأيسر محملا\nأخف على قلب وأثقل قيمة … وأقصر في سمع الجليس وأطولا\nويزهى له قوم ولم يمدحوا به … إذا مثل الراوي به أو تمثلا\nعلى أن إفراط الحياء استمالني … إليك ولم أعدل بعرضي معدلا\nفثقلت بالتخفيف عنك وبعضهم … يخفف في الحاجات حتى يثقلا !"},{"id":"diwan-abutammam:47","bookId":"diwan-abutammam","type":"poem","seq":47,"chapter":"البحر: كامل تام","title":"إني نظرت ولا صواب لعاقل","page":"","text":"إني نظرت ولا صواب لعاقل … فيما يهم به اذا لم ينظر\nفإذا كتابك قد تخير لفظه … واذا كتابي ليس بالمتخير\nواذا رسوم في كتابك لم تدع … شكا لنظار ولا متفكر\nشكل ونقط لا يخيل كأنه ال … خيلان لاحت بين تلك الأسطر"},{"id":"diwan-abutammam:48","bookId":"diwan-abutammam","type":"poem","seq":48,"chapter":"البحر: بسيط تام","title":"قد نابت الجزع من أروية النوب","page":"","text":"قد نابت الجزع من أروية النوب … واستحقبت جدة من ربعها الحقب\nألو بصبرك إخلاق اللوى وهفا … بلبك الشوق لما أقفر اللبب\nخفت دموعك في إثر الحبيب لدن … خفت من الكثبش القضبان والكثب\nمن كل ممكورة داب النعيم لها … \nأطاعها الحسن وانحط الشباب على … فؤادها وجرت في روحها النسب\nلم أنسها وروف البين تظلمها … ولامعول إلا الواكف السرب\nأدنت نقابا على الخدين وانتسبت … للناظرين بقد ليس ينتسب\nولو تبسم عجنا الطرف في برد … وفي أقاح سقتها الخمر والضرب\nمن شكله الدر في رصف النظام ومن … صفاته الفتنتان : الظلم والشنب\nكانت لنا ملعبا نلهو بزخرفه … وقد ينفس عن جد الفتى اللعب\nوعاذل هاج لي باللوم مأربة … باتت عليها هموم النفس تصطخب\nلما أطال ارتجال العذل قلت له : … الحزم يثني خطوب الدهر لا الخطب\nلم يجتمع قط في مصر ولاطرف … محمد بن أبي مروان والنوب\nلي من أبي جعفر آخية سبب … إن تبق يطلب إلى معروفي السبب\nصحت ، فما تمارى من تأملها … من نحو نائله في أنها نسب\nأمت نداه ، بي العيس التي شهدت … لها السرى والفيافي أنها نجب\nهم سرى ثم أضحى همة أمما … أضحت رجاء وأمست وهي لي نشب\nأعطى ونطفة وجهي في قرارتها … تصونها الوجنات الغضة القشب\nلن يكرم الظفر المعطى وإن أخذت … به الرغائب حتى يكرم الطلب\nإذا تباعدت الدنيا فمطلبها … إذا توردته من شعبه كثب\nردء الخلافة في الجلى إذا نزلت … وقيم الملك لا الواني ولا النصب\nجفن يعاف لذيذ النوم ناظره … شحا عليها وقلب حولها يحب\nطليعة رأيه من دون بيضتها … كما انتمى رابئ في الغزو منتصب\nحتى إذا ما انتضى التدبير ثاب له … جيش يصارع عنه ما له لجب\nشعارها اسمك إن عدت محاسنها … إذ اسم حاسدك الأدنى لها لقب\nوزير حق ووالي شرطة ورحا … ديوان ملك وشيعي ومحتسب\nكالأرحبي المذكي سيره المرطى … والوخد والملع والتقريب والخبب\nعود تساجله أيامه فبها … من مسه وبه من مسها جلب\nثبت الجنان إذا اصطكت بمظلمة … في رحله ألسن الأقوام والركب\nلا المنطق اللغو يزكو في مقاومه … يوما ولا حجة الملهوف تستلب\nكأنما هو في نادي قبيلته … لا القلب يهفو ولا الأحشاء تضطرب\nوتحت ذاك قضاء حز شفرته … كما يعض بأعلى الغارب القتب\nلا سورة تتقى منه ولابله … ولا يحيف رضا منه ولاغضب\nألقى إليك عرى الأمر الإمام ، فقد … شد العناج من السلطان والكرب\nيعشو إليك وضوء الراي قائده … خليفة إنما آراؤه شهب\nإن تمتنع منه في الأوقات رؤيته … فكل ليث هصور غيله أشب\nأو تلق من دونه حجب مكرمة … يوما فقد ألقيت من دونك الحجب\nوالصبح تخلف نور الشمس غرته … وقرنها من وراء الأفق محتجب\nأما القوافي فقد حصنت عذرتها … فما يصاب دم منها ولا سلب\nمنعت إلا من الأكفاء ناكحها … وكان منك عليها العطف والحدب\nولو عضلت عن الأكفاء أيمها … ولم يكن لك في أطهارها أرب\nكانت بنات نصيب حين ضن بها … عن الموالي ، ولم تحفل بها العرب\nأما وحوضك مملوء ، فلا سقيت … خوامسي إن كفى أرسالها الغرب\nلو أن دجلة لم تحوج وصاحبها … أرض العراقين لم تحفر بها القلب\nلم ينتدب عمر للإبل يجعل من … هذا اللجين فدارت فيهم العلب\nإن الأسنة والماذي مذ كثرا … فلا الصياصي لها قدر ولا اليلب\nلا نجم من معشر إلا وهمته … عليك دائرة يا أيها القطب\nوما ضميري في ذكراك مشترك … ولا طريقي إلى جدواك منشعب\nلي حرمة بك لولا ما رعيت وما … أوجبت من حفظها ما خلتها تجب\nبلى لقد سلفت في جاهليتهم … للحق ليس كحقي نصرة عجب\nأن تعلق الدلو بالدلو الغريبة أو … يلابس الطنب المستحصد الطنب\nإن الخليفة قد عزت بدولته … دعائم الدين ، فليعزز بك الأدب\nمالي أرى جلبا فعما ولست أرى … سوقا وما لي أرى سوقا ولاجلب !\nأرض بها عشب جرف وليس بها … ماء وأخرى بها ماء ولا عشب\nخذها مغربة في الأرض آنسة … بكل فهم غريب حين تغترب\nمن كل قافية فيها إذا اجتنيت … من كل مايجتنيه المدنف الوصب\nالجد والهزل في توشيع لحمتها … والنبل والسخف والأشجان والطرب\nلايستقى من جفير الكتب رونقها … ولم تزل تستقي من بحرها الكتب\nحسيبة في صميم المدح منصبها … إذ أكثر الشعر ملقى ما له حسب"},{"id":"diwan-abutammam:49","bookId":"diwan-abutammam","type":"poem","seq":49,"chapter":"البحر: طويل","title":"متى أنت عن ذهلية الحي ذاهل","page":"","text":"متى أنت عن ذهلية الحي ذاهل … وقلبك منها مدة الدهر آهل !\nتطل الطلول الدمع في كل موقف … وتمثل بالصبر الديار المواثل\nدوارس لم يجف الربيع ربوعها … ولامر في أغفالها وهو غافل\nفقد سحبت فيها السحائب ذيلها … وقد أخملت بالنور فيها الخمائل\nتعفين من زاد العفاة إذا انتحى … على الحي صرف الأزمة المتماحل\nلهم سلف سمر العوالي وسامر … وفيهم جمال لا يغيض وجامل\nليالي أضللت العزاء وجولت … بعقلك آرام الخدور العقائل\nمن الهيف لو أن الخلاخل صيرت … لها وشما جالت عليا الخلاخل\nمها الوحشي إلا أن هاتا أوانس … قنا الخط إلا أن تلك ذوابل\nهوى كان خلسا إن من أحسن الهوى … هوى جلت في أفنائه ، وهو خامل\nأبا جعفر إن الجهالة أمها … ولود وأم العلم جداء حائل\nأرى الحشو والدهماء أضحوا كأنهم … شعوب تلاقت دوننا وقبائل\nغدوا وكأن الجهل يجمعهم به … أب وذوو الآداب فيهم نواقل\nفكن هضبة نأوي إليها وحرة … يعرد عنها الأعوجي المناقل\nفإن الفتى في كل ضرب مناسب … مناسب روحانية من يشاكل\nولم تنظم العقد الكعاب لزينة … كما تنظم الشمل الشتيت الشمائل\nوأنت شهاب في الملمات ثاقب … وسيف إذا ما هزك الحق قاصل\nمن البيض لم تنض الأكف كنصله … ولا حملت مثلا إليه الحمائل\nمؤرث نار والإمام يشبها … وقائل فصل والخليفة فاعل\nوإنك إن صد الزمان بوجهه … لطلق ومن دون الخليفة بباسل\nلئن نقموا حوشية فيك دونها … لقد علموا عن أي علق تناضل\nهي الشيء ، مولى المرء قرن مباين … له وابنه فيها عدو مقاتل\nإذا فضلت عن رأي غيرك أصبحت … ورأيك عن جهاتها الست فاضل\nوخطب جليل دونها قد شغلته … وفي دونه شغل لغيرك شاغل\nرددت السنا في شمسه بعد كلفة … كأن انتصاف اليوم فيها أصائل\nترى كل نقص تارك العرض والتقى … كمالا إذا الملك اعتدى وهو كامل\nجمعت عرى أعمالها بعد فرقة … إليك كما ضم الأنابيب عامل\nفأضحت وقد ضمت إليك ولم تزل … تضم إلى الجيش الكثيف القنابل\nوما برحت صورا إليك نوازعا … أعنتها مذ راسلتك الرسائل\nلك القلم الأعلى الذي بشباته … تصاب من الأمر الكلى والمفاصل\nله الخلوات اللاء لولا نجيها … لما احتفلت للملك تلك المحافل\nلعاب الأفاعي القاتلات لعابه … وأري الجنى اشتارته أيد عواسل\nله ريقة طل ولكن وقعها … بآثاره في الشرق والغرب وابل\nفصيح إذا استنطقته وهو راكب … وأعجم إن خاطبته وهو راجل\nإذا ما امتطى الخمس اللطاف وأفرغت … عليه شعاب الفكر وهي حوافل\nأطاعته أطراف القنا وتقوضت … لنجواه تقويض الخيام الجحافل\nإذا استغزر الذهن الذكي وأقبلت … أعاليه في القرطاس وهي أسافل\nوقد رفدته الخنصران وشددت … ثلاث نواحيه الثلاث الأنامل\nرأيت جليلا شأنه وهو مرهف … ضنى وسمينا خطبه وهو ناحل\nأرى ابن أبي مروان أما عطاؤه … فطام وأما حكمه فهو عادل\nهو المرء لا الشورى استبدت برأيه … ولا قبضت من راحتيه العواذل\nمعرس حق ماله ولربما … تحيف منه الخطب والخطب باطل\nلقاح ، فلم تخدجه بالضيم منة … ولانال أنفا منه بالذل نائل\nترى حبله غرثان من كل غدرة … إذا نصبت تحت الحبال الحبائل\nفتى لا يرى أن الفريصة مقتل … ولكن يرى أن العيوبا لمقاتل\nولا غمر قد رقص الخفض قلبه … ولاطارف في نعمة الله جاهل\nأبا جعفر إن الخليفة إن يكن … لورادنا بحرا فإنك ساحل\nوما راغب أسرى إليك براغب … ولاسائل أم الخليفة سائل\nتقطعت الأسباب إن لم تغر لها … قوى ويصلها من يمينك واصل\nسوى مطلب ينضي الرجاء بطوله … وتخلق إخلاق الجفون الوسائل\nوقد تألف العين الدجى وهو قيدها … ويرجى شفاء السم السم قاتل\nولي همة تمضي العصور وإنها … كعهدك من أيام وعدك حامل\nسنون قطعناهن حتى كأنما … قطعنا لقرب العهد منها مراحل\nوإن جزيلات الصنائع لامرئ … إذا ما الليالي ناكرته معاقل\nوإن المعالي يوم بناءها … وشيكا كما قد تسترم المنازل\nولو حاردت شول عذرت لقاحها … ولكن حرمت الدر والضرع حافل\nمنحتكها تشفي الجوى ، وهو لاعج … وتبعث أشجان الفتى ، وهو ذاهل\nترد قوافيها إذا هي أرسلت … هوامل مجد القوم وهي هوامل\nفكيف إذا حليتها بحليها … تكون وهذا حسنها وهي عاطل\nأكابرنا عطفا علينا فإننا … بنا ظمأ مرد وأنتم مناهل"},{"id":"diwan-abutammam:50","bookId":"diwan-abutammam","type":"poem","seq":50,"chapter":"البحر: كامل تام","title":"أما وقد ألحقتني بالموكب","page":"","text":"أما وقد ألحقتني بالموكب … ومددت من ضبعي إليك ومنكبي\nفلأعرضن عن الخطوب وجورها … ولأصفحن عن الزمان المذنب\nولألبسنك كل بيت معلم … يسدى ويلحم بالثناء المعجب\nمن بزة المدح التي مشهورها … متمكن في كل قلب قلب\nنوار أهل المشرق الغض الذي … يجنونه ريحان أهل المغرب\nأبديت لي عن جلدة الماء الذي … قد كنت أعهده كثير الطحلب\nووردت بي بحبوحة الوادي ولو … خليتني لوقفت عند المذنب\nوبرقت لي برق اليقين وطالما … أمسيت مرتقبا لبرق الخلب\nوجعلت لي مندوحة من بعد ما … أكدى علي تصرفي وتقلبي\nوالحر يسلبه جميل عزائه … ضيق المحل فكيف ضيق المذهب ؟\nهيهات يأبى أن يضل بي السرى … في بلدة وسناك فيها كوكبي\nولقد خشيت بأن تكون غنيمتي … حر الزمان بها وبردالمطلب\nأما وأنت وراء ظهري معقل … فأنهضن بفقار صلب صلب\nوكذلك كانوا لا يخشون الوغا … إلا إذا عرفوا طريق المهرب"},{"id":"diwan-abutammam:51","bookId":"diwan-abutammam","type":"poem","seq":51,"chapter":"البحر: كامل تام","title":"آلت أمور الشرك شر مآل","page":"","text":"آلت أمور الشرك شر مآل … وأقر بعد تخمط وصيال\nغضب الخليفة للخلافة غضبة … رخصت لها المهجات وهي غوالي\nلما انتضى جهل السيوف لبابك … أغمدن عنه جهالة الجهال\nفلأذربيجان اختيال بعدما … كانت معرس عبرة ونكال\nسمجت ونبهنا على استسماجها … ما حولها من نضرة وجمال\nوكذاك لم تفرط كآبة عاطل … حتى يجاورها الزمان بحالي\nأطلقتها من كيده وكأنما … كانت به معقولة بعقال\nخرق من الأيام مد بضبعه … صعدا وأعطاه بغير سؤال\nخاف العزيز به الذليل وغودرت … نبعات نجد سجدا للضال\nقد أترعت منه الجوانح رهبة … بطلت لديها سورة الأبطال\nلو لم يزاحفهم لزاحفهم له … ما في صدورهم من الأوجال\nبحر من المكروه عب عبابه … ولقد بدا وشلا من الأوشال\nجفت به النعم النواعم وانثنت … سرج الهدى فيه بغير ذبال\nوأباح نصل السيف كل مرشح … لم يحمرر دمه من الأطفال\nما حل في الدنيا فواق بكية … حتى دعاه السيف بالترحال\nرعبا أراه أنه لم يقتل الآ … ساد من أبقى على الأشبال\nلو عاين الدجال بعض فعاله … لانهل دمع الأعور الدجال\nأعطى أمير المؤمنين سيوفه … فيه الرضا وحكومة المقتال\nمستيقنا أن سوف يمحو قتله … ماكان من سهو ومن إغفال\nمثل الصلاة إذا أقيمت أصلحت … ماقبلها من سائر الأعمال\nفرماه بالأفشين بالنجم الذي … صدع الدجى صدع الرداء البالي\nلاقاه بالكاوي العنيف بدائه … لما رآه لم يفق بالطالي\nيا يوم أرشق كنت رشق منية … للخرمية صائب الآجال\nأسرى بنو الإسلام فيه وأدلجوا … بقلوب أسد في صدور رجال\nقد شمروا عن سوقهم في ساعة … أمرت إزار الحرب بالإسبال\nوكذاك ما تنجر أذيال الوغى … إلا غداة تشمر الأذيال\nلما رآهم بابك دون المنى … هجر الغواية بعد طول وصال\nتخذ الفرار أخا وأيقن أنه … صري عزم من أبي سمال\nقد كان حزن الخطب في أحزانه … فدعاه داعي الحين للإسهال\nلبست له خدع الحروب زخارفا … فرقن بين الهضب والأوعال\nووردن موقانا عليه شوازبا … شعثا بشعب كالقطا الأرسال\nيحملن كل مدجج سمر القنا … بإهابه أولى من السربال\nخلط الشجاعة بالحياء فأصبحا … كالحسن شيب لمغرم بدلال\nفنجا ولو يثقفنه لتركنه … بالقاع غير موصل الأوصال\nوانصاع عن موقان وهي لجنده … وله أب بر وأم عيال\nكم أرضعته الرسل لو أن القنا … ترك الرضاع له بغير فصال !\nهيهات روع روعه بفوارس … في الحرب لا كشف ولا أميال\nجعلوا القنا الدرجات للكذجات ذا … ت الغيل والحرجات والأدحال\nفأولاك هم قد أصبحوا وشروبهم … يتنادمون كؤوس سوء الحال\nماطال بغي قط إلا غادرت … غلواؤه الأعمار غير طوال\nوبهضبتي أبرشتويم ودروذ … لقحت لقاح النصر بعد حيال\nيوم أضاء به الزمان وفتحت … فيه الأسنة زهرة الآمال\nلولا الظلام وقلة علقوا بها … باتت رقابهم بغير قلال\nفليشكروا جنح الظلام ودروذا … فهم لدروذ الظلام موالي\nوسروا بقارعة البيات فزحزحوا … بقراع لا صلف ولا مختال\nمهر البيات الصبر في متعطف … الصبر وال فيه فوق الوالي\nماكان ذاك الهول أجمع عنده … مع عزمه إلا طروق خيال\nوعشية التل الذي نعش الهدى … أصل لها فخم من الآصال\nنزلت ملائكة السماء عليهم … لما تداعى المسلمون نزال\nلم يكس شخص فيئه حتى رمى … وقت الزوال نعيمهم بزوال\nبرزت بهم هفوات علجهم وقد … يردي الجمال تعسف الجمال\nفكأنما احتالت عليه نفسه … إذ لم تنله حيلة المحتال\nفالبذ أغبر دارس الأطلال … ليد الردى أكل من الآكال\nألوت به ، يوم الخميس ، كتائب … أرسلنه مثلا من الأمثال\nمحو من البيض الرقاق أصابه … فعفاه لا محو من الأحوال\nريحان من صبر ونصر أبليا … ربعيه لا ريحا صبا وشمال\nلفحت سموم المشرفية وسطه … وهجا وكن سوابغ الأظلال\nكم صارم غصب أناف على فتى … منهم لأعباء الوغى حمال\nسبق المشيب إليه حتى ابتزه … وطن النهى من مفرق وقذال\n … قد مات صبرا ميتة الرئبال\nأبنا بكل خريدة قد أنجزت … فيها عدات الدهر بعد مطال\nخاضت محاسنها مخاوف غادرت … ماء الصبا والحسن غير زلال\nأعجلن عن شد الإزار وربما … عودن أن يمشين غير عجال\nمستر دفات فوق جرد أوقرت … أكفالها من رجح الأكفال\nبدلن طول إذالة بصيانة … وكسور خيم من كسور خجال\nونجا ابن خائنة البعولة لو نجا … بمهفهف الكشحين والآطال\nخلى الأحبة سالما لا ناسيا … عذر النسي خلاف عذر السالي\nهتكت عجاجته القنا عن وامق … أهدى الطعان له خليقه قال\nإن الرماح إذا غرسن بمشهد … فجنى العوالي في ذراه معال\nلما قضى رمضان منه قضاءه … شالت به الأيام في شوال\nمازال مغلول العزيمة سادرا … حتى غدا في القيد والأغلال\nمستسبلا للبأس طوقا من ذم … لما استبان فظاظة الخلخال\nما نيل حتى طار من خوف الردى … كل المطار وجال كل مجال\nوالنحر أصلح للشرود ، وما شفى … منه كنحر بعد طول كلال\nلاقى الحمام بسر من راء التي … \nقطعت به أسبابه لما رمى … \n … من عاف متن الأسمر العسال\nلا كعب أسفل موضعا من كعبه … مع أنه عن كل كعب عال\nسام كأن العز يجذب ضبعه … وسموه من ذلة وسفال\nمتفرغ أبدا وليس بفارغ … من لاسبيل له إلى الأشغال\nفاسلم أمير المؤمنين لأمة … أبدلتها الإمراع بالإمحال\nأمسى بك الإسلام بدرا بعد ما … محقت بشاشته محاق هلال\nأكملت منه بعد نقص كل ما … نقصته أيدي الكفر بعد كمال\nألبسته أيامك الغر التي … أيام غيرك عندهن ليالي\nوعزائما في الروع معتصمية … ميمونة الإدبار والإقبال\nفتعمق الوزراء يطفوا فوقها … طفو القذى وتعقب العذال\nوالسيف مالم يلف فيه صيقل … من طبعه لم ينتفع بصقال"},{"id":"diwan-abutammam:52","bookId":"diwan-abutammam","type":"poem","seq":52,"chapter":"البحر: منسرح","title":"إن بكاء في الدار من أربه","page":"","text":"إن بكاء في الدار من أربه … فشايعا مغرما على طربه\nما سجسج الشوق مثل جاحمه … ولاصريح الهوى كمؤتشبه\nجيدت بذاني الأكناف ساحتها … نائي المدى واكف الجدى سربه\nمزن إذا ما استطار بارقه … أعطى البلاد الأمان من كذبه\nيرجع حرى التلاع مترعة … ريا ويثني الزمان عن نوبه\nمتى يضف بلدة فقد قريت … بمستهل الشؤبوب منسكبه\nلا تسلب الأرض بعد فرقته … عهد متابيعه ولا سلبه\nمزمجر المنكبين صهصلق … يطرق أزل الزمان من صخبه\nعاذت صدوع الفلا به ولقد … صح أديم الفضاء من جلبه\nقد سلبته الجنوب والدين والدن … يا وصافي الحياة في سلبه\nوحرشته الدبور واجتنبت … ريح القبول الهبوب من رهبه\nوغادرت وجهه الشمال فقل … لا في نزور الندى ولا حقبه\nدع عنك دع ذا إذا انتقلت إلى … المدح وشب سهلة بمقتضبه\nإني لذو ميسم يلوح على … صعود هذا الكلام أو صببه\nلست من العيس أو أكلفها … وخدا يداوي المريض من وصبه\nإلى المصفى مجدا أبي الحسن … انصعن انصياع الكدري في قربه\nترمي بأشباحنا إلى ملك … نأخذ من ماله ومن أدبه\nنجم بني صالح وهم أنجم العلا … لم من عجمه ومن عربه\nرهط الرسول الذي تقطع أس … باب البرايا غدا سوى سببه\nمهذب قدت النبوة والإس … لام قد الشراك من نسبه\nله جلال إذا تسربله … أكسبه البأو غير مكتسبه\nوالحظ يعطاه غير طالبه … ويحرز الدر غير محتلبه\nكم أعطبت راحتاه من نشب … سلامة المعتفين في عطبه\nأي مداو للمحل نائله … وهانىء للزمان من جربه !\nمشمر ما يكل في طلب ال … علياء والحاسدون في طلبه\nأعلاهم دونه وأسبقهم … إلى العلى واطىء على عقبه\nيريح قوم والجود والحق وال … حاجات مشدودة إلى طنبه\nوهل يبالي إقضاض مضجعه … من راحة المكرمات في تعبه ؟\nتلك بنات المخاض راتعة … والعود في كوره وفي قتبه\nمنء ذا كعباسه إذا اصطكت ال … أحساب أم من كعبد مطلبه ؟\nهيهات أبدى اليقين صفحته … وبان نبع الفخار من غربه\nعبد المليك بن صالح بن علي … مبن قسيم النبي في نسبه\nألبسه المجد لا يريد به … بردا وصاغ السماح منه وبه\nلقمان صمتا وحكمة فإذا … قال لقطنا المرجان من خطبه\nإن جد رد الخطوب تدمى وإن … يلعب فجد العطاء في لعبه\nيتلو رضاه الغنى بأجمعه … وتحذر الحادثات في غضبه\nتزل عن عرضه العيوب وقد … تنشب كف الغني في نشبه\nتأتيه فراطنا فتحكم في … لجينه تارة وفي ذهبه\nبأي سهم رميته في نصله ال … ماضي وفي ريشه وفي عقبه ؟ !\nلا يكمن الغدر للصديق ولا … يخطو اسم ذي وده إلى لقبه\nيأبر غرس الكلام فيك فخذ … واجتن من زهوه ومن رطبه\nأما ترى الشكر من ربائطه … جاء وسرح المديح من جلبه ؟ !"},{"id":"diwan-abutammam:53","bookId":"diwan-abutammam","type":"poem","seq":53,"chapter":"البحر: طويل","title":"جعلت فداك أنت من لا ندله","page":"","text":"جعلت فداك أنت من لا ندله … على الحزم في التدبير بل نستدله\nوليس امرؤ بهديك غير مذكر … إلى كرم إلا امرؤ ضل ضله\nولكننا من يوسف بن محمد … على أمل كالفجر لاح مطله\nهلال لنا قد كاد يخمد ضوؤه … وكنا نراه البدر إذ نستهله\nهو السيف عضبا قد أرثت جفونه … وضيع حتى كل شيء يفله\nفصنه ، فإنا نرتجي في غراره … شفاء من الأعداء يوم تسله\nله خلق رحب ونفس رأيتها … إذا رزحت نفس اللئيم تقله\nففيم ولم صيرت سمعك ضيعة … ووقفا على الساعي به يستغله\nقرارة عدل سيل كل ثنية … إليها وشعب كل زور يحله\nلذلك ذا المولى المهان يهينه … فيحظى وذا العبد الذليل يذله\nأتغدو به في الحرب قبل اتغاره … وفي الخطب قعد أعيا الأولى مصمئله\nوتعقده حتى إذا استحصدت له … مرائره أنشأت بعد تحله !\nهو النفل الحلو الذي إن شكرته … فقد ذاب في أقصى لهاتك حله\nوفيء فوقره وإني لواثق … بأن لا يراك الله ممن يغله\nفلو كان فرعا من فروعك لم يكن … لنا منهم إلا ذراه وظله\nفكيف وإن لم يرزق الله إخوة … له ، فهو بعد اليوم فرعك كله ؟"},{"id":"diwan-abutammam:54","bookId":"diwan-abutammam","type":"poem","seq":54,"chapter":"البحر: وافر تام","title":"شهدت لقد لبست أبا سعيد","page":"","text":"شهدت لقد لبست أبا سعيد … خلائق تبهر الشرف الطوالا\nأتعتع في الحوائج إن خفافا … غدوت بها عليك وإن ثقالا\nأحين رفعت من شأوي وعادت … حويلي من ندى كفيك حالا ؟ !\nبفضلك صرت أكثرهم عطاء … وقبلك كنت أكثرهم سؤالا\nفلا يكدر قليبك لي ، فإني … أمد إليك أسبابا طوالا"},{"id":"diwan-abutammam:55","bookId":"diwan-abutammam","type":"poem","seq":55,"chapter":"البحر: طويل","title":"هل اجتمعت أحياء عدنان كلها","page":"","text":"هل اجتمعت أحياء عدنان كلها … بملتحم إلا وأنت أميرها ؟\nبك اليمن استعلت على كل موطن … وصار لطي تاجها وسريرها\nمحرمة أكفال خيلك في الوغى … ومكلومة لباتها ونحورها\nحرام على ارماحنا طعن مدبر … وتندق في أعلى الصدور صدورها"},{"id":"diwan-abutammam:56","bookId":"diwan-abutammam","type":"poem","seq":56,"chapter":"البحر: وافر تام","title":"سلام الله عدة رمل خبت","page":"","text":"سلام الله عدة رمل خبت … على ابن الهيثم الملك اللباب\nذكرتك ذكرة جذبت ضلوعي … إليك كأنها ذكرى تصابي\nفلا يغبب محلك كل يوم … من الأنواء ألطاف السحاب\nسقت جودا نوالا منك جودا … وربعا غير مجتنب الجناب\nفثم الجود مشدود الأواخي … وثم المجد مضروب القباب\nوأخلاق كأن المسك فيها … بصفو الراح والنطف العذاب\nوكم أحييت من ظن رفات … بها وعمرت من أمل خراب\nيمين محمد بحر خضم … طموح الموج ، مجنون العباب\nتفيض سماحة والمزن مكد … وتقطع والحسام العضب ناب\nفداك أبا الحسين من الرزايا … ومن داجي حوادثها الغضاب\nحسود قصرت كفاه عنه … وكفك للنوال وللضراب\nويحسب ما يفيد بلا نوال … وتعطي ماتفيد بلا حساب\nويغدو يستثيب بلا نوال … ونيلك كله لا للثواب\nذكرت صنيعة لك ألبستني … أثيث المال والنعم الرغاب\nتجدد كلما لبست وتبقى … إذا ابتذلت وتخلق في الحجاب\nإذا ما أبرزت زادت ضياء … وتشحب وجنتاها في النقاب\nوليست بالعوان العنس عندي … ولا هي منك بالبكر الكعاب\nفلا يبعد زمان منك عشنا … بنضرته ورونقه العجاب\nكأن العنبر الهندي فيه … وفأر المسك مفضوض الرضاب\nلياليه ليالي الوصل تمت … بأيام كأيام الشباب\nأقول ببعض ما أسديت عندي … وما أطلبتني قبل الطلاب\nولو أني استطعت لقام عني … بشكرك من مشى فوق التراب\nإذا شكرتك مذحج حيث كانت … بنو ديانها وبنو الضباب\nوجئتك في قضاعة قد أطافت … بركني عامر وبني جناب\nولاستنجدت حنظل وعمرا … ولم أعدل بسعد والرباب\nولاسترفدت من قيس ذراها … بني بدر وصيد بني كلاب\nولاحتفلت ربيعة لي جميعا … بأيام كأيام الكلاب\nفأشفي من صميم الشكر نفسي … وترك الشكر أثقل للرقاب\nإليك أثرت من تحت التراقي … قوافي تستدر بلا عصاب\nمن القرطات في الآذان تبقى … بقاء الوحي في الصم الصلاب\nعراض الجاه تجزع كل واد … مكرمة وتفتح كل باب\nمضمن كلال الركب تغني … غناء الزاد عنهم والركاب\nإذا عارضتها في يوم فخر … مسحت خدود سابقة عراب\nتصير بها وهاد الأرض هضبا … وأعلاما وتثلم في الروابي\nكتبت ولو قدرت جوى وشوقا … إليك لكنت سطرا في كتابي"},{"id":"diwan-abutammam:57","bookId":"diwan-abutammam","type":"poem","seq":57,"chapter":"البحر: كامل تام","title":"دمن ألم بها فقال سلام","page":"","text":"دمن ألم بها فقال سلام … كم حل عقدة صبره الإلمام\nنحرت ركاب القوم حتى يغبروا … رجلى ، لقد عنقوا علي ولامور\nعشقوا ، ولارزقوا ، أيعذل عاشق … رزقت هواه معالم وخيام ؟ !\nوقفوا علي اللوم حتى خيلوا … أن الوقوف على الديار حرام !\nما مر يوم واحد إلا وفي … أحشائه لمحلتيك غمام\nحتى تعمم صلع هامات الربا … من نوره وتأزر الأهضام\nولقد أراك ، فهل أراك بغبطة … والعيش غض والزمان غلام ؟ !\nأعوام وصل كان ينسي طولها … ذكر النوى ، فكأنها أيام\nثم انبرت أيام هجر أردفت … بجوى أسى ، فكأنها أعوام\nثم انقضت تلك السنون وأهلها … فكأنها وكأنهم أحلام\nأتصعصعت عبرات عينك أن دعت … ورقاء حين تصعصع الإظلام . ؟ !\nلاتنشجن لها فإن بكاءها … ضحك ، وإن بكاءك استغرام\nهن الحمام فإن كسرت عيافة … من حائهن فإنهن حمام\nالله أكبر جاء أكبر من جرت … فتحيرت في كنهه الأوهام\nمن لا يحيط الواصفون بقدره … حتى يقولوا قدره إلهام\nمن شرد الإعدام عن أوطانه … بالبذل حتى استطرف الإعدام\nوتكفل الأيتام عن آبائهم … حتى وددنا أننا أيتام\nمستسلم لله ، سائس أمة … لذوي تجهضمها له استسلام\nيتجنب الآثام ثم يخافها … فكأنما حسناته آثام\nيأيها الملك الهمام وعدله … ملك عليه في القضاء همام\nما زال حكم الله يشرق وجهه … في الأرض مذ نيطت بك الأحكام\nأسرت لك الآفاق عزمه همة … جبلت على أن المسير مقام\nإلا تكن أرواحها لك سخرت … فالعزم طوع يديك والإجذام\nالشرق غرب حين تلحظ قصده … ومخالف اليمن القصي شآم\nبالشدقميات العتاق كأنما … أشباحها بين الإكام إكام\nوالأعوجيات الجياد كأنها … تهوي وقد ونت الرياح سمام\nلما رأيت الدين يخفق قلبه … والكفر فيه تغطرس وعرام\nأوريت زند عزائم تحت الدجى … أسرجن فكرك والبلاد ظلام\nفنهضت تسحب ذيل جيش ساقه … حسن اليقين وقاده الإقدام\nمثعنجر لجب ترى سلافه … ولهم بمنخرق الفضاء زحام\nملأ الملا عصبا فكاد بأن يرى … لاخلف فيه ولا له قدام\nبسواهم لحق الأياطل شزب … تعليقها الإسراج والإلجام\nومقاتلين إذا انتموا لم يخزهم … في نصرك الأخوال والأعمام\nسفع الدؤوب وجوههم فكأنهم … وأبوهم سام أبوهم حام\nتخذوا الحديد من الحديد معاقلا … سكأنها الأرواح والأجسام\nمسترسلين إلى الحتوف ، كأنما … بين الحتوف وبينهم أرحام\nآساد موت مخدرات مالها … إلا الصوارم والقنا آجام\nحتى نقضت الروم منك بوقعة … شنعاء ليس لنقضها إبرام\nفي معرك أما الحمام فمفطر … في هبوتيه والكماة صيام\nوالضرب يقعد قرم كل كتيبة … شرس الضريبة والحتوف قيام\nففصمت عروة جمعهم فيه وقد … جعلت تفصم عن عراها الهام\nألقوا دلاء في بحورك أسلمت … ترعاتها الأكرا والأوذام\nما كان للإشراك فوزة مشهد … والله فيه وأنت والإسلام\nلما رأيتهم تساق ملوكهم … حزقا إليك كأنهم أنعام\nجرحى إلى جرحى كأن جلودهم … يطلى بها الشيان والعلام\nمتساقطي ورق الثياب كأنهم … دانوا فأحدث فيهم الإحرام\nأكرمت سيفك غربه وذبابه … عنهم وحق لسيفك الإكرام\nفرددت حد الموت وهو مركب … في حده فارتد وهو زؤام\nأيقظت هاجعهم وهل يغنيهم … سهر النواظر والعقول نيام\nجحدتك منهم ألسن لجلاجة … أقررن أنك في القلوب إمام\nإسلم أمير المؤمنين لأمة … نتجت رجاءك والرجاء عقام\nإن المكارم للخليفة لم تزل … والله يعلم ذاك والأقوام\nكتبت له ولأوليه وراثة … في اللوح حتى جفت الأقلام\nمتوطئو عقبيك في طلب العلا … والمجد ثمت تستوي الأقدام"},{"id":"diwan-abutammam:58","bookId":"diwan-abutammam","type":"poem","seq":58,"chapter":"البحر: خفيف تام","title":"ديمة سمحة القياد سكوب","page":"","text":"ديمة سمحة القياد سكوب … مستغيث بها الثرى المكروب\nلو سعت بقعة لإعظام نعمى … لسعى نحوها المكان الجديب\nلذ شؤبوبها وطاب فلو تس … طيع قامت فعانقتها القلوب\nفهي ماء يجري وماء يليه … وعزال تهمي وأخرى تذوب\nكشف الروض رأسه واستسر … المحل منها كما استسر المريب\nفإذا الرى ، بعد محل وجرجا … ن لديها يبرين أو ملحوب\nأيها الغيث حي أهلا بمغدا … ك وعند السرى وحين تؤوب\nلأبي جعفر خلائق تحكي … هن قد يشبه النجيب النجيب\nأنت فينا في ذا الأوان غريب … وهو فينا في كل وقت غريب\nضاحك في وائب الدهر طلق … وملوك يبكين حين تنوب\nفإذا الخطب راث نال الندى وال … بذل منه ما لا تنال الخطوب\nخلق مشرق ورأي حسام … ووداد عذب وريح جنوب\nكل يوم له وكل أوان … خلق ضاحك ومال كئيب\nإن تقاربه أو تباعده ما لم … تأت فحشاء فهو منك قريب\nما التقى وفره ونائله مذ … كان إلا ووفره المغلوب\nفهو مدن للجود وهو بغيض … وهو مقص للمال وهو حبيب\nيأخذ الزائرين قسرا ولو كف … م دعاهم إليه واد خصيب\nغير أن الرامي المسدد يحتا … ط مع العلم أنه سيصيب"},{"id":"diwan-abutammam:59","bookId":"diwan-abutammam","type":"poem","seq":59,"chapter":"البحر: وافر تام","title":"أرامة كنت مألف كل ريم","page":"","text":"أرامة كنت مألف كل ريم … لو استمتعت بالأنس القديم\nأدار البؤس حسنك التصابي … إلي فصرت جنات النعيم\nلئن أصبحت ميدان السوافي … لقد أصبحت ميدان الهموم\nومما ضرم البرحاء أني … شكوت فما شكوت إلى رحيم\nأظن الدمع في خدي سيبقى … رسوما من بكائي في الرسوم\nوليل بت أكلؤه كأني … سليم أو سهرت على سليم\nأراعي من كواكبه هجانا … سواما ما تريع إلى المسيم\nفأقسم لو سألت دجاه عني … لقد أنباك عن وجد عظيم\nأنخنا في ديار بني حبيب … بنات السير تحت بني العزيم\nوما إن زال في جرم ابن عمرو … كريم من بني عبد الكريم\nيكاد نداه يتركه عديما … إذا هطلت يداه على عديم\nتراه يذب عن حرم المعالي … فتحسبه يدافع عن حريم\nغريم للملم به وحاشى … نداه من مماطلة الغريم\nسفيه الرمح جاهله إذا ما … بدا فضل السفيه على الحليم\nإذا ما قيل أرعفت العوالي … فليس المرعفات سوى الكلوم\nإذا ما الضرب حش الحرب أبدى … أغر الرأي في الخطب البهيم\nتقفى الحرب منه حين تغلي … مراجلها بشيطان رجيم\nفإن شهد المقامة يوم فصل … رأيت نظير لقمان الحكيم\nإذا نزل النزيع بهم قروه … رياض الريف من أنف جميم\nفلو شاهدتهم والزائريهم … لما مزت البعيد من الحميم\nأولئك قد هدوا في كل مجد … إلى نهج الصراط المستقيم\nأحلهم الندى سطة المعالي … إذا نزل البخيل على التخوم\nفروع لا ترف عليك إلا … شهدت لها على طيب الأروم\nوفي شرف الحديث دليل صدق … لمختبر على الشرف القديم\nلهم غرر تخال إذا استنارت … بواهرها ضرائر للنجوم\nقروم للمجير بهم أسود … نكال للأسود وللقروم\nإذا نزلوا بمحل روضوه … بآثار كآثار الغيوم\nلكل من بني حواء عذر … ولاعذر لطائي لئيم\nأحق الناس بالكرم امرؤ لم … يزل يأوي إلى أصل كريم"},{"id":"diwan-abutammam:60","bookId":"diwan-abutammam","type":"poem","seq":60,"chapter":"البحر: بسيط تام","title":"لا عيش أو يتحامى جسمك الصب","page":"","text":"لا عيش أو يتحامى جسمك الصب … فتنجلي بك عن خلصانك الكرب\nلعا أبا جعفر واسلم فقد سلمت … بك المروءة وستعلى بك الحسب\nإنا جهلنا فخلناك اعتللت ولا … والله ما اعتل إلا الملك والأدب"},{"id":"diwan-abutammam:61","bookId":"diwan-abutammam","type":"poem","seq":61,"chapter":"البحر: بسيط تام","title":"أصغى إلى البين مغترا فلا جرما","page":"","text":"أصغى إلى البين مغترا فلا جرما … أن النوى أسأرت في قلبه لمما\nأصمني سرهم أيام فرقتهم … هل كنت تعرف سرا يورث الصمما"},{"id":"diwan-abutammam:62","bookId":"diwan-abutammam","type":"poem","seq":62,"chapter":"البحر: رجز تام","title":"كان لنفسي أمل فانقضى","page":"","text":"كان لنفسي أمل فانقضى … فأصبح اليأس لها معرضا\nاسخطني دهري بعد الرضا … وارتجع العرف الذي قد مضى\nلم يظلم الدهر ولكنه … أقرضني الإحسان ثم اقتضى !"},{"id":"diwan-abutammam:63","bookId":"diwan-abutammam","type":"poem","seq":63,"chapter":"البحر: سريع","title":"يا مغرس الظرف وفرع الحسب","page":"","text":"يا مغرس الظرف وفرع الحسب … ومن به طال لسان الأدب\nإنا عهدناك أخا علة … بالإمس نالتك ببعض الوصب\nفكيف أصبحت ولا زلت في … عافي أذيالها تنسحب"},{"id":"diwan-abutammam:64","bookId":"diwan-abutammam","type":"poem","seq":64,"chapter":"البحر: طويل","title":"ألم يأن أن تروى الظماء الحوائم","page":"","text":"ألم يأن أن تروى الظماء الحوائم … وأن ينظم الشمل المشتت ناظم ؟ !\nلئن أرقأ الدمع الغيور وقد جرى … لقد رويت منه خدود نواعم\nلقد كان ينسى عهد ظمياء باللوى … ولكن أملته عليه الحمائم\nبعثن الهوى في قلب من ليس هائما … فقل في فؤاد رعنه وهو هائم\nلها نغم ليست دموعا فإن علت … مضت حيث لاتمضي الدموع السواجم\nأما وأبيها لو رأتني لأيقنت … بطول جوى ينفض منه الحيازم\nرأت قسمات قد تقسم نضرها … سرى الليل والإسآد فهي سواهم\nوتلويح أجسام تصدع تحتها … قلوب رياح الشوق فيها سمائم\nينال الفتى من عيشه وهو جاهل … ويكدي الفتى في دهره وهو عالم\nولو كانت الأرزاق تجري على الحجا … هلكن إذن من جهلهن البهائم\nجزى الله كفا ملؤها من سعادة … سعت في هلاك المال والمال نائم\nفلم يجتمع شرق وغرب لقاصد … ولا المجد في كف امرئ والدراهم\nولم أر كالمعروف تدعى حقوقه … مغارم في الأقوام وهي مغانم\nولا كالعلى مالم ير الشعر بينها … فكالأرض غفلا ليس فيها معالم\nوما هو إلا القول يسري فتغتدي … له غرر في أوجه ومواسم\nيرى حكمة مافيه وهو فكاهة … ويقضي بما يقضي به ، وهو ظالم\nإلى أحمد المحمود رامت بنا السرى … نواعب في عرض الفلا ورواسم\nخوانف يظلمن الظليم إذا عدا … وسيج أبيه وهو للبرق شائم\nنجائب قد كانت نعائم مرة … من المر أو أماتهن نعائم\nإلى سالم الأخلاق من كل عائب … وليس له مال على الجود سالم\nجدير بأن لا يصبح المال عنده … جديرا بأن يبقى وفي الأرض غارم\nوليس ببان للعلى خلق امرئ … وإن جل إلا وهو للمال هادم\nله من إياد قمة المجد حيثما … سمت ولها منه البنا والدعائم\nأناس إذا راحوا إلى الروع لم ترح … مسالمة أسيافهم والجماجم\nبنو كل مشبوح الذراع إذ القنا … ثنت أذرع الأبطال ، وهي معاصم\nإذا سيفه أضحى على الهام حاكما … غدا العفو منه وهو في السيف حاكم\nأخذت بأعضاد العريب وقد خوت … عيون كليلات وذلت جماجم\nفأضحوا لو استطاعوا لفرط محبة … لقد علقت خوفا عليك التمائم\nولو علم الشيخان أد ويعرب … لسرت إذن تلك العظام الرمائم\nتلاقى بك الحيان في كل محفل … جليل وعاشت في ذراك العماعم\nفما بال وجه الشعر أغبر قاتما … وأنف العلى من عطلة الشعر راغم\nتداركه إن المكرمات أصابع … وإن حلى الأشعار فيها خواتم\nإذا أنت لم تحفظه لم يك بدعة … ولا عجبا أن ضيعته الأعاجم\nفقد هز عطفيه القريض توقعا … لعدلك مذ صارت إليك المظالم\nولولا خلال سنها الشعر ما درى … بغاة الندى من أين تؤتى المكارم"},{"id":"diwan-abutammam:65","bookId":"diwan-abutammam","type":"poem","seq":65,"chapter":"البحر: طويل","title":"أصب بحميا كأسها مقتل العذل","page":"","text":"أصب بحميا كأسها مقتل العذل … تكن عوضا إن عنفوك من النبل\nوكأس كمعسول الأماني شربتها … ولكنها اجلت وقد شربت عقلي\nإذا عوتبت بالماء كان اعتذارها … لهيبا كوقع النار في الحطب الجزل\nاذا هيت دبت في القتى خال جسمه … لما دب فيه قرية من قرى النمل\nاذا ذاقها وهي الحياة رأيته … يعبس تعبيس المقدم للقتل\nإذا اليد نالتها بوتر توقرت … على ضعفها ثم استقادت من الرجل\nوتصرع ساقيها بانصاف شربها … وصرعهم بالجور في صورة العدل\nسقى الرائح الغدي المهجر بلدة … سقتني أنفاس الصبابة والخيل\nسحاب اذا ألقت عل خلفه الصبا … يدا قالت الدنيا أتى قاتل المحل\nاذا ما ارتدى بالبرق لم يزل الندى … له تبعا أو يرتدي الروض بالبقل\nإذا انتشرت أعلامه حوله انطوت … بطون الثرى منه وشيكا على حمل\nترى الأرض تهتز ارتياحا لوقعه … كما ارتاحت البكر الهدي إلى البعل\nفجاد دمشقا كلها جود أهلها … بأنفسهم عند الكريهة والبذل\nسقاهم كما أسقاهم في لظى الوغى … ببيض صفيح الهند والسمر الذبل\nفلم يبق في أرض البقاعين بقعة … وجاد قرى الجولان بالمسبل الوبل\nبنفسي أرض الشام لا أيمن الحمى … ولا أيسرث الدهنا ولا أوسط الرمل\nولم أر مثلي مستهاما بمثلكم … ولا مثل قلبي فيه لا يغلي\nعدتني عنكم مكرها غربة النوى … لها طربة في أن تمر ولا تحلي\nاذا لحظت حبلا من الحي محصدا … رمته فلم تسلم بناقضة الفتل\nأتت بعد هجر من حبيب فحركت … صبابة ما أبقى الصدود من الوصل\nأخمسة أحوال مضت لمغيبه … وشهران بل يومان نكل من النكل !\nتوانى وشيك النجع عنه ووكلت … به عزمات أوقفته على رجل\nويمنعه من أن يبيت زماعه … على عجل ان القضاء على رسل\nقضى الدهر مني نحبه يوم فتله … هواي بارقال الغريرية الفتل\nلقد طلعت في وجه مصر بوجهه … بلا طالع سعد ولا طائر سهل\nوساوس آمال ومذهب همة … تخيل لي بين المطية والرحل\nوسورة علم لم تسدد فأصبحت … وما يتمارى أنها سورة الجهل\nنأيت فلا مالا حويت ولم أقم … فأمتع إذ فجعت بالمال والأهل\nبخلت على عرضي بما فيه صونه … رجاء اجتناء الجود من شجر البخل\nعصيت شبا عزمي لطاعة حيرة … دعتني إلى أن افتح القفل بالقفل\nوأبسط من وجهي الذي لو بذلته … إلى الأرض من نعلي لما نقبت نعلي\nعدات كريعان السراب إذا جرى … تنشر عن منع وتطوى على مطل\nلئام طغام أو كرام بزعمهم … سواسية ما أشبه الحول بالقبل !\nفلو شاء من لو شاء لم يثن أمره … لصيرت فضل المال عند ذوي الفضل\nولو أنني اعطيت بأسي نصيبه … إذن لأخذت الحزم من مأخذ سهل\nوكان ورائي من صريمة طييء … ومعن ووهب عن أمامي ما يسلي\nفلم يك ما جزعت نفسي من الأسى … ولم يك ما جرعت قومي من الثكل !"},{"id":"diwan-abutammam:66","bookId":"diwan-abutammam","type":"poem","seq":66,"chapter":"البحر: طويل","title":"أبا جعفر أضحى بك الظن ممرعا","page":"","text":"أبا جعفر أضحى بك الظن ممرعا … فمل برواعيه عن الأمل الجذب\nفو الله ما شيء سوى الحب وحده … بأعلى محلا من رجائك في قلبي"},{"id":"diwan-abutammam:67","bookId":"diwan-abutammam","type":"poem","seq":67,"chapter":"البحر: بسيط تام","title":"سلم على الربع من سلمى بذي سلم","page":"","text":"سلم على الربع من سلمى بذي سلم … عليه وسم من الأيام والقدم\nما دام عيش لبسناه بساكنه … لدنا ولو أن عيشا دام لم يدم\nيامنزلا أعنقت فيه الجنوب على … رسم محيل وشعب غير ملتئم\nهرمت بعدي والربع الذي أفلت … منه بدورك معذور على الهرم\nعهدي بمغناك حسان المعالم من … حسانة الورد والبردي والعنم\nبيضاء كان لها من غيرنا حرم … فلم تكن نستحل الصيد في الحرم\nكانت لنا صنما نحتو عليه ، ولم … نسجد كما سجد إلافشين للصنم\nزار الخيال لها لابل أزاركه … فكر إذا نام فكر الخلق لم ينم\nظبي تقنصته لما نصبت له … في آخر الليل أشراكا من الحلم\nثم اغتدى وبنا من ذكر سقم … باق ، وإن كان مشغولا عن السقم\nاليوم يسليك عن طيف ألم وعن … بلى الرسوم بلاء الأينق الرسم\nمن القلاص اللواتي في حقائبها … بضاعة غير مزجاة من الكلم\nإذا بلغن أبا كلثوم اتصلت … تلك المنى وأخذنا لحاج من أمم\nبنى به الله في بدو وفي حضر … لوائل سور عز غير منهدم\nرأته في المهد عتاب ، فقال لها … ذوو الفراسة : هذا صفوة الكرم\nخذوا هنيئا مرئيا يا بني جشم … منه أمانين من خوف ومن عدم\nفجاء والنسب الوضاح جاء به … كأنه بهمة فيهم من البهم\nطعان عمرو بن كلثوم ونائله … حذو السيور التي قدت من الأدم\nلو كان يملك عمرو مثله شبها … من صلبه لم يجد للموت من ألم\nبنانه خلج تجري وغيرته … ستر من الله ممدود على الحرم\nنال الجزيرة إمحال فقلت لهم … شيموا نداه إذا ما البرق لم يشم\nفما الربيع على أنس البلاد به … أشد خضرة عود منه في القحم\nولا أرى ديمة أمحى لمسغبة … منه على أن ذكرا طار للديم\nلغلب سؤدد طابت منابته … في منتهى قلل منها وفي قمم\nمجد رعى تلعات الدهر وهو فتى … حتى غدا الدهر يمشي مشية الهرم\nبناه جود وبأس صادق ومتى … تبن العلى بسوى هذين تنهدم\nوقف على آل سعد إن أيديهم … سم لمستكبر شهد لمؤتدم\nلاجارهم للرزايا في جوارهم … ولاعهودهم مذمومة الذمم\nأصفوا ملوك بني العباس كلهم … ذخيرة ذخروها عن بني الحكم\nمهلا بني مالك لاتجلبن إلى … حي الأراقم دؤلول ابنة الرقم\nفأي حقد أثرتم من مكامنه … وأي عوصاء جشمتم بني جشم\nلم يألكم مالك صفحا ومغفرة … لو كان ينفخ قين الحي في فحم\nلا بالمعاود ولغا في دمائكم … ولا إلى لحم خلق منكم قرم\nأخرجتموه بكره من شجيته … والنار قد تنتضى من ناضر السلم\nأوطأتموه على جمر العقوق ولو … لم يحرج الليث لم يبرح من الأجم\nقذعتم فمشيتم مشية أمما … كذاك يحسن مشي الخيل في اللجم\nإذ لا معول إلا كل معتدل … أصم يبرئ أقواما من الصمم\nمن الردينية اللاتي إذا عسلت … تشم بو صغار الأنف ذا الشمم\nإن أجرمت لم تنصل من جرائمها … وإن أساءت إلى الأقوام لم تلم\nكان الزمان بكم كلبا فادركم … بالسيف والدهر فيكم أشهر الحرم\nأمن عمى نزل الناس الربا فنجوا … وأنتم نصب سيل الفتنة العرم ؟ !\nأم ذاك من همم جاشت ، فكم ضعة … أدى إليها علو القوم في الهمم !\nتنبون عنه وتعطون القياد إذا … كلب عوى وسطكم من أكلب العجم ! !\nقد انثنى بالمنايا في أسنته … وقد أقام حياراكم على اللقم !\nجذلان من ظفر حران إن رجعت … مخضوبة منكم أظفاره بدم\nدين يكفكف منه كل بائقة … ورحمة رفرفت منه على الرحم !\nلولا مناشدة القربى لغادركم … حصائد المرهفين : السيف والقلم\nلأصبحت كالأثافي السفع أو جهكم … سودا من العار لا سودا من الحمم\nلا تجعلوا البغي ظهرا إنه جمل … من القطيعة يرعى وادي النقم\nنظرت في السير الأولى خلت فإذا … أيامه أكلت باكورة الأمم\nأفنى جديسا وطمسما كلها وسطا … بأنجم الدهر من عاد ومن إرم\nأردى كليبا وهماما وهاج به … يوم الذنائب والتحلاق للمم\nسقى شرحبيل من سم الذعاف على … أيديكم غير رعديد ولابرم\nبز التحية من لخم فلا ملك … متوج في عمامات ولا عمم\nياعثرة ما وقيتم شر مصرعها … وذلة الرأي تنسي ذلة القدم\nحين استوى الملك واهتزت مضاربه … في دولة الأسد لافي دولة الخدم\nأبناء دلفاء مهلا إن أمكم … دافت لكم علقم الأخلاق والشيم\nطائية لا أبوها كان مهتضما … ولامضى بعلها لحما على وضم\nلاتوقظوا الشر من قوم فقد غنيت … دياركم وهي تدعى موطن النعم\nهذا ابن خالكم يهدي نصيحته … من يتهم فهو فيكم غير متهم !"},{"id":"diwan-abutammam:68","bookId":"diwan-abutammam","type":"poem","seq":68,"chapter":"البحر: بسيط تام","title":"لن يبق للصيف لا رسم ولا طلل","page":"","text":"لن يبق للصيف لا رسم ولا طلل … ولا قشيب فيستكسى ولا سمل\nعدل من الدمع ان يبكي المصيف كما … يبكى الشباب ويبكى اللهو والغزل\nيمنى الزمان طوت معروفها وغدت … يسراه وهي لنا من بعدها بدل\nما للشتاء ولا للصيف من مثل … يرضى به السمع إلا الجود والبخل\nأما ترى الأرض غضبي والحصى قلق … والأفق بالحرجف النكباء يقتتل\nمن يزعم الصيف لم تذهب بشاشته … فغير ذلك أمسى يزعم الجبل\nغدا له مغفر في رأسه يقق … لا تهتك البيض فوديه ولا الأسل\nاذا خراسان عن صنبيرها كشرت … كانت قيادا لنا أنيابه العضل\nيمسي ويضحي م قيما في مبائته … وبأسه في كلى الأقوام مرتحل\nمن كان يجهل منه جد سورته … في لاقريتين وأمر الحق مكتهل\nفما الضلوع ولا الأحشاء جاهلة … ولا الكلى أنه المقدامة البطل\nهذا ولم يتزر للحرب ديدنه … وأي قرن تراه حين يشتمل\nإن يسر الله أمرا أثمرت معه … من حيث أورقت الحاجات والأمل\nفما صلائي ان كان الصلاء بها … جمر الغضا الجزل الا السير والابل\nالمرضياتك ما أرغمت آنفها … والهادياتك وهي الرشد والضلل\nتقرب الشقة القصوى أذا أخذت … سلاحها وهو الإرقال والرمل\nإذا تظلمت من أرض فصلت بها … كانت هي العز إلا انها ذلل !"},{"id":"diwan-abutammam:69","bookId":"diwan-abutammam","type":"poem","seq":69,"chapter":"البحر: طويل","title":"نسائلها أي المواطن حلت","page":"","text":"نسائلها أي المواطن حلت … وأي ديار أوطنتها وأيت\nوماذا عليها لو أشارت فودعت … إلينا بأطراف البنان وأومت\nوما كان إلا أن تولت بها النوى … فولى عزاء القلب لما تولت\nفأما عيون العاشقين فأسخنت … وأما عيون الشامتين فقرت\nولما دعاني البين وليت إذ دعا … ولما دعاها طاوعته ولبت\nفلم أر مثلي كان أوفى بذمة … ولا مثلها لم ترع عهدي وذمتي\nمشوق رمته أسهم البين فانثنى … صريعا لها لما رمته فأصمت\nولو أنها غير النوى فوقت له … بأسهمها لم تصم فيه واشوت\nكأن عليها الدمع ضربة لازب … إذا ما حمام الأيك في الأيك غنت\nلئن ظمئت أجفان عيني إلى البكا … لقد شربت عيني دما فتروت\nعليها سلام الله أني استقلت … وأنى استقرت دارها واطمأنت\nومجهولة الأعلام طامسة الصوى … إذا اعتسفتها العيس بالركب ضلت\nإذا ما تنادى الركب في فلواتها … أجابت نداء الركب فيها فاصدت\nتعسفتها والليل ملق جرانه … وجوزاؤه في الأفق حين استقلت\nبمفعمة الأنساع موجدة القرا … أمون السرى تنجو إذا العيس كلت\nطموح بأثناء الزمام كانما … تخال بها من عدوها طيف جنة\nإلى حيث يلفى الجود سهلا مناله … وخير امرى شدت إليه وحطت\nإلى خير من ساس الرعية عدله … ووطد أعلام الهدى فاستقرت\nحبيش حبيش بن المعافى الذي به … أمرت حبال الدين حتى استمرت\nولولا أبو الليث الهمام لأخلقت … من الدين أسباب الهدى وأرثت\nأقر عمود الدين في مستقره … وقد نهلت منه الليالي وعلت\nونادى المعالي فاستجابت نداءه … ولو غيره نادى المعالي لصمت\nونيطت بحقويه الأمور فأصبحت … بظل جناحيه الأمور استظلت\nوأحيا سبيل العدل بعد دثوره … وأنهج سبل الجود حين تعفت\nويلوي بأحداث الزمان انتقامه … إذا ما خطوب الدهر بالناس ألوت\nويجزيك بالحسنى إذا كنت محسنا … ويغتفر العظمى إذا النعل زلت\nيلم اختلال المعتفين بجوده … إذا ما ملمات الأمور ألمت\nهمام ، وري الزند ، مستحصد القوى … إذا ما الأمور المشكلات أظلت\nإذا ظلمات الرأي أسدل ثوبها … تطلع فيها فجره فتجلت\nبه انكشفت عنا الغيابة وانفرت … جلابيب جور عمنا فاضمحلت\nأغر ربيط الجأش ، ماض جنانه … إذا ما القلوب الماضيات ارجحنت\nنهوض بثقل العبء مضطلع به … وإن عظمت فيه الخطوب وجلت\nتطوع له الأيام خوفا ورهبة … إذا امتنعت من غيره وتأبت\nله ، كل يوم ، شمل مجد مؤلف … وشمل ندى بين العفاة مشتت\nأبا الليث ، لولا أنت لانصرم الندى … وأدركت الأحداث ما قد تمنت\nأخاف فؤاد الدهر بطشك فانطوت … على رعب أحشاؤه وأجنت\nحللت من العز المنيف محلة … أقامت بفوديها العلى فأبنت\nليهنىء تنوخا خير أسرة … إذا أحصيت أولى البيوت وعدت\nوأنك منها في اللباب الذي له … تطأطأت الأحياء صغرا وذلت\nبنى لتنوخ الله عزا مؤبدا … تزل عليه وطأة المتثبت\nإذا ماحلوم الناس حلمك وازنت … رجحت بأحلام الرجال وخفت\nإذا ما يد الأيام مدت بنانها … إليك بخطب لم تنلك وشلت\nوإن أزمات الدهر حلت بمعشر … أرقت دماء المحل فيها فطلت\nإذا ما امتطينا العيس نحوك لم نخف … عثارا ولم نخش اللتيا ولا التي"},{"id":"diwan-abutammam:70","bookId":"diwan-abutammam","type":"poem","seq":70,"chapter":"البحر: كامل تام","title":"أرض مصردة وأخرى تثجم","page":"","text":"أرض مصردة وأخرى تثجم … منها التي رزقت وأخرى تحرم\nفإذا تأملت البلاد رأيتها … تثري كما تثري الرجال وتعدم\nحظ تعاوره البقاع لوقته … واد به صفر وواد مفعم !\nلولاه لم تكن النبوة ترتقي … شرف الحجاز ولا الرسالة تتهم\nولذاك أعرقت الخلافة بعدما … عمرت عصورا وهي علق مشئم\nوبه رأينا كعبة الله التي … هي كوكب الدنيا تحل وتحرم\nتلك الجزيرة مذ تحمل مالك … أمست وباب الغيث عنها مبهم\nولعت قراها غبرة ولقد ترى … في ظله وكأنما هي أنجم\nغنيت زمانا جنة فكأنما … فتحت إليها منذ سار جهنم\nالجو أكلف والجناب لفقده … محل وذاك الشق شق مظلم\nأقوت فلم أذكر بها لما خلت … إلا مني لما تقضى الموسم\nولقد أراها وهي عرس كاعب … فاليوم أضحت وهي ثكلى أيم\nإذ في ديار ربيعة المطر الحيا … وعلى نصيبين الطريق الأعظم\nذل الحمى مذ أوطئت تلك الربا … والغاب مذ أخلاه ذاك الضيغم\nإن القباب المستقلة بينها … ملك يطيب به الزمان ويكرم\nلا تألف الفحشاء برديه ولا … يسري إليه مع الظلام المأثم\nمتبذل في القوم وهو مبجل … متواضع في الحي وهو معظم\nيعلو فيعلم أن ذلك حقه … ويذيل فيهم نفسه فيكرم\nمهلا بني عمرو بن غنم إنكم … هدف الأسنة والقنا يتحطم\nالمجد أعنق والديار فسيحة … والعز أقعس والعديد عرمرم\nما منكم إلا مردى بالحجا … أو مبشر بالأحوذية مؤدم\nعمرو بن كلثوم بن مالك بن عت … اب بن سعد سهمكم لا يسهم\nخلقت ربيعة مذ لدن خلقت يدا … جشم بن بكر كف ها والمعصم\nتغزو فتغلب تغلب مثل اسمها … وتسيح غنم في البلا فتغنم\nوستذكرون غدا صنائع مالك … إن جل خطب أو تدوفع مغرم\nفمن النقي من العيوب وقد غدا … عن داركم ومن العفيف المسلم\nما لي رأيت ترابكم يبسا له … مالي أرى أطوادكم تتهدم ؟\nما هذه القربى التي لا تصطفى … ما هذه الرحم التي لا ترحم ؟ !\nحسد القرابة للقرابة قرحة … أعيت عواندها وجرح أقدم\nتلكم قريش لم تكن آراؤها … تهفو ولا أحلامها تتقسم\nحتى إذا بعث النبي محمد … فيهم غدت شحناؤهم تتضرم\nعزبت عقولهم وما من معشر … إلا وهم منه ألب وأحزم !\nلما أقام الوحي بين ظهورهم … ورأوا رسول الله أحمد منهم\nومن الحزامة لو تكون حزامة … ألا يؤخر من به يتقدم\nإن تذهبوا عن مالك أو تجهلوا … نعماه فالرحم القريبة تعلم\nهي تلك مشكاة بكم لو تشتكي … مظلومة لو أنها تتظلم\nكانت لكم أخلاقه معسولة … فتركتموها وهي ملح علقم\nحتى إذا أجنت لكم داوتكم … من دائكم إن الثقاف يقوم\nفقسا لتزدجروا ومن يك حازما … فليقس أحيانا وحينا يرحم\nواخافكم كي تغمدوا أسيافكم … إن الدم المغتر يحرسه الدم\nولقد جهدتم أن تزيلوا عزه … فإذا أبان قد رسا ويلملم\nوطعنتم في مجده فثنتكم … زعف يفل بها السنان اللهذم\nأعزز عليه إذا ابتأستم بعده … وتذكرت بالأمس تلك الأنعم\nووجدتم قيظ الأذى ورميتم … بعيونكم أين الربيع المرهم\nوندمتم ولو استطاع على جوى … أحشائكم لوقاكم أن تندموا\nولو انها من هضبة تدنو له … لدنا لها أو كان عرق يحسم\nما ذغذغت تلك السروب وأصبحت … فرقين في قرنين تلك الأسهم\nولقد علمت لدن لجحتم أنه … ما بعد ذاك العرس إلا المأتم\nعلما طلبت رسومه فوجدتها … في الظن ، إن الألمعي منجم\nما زلت أعرف وبله من عارض … لما رأيتسماءه تتغيم\nيا مال قد علمت نزار كلها … ما كان مثلك في الأراقم أرقم\nطالت يدي لما رأيتك سالما … وانحت عن خدي ذاك العظلم\nوشممت ترب الرحبة العبق الثرى … وسقى صداي\nكم حل في أكنافها من معدم … أمسى به يأوي إليه المعدم\nوصنيعة لك قد كتمت جزيلها … فأبى تضوعها الذي لا يكتم\nمجد تلوح فضوله وفضيلة … لك سافر والحق لا يتلثم\nتتكلف الجلى ومن أضحى له … بيتاك في جشم فلا يتجشم\nوتشرف العليا وهل بك مذهب … عنها وأنت على المكارم قيم ؟ !\nأثنيت إذ كان الثناء حبالة … شركا يصاد به الكريم المنعم\nووفيت إن من الوفاء تجارة … وشكرت إن الشكر حرت مطعم"},{"id":"diwan-abutammam:71","bookId":"diwan-abutammam","type":"poem","seq":71,"chapter":"البحر: وافر تام","title":"لعلك ذاكر الطلل القديم","page":"","text":"لعلك ذاكر الطلل القديم … وموف بالعهود على الرسوم\nوواصف ناقة تذر المهارى … موكلة بوخد أو رسيم\nوقد أممت بيت الله نضوا … على عيرانة حرف سعوم\nأتيت القادسية وهي ترنو … الي بعين شيطان رجيم\nفما بلغت بنا عسفان حتى … رنت بلحاظ لقمان الحكيم\nوبدلها السى بالجهل حلما … وقد أديمها قد الأديم\nأذاب سنامها قطع الفيافي … ومزق جلدها نضج العصيم\nطواها طيها الموماة وخدا … الى أجبال مكة والحطيم\nرمت خطواتها ببني خطايا … مواشكة إلى رب كريم\nبكل بعيدة الأرجاء تيه … كأن أوارها وهج الجحيم\nأقول بها وقد أوحت بعين … إلي تشكي الدنف السقيم\nبكورك أشعر الثقلين طرا … وأوفى الناس في حسب صميم\nلمالك تشتكين وأنت تحتي … وتحت محمد بدر النجوم ؟\nمتى أظمتك هاجرة فشيمي … أنامله تروك بالنسيم\nوإنغشيتك ظلماء فجلي … بغرته دجى الليل البهيم\nفمرت مثلما يمشي شهيد … سويا إلى صراط مستقيم\nولولا الله يوم منى لأبدت … هواها كل ذات حشا هضيم\nرمين أخا اغتراب واكتئاب … بعيني جؤذر وبجيد ريم"},{"id":"diwan-abutammam:72","bookId":"diwan-abutammam","type":"poem","seq":72,"chapter":"البحر: طويل","title":"أقول لمرتاد الندى عند مالك","page":"","text":"أقول لمرتاد الندى عند مالك … تعوذ بجدوى مالك وصلاته\nفتى جعل المعروف من دون عرضه … سريعا إلى الممتاح قبل عداته\nولو قصرت أمواله عن سماحه … لقاسم من يرجوه شطر حياته\nوإن لم يجد في قسمة العمر حيلة … وجاز له الإعطاء من حسناته\nلجاد بها غير كفر بربه … وآساهم من صومه وصلاته"},{"id":"diwan-abutammam:73","bookId":"diwan-abutammam","type":"poem","seq":73,"chapter":"البحر: كامل تام","title":"ما للدموع تروم كل مرام","page":"","text":"ما للدموع تروم كل مرام … والجفن ثاكل هجعة ومنام !\nيا حفرة المعصوم تربك مودع … ماء الحياة وقاتل الإعدام\nإن الصفائح منك قد نضدت على … ملقى عظام لو علمت عظام !\nفتق المدامع أن لحدك حله … سكن الزمان وممسك الأيام\nومصرف الملك الجموح كأنه … قد زم مصعبه له بزمام\nهدمت صروف الموت أرفع حائط … ضربت دعائمه على الإسلام\nدخلت على ملك الملوك رواقه … وتشزنت لمقوم القوام\nمفتاح كل مدينة قد أبهمت … غلقا ومخلي كل دار مقام\nومعرف الخلفاء أن حظوظها … في حيز الإسراج والإلجام\nأخذ الخلافة عن أسنته التي … منعت حمى الآباء والأعمام\nفلسورة الأنفال في ميراثه … آثارها ولسورة الأنعام\nما دام هارون الخليفة فالهدى … في غبطة موصولة بداوم\nإنا رحلنا واثقين بواثق … بالله شمس ضحى وبدر تمام\nلله أي حياة انبعثت لنا … يوم الخميس وبعد أي حمام !\nأودى بخير إمام اضطربت به … شعب الرجال وقام خير إمام\nتلك الرزية لا رزية مثلها … والقسم ليس كسائر الأقسام\nأو ي فتقد ذو النون في الهيجا فقد … دفع الإله لنا عن الصمصام\nأو جب منا غارب غدوا فقد … رحنا بأتمك ذروة وسنام\nهل غير بؤسى ساعة ألبستها … بنداك ما لبست من الإنعام !\nنقض كرجع الطرف قد أبرمته … يا ابن الخلائف أيما إبرام\nما إن رأى الأقوام شمسا قبلها … أفلت فلم تعقبهم بظلام\nأكرم بيومهم الذي ملكتهم … في صدره وبعامهم من عام\nلو لم يكن بدعا لقد نصبوا له … سمة يبين بها من الأعوام\nلغدوا وذاك الحول حول عبادة … فيهم وذاك الشهر شهر صيام\nلما دعوتهم لأخذ عهودهم … طار السرور بمعرق وشآم\nفكان هذا قادم من غيبة … وكأن ذاك مبشر بغلام\nقسمت أمير المؤمنين قلوبهم … بين المحبة فيك والإعظام\nشرحت بدولتك الصدور وأصبحت … خشع العيون إليك وهي سوام\nما أحسب القمر المنير إذا بدا … بدرا بأضوأ منك في الأوهام\nهي بيعة الرضوان يشرع وسطها … باب السلامة فادخلوا بسلام\nوالمركب المنجي فمن يعدل به … يركب جموحا غير ذات لجام\nيتبع هواه ولا لقاح لرهطه … بسل وليست أرضه بحرام\nوعبادة الأهواء في تطويحها … بالدين فوق عبادة الأصنام\nإن الخلافة أصبحت حجراتها … ضربت على ضخم الهموم همام\nملك يرى الدنيا بأيسر لحظة … ويرى التقى رحما من الأرحام\nلا قدح في عود الإمامة بعدما … متت إليك بحرمة وذمام\nهيهات تلك قلادة الله التي … ماكان يتركها بغير نظام\nإرث النبي وجمرة الملك التي … لم تخل من لهب بكم وضرام\nمذخورة أحرزتها بحكومة … لله تعلو أرؤس الحكام\nلسنا مريدي حجة نشفي بها … من ريبة سقما من الأسقام\nوالصبر بالأرواح يعرف فضله … من غيره ابتغيت ولا أعلام\nفأقم مخالفنا بكل مقوم … واحسم مغاندنا بكل حسام\n … صبر الملوك وليس بالاجسام\nلا تدهنوا في حكمه ف … تردي غواربه وليس بطام\nيابن الكواكب من أئمة هاشم … والرجح الأحساب والأحلام\nأهدى إليك الشعر كل مفهه … خطل وسدد فيك كل عبام\nغرض المديح تقاربت آفاقه … ورمى فقرطس فيه غير الرامي"},{"id":"diwan-abutammam:74","bookId":"diwan-abutammam","type":"poem","seq":74,"chapter":"البحر: وافر تام","title":"صريع هوى تغاديه الهموم","page":"","text":"صريع هوى تغاديه الهموم … بنيسابور ليس له حميم\nغريب ليس يؤنسه قريب … ولا يأوي لغربته رحيم\nمقيم في الديار نوى شطون … يشافهه بها كمد مقيم\nيمد زمامه طمع مقيم … تدرع ثوبه رجل عديم\nرجاء ما يقابله رجاء … هو اليأس الذي عقباه شوم\nفلا عجب وإن كانت ركابي … بأرض طار طائرها المشوم\nفقد فارقت بالغربي دارا … بأرض الشام حف بها النعيم\nوكنت بها الممنع غير وغد … ولا نكد اذا حل العظيم\nفإن أك حللت بدار هون … صبوت بها فقد يصبو الحليم\nألومك لا ألوم سؤاك دهرا … قضى لي بالذي يقضي سدوم\nإذا أنا لم ألم عثرات دهر … أصبت بها الغداة فمن ألوم\nوفي الدنيا غنى لم أنب عنه … ولكن ليس في الدنيا كريم !"},{"id":"diwan-abutammam:75","bookId":"diwan-abutammam","type":"poem","seq":75,"chapter":"البحر: كامل تام","title":"قف بالطلول الدارسات علاثا","page":"","text":"قف بالطلول الدارسات علاثا … أمست حبال قطينهن رثاثا\nقسم الزمان ربوعها بين الصبا … وقبولها ودبورها أثلاثا\nفتأبدت من كل مخطفة الحشا … غيداء تكسى يارقا ورعاثا\nكالظبية الأدماء صافت فارتعت … زهر العرار الغض والجثجاثا\nحتى إذا ضرب الخريف رواقه … سافت برير أراكة وكباثا\nسيافة اللحظات يغدو طرفها … بالسحر في عقد في عقد النهى نفاثا\nزالت بعينيك الحمول كأنها … نخل مواقر من نخيل جواثا\nيوم الثلاثا لن أزال لبينهم … كدر الفؤاد لكل يوم ثلاثا\nإن الهموم الطارقاتك موهنا … منعت جفونك أن تذوق حثاثا\nورأيت ضيف لهم لا يرضى قرى … إلا مداخلة الفقار دلاثا\nشجعاء جرتها الذميل تلوكه … أصلا إذا راح المطي غراثا\nأجدا إذا ونت المهارى أرقلت … رقلا كتحريق الغضا حثحاثا\nطلبت فتى جشم بن بكر مالكا … ضرغامها وهزبرها الدلهاثا\nملك إذا استسقيت مزن بنانه … قتل الصدى وإذا استغيث أغاثا\nقد جربته تغلب ابنة وائل … لاخاترا غدرا ولا نكاثا\nمثل السبيكة ليس عن أعراضها … بالغيب لا ندسا ولا بحاثا\nضرح القذى عنها وشذب سيفه … عن عيصها الخراب والخباثا\nضاحي المحيا للهجير وللقنا … تحت العجاج تخاله محراثا\nهم مزقوا عنه سبائب حلمه … وإذا أبو الأشبال أحرج عاثا\nلولا القرابة جاسهم بوقائع … تنسي الكلاب وملهما وبعاثا\nبالخيل فوق متونهن فوارس … مثل الصقور إذا لقين بغاثا\nلكن قراكم صفحه من لم يزل … وأبوه فيكم رحمة وغياثا\nعف الإزار تنال جارة بيته … أرفاده وتجنب الأرفاثا\nعمرو بن كلثوم بن مالك الذي … ترك العلى لبني أبيه تراثا\nوزعوا الزمان وهم كهول جلة … وسطوا على أحداثه أحداثا\nألقى عليه نجاره فأتى به … يقظان لا ورعا ولاملتاثا\nتزكو مواعده إذا وعد امرىء … أنساك أحلام الكرى الأضغاثا\nوترى تسحبنا عليه كأنما … جئناه نطلب عنده ميراثا\nكم مسهل بك لو عدتك قلاصه … تبغي سواك لأوعثت إيعاثا\nخولته عيشا أغن وجاملا … دثرا ومالا صامتا وأثاثا\nيا مالك ابن المالكين أرى الذي … كنا نؤمل من إيابك راثا\nلولا اعتمادك كنت ذا مندوحة … عن برقعيد وأرض باعيناثا\nوالكامخية لم تكن لي منزلا … فمقابر اللذات من قبراثا\nلم آتها من أي وجه جئتها … إلا حسبت بيوتها أجداثا\nبلد الفلاحة لو أتاها جرول … أعني الحطيئة لاعتدى حراثا\nتصدا بها الأفهام بعد صقالها … وترد ذكران العقول إناثا\nأرض خلعت اللهو خلعي خاتمي … فيها وطلقت السرور ثلاثا"},{"id":"diwan-abutammam:76","bookId":"diwan-abutammam","type":"poem","seq":76,"chapter":"البحر: خفيف تام","title":"أنا في ذمة الكريم سليما","page":"","text":"أنا في ذمة الكريم سليما … ن السليم الهوى الرئيف المهام\nنطت همي منه بهمة قوم … ثقلت وطأتي على الأيام\nبحسام اللسان والرأي أمضى … حين ينضى من الجراز الحسام\nماجد أفرطت عنايته حت … تى توهمت أنها في المنام\nما تواجهت نحو أفق من الآ … فاق إلا وجدتها من أمامي\nكل يوم ترى نوال أبي نص … \nلم أزل في دمامه المعظم المك … رم حتى ظننته في ذمامي\nيا سليمان ترف الله أرضا … أنت فيها بمستهل الغمام\nولعمري لقد كفيت لك الدع … وة إذ كنت شاتيا بالشآم\nأنا ثاو بحمص في كل ضرب … من ضروب الإكثار والإفحام\nكل فدم أخاف حين أراه … مقبلا أن يشجني بالسلام\nرافعا كفه لبري فلا أح … سبه جاءني لغير اللطام\nفبحقي إلا خصصت أبا الطي … يب عني بطيب من سلامي\nوثنائي من قبل هذا ومن بع … د وشكري غض لعبد السلام"},{"id":"diwan-abutammam:77","bookId":"diwan-abutammam","type":"poem","seq":77,"chapter":"البحر: كامل تام","title":"يوم الفراق لقد خلقت عظيما","page":"","text":"يوم الفراق لقد خلقت عظيما … وتركت جسمي لا سقمت سقيما\nما للفراق تفرقت أعضاؤه … ما زال يعصف باللقاء قديما !\nما زلت بعدك يا أخي في حسرة … وتلدد حتى أراك سليما\nاقر السلام عليك مني كلما … جرت الرياح فانشقتك نسيما"},{"id":"diwan-abutammam:78","bookId":"diwan-abutammam","type":"poem","seq":78,"chapter":"البحر: مخلع البسيط","title":"صرف النوى ليس بالمكيث","page":"","text":"صرف النوى ليس بالمكيث … ينبث ما ليس بالنبيث\nهبت لأحبابنا رياح … غير سواه ولا ريوث\nبدور ليل التمام حسنا … عين حقوف ، ظباء ميث\nبين الخلاخيل والأساوي … ر والدماليج والرعوث\nمن كل رعبوبة تردى … بثوب فينانها الأثيث\nكالرشإ العوهج اطباه … روع إلى مغزل رغوث\nرعت جنابي عويرضات … من خزمات ومن شثوث\nولاحب مشكل النواحي … منخرق السهل والوعوث\nلم تزجر العيس في قراه … مذ عصر نوح وعصر شيث\nكأن صوت النعام فيه … إذا دعا صوت مستغيث\nقلصته بالقلاص تهوي … بالوخد من سيرها الحثيث\nمن كل صلب القرا معوج … وكل عيرانة دلوث\nذي ميعة مشيه الدفقى … وذات لوث بها ملوث\nيطلبن من عقد وعد موسى … غير سحيل ولانكيث\nبنان موسى إذا استهلت … للناس نابت عن الغيوث\nحيث الندى والسدى جميعا … وملجأ الخائف الكريث\nحيث لبون النوال تهمي … غير شطور ولا ثلوث\nوالمجد من تالد قديم … ثم ومن طارف حديث\nإن تستبثه تجد عراما … من مستباث لمستبيث\nوحية أفعوان لصب … يعيث في مهجة العيوث\nتغدو المنايا مسخرات … وقفا على سمه النفيث\nوصارم الشفرتين عضبا … غير ددان ولا أنيث\nليثا ولكنه حمام … صب انتقاما على الليوث\nأنكد بأري النوال ما لم … يحل من العشب والجثوث\nما الجود بالجود أو تراه … ليس بنزر ولا لبيث\nطال المدى فاعتراك عتب … من صادق الود مستريث\nخذها فما نالها بنقص … موت جرير ولا البعيث\nوكن كريما تجد كريما … في مدحه يا أبا المغيث"},{"id":"diwan-abutammam:79","bookId":"diwan-abutammam","type":"poem","seq":79,"chapter":"البحر: كامل تام","title":"أزعمت أن الربع ليس يتيم","page":"","text":"أزعمت أن الربع ليس يتيم … والدمع في دمن عفت لا يسجم !\nيا موسم اللذات غالتك النوى … بعدي فربعك للصبابة موسم !\nولقد أراك من الكواعب كاسيا … فاليوم أنت من الكواعب محرم\nلحظت بشاشتك الحوادث لحظة … مازلت أحلم أنها لا تسلم\nأين التي كانت إذا شاءت جرى … من مقلتي دمع يعصفره دم\nبيضاء تسري في الظلام فيكتسي … نورا وتسرب في الضياء فيظلم\nيستعذب المقدام فيها حتفه … فتراه وهو المستميت المعلم\nمقسومة في الحسن بل هي غاية … فالحسن فيها والجمال مقسم\nملطومة بالورد أطلق طرفها … في الخلق فهو مع المنون محكم\nمذلت ولم تكتم جفاءك تكتم … إن الذي يمق المذول لمعرم\nإن كان وصلك آض وهو محرم … منك الغداة فما السلو محرم\nعزم يفل الجيش وهو عرمرم … ويرد ظفر الشوق وهو مقلم\nوفتى إذا ظلم الزمان فما يرى … إلا إلى عزماته يتظلم !\nلولا ابن حسان المرجى لم يكن … بالرقة البيضاء لي متلوم\nشافهت أسباب الغنى بمحمد … حتى ظننت بأنها تتكلم\nقد تيمت منه القوافي بامرئ … مازال بالمعروف وهو متيم\nيحلو ويعذب إن زمان ناله … بغنى وتلتاث الخطوب فيكرم\nتلقاه إن طرق الزمان بمغرم … شرها إليه كأنما هو مغنم\nلا يحسب الإقلال عدما بل يرى … أن المقل من المروءة معدم\nمازال وهو إذا الرجال تواضحوا … عند المقدم حيث كان يقدم\nيحتل في سعد بن ضبة في ذرا … عادية قد كللتها الأنجم\nقوم يمج دما على أرماحهم … يوم الوغى المستبسل المستلئم\nيعلون حتى ما يشك عدوهم … أن المنايا الحمر حي منهم\nلو كان في الدنيا قبيل آخر … بإزائهم ماكان فيهم مصرم\nولأنت أوضح فيهم من غرة … شدخت وفاز بها الجواد الأدهم\nتجري على آثارهم في مسلك … ماإن له إلا المكارم معلم\nلم ينا عني مطلب ومحمد … عون عليه أو إليه سلم\nلم يذعر الأيام عنك كمرتد … بالعقل يفهم عن أخيه ويفهم\nممن إذا ما الشعر صافح سمعه … يوما رأيت ضميره يتبسم"},{"id":"diwan-abutammam:80","bookId":"diwan-abutammam","type":"poem","seq":80,"chapter":"البحر: كامل تام","title":"هذا كتاب فتى له همم","page":"","text":"هذا كتاب فتى له همم … ساقت إليك رجاءه هممه\nغل الزمان يدي عزيمته … وهوت به من حالق قدمه\nوتواكلته ذوو قرابته … وطواه عن أكفائه عدمه\nافضى إليك بسره قلم … لو كان يعقله بكى قلمه"},{"id":"diwan-abutammam:81","bookId":"diwan-abutammam","type":"poem","seq":81,"chapter":"البحر: بسيط تام","title":"أبا سعيد وما وصفي بمتهم","page":"","text":"أبا سعيد وما وصفي بمتهم … على الثناء ولا شكري بمخترم\nلئن جحدتك ما أوليت من حسن … إن لفي اللؤم أولى منك في الكرم\nأنسى ابتسامك والألوان كاسفة … تبسم الصبح في داج من الظلم\nكذا أخوك الندى لو أنه بشر … لم يلف طرفة عين غير مبتسم\nرددت رونق وجهي في صحيفته … رد الصقال بماء الصارم الخذم\nوما أبالي وخير القول أصدقه … حقنت لي ماء وجهي أو حقنت دمي"},{"id":"diwan-abutammam:82","bookId":"diwan-abutammam","type":"poem","seq":82,"chapter":"البحر: بسيط تام","title":"قل للأمير لقد قلدتني نعما","page":"","text":"قل للأمير لقد قلدتني نعما … فت الثناء بها ماهبت الريح\nيا مانحي الجاه إذ ضن الجواد به … شكريك ما عشت للأسماع ممنوح\nلم يلبس الله نوحا فضل نعمته … إلا لما بثه من شكره نوح\nذمت سماحته الدنيا إليه ، فما … يمسي ويصبح إلا وهو ممدوح\nوللأمور إذا الآراء ضقن بها … يوم التجادل من آرائه فيح\nلم يغلق الله باب العرف عن أحد … باب الأمير له المألوف مفتوح\nلن يعدم المجد من كانت أوائله … من آل كسرى البهاليل المراجيح\nموري الفؤاد ، فلو كانت بعزمته … تذكى المصابيح لم تخب المصابيح\nكأنه لاجتماع الروح فيه له … من كل جارحة في جسمه روح"},{"id":"diwan-abutammam:83","bookId":"diwan-abutammam","type":"poem","seq":83,"chapter":"البحر: طويل","title":"متى كان سمعي خلسة للوائم","page":"","text":"متى كان سمعي خلسة للوائم … وكيف صغت للعاذلات عزائمي ؟ !\nإذا المرء أبقى بين رأييه ثلمة … تسد بتعنيف فليس بحازم\nسأوطئ أهل العسكر الآن عسكرا … من الذل محاء لتلك المعالم\nفإني ما حوزفت في طلب العلى … ولكنكم حورفتم في المكارم\nرويدا يقر الأمر في مستقره … فما المجد عما تفعلون بنائم\nومالي من ذنب إلى الرزق خلته … سوى أملي إياكم للعظائم\nبعين العلى أصبحتم بين هادم … دعائمها الطولى وبان كهادم\nلعمر النوى لا زلت بعد محمد … مسحا عليه بالدموع السواجم\nفتى فيصلي العزم يعلم أنه … نشا رأيه بين السيوف الصوارم\nإذا سار فيه الظن كان بكل ما … يؤمل من جدواه أول قادم\nأسأءت يداه عشرة المال بالندى … وأحسنتا فينا خلافة حاتم"},{"id":"diwan-abutammam:84","bookId":"diwan-abutammam","type":"poem","seq":84,"chapter":"البحر: خفيف تام","title":"إن عهدا لو تعلمان ذميما","page":"","text":"إن عهدا لو تعلمان ذميما … أن تناما عن ليلتي أو تنيما\nكنت أرعى البدور حتى إذا ما … فارقوني أمسيت أرعى النجوما\nقد مررنا بالدار وهي خلاء … وبكينا طلولها والرسوما\nوسألنا ربوعها فانصرفنا … بسقام وما سألنا حكيما\nأصبحت روضة الشباب هشيما … وغدت ريحه البليل سموما\nشعلة في المفارق استودعتني … في صميم الفؤاد ثكلا صميما\nتستثير الهموم ما اكتن منها … صعدا وهي تستثير الهموما\nغرة بهمة ألا إنما كن … ت أغرا أيام كنت بهيما\nدقة في الحياة تدعى جلالا … مثلما سمي اللديغ سليما\nحلمتني زعمتم وأراني … قبل هذا التحليم كنت حليما\nمن رأى بارقا سرى صامتيا … جاد نجدا سهولها والحزوما ؟\nيوسفيا محمديا حفيا … بذليل الثرى رؤوفا رحيما\nفسقى طيئا وكلبا ودودا … ن وقيسا ووائلا وتميما\nلن ينال العلى خصوصا من الفت … يان من لم يكن نداه عموما\nنشأت من يمينه نفخات … ماعليها ألا تكون عيوما\nألبست نجدا الصنائع لا شي … حا ولا جنبة ولا قيصوما\nكرمت راحتاه في أزمات … كان صوب الغمام فيها لئيما\nلا رزيناه ما ألذ إذا هز … وأندى كفا وأكرم خيما !\nوجه العيس وهي عيس إلى الله … فآلت مثل القسي حطيما\nوأحق الأقوام أن يقضي الدي … ن امرؤ كان للإله غريما\nفي طريق قد كان قبل شراكا … ثم لما علاه صار أديما\nلم يحدث نفسا بمكة حتى … جازت الكهف خيله والرقيما\nحرم الدين زاره بعد أن لم … يبق للكفر والضلال حريما\nحين عفى مقام إبليس سامى … بالمطايا مقام إبراهيما\nحطم الشرك حطمة ذكرته … في دجى الليل زمزما والحطيما\nفاض فيض الآتي حتى غدا المو … سم من فضل سيبه موسوما\nقد بلونا أبا سعيد حديثا … وبلونا أبا سعيد قديما\nووردناه ساحلا وقليبا … ورعيناه بارضا وجميما\nفعلمنا أن ليس إلا بشق الن … فس صار الكريم يدعى كريما\nطلب المجد يورث المرء خبلا … وهموما تقضقض الحيزوما\nفتراه وهو الخلي شجيا … وتراه وهو الصحيح سقيما\nتجد المجد في البرية منثو … را وتلقاه عنده منظوما\nتيمته العلى فليس يعد ال … بؤس بؤسا ولا النعيم نعيما\nوتؤام الندى يري الكرم الفا … رد في أكثر المواطن لوما\nكلما زرته وجدت لديه … نسبا ظاعنا ومجدا مقيما\nأجدر الناس أن يرى وهو مغبو … ن وهيهات أن يرى مظلوما\nكل حال تلقاه فيها ولكن … ليس يلقى في حالة مذموما\nوإذا كان عارض الموت سحا … خضلا بالردى أجش هزيما\nفي ضرام من الوغى واشتعال … تحسب الجو منهما مهموما\nواكتست ضمر الجياد المذاكي … من لباس الهيجا دما وحميما\nفي مكر تلوكها الحرب فيه … وهي مقورة تلوك الشكيما\nقمت فيها بحجة الله لما … أن جعلت السيوف عنك خصوما\nفتح الله في اللواء لك الخا … فق يوم الاثنين فتحا عظيما\nحومته ريح الجنوب ولن يح … مد صيد الشاهين حتى يحوما\nفي غداة مهضوبة كان فيها … ناضر الروض للسحاب نديما\nلينت مزنها فكانت رهاما … وسجت ريحها فكانت نسيما\nنعمة الله فيك لا أسأل الل … ه إليها نعمى سوى أن تدوما\nولو أني فعلت كنت كمن يس … أله وهو قائم أن يقوما"},{"id":"diwan-abutammam:85","bookId":"diwan-abutammam","type":"poem","seq":85,"chapter":"البحر: بسيط تام","title":"أهد الدموع إلى دار وما صحها","page":"","text":"أهد الدموع إلى دار وما صحها … فللمنازل سهم في سوافحها\nأشلى الزمان عليها كل حادثة … وفرقة تظلم الدنيا لنازحها\nحلفت حقا ، لقد قلت ملاحتها … بمن تخرم عنها من ملائحها\nإن تبرحا وتباريحي على كبد … ما تستقر ، فدمعي غير بارحها\nدار أجل الهوى عن أن ألم بها … في الركب إلا وعيني من منائحها\nإذا وصفت لنفسي هجرها جمحت … ودائع الشوق في أقصى جوانحها\nوإن خطبت إليها صبرها جعلت … جراحة الوجد تدمى في جوارحها\nما للفيافي وتلك العيس قد خزمت … فلم تظلم إليها من صحاصحها ؟\nفتل إذا ابتكر الغادي على أمل … خلفنه يزجر الحسرى برائحها\nتصغي إلى الحدو إصغاء القيان إلى … نغم إذا استغربته من مطارحها\nحتى تؤوب كأن الطلح معترض … بشوكه في المآقي من طلائحها\nإلى الأكارم أفعالا ومنتسبا … لم يرتع الذم ، يوما ، في طوائحها\nآساس مكة والدنيا بعذرتها … لم ينزل الشيب في مثنى مسائحها\nقوم هم أمنوا قبل الحمام بها … من بين ساجعها الباكي ونائحها\nكانوا الجبال لها قبل الجبال وهم … سالوا ولم يك سيل في أباطحها\nوالفضل إن شمل الإظلام ساحتها … مصباحها المتجلي من مصابحها\nمن خيرها مغرسا فيها ووسعها … شعبا تحط إليه عير مادحها\nلا تفت تزجي فتي العيس ساهمة … إلى فتى سنها منها وقارحها\nحتى تناول تلك القوس باريها … حقا وتلقي زنادا عند قادحها\nكأن صاعقة في جوف بارقة … زئيره واغلا في أذن نابحها\nسنان موت ذعاف من أسنتها … صفيح تتحامى من صفائحها\nذر تدرإ وإباء في الأمور وهل … جواهر الطير إلا في جوارحها !\nهشما لأنف المسامي حينه فسما … لهاشم ، فضلها فيها ابن صالحها\nياحاسد الفضل لا أعرفك محتشدا … لغمرة أنت عندي غير سابحها\nلكوكب نازح من كف لامسه … وصخرة وسمها في قرن ناطحها\nولاتقل إننا من نبعة فلقد … بانت نجائب إبل من نواضحها\nسميدع يتغطى من صنائعه … كما تغطى رجال من فضائحها\nوفارة المسك لا يخفي تضوعها … طول الحجاب ولا يزري بفائحها\nلله درك في الخود التي طمحت … ما كان أرقاك يا هذا لطامحها\nنقية الجيب لا ليل بمدخلها … في باب عيب ولاصبح بفاضحها\nأخذتها لبوة العريس ملبدة … في الغاب والنجم أدنى من مناكحها\nلو أن غير أبي الأشبال صافحها … شكت بمخلبها كفي مصافحها\nجاءت بصقرين غطريفين لو وزنا … بهضب رضوى إذا مالا براجحها\nبهاشميين بدريين إن لحجت … مغالق الدهر كانا من مفاتحها\nنصلان قد أثبتا في قلب شائنها … نارين أوقدتا في كشح كاشحها\nوكذب الله أقولا قرنت بها … بحجة تسرج الدنيا بواضحها\nمضيئة نطقت فينا كما نطقت … ذبيحة المصطفى موسى لذابحها\nلئن قلبيك جاشت بالسماحة لي … لقد وصلت بشكري حبل ماتحها\nوقد رأتني قريش ساحبا رسني … إليك عن طلقها وجها وكالحها\nإذا القصائد كانت من مدائحهم … فأنت لاشك عندي من مدائحها\nوإن غرائبها أجدبن من بلد … كانت عطاياك أندى من مسارحها"},{"id":"diwan-abutammam:86","bookId":"diwan-abutammam","type":"poem","seq":86,"chapter":"البحر: طويل","title":"عسى وطن يدنو بهم ولعلما","page":"","text":"عسى وطن يدنو بهم ولعلما … وأن تعتب الأيام فيهم فربما\nلهم منزل قد كان بالبيض كالمها … فصيح المغاني ثم أصبح أعجما\nورد عيون الناظرين مهانة … وقد كان مما يرجع الطرف مكرما\nتبدل غاشيه بريم مسلم … تردى رداء الحسن طيفا مسلما\nومن وشي خد لم ينمنم فرنده … معالم يذكرن الكتاب المنمنا\nوبالحلي إن قامت ترنم فوقها … حماما إذا لاقى حماما ترنما\nوبالخدلة الساق المخدمة الشوى … قلائص يتبعن العبنى المخدما\nسوار إذا قاتلن ممتنع الفلا … جعلن الشعارين الجديل وشدقما\nإلى حائط الثغر الذي يورد القنا … من الثغرة الريا القليب المهدما\nبسابغ معروف الأمير محمد … حدا هجمات المال من كان مصرما\nوحط الندى في الصامتين رحله … وكان زمانا في عدي بن أخزما\nيرى العلقم المأدوم بالعز أرية … يمانية والأري بالضيم علقما\nإذا فرشوه النصف ماتت شذاته … وإن رتعوا في ظلمه كان أظلما\nلقد أصبح الثغران في الدين بعدما … رأوا سرعان الذل فذا وتوءما\nوكنت لناشيهم أبا ولكهلهم … أخا ولذي التقويس والكبرة آبنما\nومن كان بالبيض الكواعب مغرما … فما زلت بالبيض القواضب مغرما\nومن تيمت سمر الحسان وأدمها … فما زلت بالسمر العوالي متيما\nجدعت لهم أنف الضلال بوقعة … تخرمت في غمائها من تخرما\nلئن كان أمسى في عقرقس أجدعا … لمن قبل ما أمسى بميمذ أخرما\nثلمتهم بالمشرفي وقلما … تثلم عز القوم إلا تهدما\nقطعت بنان الكفر منهم بميمذ … وأتبعتها بالروم كفا ومعصما\nوكم جبل بالبذ منهم هددته … وغاو غوى حلمته لو تحلما !\nومقتبل حلت سيوفك رأسه … ثغاما ولولا وقعها كان عظلما\nفلما أبت أحكامه الشيبة اغتدى … قناك لما قد ضيع الشيب محكما\nإذا كنت للألوى الأصم مقوما … فأورد وريديه الأصم المقوما\nولما التقى البشران أنقع بشرنا … لبشرهم حوضا من الصبر مفعما\nوساعده تحت البيات فوارس … تخالهم في فحمة الليل أنجما\nوقد نثرتهم روعة ثم أحدقوا … به مثلما ألفت عقدا منظما\nبسافر حر الوجه لو رام سوءة … لكان بجلبات الدجى متلثما\nمثلت له تحت الظلام بصورة … على البعد أقنته الحياء فصمما\nكيوسف لما أن رأى أمر ربه … وقد هم أن يعروري الذنب أحجما\nوقد قال إما أن أغادر بعدها … عظيما وإما أن أغادر أعظما\nونعم الصريخ المستجاش محمد … إذا حن نوء للمنايا وأرزما\nأشاح بفتيان الصباح فأكرهوا … صدور القنا الخطي حتى تحطما\nهو افترع الفتح الذي سار معرقا … وأنجد في علو البلاد وأتهما\nله وقعة كانت سدى فأنرتها … بأخرى وخير النصر ما كان ملحما\nهما طرفا الدهر الذي كان عهدنا … باوله غفلا فقد صار معلما\nلقد أذكرانا بأس عمرو ومسهر … وما كان من إسفندياذ ورستما\nرأى الروم صبحا أنها هي إذ رأوا … غداة التقى الزحفان انهما هما\nهزبرا غريف شد من أبهريهما … ومتنيهما قرب المزعفر منهما\nفأعطيت يوما لو تمنيت مثله … لأعجز ريعان المنى والتوهما\nلحقتهما في ساعة لو تأخرت … لقد زجر الإسلام طائر أشأما\nفلو صح قول الجعفرية في الذي … تنص من الإلهام خلناك ملهما\nفإن يك نصرانيا النهر آلس … فقد وجدوا وادي عقرقس مسلما\nبه سبتوا في السبت بالبيض والقنا … سباتا ثووا منه إلى الحشر نوما\nفلو لم يقصر بالعروبة لم يزل … لنا عمر الأيام عيدا وموسما\nوما ذكر الدهر العبوس بأنه … له ابن كيوم السبت إلا تبسما\nولم يبق في أرض البقلار طائر … ولا سبع إلا وقد بات مولما\nولا رفعوا في ذلك اليوم إثلبا … ولا حجرا إلا رأوا تحته دما\nرموا بابن حرب سل فيهم سيوفه … فكانت لنا عرسا وللشرك مأتما\nأفظ بني حواء قلبا عليهم … ولم يقس منه القلب إلا ليرحما\nإذا أجرموا قنا القنا من دمائهم … وإن لم يجد جرما عليهم تجرما\nهو الليث ليث الغاب بأسا ونجدة … وإن كان أحيا منه وجها وأكرما\nأشد ازدلافا بين درعين مقبلا … وأحسن وجها بين بردين محرما\nجدير إذا ما الخطب طال فلم تنل … ذؤابته أن يجعل السيف سلما\nكريم إذا زرناه لم يقتصر بنا … على الكرم المولود أو يتكرما\nتجشم حمل الفادحات وقلما … أقيمت صدور المجد إلا تجشما\nوكنت أخا الإعدام لسنا لعلة … فكم بك بعد العدم أغنيت معدما\nوإذ أنا ممنون علي ومنعم … فأصبحت من خضراء نعماك منعما\nومن خدم الأقوام يرجوا نوالهم … فإني لم أخدمك إلا لأخدما !"},{"id":"diwan-abutammam:87","bookId":"diwan-abutammam","type":"poem","seq":87,"chapter":"البحر: طويل","title":"سقى الله من اهوى على بعد نائه","page":"","text":"سقى الله من اهوى على بعد نائه … وإعراضه عني وطول جفائه\nأبى الله الا أن كلفت بحبه … فأصبحت فيه راضيا بقضائه\nوأفردت عيني بالدموع فأصبحت … وقد غص منها كل جفن بمائه\nفإن مت من وجد به وصبابة … فكم من محب مات قبلي بدائه"},{"id":"diwan-abutammam:88","bookId":"diwan-abutammam","type":"poem","seq":88,"chapter":"البحر: خفيف تام","title":"سعدت غربة النوى بسعاد","page":"","text":"سعدت غربة النوى بسعاد … فهي طوع الإتهام والإنجاد\nفارقتنا وللمدامع أنوا … ء سوار على الخدود غواد\nكل يوم يسفحن دمعا طريفا … يمترى مزنه بشوق تلاد\nواقعا بالخدود والحر منه … واقع بالقلوب والأكباد\nوعلى العيس خرد يتبسم … ن عن الأشنب الشتيت البراد\nكان شوك السيال حسنا فأمسى … دونه للفراق شوك القتاد\nشاب رأسي ، وما رأيت مشيب الرأ … س إلا من فضل شيب الفؤاد\nوكذاك القلوب في كل بؤس … ونعيم طلائع الأجساد\nطال إنكاري البياض وإن عمر … ت حينا ، أنكرت لون السواد\nنال رأسي من ثغرة الهم مالم … يستنله من ثغرة الميلاد\nزارني شخصه بطلعة ضيم … عمرت مجلسي من العواد\nيا أبا عبد الله أوريت زندا … في يدي كان دائم الإصلاد\nأنت جبت الظلام عن سبل الآ … ل إذ ضل كل هاد وحاد\nفكأن المغذ فيها مقيم … وكأن الساري عليهن غاد\nوضياء الآمال أفسح في الطر … ف وفي القلب من ضياء البلاد\nكان في الأجفلى وفي النقرى عر … فك نضر العموم نضر الوحاد\nومن الحظ في العلى خضرة المعرو … ف في الجمع منه والإفراد\nكنت عن غرسه بعيدا فأدنت … ني إليه يداك عند الجداد\nساعة لو تشاء بالنصف فيها … لمنعت البطاء خصل الجياد\nلزموا مركز الندى وذراه … وعدتنا عن مثل ذاك العوادي\nغير أن الرب إلى سبل الأنوا … ء أدنى والحظ حظ الوهاد\nبعدما أصلت الوشاة سيوفا … قطعت في وهي غير حداد\nمن أحاديث حين دوختها بالرأ … ي كانت ضعيفة الإسناد\nفنفى عنك زخرف القول سمع … لم يكن فرصة لغير السداد\nضرب الحلم والوقار عليه … دون عور الكلام بالأسداد\nوحوان أبت عليها المعالي … أن تسمى مطية الأحقاد\nولعمري أن لو أضحت لأقدم … ت لحتفي ضغينة الحساد\nحمل العبء كاهل لك أمسى … لخطوب الزمان بالمرصاد\nعاتق معتق من الهون إلا … من مقاساة مغرم أو نجاد\nللحمالات والحمائل فيه … كلحوب الموارد الأعداد\nملئتك الأحساب أي حياء … وحيا أزمة وحية واد !\nلو تراخت يداك عنها فواقا … أكلتها الأيام أكل الجراد\nأنت ناضلت دونها بعطايا … رائحات على العفاة غوادي\nفإذا هلهل النوال أتتنا … ذات نيرين مطبقات الأيادي\nكل شيء غث إذا عاد وال … معروف غث ما كان غير معاد\nكادت المكرمات تنهد لولا … أنها أيدت بخير إياد\nعندهم فرج اللهيف وتص … ديق ظنون الزوار والرواد\nبأحاظي الجدود لا بل بوشك … الجد لا بل بسؤدد الأجداد\nوكأن الأعناق يوم الوغى أو … لى بأسيافهم من الأغماد\nفإذا ضلت السيوف غداة الرو … ع كانت هواديا للهوادي\nقد بثثتم غرس المودة والشح … ناء في قلب كل قار وباد\nأبغضوا عزكم وودوا نداكم … فقروكم من بغضة ووداد\nلاعدمتم غريب مجد ربقتم … في عراه نوافر الأضداد"},{"id":"diwan-abutammam:89","bookId":"diwan-abutammam","type":"poem","seq":89,"chapter":"البحر: كامل تام","title":"قل للأمير أبي سعيد ذي الندى","page":"","text":"قل للأمير أبي سعيد ذي الندى … والمجد زاد الله في إكرامه\nيا واهب العيس الهموس برحلها … والأعوجي بسرجه ولجامه\nوالحامل الأقوام فوق سلاهب … والحاكي الرئبال في إقدامه\nوالواهب الصمصامة السيف الذي … يجري زعاف الموت في إسطامه\nأنت المباري الريح في نفخاتها … والمستهين مع الندى بملامه\nفمن أين أرهب أن يراني راجلا … أحد وما أرجو سوى أيامه\nأحمل هداك الله رجلي يا بن من … جادت يداه بنهده وغلامه\nقسم الحياء على الأنام جميعهم … فذهبت أنت فقدته بزمامه\nوتقسم الناس السخاء مجزأ … وذهبت أنت برأسه وسنامه\nوتركت للناس الإهاب ومابقى … من فرثه وعروقه وعظامه"},{"id":"diwan-abutammam:90","bookId":"diwan-abutammam","type":"poem","seq":90,"chapter":"البحر: كامل تام","title":"أفنيت فيك معاني الشكوى","page":"","text":"أفنيت فيك معاني الشكوى … وصفات ما ألقى من البلوى\nقلبت آفاقض الكلام فما … أبصرتني أغفلت عن معنى\nوأعد ما لا أشتكي غبنا ، … فأعود فيه مرة أخرى\nفلو أن ما أشكو إلى بشر … لأراحني من ذلة الشكوى\nلكنما أشكو إلى حجر … تنبو المعاول عنه أو أقسى\nظبي بمبكاه ومضحكه … فينا تنير وتظلم الدنيا"},{"id":"diwan-abutammam:91","bookId":"diwan-abutammam","type":"poem","seq":91,"chapter":"البحر: وافر تام","title":"سقى عهد الحمى سبل العهاد","page":"","text":"سقى عهد الحمى سبل العهاد … وروض حاضر منه وباد\nنزحت به ركي العين لما … رأيت الدمع من خير العتاد\nفيا حسن الرسوم وما تمشى … إليها الدهر في صور البعاد\nوإذ طير الحوادث في رباها … سواكن ، وهي غناء المراد\nمذاكي حلبة وشروب دجن … وسامر فتية وقدور صاد\nوأعين ربرب كحلت بسحر … وأجساد تضمخ بالجساد\nبزهر والحذاق وآل برد … ورت في كل صالحة زنادي\nوإن يك من بني أدد جناحي … فإن أثيث ريشي من إياد\nغدوت بهم أمد ذوي ظلا … وأكثر من ورائي ماء واد\nهم عظمى الأثافي من نزار … وأهل الهضب منها والنجاد\nمعرس كل معضلة وخطب … ومنبت كل مكرمة وآد\nإذا حدث القبائل ساجلوهم … فإنهم بنو الدهر التلاد\nتفرج عنهم الغمرات بيض … جلاد تحت قسطلة الجلاد\nوحشو حوادث الأيام منهم … معاقل مطرد وبنو طراد\nلهم جهل السباع إذا المنايا … تمشت في القنا وحلوم عاد\nلقد أنست مساوىء كل دهر … محاسن أحمد بن أبي دواد\nمتى تحلل به تحلل جنابا … رضيعا للسواري والغوادي\nترشح نعمة الأيام فيه … وتقسم فيه أرزاق العباد\nوما اشتبهت طريق المجد إلا … هداك لقبلة المعروف هاد\nوما سافرت في الآفاق إلا … ومن جدواك راحلتي وزادي\nمقيم الظن عندك والأماني … وإن قلقت ركابي في البلاد\nمعاد البعث معروف ولكن … ندى كفيك في الدنيا معادي\nأتاني عائر الأنباء تسري … عقاربه بداهية نآد\n … يجر به على شوك القتاد\nكأن الشمس جللها كسوف … أو استترت برجل من جراد\nبأني نلت من مضر وخبت … إليك شكيتي خبب الجواد\nوما ربع القطيعة لي بربع … ولانادي الأذى مني بناد\nوأين يجور عن قصد لساني … وقلبي رائح برضاك غاد !\nومما كانت الحكماء قالت … لسان المرء من خدم الفؤاد\nفقدما كنت معسول الأماني … ومأدوم القوافي بالسداد\nلقد جازيت بالإحسان سوءا … إذا وصبغت عرفك بالسواد\nوسرت أسوق عير اللؤم حتى … أنخت الكفر في دار الجهاد\nفكيف وعتب يوم منك فذ … أشد علي من حرب الفساد !\nوليست رغوتي من فوق مذق … ولا جمري كمين في الرماد\nوكان الشكر للكرماء خصلا … وميدانا كميدان الجياد\nعليه عقدت عقدي ولاحت … مواسمه على شيمي وعادي\nوغيري يأكل المعروف سحتا … وتشجب عنده بيض الأيادي\nتثبت إن قولا كان زورا … أتى النعمام قبلك عن زياد\nوأرث بين حي بني جلاح … سنا حرب وحي بني مصاد\nوغادر في صروف الدهر قتلى … بني بدر على ذات الإصاد\nفما قدحاك للباري وليست … متون صفاك من نهر المرادي\nولو كشفتني لبلوت خرقا … يصافي الأكرمين ولا يصادي\n … إلى بعض الموارد وهو صادي\nإليك بعثت ابكار المعاني … يليها سائق عجل وحادي\nجوائر عن ذنابى القوم حيرى … هوادي للجماجم والهوادي\nيذللها بذكرك قرن فكر ، … إذا حرنت ، فتسلس في القياد\nلها في الهاجس القدح المعلى … وفي نظم القوافي والعماد\nمنزهة عن السرق المورى … مكرمة عن المعنى المعاد\nتنصل ربها من غير جرم … إليك سوى النصيحة والوداد\nومن يأذن إلى الواشين تسلق … "},{"id":"diwan-abutammam:92","bookId":"diwan-abutammam","type":"poem","seq":92,"chapter":"البحر: بسيط تام","title":"أبا سعيد تلاقت عندك النعم","page":"","text":"أبا سعيد تلاقت عندك النعم … فانت طود لنا منج ومعتصم\nلا زال جودك يخشى البخل صولته … وزال عودك تسقي روضه الديم\nأشرفت منك على بحر الغنى ويدي … يجول في مستواها الفقر والعدم\nفسوف يثبت ركن المدح فيك أخ … لولا رجاؤك لم يثبت له قدم\nأحرمت دونك خوف النائبات فما … شككت إذ قمت دوني أنك الحرم"},{"id":"diwan-abutammam:93","bookId":"diwan-abutammam","type":"poem","seq":93,"chapter":"البحر: وافر تام","title":"أيسلبني ثراء المال ربي","page":"","text":"أيسلبني ثراء المال ربي … وأطلب ذاك من كف جماد ؟\nزعمت إذا بأن الجود أمسى … له رب سوى ابن أبي داود !"},{"id":"diwan-abutammam:94","bookId":"diwan-abutammam","type":"poem","seq":94,"chapter":"البحر: كامل تام","title":"نثرت فريد مدامع لم ينظم","page":"","text":"نثرت فريد مدامع لم ينظم … والدمع يحمل بعض ثقل المغرم\nوصلت دموعا بالنجيع فخدها … في مثل حاشية الرداء المعلم\nولهت فأظلم كل شيء دونها … وأنار منها كل شيء مظلم\nوكأن عبرتها عشية ودعت … مهراقة من ماء وجهي أو دمي\nضعفت جوارح من أذاقته النوى … طعم الفراق فذم طعم العلقم\nهي ميتة إلا سلامة أهلها … من خلتين : من الثرى والماتم\nإن شئت أن يسود ظنك كله … فأجله في هذا السواد الأعظم\nليس الصديق بمن يعيرك ظاهرا … متبسما عن باطن متجهم\nفليبلغ الفتيان عني مالكا … إني متى يتثلموا أتهدم\nولتعلم الأيام أني فتها … بأبي الحسين محمد بن الهيثم\nبأغر ليس بتوأم ويمينه … تغدو وتطرق بالنوال التوأم\nقد قلت للمغتر منه بصفحه … وأخو الكرى لو لم ينم لم يحلم\nلا يلحمنكه تحلمه فقد … يودي بك الوادي وليس بمفعم\nحدت الوفود إلى الجزيرة عيسها … من منجد بمحله أو متهم\nفكأنما لولا المناسك أشركت … ساحاتها أو أوثرت بالموسم\nوكأنه من مدحهم في روضة … وكأنهم من سيبه في مقسم\nكلف برب المجد يزعم أنه … لم يبتدأ عرف إذا لم يتمم\nنظمت له خرز المديح مكارم … ينفثن في عقد اللسان المفحم\nفي قله كثر السماك وإن غدا … هطلا وعفو يديه جهد المرزم\nخدم العلى فخدمنه وهي التي … لاتخدم الأقوام مالم تخدم\nوإذا انتمى في قلة من سؤدد … قالت له الأخرى بلغت تقدم\nما ضر أروع يرتقي في همة … علياء ألا يرتقي في سلم\nيأبى لعرضك أن يغادر عرضة … ماحوله من مالك المستلحم\nإن التلاد على نفاسة قدره … لا يرغم الأزمات ما لم يرغم\nلا يستطال على الخطوب ولا ترى … أكرومة نصفا إذا لم يظلم\nوصنيعة لك ثيب أهديتها … وهي الكعاب لعائذ بك مصرم\nحلت محل البكر من معطى وقد … زقت من المعطى زفاف الأيم\nليزدك وجدا بالسماحة ما ترى … من كيمياء المجد تغن وتغنم\nإن الثناء يسير عرضا في الورى … ومحله في الطول فوق الأنجم\nوإذا المواهب أظلمت ألبستها … بشرا كبارقة الحسام المخذم\nأعطيت ما لم تعطه ولو انقضى … حسن اللقاء حرمت مالم تحرم\nلقددت من شيم كأن سيورها … يقددن من شيم السحاب المرزم\nلو قلت حصل بعضها أو كلها … في حاتم لدعيت دافع مغرم\nشهرت فما تنفك توقع باسمها … من قبل معناها بعدم المعدم\nإن القصائد يممتك شواردا … فتحرمت بنداك قبل تحرمي\nما عرست حتى أتاك بفارس … ريعانها والغزو قبل المغنم\nفجعلت قيمها الضمير ومكنت … منه فصارت قيما للقيم\nخذها فما زالت على استقلالها … مشغولة بمثقف ومقوم\nتذر الفتي من الرجاء وراءها … وترود في كنف الرجاء القشعم\nزهراء أحلى في الفؤاد من المنى … وألذ من ريق الأحبة في الفم"},{"id":"diwan-abutammam:95","bookId":"diwan-abutammam","type":"poem","seq":95,"chapter":"البحر: طويل","title":"ذكرتك حتى كدت أنساك للذي","page":"","text":"ذكرتك حتى كدت أنساك للذي … توقد من نيران ذكرك في قلبي\nبكيتك لما مثل النأي بالهوى … كأن لم يمثل بي صدودك في القرب\nوهل كان لي في القرب عندك راحة … ووصلك سهم البين في الشرق والغرب\nبلى كان لي في الصبر عنك معول … ومندوحة لولا فضولي في الحب"},{"id":"diwan-abutammam:96","bookId":"diwan-abutammam","type":"poem","seq":96,"chapter":"البحر: كامل تام","title":"أرأيت أي سوالف وخدود","page":"","text":"أرأيت أي سوالف وخدود … عنت لنا بين اللوى فزرود !\nأتراب غافلة الليالي ألفت … عقد الهوى في يارق وعقود\nبيضاء يصرعها الصبا عبث الصبا … أصلا بخوط البانة الأملود\nوحشية ترمي القلوب إذا اغتدت … وسنى ، فما تصطاد غير الصيد\nلا حزم عند مجرب فيها ولا … جبار قوم عندها بعنيد\nمالي بربع منهم معهود … إلا الأسى وعزيمة المجلود\nإن كان مسعود سقى أطلالهم … سبل الشؤون ، فلست من مسعود\nظعنوا فكان بكاي حولا بعدهم … ثم ارعويت وذاك حكم لبيد\nأجدر بجمرة لوعة إطفاؤها … بالدمع أن تزداد طول وقود\nلا أفقر الطرب القلاص ولا أرى … مع زير نسوان أشد قتودي\nشوق ضرحت قذاته عن مشربي … وهوى أطرت لحاءه عن عودي\nعامي وعام العيس بين وديقة … مسجورة وتنوفة صيخود\nحتى أغادر كل يوم بالفلا … للطير عيدا من بات العيد\nهيهات منها روضة محمودة … حتى تناخ بأحمد المحمود\nبمعرس العرب الذي وجدت به … أمن المروع ونجدة المنجود\nحلت عرا أثقالها وهمومها … أبناء إسماعيل فيه وهود\nأمل أناخ بهم وفودا فاغتدوا … من عنده وهم مناخ وفود\nبدأ الندى وأعاده فيهم وكم … من مبدىء للعرف غير معيد !\nيا أحمد بن أبي داود حطتني … بحياطتي ولددتني بلدودي\nومنحتني ودا حميت ذماره … وذمامه من هجرة وصدود\nولكم عدو قال لي متمثلا … كم من ودود ليس بالمودود !\nأضحت إياد في معد كلها … وهم إياد بنائها الممدود\nتنميك في قلل المكارم والعلى … زهر لزهر أبوة وجدود\nإن كنتم عادي ذاك النبع إن … نسبوا وفلقة ذلك الجلمود\nوشركتموهم ، دوننا ، فلأنتم … شركاؤنا من دونهم في الجود\nكعب وحاتم اللذان تقسما … خطط العلى من طارف وتليد\nهذا الذي خلف السحاب ومات ذا … في المجد ميتة خضرم صنديد\nإلا يكن فيها الشهيد فقومه … لايسمحون به بألف شهيد\nما قاسيا في المجد إلا دون ما … قاسيته في العدل والتوحيد\nفاسمع مقالة زائر لم تشتبه … آراؤه عند اشتباه البيد\nيستام بعض القول منك بفعله … كملا وعفو رضاك بالمجهود\nأسرى طريدا للحياء من التي … زعموا ، وليس لرهب ة بطريد\nكنت الربيع أمامه ووراءه … قمر القبائل خالد بن يزيد\nفالغيث من زهر سحابة رأفة … والركن من شيبان طود حديد\nوغدا تبين ما براءة ساحتي … لو قد نفضت تهائمي ونجودي\nهذا الوليد رأى التثبت بعدما … قالوا يزيد بن المهلب مود\nفتزعزع الزور المؤسس عنده … وبناء هذا الإفك غير مشيد\nوتمكن ابن أبي سعيد من حجا … ملك بشكر بني الملوك سعيد\nما خالد لي دون أيوب ولا … عبد العزيز ولست دون وليد\nنفسي فداؤك أي باب ملمة … لم يرم فيه إليك بالإقليد !\nلمقارف البهتان غير مقارف … ومن البعيد الرهط غير بعيد\nلما أظلتني غمامك أصبحت … تلك الشهود علي وهي شهودي\nمن بعد أن ظنوا بأن سيكون لي … يوم ببغيهم كيوم عبيد\nأمنية ما صادفوا شيطانها … فيها بعفريت ولا بمريد\nنزعوا بسهم قطيعة يهفو به … ريش العقوق ، فكان غير سديد\nوإذا أراد الله نشر فضيلة … طويت أتاح لها لسان حسود\nلولا اشتعال النار ، فيما جاورت … ما كان يعرف طيب عرف العود\nلولا التخوف للعواقب لم تزل … للحاسد النعمى على المحسود\nخذها مثقفة القوافي ربها … لسوابغ النعماء غير كنود\nحذاء تملأ كل أذن حكمة … بلاغة وتدر كل وريد\nكالطعنة النجلاء من يد ثائر … بأخيه أو كالضربة الأخدود\nكالدر والمرجان ألف نظمه … بالشذر في عنق الفتاة الرود\nكشقيقة البرد المنمنم وشيه … في أرض مهرة أو بلاد تزيد\nيعطي بها البشرى الكريم ويحتبي … بردائها في المحفل المشهود\nبشرى الغني أبي البنات تتابعت … بشراؤه بالفارس المولود\nكرقى الأوساد والأراقم طالما … نزعت حمات سخائم وحقود"},{"id":"diwan-abutammam:97","bookId":"diwan-abutammam","type":"poem","seq":97,"chapter":"البحر: طويل","title":"أمالك إن الحزن أحلام حالم","page":"","text":"أمالك إن الحزن أحلام حالم … ومهما يدم فالوجد ليس بدائم\nأمالك إفراط الصبابة تارك … جنا واعوجاجا في قناة المكارم\nتأمل رويدا هل تعدن سالما … إلى آدم أم هل تعد ابن سالم\nمتى ترع هذا الموت عينا بصيرة … تجد عادلا منه شبيها بظالم\nوإن تك مفجوعا بأبيض لم يكن … يشد على جداوه عقد التمائم\nبفارس دعمي وهضبة وائل … وكوكب عتاب وجمرة هاشم\nشجا الريح فازدادت حنينا لفقده … وأحدث شجوا في بكاء الحمائم\nفمن قبله ما قد أصيب نبينا … أبو القاسم النور المبين بقاسم\nوقال علي في التعازي لأشعث … وخاف عليه بعض تلك المآثم\nوللطرفات يوم صفين لم يمت … خفاتا ولا حزنا عدي بن حاتم\nخلقنا رجالا للتصبر والأسى … وتلك الغواني للبكا والمآتم\nوأي فتى في الناس أحرض من فتى … غدا في حفارات الدموع السواجم\nوهل من حكيم ضيع الصبر بعدما … رأى الحكماء الصبر ضربة لازم !\nولم يحمدوا من عالم غير عامل … خلافا ولا من عامل غير عالم\nرأوا طرقات العجز عوجا قطيعة … وأقطع عجز عندهم عجز حازم\nفلا برحت تسطو ربيعة منكم … بأرقم عطاف وراء الأراقم\nفأنت وصنواك النصيران إخوة … خلقتم سعوطا للأنوف الرواغم\nثلاثة أركان وما أنهد سؤدد … إذا ثبتت فيه ثلاث دعائم"},{"id":"diwan-abutammam:98","bookId":"diwan-abutammam","type":"poem","seq":98,"chapter":"البحر: طويل","title":"ومنفرد بالحسن خلو من الهوى","page":"","text":"ومنفرد بالحسن خلو من الهوى … بصير بأبواب التجرم والعتب\nولوع بسوء الظن لا يعرف الوفا … يبيت على سلم ويغدو على حرب"},{"id":"diwan-abutammam:99","bookId":"diwan-abutammam","type":"poem","seq":99,"chapter":"البحر: طويل","title":"أأحمد إن الحاسدين حشود","page":"","text":"أأحمد إن الحاسدين حشود … وإن مصاب المزن حيث تريد\nفلا تبعدن مني قريبا فطالما … طلبت فلم تبعد وأنت بعيد\nأصخ تستمع حر القوافي فإنها … كواكب إلا أنهن سعود\nولاتمكن الإخلاق منها فإنما … يلذ لباس البرد وهو جديد"},{"id":"diwan-abutammam:100","bookId":"diwan-abutammam","type":"poem","seq":100,"chapter":"البحر: كامل تام","title":"يا ربع لو ربعوا على ابن هموم","page":"","text":"يا ربع لو ربعوا على ابن هموم … مستسلم لجوى الفراق سقيم\nقد كنت معهودا بأحسن ساكن … منا وأحسن دمنة ورسوم\nأيام للأيام فيك غضارة … والدهر في وفيك غير مليم\nوظباء أنسك لم تبدل منهم … بظباء وحشك ظاعنا بمقيم\nمن كل ريم لو تبدى قطعت … ألحاظ مقلته فؤاد الريم\nأما الهوى فهو العذاب فإن جرت … فيه النوى فأليم كل أليم\nأمر التجلد بالتلدد حرقة … أمرت جمود دموعه بسجوم\nولا والطلول الدارسات ألية … من معرق في العاشقين صميم\nما حاولت عيني تأخر ساعة … فالدمع مذ صار الفراق غريمي\nلم يبرح البين المشت جوانحي … حتى تروت من هوى مسموم\nوإلى جناب أبي الحسين تشنعت … بزمامها كالمصعب المخطوم\nجاءتك في معج خوائف في البرى … وعوارف بالمعلم المأموم\nمن كل ناجية كأن أديمها … حيصت ظهارته بجلد أطوم\nتنئي ملاطيها إذا ما استكرهت … سعدانة كإدارة الفرزوم\nطلبتك من نسل الجديل وشدقم … كوم عقائل من عقائل كوم\nينسن أصوات الحداة ونبرها … طربا لأصوات الصدى والبوم\nفأصبن بحر نداك غير مصرد … وردا وأم نداك غير عقيم\nلما وردن حياض سيبك طلحا … خيمن ثم شربن شرب الهيم\nإن الخليفة والخليفة قبله … وجداك ترب نصيحة وعزيم\nوجداك محمودا فلما يألوا … لك في مفاوضة ولا تقديم\nما زلت من هذا وذلك لابسا … حللا من البتجيل والتعظيم\nنفسي فداؤك والجبال وأهلها … في طرمساء من الحروب بهيم\nبالداذويه وخيزج وذواتها … عهد لسيفك لم يكن بذميم\nبالمصعبيين الذين كأنهم … آساد أغيال وجن صريم\nمثل الب دور تضيء إلا أنها … قد قلنست من بيضها بنجوم\nولى بها المخذول يعذل نفسه … متمطرا في جيشه المهزوم\nراموا اللتيا والتي فاعتاقهم … سيف الإمام ودعوة المظلوم\nناشدتهم بالله يوم لقيتهم … والخيل تحت عجاجة كالنيم\nومنحتهم عظتيك من متوعر … متسهل قاسي الفؤاد رحيم\nحتى إذا جمحوا هتكت بيوتهم … بالله ثم الثامن المعصوم\nفتجردت بيض الس يوف لهامهم … وتجرد التوحيد للتخريم\nغاديتهم بالمشرقين بوقعة … صدعت صواعقها جبال الروم\nأخرجتهم بل أخرجتهم فتنة … سلبتهم من نضرة ونعيم\nنقلوا من الماء النمير وعيشة … رغد إلى الغسلين والزقوم\nوالحرب تعلم حين تجهل غارة … تغلي على حطب القنا المحطوم\nأن المنايا طوع بأسك والوغى … ممزوج كأسك من ردى وكلوم\nوالحرب تركب رأسها في مشهد … عدل السفيه به بألف حليم\nفي ساعة لو أن لقمانا بها … وهو الحكيم لصار غير حكيم\nجثمت طيور الموت في أوكارها … فتركن طير العقل غير جثوم\nوالسيف يحلف أنك السيف الذي … ما اهتز إلا اجتث عرش عظيم\nمشت الخطوب القهقرى لما رأت … خببي إليك مؤكدا برسيم\nفزعت إلى التوديع غير لوابث … لما فزعت إليك بالتسليم\nوالدهر ألام من شرقت بلومه … إلا إذا أشرقته بكريم\nأهببت لي ريح الرجاء فأقدمت … هممي بها حتى استبحن همومي\nأيقظت للكرم الكرام بناطق … لنداك أظهر كنز كل قديم\nولقد نكون ولا كريم نناله … حتى تخوض إليه ألف لئيم\nفسننت بالمعروف من أثر الندى … سننا شفت من دهرنا المذموم\nوسم الورى بخصاصة فوسمته … بسماحة لاحت على الخرطوم\nجليت فيه بمقلة لم يقذها … بخل ولم تسفح على معدوم\nيقع أنبساط الرزق في لحظاتها … نسقا إذا وقعت على محروم\nويد يظل المال يسقط كيده … فيها سقوط الهاء في الترخيم\nلا يأمل المال النجاة إذا عدا … صرف الزمان مجاءة بعديم\nقل للخطوب إليك عني ، إنني … "},{"id":"diwan-abutammam:101","bookId":"diwan-abutammam","type":"poem","seq":101,"chapter":"البحر: كامل تام","title":"هي فرقة من صاحب لك ماجد","page":"","text":"هي فرقة من صاحب لك ماجد … فغدا إذابة كل دمع جامد\nفافزع إلى ذخر الشؤون وغربه … فالدمع يذهب بعض جهد الجاهد\nوإذا فقدت أخا ولم تفقد له … دمعا ولاصبرا فلست بفاقد\nأعلي يا بن الجهم إنك دفت لي … سما وخمرا في الزلال البارد\nلاتبعدن أبدا ولا تبعد فما … أخلاقك الخضر الربا بأباعد\nإن يكد مطرف الإخاء فإننا … نغدو ونسري في إخاء تالد\nأو يختلف ماء الوصال فماؤنا … عذب تحدر من غمام واحد\nأو يفترق نسب يؤلف بيننا … أدب أقمناه مقام الوالد\nلو كنت طرفا كنت غير مدافع … للأشقر الجعدي أو للذائذ\nأو قدمتك السن خلت بأنه … من لفظك اشتقت بلاغة خالد\nأو كنت يوما بالنجوم مصدقا … لزعمت أنك أنت بكر عطارد\nصعب فإن سومحت كنت مسامحا … سلسا جريرك في يمين القائد\nألبست فوق بياض مجدك نعمة … بيضاء حلت في سواد الحاسد\nومودة ، لا زهدت في راغب ، … يوما ، ولا هي رغبت في زاهد\nغناء ليس بمنكر أن يغتدي … في روضها الراعي أمام الرائد\nما أدعي لك جانبا من سؤدد … إلا وأنت عليه أعدل شاهد"},{"id":"diwan-abutammam:102","bookId":"diwan-abutammam","type":"poem","seq":102,"chapter":"البحر: كامل تام","title":"لولا أبو يعقوب في إبرامه","page":"","text":"لولا أبو يعقوب في إبرامه … سبب العلى لا نحل ثني ذمامه\nليث إذا الحاجات لذن بحقوه … في كره منها وفي إقدامه\nأنظر إلى الآمال كيف رتوعها … في فكره وقعوده وقيامه\nكيف الشكاية للزمان وصرفه … وندى الأمير وأنت في أيامه\nهذا سحاب أنت سقت غمامه … وعليك بعد الله فيض غمامه\nإن ابتداء العرف مجد باسق … والمجد كل المجد في استتمامه\nهذا الهلال يروق أبصار الورى … حسنا وليس كحسنه لتمامه"},{"id":"diwan-abutammam:103","bookId":"diwan-abutammam","type":"poem","seq":103,"chapter":"البحر: خفيف تام","title":"غير مستأنس بشيء إذا غبت","page":"","text":"غير مستأنس بشيء إذا غبت … سوى ذكرك الذي لا يغيب\nأنت دون الجلاس أنيس أن … ت بعيدا فالحزن فيك قريب"},{"id":"diwan-abutammam:104","bookId":"diwan-abutammam","type":"poem","seq":104,"chapter":"البحر: كامل تام","title":"طلل الجميع ، لقد عفوت حميدا","page":"","text":"طلل الجميع ، لقد عفوت حميدا … وكفى على رزئي بذاك شهيدا\nدمن كأن البين أصبح طالبا … دمنا لدى آرامها وحقودا\nقربت نازحة القلوب من الجوى … وتركت شأو الدمع فيك بعيدا\nخضلا ، إذا العبرات لم تبرح لها … وطنا سرى قلق المحل طريدا\nأمواقف الفتيان تطوي لم تزر … من كل لهفان زدت في أود ال\nأذكرتنا الملك المضلل في الهوى … والأعشيين وطرفة ولبيدا\nحلوا بها عقد النسيب ونمنموا … من وشيها حللا لها وقصيدا\nراحت غواني الحي عنك غوانيا … يلبسن نأيا تارة وصدودا\nمن كل سابغة الشباب إذا بدت … تركت عميد القريتين عميدا\nأولعن بالمرد الغطارف بدنا … غيدا ألفنهم لدانا غيدا\nأحلى الرجال من النساء مواقعا … من كان أشبههم بهن خدودا\nفاطلب هدوءا بالتقلقل واستثر … بالعيس من تحت السهاد هجودا\nمن كل معطية على علل السرى … وخدا يبيت النوم منه شريدا\nتخدي بمنصلت يظل إذا ونى … ضرباؤه حلسا لها وقتودا\nجعل الدجى جملا وودع راضيا … بالهون يتخذ القعود قعودا\nطبلت ربيع ربيعة الممهي لها … فوردن ظل ربيعة الممدودا\nبكريها علويها صعبيها ال … حصني شيبانها الصنديدا\nذهليها مريها مطريها … يمنى يديها خالد بن يزيدا\nنسب كأن عليه من شمس الضحى … نورا ومن فلق الصباح عمودا\nعريان لا يكبو دليل من عمى … فيه ولا يبغي عليه شهودا\nشرف على أولى الزمان وإنما … خلق المناسب أن يكون جديدا\nلو لم تكن من نبعة نجدية … علوية لظننت عودك عودا\nمطر أبوك أبو أهلة وائل … ملأ البسيطة عدة وعديدا\nكل امرئ لاجئ إلى سنده … ولد الحتوف أساودا وأسودا\nربدا ومأسدة على أكتادها … لبد تخال فليلهن لبودا\nورثوا الأبوة والحظوظ فأصبحوا … جمعوا جدودا في العلى وجدودا\nوقر النفوس إذا كواكب قعضب … أردين عفريت الوغى المريدا\nزهرا إذا طلعت عل حجب الكلى … نحست وإن غابت تكون سعودا\nما إن ترى إلا رئيسا مقصدا … تحت العجاج وعاملا مقصودا\nفزعوا إلى الحلق المضاعف وارتدوا … فيها حديدا في الشؤون حديدا\n … مشيا يهد الراسيات وئيدا\nيغشون أسفحهم مذانب طعنة … سيح وأشنع ضربة أخدودا\nما إن ترى الأحساب بيضا وضحا … إلا بحيث ترى المنايا سودا\nلبس الشجاعة إنها كانت له … قدما نشوغا في الصبا ولدودا\nبأسا قبيليا وبأس تكرم … \nوإذا رأيت أبا يزيد في ندى … \nيقري مرجيه مشاشة ماله … وشبا الأسنة ثغرة ووريدا\nأيقنت أن من السماح شجاعة … تدمي ، وان من الشجاعة جودا\nوإذا سرحت الطرف حول قبابه … لم تلق إلا نعمة وحسودا\nومكارما عتق النجار ، تليدة … إن كان هضب عمايتين تليدا\nومتى حللت به أنالك جهده … ووجدت بعد الجهد فيه مزيدا\nمتوقد منه الزمان وربما … كان الزمان بآخرين بليدا\nأبقى يزيد ومزيد وأبوهما … وأبوه ركنك في الفخار شديدا\nسلفوا يرون الذكر عقبا صالحا … ومضوا يعدون الثناء خلودا\nإن القوافي والمساعي لم تزل … مثل النظام ، إذا أصاب فريدا\nهي جوهر نثر ، فإن ألفته … بالشعر صار قلائدا وعقودا\nفي كل معترك وكل مقامة … يأخذن منه ذمة وعهودا\nفإذا القصائد لم تكن خفراءها … لم ترض منها مشهدا مشهودا\nمن أجل ذلك كانت العرب الألى … يدعون هذا سؤددا محدودا\nوتند عندهم العلى إلا على … جعلت لها مرر القصيد قيودا"},{"id":"diwan-abutammam:105","bookId":"diwan-abutammam","type":"poem","seq":105,"chapter":"البحر: منسرح","title":"بني حميد الله فضلكم","page":"","text":"بني حميد الله فضلكم … أبقى لكم اصرما فأسعدكم\nأبقى لكم والدا يبركم … أنجدكم في الوغى وأمجدكم\nفاتخذوه لذاك سيدكم … فعرفه في الأنام سودكم\nلو كان في يوم بابك لكم … لم تفقدوا في اللقاء سيدكم\nالله أعطاكم برأفته … أصرم منا منه ليبلوكم\nألا اشكروا الله ذا الجلال فقد … بالصنع في أصرم تغدكم\nمازال في قومكم لكم ملك … يراب زلاتكم ويكلأكم"},{"id":"diwan-abutammam:106","bookId":"diwan-abutammam","type":"poem","seq":106,"chapter":"البحر: كامل تام","title":"أطفأت نارهواك من قلبي","page":"","text":"أطفأت نارهواك من قلبي … وحللتني من عرو ؟ الحب\nابرأت قرحة لوعة ثبتت … بين الشغاف كقرحة الجنب\nما الذنب يا كنز الذنوب معا … لك في الهوى لكنه ذنبي\nفاسلم ولا تسلم فلاعجب … من لم يقل من هجره حسبي ؟\n … لم تنج لؤلؤة من الثقب !"},{"id":"diwan-abutammam:107","bookId":"diwan-abutammam","type":"poem","seq":107,"chapter":"البحر: منسرح","title":"مالكثيب الحمى إلى عقده","page":"","text":"مالكثيب الحمى إلى عقده … مابال جرعائه إلى جرده !\nماخطبه ما دهاه ما غاله … ما ناله في الحسان من خرده\nالسالبات امرءا عزيمته … بالسحر والنافثات في عقده\nلبسن ظلين ظل أمن من الده … ر وظلا من لهوه ودده\nفهن يخبرن عن بلهنية ال … عيش ويسألن منه عن جحده\nورب ألمى منهن أشنب قد … رشفت مالا يذوب من برده\nقلتا من الريق ناقع الذوب … إلا أن برد الأكباد في جمده\nكالخوط في القد والغزالة في البه … جة وابن الغزال في غيده\nوما حكاه ولا نعيم له … في جيده بل حكاه في جيده\nفالربع قد عزني على جلدي … مامح من سهله ومن جلده\nلم يبق شر الفراق منه سوى … شريه من نؤيه ومن وتده\nسأخرق لخرق بابن خرقاء كال … هيق إذا ما استحم في نجده\nمقابل في الجديل صلب القرا … لوحك من عجبه إلى كتده\nتامكه نهده مداخله … ملمومه محزئله أجده\nإلى المفدى أبي يزيد الذي … يضل غمر الملوك في ثمده\nظل عفاة ، يحب زائره … حب الكبير الصغير من ولده\nإذا أناخوا ببابه أخذوا … حكميهم من لسانه ويده\n … أموال حتى أقمت من أوده\nمستمطر حل من بني مطر … ووسمهم لائح على تلده\nفهم يميسون البخترية في … بروده والأنام في برده\nلايندبون القتيل أو يأتي الحو … ل لهم كاملا على قوده\nإناء مجد ملآن بورك في … صريحه للعلى وفي زبده\nوهضب عز تجري السماحة في … حدوره والإباء في صعده\nيزيد والمزيدان في الحرب ال … زائدتان الطودان من مصده\nنعم لواء الخميس أبت به يو … وخميس عالي الضحى أفده\nخلت عقابا بيضاء في حجرات ال … ملك طارت منه وفي سدده\nفشاغب الجو وهو مسكنه … وقاتل الريح وهي من مدده\nومر تهفو ذؤابتاه على … أسمر متنا يوم الوغى جسده\nمارنه لدنه مثقفه … عراصه في الأكف مطرده\nتخفق أفياؤه على ملك … يرى طراد الأبطال من طرده\nنال بعاري القنا ولابسه … مجدا تبيت الجوزاء عن أمده\nيعلم أن ليس للعلى لقم … قصد لمن لم يطأ على قصده\nيا فرحة الثغر بالخليفة من … يزيده المرتضى ومن أسده\nتضرم ناراه في قري ووغى … من حد أسيافه ومن زنده\nممتلئ الصدر والجوانح من … رحمة مملوئهن من حسده\nيأخذ من راحة لشغل ويس … تبقي ليبس الزمان من لغده\nفهو لو اسطاع عند أسعده … لحز عضوا من يومه لغده\nإذ منهم من يعد ساعته الط … لق عتادا له على أبده\nألوى كثير الأسى على سؤدد ال … عيش قليل الأسى على رغده\nقريحة العقل من معاقله … والصبر في النائبات من عدده\nيا مضغنا خالدا لك الثكل إن … خلد حقدا عليك في خلده\nإليك عن سيل عارض خضل الش … ؤبوب يأتي الحمام من نضده\nمسفه ثره مسحسحه … وابله مستهله برده\nوهل يساميك في العلى ملك … صدرك أولى بالرحب من بلده\nأخلاقك الغر دون رهطك أثر … رى منه في رهطه وفي عدده\nومشهد صير الكماة به … خطبانه سلما إلى شهده\nكأنما مبرم القضاء به … من رسله والمنون من رصده\nأرث من خالد بمنصلت ال … إقدام يوم الهياج منجرده\nكالبدر حسنا وقد يعاوده … عبوس ليث العرين في عبده\nكالسيف يعطيك ملء عينيك من … فرنده تارة ومن ربده\nتالله أنسى دفاعه الزور من … عوراء ذي نيرب ومن فنده\nولا تناسى أحياء ذي يمن … ماكان من نصره ومن حشده\nجلة أنماره وهمدانه والش … م من أزده ومن أدده\nآثرني إذ جعلته سندا … كل امرىء لاجىء إلى سنده\nفي غلة أوقدت على كبد ال … سائل نارا تعيي على كبده\nإيثار شزر القوى يرى جسد ال … معروف أولى بالطب من جسده\nوجئته زائرا ، فجاوز بي ال … أخلاق من ماله إلى جدده\nفرحت من عنده ولي رفد … ينالها المعتفون من رفده\nوهل يرى العسر عذرة رجل … خالد المزيدي من عدده"},{"id":"diwan-abutammam:108","bookId":"diwan-abutammam","type":"poem","seq":108,"chapter":"البحر: كامل تام","title":"لامته لام عشيرها وحميمها","page":"","text":"لامته لام عشيرها وحميمها … منها خلائق قد ابن ذميمها\nلم تدر كم من ليلة قد خاضها … ليلاء وهي تنامها وتنيمها\nنكرت فتى أذرى بنضرة وجهه … وبمائه تكد الخطوب ولومها\nلا تنكري همي فإني زائدي … حزما حضار النائبات وشومها\nفلقبل أظهر صقل سيف أثره … فبدا وهذبت القلوب همومها\nوالحادثات وإن أصابك بوسها … فهو الذي أنباك كيف نعيمها\nأو ما رأيت منازل ابنة مالك … رسمت له كيف الزفير رسومها\nأناؤها وطلولها ونجادها … ووهادها وحديثها وقديمها\nتغدو الرياح سوافيا وعوافيا … فتضيم مغناها وليس يضيمها\nوكأنما ألقى عصاه بها النوى … من شقة قذف فليس يريمها\nإني كشفتك أزمة بأعزة … غر إذا عمر الأمور بهيمها\nبثلاثة كثلاثة الراح استوى … لك لونها ومذاقها وشميمها\nوثلاثة الشجر الجني تكافأت … أفنانها وثمارها وأرومها\nوثلاثة الدلو أستجيد لماتح … أعوادها ورشاؤها وأديمها\nوثلاثة القدر اللواتي أشكلت … أأخيرها ذو العبء أم قيدومها\nوإذا علوق الحاج يوما سكنت … بهم فقد رئمتك حين ترومها\nعبد الحميد لها وللفضل الربا … فيها ومثل السيف إبراهيمها\nجازوا خلائق قد تيقنت العلى … كل التيقن أنهن نجومها\nلو أن باقلا المفهه ينبري … في مدحها سهلت عليه خزومها\nولو ان سحبان المفوة ينتحي … في ذمها لم يدر كيف يذيمها\nإنا أتيناكم نصون مآربا … يستصغر الحدث العظيم عظيمها\nبالعيس قاسمنا الفلا أشلاءها … والبيد لا يعطى السواء قسيمها\nفلنا أمين فصوصها وشخوصها … ولها وري سديفها ولحومها\nأخذت محالتها السهوب وبدءها … فالبعد يعذرها ونحن نلومها\nصفح عن النبآت ليس يؤودها … جرس الدجى مكاؤها ونئيمها\nليلية قد وقرت هاماتها … من قبل أصداء الفلاة وبومها\nمهرية بلغ الكراية ركبها … منها وغاب مريحها ومسيمها\nفعنيقها يعضيدها ووسيجها … سعدانها وذميلها تنومها\nملك الكلال رقابها وأنوفها … فنعوبها دين - لها وسعومها\nفكأن مهملها مخيس غيرها … وكأنما مخلوعها مخطومها"},{"id":"diwan-abutammam:109","bookId":"diwan-abutammam","type":"poem","seq":109,"chapter":"البحر: بسيط تام","title":"مربب الحزن في القلوب","page":"","text":"مربب الحزن في القلوب … وناصر العزم في الذنوب\nما شئت من منظر عجيب … فيه ومن منطق أريب\nلما رأى رقبة الأعادي … على معنى به كئيب\nجرد لي من هواه ودا … صار رقيبا على الرقيب"},{"id":"diwan-abutammam:110","bookId":"diwan-abutammam","type":"poem","seq":110,"chapter":"البحر: طويل","title":"يقول أناس في حبيناء عاينوا","page":"","text":"يقول أناس في حبيناء عاينوا … عمارة رحلي من طريف وتالد\nأصادفت كنزا أم صبحت بغارة … ذوي غرة حاميهم غير شاهد\nفقلت لهم لا ذا ولا ذاك ديدني … ولكنني أقبلت من عند خالد\nجذبت نداه غدو السبت جذبة … فخر صريعا بين أيدي القصائد\nفأبت بنعمى منه بيضاء لدنة … كثيرة قرح في قلوب الحواسد\nهي الناهد الريا إذا نعمة امرىء … سواه غدت ممسوحة غير ناهد\nفرعت عقاب الأرض والشعر مادحا … له فارتقى بي في عقاب المحامد\nفألبسني من أمهات تلاده … وألبسته من أمهات قلائدي"},{"id":"diwan-abutammam:111","bookId":"diwan-abutammam","type":"poem","seq":111,"chapter":"البحر: وافر تام","title":"سقت رفها وظاهرة وغبا","page":"","text":"سقت رفها وظاهرة وغبا … أبا بشر أهاضيب الغمام\nلبست به الصبابة غير أني … سررت به لزمزم والمقام\nغداة غدت به أجد حلال … تشذر تحت غطريف حرام\nثوت لفراقه الآداب شعثا … وجفت بعده غدر الكلام\nأخو ثقة نأى فبقيت لما … نأى غرضا لإخوان السلام\nذوي الهمم الهوامد والأكف ال … جوامد والمروات النيام\nيظل عليك أصفحهم حقودا … لرؤيا إن رآها في المنام\nومن شر المياه إذا استميحت … أواجنها على طول المقام"},{"id":"diwan-abutammam:112","bookId":"diwan-abutammam","type":"poem","seq":112,"chapter":"البحر: بسيط تام","title":"لأشكرنك إن لم أوت من أجلي","page":"","text":"لأشكرنك إن لم أوت من أجلي … شكرا يوافيك عني آخر الأبد\nوإن توردت من بحر البحور ندى … ولم أنل منه إلا غرفة بيدي"},{"id":"diwan-abutammam:113","bookId":"diwan-abutammam","type":"poem","seq":113,"chapter":"البحر: بسيط تام","title":"إلياس كن في ضمان الله والذمم","page":"","text":"إلياس كن في ضمان الله والذمم … ذا مهجة عن ملمات النوى حرم\nسلامة لك لاتهتاج نضرتها … ودعدعا ولعا في النعل والقدم\nالله عافاك منها علة عرضا … لم تنح أظفارها إلا على الكرم\nتكشفت هبوات الثغر مذ كشفت … آلاء ربك ما استشعرت من سقم\nفإن يكن وصب عاينت سورته … فالورد حلف لليث الغابة الأضم\nإن الرياح إذا ما أعصفت قصفت … عيدان نجد ولم يعبأن بالرتم\nبنات نعش ونعش لا كسوف لها … والشمس والبدر منه الدهر في الرقم\nوالحادثات عدو الأكرميين فما … تعتام إلا امرأ يشفى من القرم\nفليهنك الأجر والنعمى التي عظمت … حتى جلت صدأ الصمصامة الخذم\nقد ينعم الله بالبلوى وإن عظمت … ويبتلي الله بعض القوم بالنعم !"},{"id":"diwan-abutammam:114","bookId":"diwan-abutammam","type":"poem","seq":114,"chapter":"البحر: طويل","title":"ألا يا خليلي اللذين كلاهما","page":"","text":"ألا يا خليلي اللذين كلاهما … يلبيك عند النائبات نجيب\nأعيناعلى ظبي جعلت نصيبه … ومالي فيه ما حييت نصيب"},{"id":"diwan-abutammam:115","bookId":"diwan-abutammam","type":"poem","seq":115,"chapter":"البحر: كامل تام","title":"أرويت طمآن الصعيد الهامد","page":"","text":"أرويت طمآن الصعيد الهامد … وملأت من جزعيك عين الرائد\nولقد أتيتك صاديا فكرعت في … شيم ألذ من الزلال البارد\nمهدت لاسمك منزلا ومحلة … في الشعر بين نوادر وشواهد\nفهو المراح لكل معنى عازب … وهو العقال لكل بيت شارد\nكم نعمة زينتني بسموطها … كالعقد في عنق الكعاب الناهد\nغادرتها كالسور عولي سمكه … مضروبة بيني وبين الحاسد\nفاشدد يديك على يدي وتلافني … من مطلب كدر الموارد راكد\nأصبحت في طرقاته ووجوهه … أعمى وكنت نبيل القائد\nتلك القليب مباحة أرجاؤها … والحوض منتظر ورود الوارد\nوالدلو بالغة الرشاء مليئة … بالري إن وصلت بباع واحد"},{"id":"diwan-abutammam:116","bookId":"diwan-abutammam","type":"poem","seq":116,"chapter":"البحر: كامل تام","title":"ليت الظباء أبا العميثل خبرت","page":"","text":"ليت الظباء أبا العميثل خبرت … خبرا يروي صاديات الهام\nإن الأمير إذا الحوادث أظلمت … نور الزمان وحلية الإسلام\nوالله ما يدري بأية حالة … يبأى مجاوره على الأيام\nأبما يجامعه لديه من الغنى … أم ما يفارقه من الإعدام\nوأرى الصحيفة قد علتها فترة … فترت لها الأرواح في الأجسام\nإن الجياد إذا علتها صنعة … راقت ذوي الألباب والإفهام\nلتزيد الأبصار فيها فسحة … وتأملا بعناية القوام\nلولا الأمير وأن حاكم رأيه … في الشعر أصبح أعدل الحكام\nلثكلت آمالي لديه بأسرها … أو كان إنشادي خفير كلامي\nولخفت في تفريقه ما بيننا … ما قيل في عمرو وفي الصمصام"},{"id":"diwan-abutammam:117","bookId":"diwan-abutammam","type":"poem","seq":117,"chapter":"البحر: طويل","title":"تلقاه طيفي في الكرى فتجنبا","page":"","text":"تلقاه طيفي في الكرى فتجنبا … وقبلت يوما ظله فتغضبا\nوخبرأني قدمررت ببابه … لأخلس منه نظرة فتحجبا\nولو مرت الريح الصبا عند أذنه … بذكري لسب الريح أو لتعتبا !\nولم تجر مني خطرة بضميره … فتظهر إلا كنت فيها مسببا\nوما زاده عندي قبيح فعاله … ولا الصد والاعراض إلا تحببا"},{"id":"diwan-abutammam:118","bookId":"diwan-abutammam","type":"poem","seq":118,"chapter":"البحر: بسيط تام","title":"يا بعد غاية العين إن بعدوا","page":"","text":"يا بعد غاية العين إن بعدوا … هي الصبابة طول الدهر والسهد\nقالوا : الرحيل غدا لاشك ، قلت لهم … اليوم أيقنت أن اسم الحمام غد\nكم من دم يعجز الجيش اللهام إذا … بانوا ستحكم فيه العرمس الاجد\nما لامرىء خاض في بحر الهوى عمر … إلا وللبين منه السهل والجلد\nكأنما البين من إلحاحه أبدا … على النفوس أخ للموت أو ولد\nتداو من شوقك الأقصى بما فعلت … خيل ابن يوسف والأبطال تطرد\nذاك السرور الذي آلت بشاشته … ألا يجاورها في مهجة كمد\nلقيتهم والمنايا غير دافعة … لما أمرت به والملتقى كبد\nفي موقف وقف الموت الزعاف به … فالموت يوجد والأرواح تفتقد\nفي حيث لا مرتع البيض الرقاق إذا … أصلتن جدب ولا ورد القنا ثمد\nمستصحبا نية قد طال ما ضمنت … لك الخطوب فأوفت بالذي تعد\nورحب صدر لو أن الأرض واسعة … كوسعه لم يضق عن أهلها بلد\nصدعت جريتهم في عصبة قلل … قد صرح الماء عنها وانجلى الزبد\nمن كل أروع ترتاع المنون له … إذا تجرد لا نكس ولا جحد\nيكاد حين يلاقي القرن من حنق … قبل السنان على حوبائه يرد\nقلوا ، ولكنهم طابوا ، فأنجدهم … جيش من الصبر لا يحصى له عدد\nإذا رأوا للمنايا عارضا لبسوا … من اليقين دروعا مالها زرد\nنأوا عن المصرخ الأدنى ، فليس لهم … إلا السيوف على أعدائهم مدد\nولى معاوية عنهم وقد حكمت … فيه القنا ، فأبى المقدار والأمد\nنجاك في الروع ما نجى سميك في … صفين والخيل بالفرسان تنجرد\nإن تنفلت وأنوف الموت راغمة … فاذهب فأنت طليق الركض يا لبد\nلاخلق أربط جأشا منك يوم ترى … أبا سعيد ولم يبطش بك الزؤد\nأما وقد عشت يوما بعد رؤيته … فافخر فإنك أنت الفارس النجد\nلو عاين الأسد الضرغام رؤيته … ما ليم أن ظن رعبا أنه الأسد\nشتان بينهما في كل نازلة … نهج القضاء مبين فيهما جدد\nهذا على كتفيه كل نازلة … تخشى ، وذاك على أكتافه اللبد\nأعيا علي وما أعيا بمشكلة … بسندبايا ويوم الروع محتشد\nمن كان أنكأ حدا في كتائبهم … أأنت أم سيفك الماضي أم الأحد ؟\nلا يوم أكثر منه منظرا حسنا … والمشرفية في هاماتهم تخد\nأنهبت أرواحه الأرماح إذ شرعت … فما ترد لريب الدهر عنه يد\nكأنها وهي في الأوداج والغة … وفي الكلى تجد الغيظ الذي نجد\nمن كل أزرق نظار بلا نظر … إلى المقاتل ما في متنه أود\nكأنه كان ترب الحب مذ زمن … فليس يعجزه قلب ولا كبد\nتركت منهم سبيل النار سابلة … في كل يوم إليها عصبة تفد\nكأن بابك بالبذين بعدهم … نؤي أقام خلاف الحي أو وتد\nبكل منعرج من فارس بطلس … \nلما غدا مظلم الأحشاء من أشر … أسكنت جانحتيه كوكبا يقد\nوهارب ودخيل الروع يجلبه … إلى المنون كما يستجلب النقد\nكأنما نفسه من طول حيرتها … منها على نفسه يوم الوغى رصد\nتالله ندري : أألإسلام يشكرها … من وقعة أم العباس أم أدد\nيوم به أخذ الإسلام زينته … بأسرها واكتسى فخرا به الأبد\nيوم يجي إذا قام الحساب ولم … يذممه بدر ولم يفضح به أحد\nوأهل موقان إذ ماقوا فلا وزر … أنجاهم منك في الهيجا ولا سند\nلم تبق مشركة إلا وقد علمت … إن لم تتب أنه للسيف ما تلد\nوالببر حين اطلخم الأمر صبحهم … قطر من الحرب لما جاءهم خمدوا\nكادت تحل طلاهم من جماجمهم … لو لم يحلوا ببذل الحكم ما عقدوا\nلكن ندبت لهم رأي ابن محصنة … يخاله السيف سيفا حين يجتهد\nفي كل يوم فتوح منك واردة … تكاد تفهمها من حسنها البرد\nوقائع عذبت أنباؤها وحلت … حتى لقد صار مهجورا لها الشهد\nإن ابن يوسف نجى الثغر من سنة … أعوام يوسف عيش عندها رغد\nآثار أموالك الأدثار قد خلقت … وخلفت نعما آثارها جدد\nفافخر فما من سماء للندى رفعت … إلا وأفعالك الحسنى لها عمد\nواعذر حسودك فيما قد خصصت به … إن العلى حسن في مثلها الحسد"},{"id":"diwan-abutammam:119","bookId":"diwan-abutammam","type":"poem","seq":119,"chapter":"البحر: بسيط تام","title":"حبست فاحتبست من أجلك الديم","page":"","text":"حبست فاحتبست من أجلك الديم … ولم يزل نابيا عن صحبك العدم\nيا بن المسيب قولا غير ماكذب … لولاك لم يدرض ما المعروف والكرم\nجللتني نعما جلت وأجر بأن … يجل شكري إذ جلت لي النعم\nيا من إذا قعدت بالقوم همتهم … عن اكتساب العلى قامت به الهمم\nرأيت عودك من نبع أرومته … ما في جوانبه لين ولا وصم\nأنت السليل فسل السيف منتصرا … لذمة الشعر إذ ضاعت له الذمم\nعلوت من مجد قيس في الورى علما … أعيا الورى وعلا مجدا بك العلم"},{"id":"diwan-abutammam:120","bookId":"diwan-abutammam","type":"poem","seq":120,"chapter":"البحر: بسيط تام","title":"لئن جحدتك ما لاقيت فيك لقد","page":"","text":"لئن جحدتك ما لاقيت فيك لقد … صحت شهود تباريحي وتعذيبي\nبزفرة بعد أخرى طالما شهدت … بأنها انتزعت من صدر مكروب\nلكن عدوت على جسمي فبنت به … يامن رأى الظبي عداء على الديب"},{"id":"diwan-abutammam:121","bookId":"diwan-abutammam","type":"poem","seq":121,"chapter":"البحر: طويل","title":"سرت تستجير الدمع خوف نوى غد","page":"","text":"سرت تستجير الدمع خوف نوى غد … وعاد قتادا عندها كل مرقد\nوأنقذها من غمرة الموت ، أنه … صدود فراق لا صدود تعمد\nفأجرى لها الإشفاق دمعا موردا … من الدم فوق خد مورد\nهي البدر يغنيها تودد وجهها … إلى كل من لاقت وإن لم تودد\nولكنني لم أحو وفرا مجمعا … ففزت به إلا بشمل مبدد\nولم تعطني الأيام نوما مسكنا … ألذ به إلا بنوم مشرد\nوطول مقام المرء في الحي مخلق … لديباجتيه فاغترب تتجدد\nفإني رأيت الشمس زيدت محبة … إلى الناس أن ليست عليهم بسرمد\nحلفت برب البيض تدمى متونها … ورب القنا المناد والمتقصد\nلقد كف سيف الصامتي محمد … تباريح ثأر الصامتي محمد\nرمى الله منه بابكا وولاته … بقاصمة الأصلاب في كل مشهد\nبأسمح من غر الغمام سماحة … وأشجع من صرف الزمان وأنجد\nإذا ما دعوناه بأجلح أيمن … دعاه ، ولم يظلم بأصلع أنكد\nفتى يوم بذ الخرمية لم يكن … بهياب نكس ولا بمعرد\nقفا سندبايا والرماح مشيحة … تهدى إلى الروح الخفي فتهتدي\nعدا الليل فيها عن معاوية الردى … وما شك ريب الدهر في أنه ردي\nلعمري لقد حررت يوم لقيته … لو أن القضاء وحده لم يبرد\nفإن يكن المقدار فيه مفندا … فما هو في أشياعه بمفند\nوفي أرشق الهيجاء والخيل ترتمي … بأبطالها في جاحم متوقد\nعططت على رغم العدا عزم بابك … بصبرك عط الأتحمي المعضد\nفإلا يكن ولى بشلو مقدد … هناك فقد ولى بعزم مقدد\nوقد كانت الأرماح أبصرن قلبه … فأرمدها ستر القضاء الممدد\nوموقان كانت دار هجرته فقد … توردتها بالخيل أي تورد\nحططت بها ، يوم العروبة ، عزه … وكان مقيما بين نسر وفرقد\nرآك سديد الرأي والرمح في الوغى … تأزر بالإقدام فيه وترتدي\nوليس يجلي الكرب رأي مسدد … إذا هو لم يؤنس برمح مسدد\nفمر مطيعا للعوالي معودا … من الخوف والإحجام ما لم يعود\nوكان هو الجلد القوى ، فسلبته … بحسن الجلاد المحض حسن التجلد\nلعمري لقد غادرت حسي فؤاده … قريب رشاء للقنا سهل مورد\nوكان بعيد القعر من كل ماتح … فغادرته يسقى ويشرب باليد\nوللكذج العليا سمت بك هم ة … طموح يروح النصر فيها ويغتدي\nوقد خزمت بالذل انف ابن خازم … وأعيت صياصيها يزيد بن مزيد\nلما بت في الدنيا بنوم مسهد … وأطلقت فيهم كل حتف مقيد\nوبالهضب من أبرشتويم ودروذ … على كل نشزمتلئب وفرفد\nأفادتك فيها المرهفات مآثرا … \nوليلة أبليت البيات بلاءه … من الصبر في وقت من الصبر مجحد\nفيا جولة لاتجحديه وقاره … ويا سيف لا تكفر ويا ظلمة أشهدي\nوياليل لو أني مكانك بعدها … لما بث في الدنيا بنوم مسهد\nوقائع أصل النصر فيها وفرعه … إذا عدد الإحسان أو لم يعدد\nفمهما تكن من وقعة بعد لا تكن … سوى حسن مما فعلت مردد\nمحاسن أصناف المغنين جمة … وما قصبات السبق إلا لمعبد\nجلوت الدجى عن أذربيجان بعدما … تردت بلون كالغمامة أربد\nوكانت وليس الصبح فيها بأبيض … فأمست وليس الليل فيها بأسود\nرأى بابك منك التي طلعت له … بنحس وللدين الحنيف بأسعد\nهززت له سيفا من الكيد إنما … تجذ به الأعناق مالم يجرد\nيسر الذي يسطو به وهو مغمد … ويفضح من يسطو به غير مغمد\nوإني لأرجو أن تقلد جيده … قلادة مصقول الذباب مهند\nمنظمة بالموت يحظى بحليها … مقلدها في الناس دون المقلد\nإليك هتكنا جنح ليل كأنه … قد اكتحلت منه البلاد بإثمد\nتقلب في الآفاق صلا كأنما … يقلب في فكيه شقة مبرد\nتلافى جداك المجتدين فأصبحوا … ولم يبق مذخور ولم يبق مجتد\nإذا ما رحى دارت أدرت سماحة … رحى كل إنجاز على كل موعد\nأتيتك لم أفزع إلى غير مفزع … ولم أنشد الحاجات في غير منشد\nومن يرج معروف البعيد فإنما … يدي عولت في النائبات على يدي"},{"id":"diwan-abutammam:122","bookId":"diwan-abutammam","type":"poem","seq":122,"chapter":"البحر: بسيط تام","title":"جادتك عني عيون المزن والديم","page":"","text":"جادتك عني عيون المزن والديم … وزال عيشك موصولا به النعم\nأصبحت لا صقبا مني ولا أمما … فالصبر لا صقب مني ولا أمم\nوليت عني فدمع العين منسجم … يبكي التلاقي وماء القلب منسجم\nإني لمن أن أرى حيا وقد برحت … بك النوى يا شقيق النفس محتشم\nإن لم أقم مأتما للبين أشهده … أهل الوفاء فودي فيك متهم\nشبهاك في كل يوم عز جانبه … ليث العرينة والصمصامة الخذم\nما جاد جودك إذ تعطي بلا عدة … ما يرتجى منك لا كعب ولا هرم"},{"id":"diwan-abutammam:123","bookId":"diwan-abutammam","type":"poem","seq":123,"chapter":"البحر: بسيط تام","title":"قال الوشاة بدا في الخد عارضه","page":"","text":"قال الوشاة بدا في الخد عارضه … فقلت لا تكثروا ما ذاك عائبه\nلما استقل بأرداف تجاذبه … واخضر فوق جمان الدر شاربه\nوأقسم الورد أيمانا مغلظة … أن لا تفارق خديه عجائبه\nوكلمته جفون غير ناطقة … فكان من رده ما قال حاجبه\nالحسن منه على ما كنت أعهده … والشعرحرز له ممن يطالبه\nأحلى وأحسن ما كانت شمائله … اذ لاح عارضه وأسود شاربه\nوصار من كان يلحي في مودته … إن سيل عني وعنه قال صاحبه"},{"id":"diwan-abutammam:124","bookId":"diwan-abutammam","type":"poem","seq":124,"chapter":"البحر: وافر تام","title":"أظن دموعها سنن الفريد","page":"","text":"أظن دموعها سنن الفريد … وهي سلكاه من نحر وجيد\nلها من لوعة البين التدام … يعيد بنفسجا ورد الخدود\nحمتنا الطيف من أم الوليد … خطوب شيبت رأس الوليد\nرآنا مشعري أرق وحز ن … وبغيته لدى الركب الهجود\nسهاد يرجحن الطرف منه … ويولع كل طيف بالصدود\nبأرض البذ في خيشوم حرب … عقيم من وشيك ردى ولود\nترى قسماتنا تسود فيها … وما أخلاقنا فيها بسود\nتقاسمنا بها الجرد المذاكي … سجال الكر والدأب العنيد\nفتمسي في سوابغ محكمات … وتمسي في السروج وفي اللبود\nحذوناها الوجى والأين حتى … تجاوزت الركوع إلى السجود\nإذا خرجت من الغمرات قلنا … خرجت حبائسا إن لم تعودي\nفكم من سؤدد أمكنت منه … برمته على أن لم تسودي\nأهانك للطراد لم تهوني … عليه وللقياد أبو سعيد\nبلاك فكنت أرشية الأماني … وبرد مسافة المجد البعيد\nفتى هز القنا فحوى سناء … بها لا بالأحاظي والجدود\nإذا سفك الحياء الروع ، يوما … وقى دم وجهه بدم الوريد\nقضى من سندبايا كل نحب … وأرشق والسيوف من الشهود\nوأرسلها على موقان رهوا … تثير النقع أكدر بالكديد\nرآه العلج مقتحما عليه … كما اقتحم الفناء على الخلود\nفمر ولو يجاري الريح خيلت … لديه الريح ترسف في القيود\nشهدت لقد أوى الإسلام منه … غدائتذ إلى ركن شديد\nوللكذجات كنت لغير بخل … عقيم الوعد منتاج الوعيدش\nغدت غيرانهم لهم قبورا … كفت فيهم مؤونات اللحود\nكأنهم معاشر أهلكوا من … بقايا قوم عاد أو ثمود\nوفي أبرشتويم وهضبتيها … طلعت على الخلافة بالسعود\nبضرب ترقص الأحشاء منه … وتبطل مهجة البطل النجيد\nبيت البيات بعقد جأش … أشد قوى من الحجر الصلود\nرأوا ليث الغريفة وهو ملق … دراعيه جميعا بالوصيد\nعليما أن سيرفل في المعالي … إذا ما بات يرفل في الحديد\nوكم سرق الدجى من حسن صبر … وغطى من جلاد فتى جليد\nويوم التل تل البذ أبنا … ونحن قصار أعمار الحقود\nقسمناهم فشطر للعوالي … وآخر في لظى حرق الوقود\nكأن جهنم انضمت عليهم … كلاها غير تبديل الجلود\nويوم انصاع بابك مستمرا … مباح العقر مجتاح العديد\nتأمل شخص دولته … بجسم ليس بالجسم المديد\nفأزمع نية هربا فحامت … حشاشته على أجل بليد\nتقنصه بنو سنباط أخذا … بأشراك المواثق والعهود\nولولا أن ريحك دربتهم … لأحجمت الكلاب عن الأسود\nوهرجاما بطشت به فقلنا … خيار البز كان على القعود\nوقائع قد سكبت بها سوادا … على ما احمر من ريش البريد\nلئن عمت بني حواء نفعا … لقد خصت بني عبد الحميد\nأقول لسائلي بأبي سعيد … كأن لم يشفه خبر القصيد\nأجل عينيك في ورقي مليا … فقد عاينت عام المحل عودي\nلبست سواه أقواما فكانوا … كما أغنى التيمم بالصعيد\nوتركي سرعة الصدر اغتباطا … يدل على موافقة الورود\nفتى أحيت يداه بعد يأس … لنا الميتين من كرم وجود"},{"id":"diwan-abutammam:125","bookId":"diwan-abutammam","type":"poem","seq":125,"chapter":"البحر: متقارب تام","title":"وقائلة حج عبد العزيز","page":"","text":"وقائلة حج عبد العزيز … فقلت لها حج غيث الأنام\nلقد حمل الجمل المستقل … بعبد العزيز سجال الغمام\nمطاف يطوف ببيت الحرام … وركن حوى ركنه باستلام\nمضى محرما بحلال الثراء … فأرضى به رب بيت الحرام\nأقام طويلا بدار المقام … فأمرضنا منه طول المقام\nوآب معرى من السيئا … ت يرفل في الحسنات الجسام\nمناسكه فيه مقبولة … وحجته برة بالتمام\nوأبقى مآثر محمودة … معمرة عمر ركني شمام\nفدونك تهنئة حرة … نظام امرئ حاذق بالنظام"},{"id":"diwan-abutammam:126","bookId":"diwan-abutammam","type":"poem","seq":126,"chapter":"البحر: خفيف تام","title":"إجعلي في الكرى لعيني نصيبا","page":"","text":"إجعلي في الكرى لعيني نصيبا … كي تنال المكروه والمحبوبا\nاشركي بين دمع عيني ونومي … واجعلي لي من الرقاد نصيبا\nكنت أهوى البيض الحسان فقد … ح حبي عن غيرها محجوبا\nقربتها المنى وباعدها النأ … ي فأضحت مني بعيدا قريبا\nإن تكن مقلتي إذا غبت تس … لي عليها الدموع حتى تؤوبا\nفلكم نظرة تسر بها من … ك لها روعة تشق القلوبا"},{"id":"diwan-abutammam:127","bookId":"diwan-abutammam","type":"poem","seq":127,"chapter":"البحر: كامل تام","title":"أسقى طلولهم أجش هزيم","page":"","text":"أسقى طلولهم أجش هزيم … وغدت عليهم نضرة ونعيم\nجادت معاهدهم عهاد سحابة … ما عهدها عند الديار ذميم\nسفه الفراق عليك يوم رحيلهم … وبما أراه وهو عنك حليم\nظلمتك ظالمة البريء ظلوم … والظلم من ذي قدرة مذموم\nزعمت هواك عفا الغداة كما عفت … منها طلول باللوى ورسوم\nلا والذي هو عالم أن النوى … صبر وأن أبا الحسين كريم\nمازلت عن سنن الوداد ولاغدت … نفسي على ألف سواك تحوم\nلمحمد بن الهيثم بن شبانة … مجد إلى جنب السماك مقيم\nملك إذا نسب الندى من ملتقى … طرفيه فهو أخ له وحميم\nكالليث ليث الغاب إلا أن ذا … في الروع بسام وذاك شتيم\nطحطحت بالخيل الجبال من العدى … والكفر يقعد بالهدى ويقوم\nبالسفح من همذان إذ سفحت دما … رويت بجمته الرماح الهيم\nيوم وسمت به الزمان ووقعة … بردت على الإسلام وهي سموم\nلمعت أسنته فهن مع الضحى … شمس وهن مع الظلام نجوم\nنضيت سيوفك للقراع فأغمدت … والخرمية كيدها مخروم\nأبليت فيه الدين يمن نقيبة … تركت إمام الكفر وهو أميم\nبرقت بوارق من يمينك غادرت … وضحا بوجه الخطب وهو بهيم\nضربت أنوف المحل حتى أقلعت … والعدم تحت غمامها معدوم\n … للنجم أو للمرزمين نديم\nغيث حوى كرم الطبائع دهره … والغيث يكرم مرة ويلوم\nما زال يهذي بالمواهب دائبا … حتى ظننا أنه محموم\nللجود سهم في المكارم والتقى … ما ربه المكدي ولا المسهوم\nوبيان ذلك أن أول من حبا … وقرى خليل الله إبراهيم\nأعطيتني دية القتيل وليس لي … عقل ولاحق عليك قديم\nإلا ندى كالدين حل قضاؤه … إن الكريم لمعتفيه غريم\nعرف غدا ضربا نحيفا عنده … شكر الرجال وأنه لجسيم\nأخفيته فخفيته وطويته … فنشرته والشخص منه عميم\nجود مشيت به الضراء تواضعا … وعظمت عن ذكراه وهو عظيم\nالنار نار الشوق في كبد الفتى … والبين يوقده هوى مسموم\nخير له من أن يخامر صدره … وحشاه معروف امرئ مكتوم\nسرق الصنيعة فاستمر بلعنة … يدعو عليه النائل المظلوم\nأأقنع المعروف وهو كأنه … قمر الدجى إني إذن للئيم !\nمثر من المال الذي ملكتني … أعناقه ومن الوفاء عديم ؟ !\nفأروح في بردين لم يسحبهما … قبلي فتى وهما الغنى واللوم ؟"},{"id":"diwan-abutammam:128","bookId":"diwan-abutammam","type":"poem","seq":128,"chapter":"البحر: مجزوء الرمل","title":"قد قصرنا دونك الابصار","page":"","text":"قد قصرنا دونك الابصار … خوفا ان تذوبا\nكلمازدناك لحظا … زدتنا حسنا وطيبا\nمرضت الحاظ عين … فأمرضت القلوبا !"},{"id":"diwan-abutammam:129","bookId":"diwan-abutammam","type":"poem","seq":129,"chapter":"البحر: طويل","title":"سأشكر لابني وهب الهبة التي","page":"","text":"سأشكر لابني وهب الهبة التي … هي الود صاناه بحسن صيانه\nعفاء على دهياء كانا إزاءها … ونكل لداجي الخطب يعتورانه\nإلى خيفي منى فالموقفين … \nتدفقتما من طل مزن ووبله … ومن شرخ معروف ومن عنفوانه\nوهل لي غداة السبق عذر وأنتما … بحيث ترى عيناي يوم رهانه !\nرأيتكما من ريب دهري هضبة … وما زلتما لازلتما من رعانه\nفأصبح لي تحت الجران فريسة … ولولاكما أصبحت تحت جرانه\nوملكتماني صعبة وخشاشها … وأمكنتما من طامح وعنانه\nلئن رمت أمرا غبتما عند بكره … لقد سرني فعلاكما في عوانه\nوماخير برق لاح في غير وقته … وواد غدا ملآن قبل أوانه ؟ !\nتلطفتما للدهر حتى أجابني … وقد أزمنت رجلي هنات زمانه\nوما زلتما من نبعه إن عجمتما … لضيم ، وعند الجود من خيزرانه\nلعمري لقد أصبحتما العرف صاحبا … له مقول نعماكما في ضمانه\nويأخذ من أيديكما وهواكما … فلا عجب أن تأخذا من لسانه"},{"id":"diwan-abutammam:130","bookId":"diwan-abutammam","type":"poem","seq":130,"chapter":"البحر: بسيط تام","title":"ما اليوم أول توديع ولا الثاني","page":"","text":"ما اليوم أول توديع ولا الثاني … البين أكثر من شوقي وأحزاني\nدع الفراق فإن الدهر ساعده … فصار أملك من روحي بجثماني\nخليفة الخضر من يربع على وطن … في بلدة فظهور العيس أوطاني\nبالشام أهلي وبغداد الهوى وأنا … بالرقتين وبالفسطاط إخواني\nوما أظن النوى ترضى بما صنعت … حتى تطوح بي أقصى خراسان\nخلفت بالأفق الغربي لي سكنا … قد كان عيشي به حلوا بحلوان\nغصن من البان مهتز على قمر … يهتز مثل اهتزاز الغصن في البان\nأفنيت من بعده فيض الدموع كما … أفنيت في هجره صبري وسلواني\nوليس يعرف كنه الوصل صاحبه … حتى يغادى بنأي أو بهجران\nإساءة الحادثات استبطني نفقا … فقد أظلك إحسان ابن حسان\nأمسكت منه بود شد لي عقدا … كأنما الدهر في كفي بها عان\nإذا نوى الدهر أن يودي بتالده … لم يستعن غير كفيه بأعوان\nلو أن إجماعنا في فضل سؤدده … في الدين لم يختلف في الأمة اثنان"},{"id":"diwan-abutammam:131","bookId":"diwan-abutammam","type":"poem","seq":131,"chapter":"البحر: طويل","title":"تجرع أسى قد أقفر الجرع الفرد","page":"","text":"تجرع أسى قد أقفر الجرع الفرد … ودع حسي عين يجتلب ماءها الوجد\nإذا انصرف المحزون قد فل صبره … سؤال المغاني فالبكاء له رد\nبدت للنوى أشياء قد خلت أنها … سيبدؤني ريب الزمان إذا تبدو\nنوى كانقضاض النجم كانت نتيجة … من الهزل يوما إن هزل الهوى جد\nفلا تحسبا هندا لها الغدر وحدها … سجي نفس كل غانية هند\nوقالوا أسى عنها وقد خصم الأسى … جوانح مشتاق إذا خاصمت لد\nوعين إذا هيجتها عادت الكرى … ودمع إذا استنجدت أسرابه نجد\nوما خلف أجفاني شؤون بخيلة … ولا بين أضلاعي لها حجر صلد\nوكم تحت أرواق الصبابة من فتى … من القوم حر دمعه للهوى عبد\nوما أحد طار الفراق بقلبه … بجلد ولكن الفراق هوالجلد\nومن كان ذا بث على النأي طارف … فلي أبدا من صرفه حرق تلد\nفلا ملك فرد المواهب واللهى … يجاوز بي عنه ولا رشأ فرد\nمحمد يا بن الهيثم انقلبت بنا … نوى خطأ في عقبها لوعة عمد\nوحقد من الأيام ، وهي قديرة … وشر السجايا قدرة جارها حقد\nإساءة دهر أذكرت حسن فعله … إلي ولولا الشري لم يعرف الشهد\nأما وأبي أحداثه إن حادثا … حدا بي عنك العيس للحادث الوغد\nمن النكبات الناكبات عن الهوى … فمحبوبها يحبو ومكروهها يعدو\nليالينا بالرقتين وأهلها … سق العهد منك العهد والعهد والعهد\nسحاب متى يسحب على النبت ذيله … فلا رجلق ينبو عليه ولا جعد\nضربت لها بطن الزمان وظهره … فلم ألق من أيامها عوضا بعد\nلدى ملك من أيكة الجود لم يزل … على كبد المعروف من فعله برد\nرقيق حواشي الحلم لو أن حلمه … بكفيك ما ماريت في انه برد\nوذو سورة تفري الفري شباتها … ولا يقطع الصمصام ليس له حد\nوداني الجدا تأتي عطاياه من عل … ومنصبه وعر مطالعه جرد\nفقد نزل المرتاد منه بماجد … مواهبه غور وسؤدده نجد\nغدا بالأماني لم يرق ماء وجهه … مطال ولم يعقد بآماله الرد\nبأوفاهم برقا إذا أخلف السنا … وأصدقهم رعدا إذا كذب الرعد\nأبلهم ريقا وكفا لسائل … وأنضرهم وعدا ، إذا صوح الوعد\nكريم ، إذا ألقى عصاه مخيما … بأرض ، فقد ألقى بها رحله المجد\nبه أسلم المعروف بالشام بعدما … ثوى منذ أودى خالد وهو مرتد\nفتى لا يرى بدا من البأس والندى … ولا شيء إلا منه غيرهما بد\nحبيب بغيض عند راميك عن قلى … وسيف على شانيك ليس له غمد\nوكم أمطرته نكبة ثم فرجت … ولله في تفريجها ولك الحمد\nوكم كان دهرا للحوادث مضغة … فأضحت جميعا وهي عن لحمه درد\nتصارعه لولاك كل ملمة … ويعدو عليه الدهر من حيث لا يعدو\nتوسطت من أبناء ساسان هضبة … لها الكنف المحلول والسند النهد\nبحيث انتمت زرق الأجادل منهم … علوا وقامت عن فرائسها الأسد\nألم تر أن الجفر جفرك في العلى … قريب الرشاء لا جرور ولا ثمد\nإذا صدرت عنه الأعاجم كلها … فأول من يروى به بعدها الأزد\nلهم بك فخر لا الرباب تربه … بدعوى ولم تسعد بأيامه سعد\nوكم لك عندي من يد مستهلة … علي ولا كفران عندي ولا جحد\nيد يستذل الدهر في نفحاتها … ويخضر من معروفها الأفق الورد\nومثلك قد خولته المدح جازيا … وإن كنت لا مثل إليك ولا ند\nنظمت له عقدا من الشعر تنضب ال … بحار وما دناه من حليها عقد\nتسير مسير الشمس مطرفاتها … وما السير منها لا العنيق ولا الوخد\nتروح وتغدو ، بل يراح ويغتدي … بها وهي حيرى لا تروح ولا تغدو\nتقطع آفاق البلاد سوابقا … وما ابتل منها لا عذار ولا خد\nغرائب ما تنفك فيها لبانة … لمرتجز يحدو ومرتجل يشدو\nإذا حضرت ساح الملوك تقبلت … عقائل منها غير ملموسة ملد\nأهين لها ما في البدور وأكرمت … لديهم قوافيها كما يكرم الوفد"},{"id":"diwan-abutammam:132","bookId":"diwan-abutammam","type":"poem","seq":132,"chapter":"البحر: بسيط تام","title":"ألقت على غاربي حبل امرئ عان","page":"","text":"ألقت على غاربي حبل امرئ عان … نوى تقلب دوني طرف ثعبان\nتواترت نكبات الدهر ترشقني … من كل صائبة عن قوس غضبان\nمدت عنان رجائي فاستقدت له … حتى رمت بي في بحر ابن حسان\nبحر من الجود يرمي موجه زبدا … حبابه فضة زينت بعقيان\nلولا ابن حسان مات الجود وانتشرت … مناحس البخل تطوي كل إحسان\nلما تواترت الأيام تعبث بي … وأسقطت ريحها أوراق أغصاني\nوصلت كف منى بكف غنى … فارقت بينهما همي وأحزاني\nحتى لبست كسى لليسر تنشرها … على اعتساري يد لم تسه عن شاني\nيد من اليسر قدت حلتي عسري … حتى مشى عسري في شخص عريان\nوصالحتني الليالي بعدما رجحت … على سروري غمومي أي رجحان\nفاليوم سالمني دهري وذكرني … من المدائح ماقد كان أنساني !\nثم انتضت للعدا الأيام صارمها … واستقبلتها بوجه غير حسان\nسأبعث اليوم آمالي إلى ملك … يلقى المديح بقلب غير نسيان\nتفاءلت مقلتي فيه إذا اختلجت … بالخير من فوقها أشفار أجفاني\nيا من به بدنت من بعدما هزلت … مني المنى وأرتني وجه خسراني\nكن لي مجيرا من الأيام إن لها … يدا تفحص عن سري وإعلاني\nيابن الأكارم والمرجو من مضر … إذا الزمان جلا عن وجه خوان\nإليك ساقتني الآمال يجنبها … سحاب جودك من أرضي وأوطاني !"},{"id":"diwan-abutammam:133","bookId":"diwan-abutammam","type":"poem","seq":133,"chapter":"البحر: خفيف تام","title":"حسنت عبرتي وطاب نحيبي","page":"","text":"حسنت عبرتي وطاب نحيبي … فيك ياكنز كل حسن وطيب\nلك قد أدق من أن يحاكى … بقضيب في الحسن أو بكثيب\nأي شيء يكون أحسن من صب … صب أديب متيم بأديب\nجاز حكمي في قالبه وهواه … بعد ما جاز حكمه في القلوب\nكاد أن يكتب الهوى بين عين … يه كتابا هذا حبيب حبيب\nغير أني لو كنت أعشق نفسي … لتنغصت عيشها بالرقيب"},{"id":"diwan-abutammam:134","bookId":"diwan-abutammam","type":"poem","seq":134,"chapter":"البحر: وافر تام","title":"جعلت فداك عبد الله عندي","page":"","text":"جعلت فداك عبد الله عندي … بعقب الهجر منه والبعاد\nله لم من الكتاب بيض … قضوا حق الزيارة والوداد\nوأحسب يومهم إن لم تجدهم … مصادف دعوة منهم جماد\nفكم نوء من الصهباء سار … وآخر منك بالمعروف غاد\nفهذا يستهل على غليلي … وهذا يستهل على تلادي\nويسقي ذا مذانب كل عرق … ويترع ذا قرارة كل واد\nدعوتهم عليك وكنت ممن … نعنيه على العقد الجياد"},{"id":"diwan-abutammam:135","bookId":"diwan-abutammam","type":"poem","seq":135,"chapter":"البحر: منسرح","title":"أعقبك الله صحة البدن","page":"","text":"أعقبك الله صحة البدن … ما هتف الهاتفات في الغصن\nكيف وجدت الدواء أوجدك الل … هشفاء به مدى الزمن ؟\nلانزع الله منك صالحة … أبليتها من بلائك الحسن\nلازلت تزهى بكل عافية … تجتثها من معارض الفتن\nلو أن أعمارنا تطاوعنا … شاطره العمر سادة اليمن\nإن بقاء الجواد أحمد في … أعناقنا منة من المنن"},{"id":"diwan-abutammam:136","bookId":"diwan-abutammam","type":"poem","seq":136,"chapter":"البحر: مجزوء الكامل","title":"نظري اليك يشير لي","page":"","text":"نظري اليك يشير لي … هد لي بأنك لي حبيب\nوتباعدي حذرالوشا … وأنت من قلبي قريب\nفانظرإلى ولعي بذك … كلما غفل الرقيب\nوانظر إلى جسمي ففي … ما حل بي العجب العجيب"},{"id":"diwan-abutammam:137","bookId":"diwan-abutammam","type":"poem","seq":137,"chapter":"البحر: طويل","title":"أبا القاسم المحمود ، إن ذكر الحمد","page":"","text":"أبا القاسم المحمود ، إن ذكر الحمد … وقيت رزايا ما يروح وما يغدو\nوطابت بلاد أنت فيها فأصبحت … ومربعها غور ومصطافها نجد\nفإن نك قد نالتك أطراف وعكة … فلا عجب أن يوعك الأسد الورد\nسلمت وإن لك الدعوة آسمها … وكان الذي يحظى بإنجاحها السعد\nفقد أصبحت من صفرة في وجوهها … وراياتها سيان غما بك الأزد\nبنا لا بك الشكوى فليس بضائر … إذا صح نصل السيف ما لقي الغمد"},{"id":"diwan-abutammam:138","bookId":"diwan-abutammam","type":"poem","seq":138,"chapter":"البحر: كامل تام","title":"بذ الجلاد البذ فهو دفين","page":"","text":"بذ الجلاد البذ فهو دفين … ما إن به إلا الوحوش قطين\nلم يقر هذا السيف هذا الصبر في … هيجاء إلا عز هذا الدين !\nقد كان عذرة مغرب فافتضها … بالسيف فحل المشرق الأفشين\nفأعادها تعوي الثعالب وسطها … ولقد ترى بالأمس وهي عرين\nجادت عليها من جماجم أهلها … ديم أمارتها طلى وشؤون\nكانت من الدم قبل ذاك مفازة … غورا فأمست وهي منه معين\nبحرا من الهيجاء يهفو ماله … إلا الجناجن والضلوع سفين\nلاقاهم ملك حياه بالعلى … جرس وجانا خرة الميمون\nملك تضيء المكرمات إذا بدا … للملك منه غرة وجبين\nساس الجيوش سياسة ابن تجارب … رمقته عين الملك وهو جنين\nلانت مهزته فعز وإنما … يشتد بأس الرمح حين يلين\nوترى الكريم يعز حين يهون … وترى اللئيم يهون حين يهون\nقاد المنايا والجيوش فأصبحت … ولها بأرشق قسطل عثنون\nفتركت أرشق وهي يرقى باسمها … صم الصفا فتفيض منه عيون\nلو تستطيع الحج يوما بلدة … حجت إليها كعبة وحجون\nلاقاك بابك وهو يزئر فانثني … وزئيره قد عاد وهو أنين\nلاقى شكائم منك معتصمية … أهزلت جنب الكفر وهو سمين\nلما رأى علميك ولى هاربا … ولكفره طرف عليه سخين\nولى ولم يظلم وهل ظلم امرؤ … حث النجاء وخلفه التنين ! !\nأوقعت في أبرشتويم وقائعا … أضحكن سن الدين وهو حزين\nأوسعتهم ضربا تهد به الكلى … ويخف منه المرء وهو ركين\nضربا كأشداق المخاض وتحته … طعن كأن وجاءه طاعون\nبأس تفل به الصفوف وتحته … رأي تفل به العقول رزين\nأخلى جلادك صدره ولقد برى … وفؤاده من نجدة مسكون\nسجنت تجاربه فضول عرامه … إن التجارب للعقول سجون\nوعشية التل انصرفت وللهدى … شوق إليك مداور وحنين\nعبأ الكمين له فظل لحينه … وكمينه المخفى عليه كمين !\nيا وقعة ما كان أعتق يومها … إذ بعض أيام الزمان هجين\nلو أن هذا الفتح شك لاشتفت … منه القلوب ، فكيف وهو يقين\nوأخذت بابك حائرا دون المنى … ومنى الضلال مياههن أجون\nطعن التلهف قلبه ففؤاده … من غير طعنة فارس مطعون !\nورجا بلاد الروم فاستعصى به … أجل أصم عن النجاء حرون\nهيهات لم يعلم بأنك لو ثوى … بالصين لم تبعد عليك الصين\nمانال ماقد نال فرعون ولا … هامان في الدنيا ولا قارون\nفسيشكر الإسلام ما أوليته … والله عنه بالوفاء ضمين"},{"id":"diwan-abutammam:139","bookId":"diwan-abutammam","type":"poem","seq":139,"chapter":"البحر: خفيف تام","title":"شمس دجن تطلعت من قضيب","page":"","text":"شمس دجن تطلعت من قضيب … أمرت عينها بسحر القلوب\nلو تحل القناع للشمس والبد … در ضياء تقنقا بغروب\nأنا من لحظ وجنتيه جريح … أتداوى بعبرة ونحيب\nحرق الشوق والهوى يتصا … رخن علي مشققات الجيوب"},{"id":"diwan-abutammam:140","bookId":"diwan-abutammam","type":"poem","seq":140,"chapter":"البحر: كامل تام","title":"يا دار دار عليك إرهام الندى","page":"","text":"يا دار دار عليك إرهام الندى … واهتز روضك في الثرى فترأدا\nوكسيت من خلع الحيا مستأسدا … أنفا يغادر وحشه مستأسدا\nطلل عكفت عليه أسأله إلى … أن كاد يصبح ربعه لي مسجدا\nوظللت أنشده وانشد أهله … والحزن خدني ناشدا أو منشدا\nسقيا لمعهدك الذي لو لم يكن … ما كان قلبي للصبابة معهدا\nلم يعط نازلة الهوى حق الهوى … دنف أطاف به الهوى فتجلدا\nصب تواعدت الهموم فؤاده … إن أنتم أخلفتموه موعدا\nلم تنكرين مع الفراق تبلدي … وبراعة المشتاق أن يتبلدا\nياصاحبي بدمشق لست بصاحبي … إن لم تمهد للهموم ممهدا\nأدن المعبدة السناد وأنئها … بالسير ما دام الطريق معبدا\nوإلى بني عبد الكريم تواهقت … رتك النعام رأى الظلام فخودا\nكم أنجموا قمرا حمى بفعاله … قمرا ومكرمة تناغي الفرقدا\nمتهللا في الروع منهلا إذا … ما زند اللحز الشحيح وصردا\nمن كان أحمد مرتعا أو ذمة … فالله أحمد ثم أحمد أحمدا\nأضحى عدوا للصديق إذا غدا … في الحمد يعذله صديقا للعدا\nأفنيت منه الشعر في متمدح … قد ساد حتى كاد يفني السؤددا\nعضب العزيمة في المكارم لم يدع … في يومه شرفا يطالبه غدا\nبرزت في طلب المعالي واحدا … فيها تسير مغورا أومنجدا\nعجبا بأنك سالم من وحشة … في غاية ما زلت فيها مفردا\nوأنا الفداء إذا الرماح تشاجرت … لك والرماح من الرماح لك الفدا\nوسلمت ، أنا لا تزال سوالما … آمالنا بك ما سلمت من الردى\nكم جئت في الهيجا بيوم أبيض … والحرب قد جاءت بيوم أسودا\nأقدمت ، لم ترك الحمية مصدرا … عنها ولم ير فيك قرنك موردا\nلم تغمد السيف الذي قلدته … حتى تمنى نصله أن يغمدا\nهيهات لا ينأى الفخار وإن نأى … عن طالب كانت مطيته الندى\nأنى يفوتك ما طلبت وإنما … وطراك أن تعطي الجزيل وتحمدا\nلما زهدت زهدت في جمع الغنى … ولقد رغبت فكنت فيه أزهدا\nفالمال أن ملت ليس بسالم … من بطش جودك مصلحا أومفسدا\nولأنت أكرم من نوالك محتدا … ونداك أكرم من عدوك محتدا\nلاتعدمنك طيء فلقلما … عدمت عشيرتك الجواد السيدا"},{"id":"diwan-abutammam:141","bookId":"diwan-abutammam","type":"poem","seq":141,"chapter":"البحر: كامل تام","title":"وأبي المنازل إنها لشجون","page":"","text":"وأبي المنازل إنها لشجون … وعلى العجومة إنها لتبين\nفاعقل بنضو الدار نضوك يقتسم … فرط الصبابة مسعد وحزين\nلاتمنعني وقفة أشفي بها … داء الفريق فإنها ماعون\nواسق الأثافي من شؤوني ريها … إن الضنين بدمعه لضنين\nوالنؤي أهمد شطره فكأنه … تحت الحوادث حاجب مقرون\nحزن غداة الحزن هاج غليله … في أبرق الحنان منك حنين\nسمة الصبابة زفرة أو عبرة … متكفل بهما حشا وشؤون\nلولا التفجع لأدعى هضب الحمى … وصفا المشقر أنه محزون\nسيروا بني الحاجات ينجح سعيكم … غيث سحاب الجود منه هتون\nفالحادثات بوبله مصفودة … والمحل في شؤبوبه مسجون\nحملوا ثقيل الهم واستنعى بهم … سفر يهد المتن وهو متين\nحتى إذا ألقوه عن أكتافهم … بالعزم وهو على النجاح ضمين\nوجدوا جناب الملك أخضر واجتلوا … هارون فيه كأنه هارون\nألفوا أمير المؤمنين وجوده … خضل الغمام وظله مسكون\nفغدوا وقد ثقوا برأفة واثق … بالله طائره لهم ميمون\nقرت به تلك العيون بالملك وأشرقت … تلك الخدود وإنهن لجون\nملكوا خطام العيش بالملك الذي … أخلاقه للمكرمات حصون\nملك إذا خاض المسامع ذكره … خف الرجاء إليه وهو ركين\nليث إذا خفق اللواء رأيته … يعلو قرا الهيجاء وهي زبون\nلحياضها متودد ولخطبها … متعمد وبثديها ملبون\nجعل الخلافة فيه رب قوله … سبحانه للشيء كن فيكون\nولقد رأيناها له بقلوبنا … وظهور خطب دونه وبطون\nولذاك قيل من الظنون جلية … صدق وفي بعض القلوب عيون\nولقد علمنا مذ ترعرع أنه … لأمين رب العالمين أمين\nيابن الخلائف إن بردك ملؤه … كرم يذوب المزن منه ولين\nنور من الماضي عليك كأنه … نور عليه من النبي مبين\nيسمو بك السفاح والمنصور وال … مهدي والمعصوم والمأمون\nمن يعش ضوء الآل يعلم أنهم … ملأ لدى ملإ السماء مكين\n … ظل الهدى ، غاب لها وعرين\nقوم غدا الميراث مضروبا لهم … سور عليه من القران حصين\nفيهم سكينة ربهم وكتابه … وإمامتاه واسمه المحزون\nواد من السلطان محمى لم يكن … ليضيم فيه الملك إلا الدين\nفي دولة بيضاء هارونية … متكنفاها النصر والتمكين\nقد أصبح الإسلام في سلطانها … والهند بعض ثغورها والصين\nيفدي أمين الله كل منافق … شنآنه بين الضلوع كمين\nممن يداه يسريان ولم تزل … فينا وكلتا راحتيك يمين\nتدعى بطاعتك الوحوش فترعوي … والأسد في عريسها فتدين\nمافوق مجدك مرتقى مجد ولا … كل افتخار دون فخرك دون\nجاءتك من نظم اللسان قلادة … سمطان فيها اللؤلؤ المكنون\nحذيت حذاء الحضرمية أرهفت … وأجادها التخصير والتلسين\nإنسية وحشية كثرت بها … حركات أهل الأرض وهي سكون\nينبوعها خضل وحلي قريضها … حلي الهدي ونسجها موضون\nأما المعاني فهي أبكار إذا … نصت ولكن القوافي عون\nأحذاكها صنع اللسان يمده … جفر إذا نضب الكلام معين\nويسيء بالإحسان ظنا لاكمن … هو بابنة وبشعره مفتون\nيرمي بهمته إليك وهمه … أمل له أبدا عليك حرون\nفمناه في حيث الأماني رتع … ورجاؤه حيث الرجاء كنين\nولعل ما يرجوه مما لم يكن … بك عاجلا أو آجلا سيكون"},{"id":"diwan-abutammam:142","bookId":"diwan-abutammam","type":"poem","seq":142,"chapter":"البحر: مجزوء الرمل","title":"زفرات مقلقلات","page":"","text":"زفرات مقلقلات … اسعدتها العبرات\nوعويل من غليل … أضرمته الحسرات\nونحيب ووجيب … ودموع مسبلات\nوتباريح اشتياق … وهموم طارقات\nوفؤاد مستهام … جننته الوجنات\nوفتون من فتور … أورثته اللحظات\nوحبيب صد لما … كثرت فيه الوشاة"},{"id":"diwan-abutammam:143","bookId":"diwan-abutammam","type":"poem","seq":143,"chapter":"البحر: بسيط تام","title":"يا أيها السائلي عن عرصة الجود","page":"","text":"يا أيها السائلي عن عرصة الجود … إن فتى الباس داود بن داود\nفتى متى ما ينلك الدهر صالحة … يقل لأمثالها من فعله عودي\nأصبح في الناس محمودا لسؤدده … لازال مكتسيا سربال محسود"},{"id":"diwan-abutammam:144","bookId":"diwan-abutammam","type":"poem","seq":144,"chapter":"البحر: بسيط تام","title":"إن الأمير حمام الجارم الجاني","page":"","text":"إن الأمير حمام الجارم الجاني … ومستراد أماني الموثق العاني\nإذا ثوى جار قوم في بلادهم … فجاره نازل في رأس غمدان\nكم صامت صامتي الضرب فزت به … منه وحلي من المعروف حلاني\nيعطي فيكسبني حمدا بنائله … وتالدي وافر باق وقنياني\nفمن رآني من الأقوام كلهم … فقد رأى محسنا من غير إحسان\nجاني نخيل سواه كان ألفها … غرسا ، وساكن قصر غيره الباني\nهل أنت صائن عرضي لي ومفلتي … بماء وجهي سليما من سليمان\nفتى فتاء وفتيانية وأخو … نوائب وملمات وأزمان\nمسن فكر إذا كلت مضاربه … يوما وصقيل ألباب وأذهان\nذو الود مني وذو القربى بمنزلة … وإخوتي أسوة عندي وإخواني\nلاتخلقن خلقي فيهم وقد سطعت … ناري وجدد من حالي الجديدان\nفي دهري الأول المذموم أعرفهم … فالآن أنكرهم في دهري الثاني ؟ !\nلاقى إذن غرسهم أكدى ثرى وجرت … مني ظنونهم في شر ميدان\nعصابة جاورت آدابهم أدبي … فهم وإن فرقوا في الأرض جيراني\nأرواحنا في مكان واحد وغدت … أبداننا في شآم أو خراسان\nورب نائي المغاني روجه أبدا … لصيق روحي ، ودان ليس بالداني\nأفي أخ لي فرد لا قسيم له … في خالص الود من سري وإعلاني\nترد عن بحرك المورود راجعة … بغير حاجاتها دلوي وأشطاني ؟ !\nمسلط حيث لا سلطان لي ويدي … مغلولة النفع والسلطان سلطاني\nكالنار باردة في عودها ولها … إن فارقته اشتعال ليس بالواني\nما أنس لا أنس قولا قاله رجل … غضضت في عقبه طرفي وأجفاني\nنل الثريا أو الشعرى فليس فتى … لم يغن خمسين إنسانا بإنسان !"},{"id":"diwan-abutammam:145","bookId":"diwan-abutammam","type":"poem","seq":145,"chapter":"البحر: مجزوء الرمل","title":"أنا ميتق ولئن م","page":"","text":"أنا ميتق ولئن م … فمن حبي أموت\nلغزال من بني الأ … فر فيه جبروت\nعبد الخلق له بي … ن يديه الملكوت\nيمنع القبلةمن يه … واه والتسليم قوت\nإن تضرعت بنطق … فحماداه السكوت"},{"id":"diwan-abutammam:146","bookId":"diwan-abutammam","type":"poem","seq":146,"chapter":"البحر: بسيط تام","title":"إن شئت أتبعت إحسانا بإحسان","page":"","text":"إن شئت أتبعت إحسانا بإحسان … فكان جودك من روح وريحان\nفقد - لعمري - فتقت الماء من حجر … في هضبة وهصرت الغصن للجاني\nفاسأل سليماننا تفديه أنفسنا … يامن سليمانه يرعى سليماني !\nوحسبه بك إلا أن همته … أن يقتني مع رضوى طود ثهلان\nلو كان وصما لراج أن يكون له … ركنان ما هز رمح فيه نصلان\nولم يعد من الأبطال ليث وغى … زرت عليه غداة الروع درعان"},{"id":"diwan-abutammam:147","bookId":"diwan-abutammam","type":"poem","seq":147,"chapter":"البحر: كامل تام","title":"قمر تبسم عن جمان نابت","page":"","text":"قمر تبسم عن جمان نابت … فظللت أرمقه بعين الباهت\nما زال يقصر كل حسن دونه … حتى تفاوت عن صفات الناعت\nسجد الجمال لوجهه لمارأى … دهش العقول لحسنه المتفاوت\nإني لأرجو أن أنال وصاله … بالعطف منه ورغم أنف الشامت"},{"id":"diwan-abutammam:148","bookId":"diwan-abutammam","type":"poem","seq":148,"chapter":"البحر: طويل","title":"عفت أربع الحلات للأربع الملد","page":"","text":"عفت أربع الحلات للأربع الملد … لكل هضيم الكشح مجدولة القد\nلسلمى سلامان وعمر عامر … وهند بني هند وسعدي بني سعد\nديار هراقت كل عين شحيحة … وأوطأت الأحزان كل حشا صلد\nفعوجا صدور الأرحبي وأسهلا … بذاك الكثيب السهل والعلم الفرد\nولاتسألاني عن هوى قد طعمتما … جواه فليس الوجد إلا من الوجد\nحططت إلى أرض الجديدي أرحلي … بمهرية تنباع في السير أو تخدي\nتؤم شهاب الحرب حفصا ورهطه … بنو الحرب لا ينبو ثراهم ولا يكدي\nومن شك أن الجود والبأس فيهم … كمن شك في أن الفصاحة في نجد\nأنخت إلى ساحاتهم وجنابهم … ركابي وأضحى في ديارهم وفدي\nإلى سيفهم حفص ومازال ينتضى … لهم مثل ذاك السيف من ذاك الغمد\nفلم أغش بابا أنكرتني كلابه … ولم أتشبث بالوسيلة من بعد\nفأصبحت لا ذل السؤال أصابني … ولا قدحت في خاطري روعة الرد\nيرى الوعد أخزى العار إن هو لم تكن … مواهبه تأتي مقدمة الوعد\nفلو كان ما يعطيه غيثا لأمطرت … سحائبه من غير برق ولا رعد\nدرية خيل مايزال لدى الوغى … له مخلب ورد من الأسد الورد\nمن القوم جعد أبيض الوجه والندى … وليس بنان يجتدى منه بالجعد\nوأنت وقد مجت خراسان داءها … وقد نغلت أطرافها نغل الجلد\nوأوباشها خزر إلى العرب الألى … لكيما يكون الحر من خول العبد\nليالي بات العز في غير بيته … وعظم وغد القوم في الزمن الوغد\nوما قصدوا إذ يسحبون على المنى … برودهم إلا إلى وارث البرد\nوراموا دم الإسلام لا من جهالة … ولا خطإ بل حاولوه على عمد\nفمجوا به سما وصابا ولو نأت … سيوفك عنهم كان أحلى من الشهد\nضممت إلى قحطان عدنان كلها … ولم يجدوا إذ ذاك من ذاك من بد\nفأضحت بك الأحياء أجمع ألفة … كما أحكمت في النظم واسطة العقد\nوكنت هناك الأحنف الطب في بني … تميم جميعا ، والمهلب في الأزد\nوكنت أبا غسان مالك وائل … عشية دانى حلفه الحلف بالعقد\nولما أماتت أنجم العرب الدجى … سرت وهي أتباع لكوكبك السعد\nوهل أسد العريس إلا الذي له … فضيلته في حيث مجتمع الأسد\nفهم منك في جيش قريب قدومه … عليهم وهم من يمن رأيك في جند\nووقرت يافوخ الجبان على الردى … وزدت غداة الروع في نجدة النجد\nرأيت حروب الناس هزلا وإن علا … سناها وتلك الحرب معتمد الجد\nفيا طيب مجناها ويا برد وقعها … على الكبد الحرى وزاد على البرد\nورفعت طرفا كان لولاك خاشعا … وأوردت ذود العز في أول الورد\nفتى برحت هاماته وفعاله … به فهو في جهد وما هو في جهد\nمتت إليه بالقرابة بيننا … وبالرحم الدنيا فأغنت عن الود\nرأى سالف الدنيا وشابك آله … أحق بأن يرعاه في سالف العهد\nفيا حسن ذاك البر إذ أنا حاضر … وياطيب ذاك القول والذكر من بعدي\nوما كنت ذا فقر إلى صلب ماله … ما كان حفص بالفقير إلى حمدي\nولكن رأى شكري قلادة سؤدد … فصاغ لها سلكا بهيا من الرفد\nفما فاتني ما عنده من حبائه … ولا فاته من فاخر الشعر ما عندي\nوكم من كريم قد تخضر قلبه … بذاك الثناء الغض في طرق المجد"},{"id":"diwan-abutammam:149","bookId":"diwan-abutammam","type":"poem","seq":149,"chapter":"البحر: بسيط تام","title":"أراك أكبرت إدماني على الدمن","page":"","text":"أراك أكبرت إدماني على الدمن … وحملي الشوق من باد ومكتمن\nلا تكثرن ملامي إن عكفت على … ربع الحبيب فلم أعكف على وثن\nسلوت إن كنت أدري ما تقول إذن … مجت مقالتها في وجهها أذني\nالحب أولى بقلبي في تصرفه … من أن يغادرني يوما بلا شجن\nحلبت صرف النوى صرف الأسى وحدا … بالبث في دولة الإغرام والددن\nمما وجدت على الأحشاء أوقد من … دمع على وطن لي في سوى وطني\nصيرت لي من تباري عبرتي سكنا … مذ صرت فردا بلا إلف ولا سكن\nمن ذا يعظم مقدار السرور بمن … يهوى إذا لم يعظم موضع الحزن ؟ !\nالعيش والهم والليل والتمام معا … ثلاثة أبدا يقرن في قرن\nأقول للحرة الوجناء لاتهني … فقد خلقت لغير الحوض والعطن\nما يحسن الدهر أن يسطو على رجل … إذا تعلق حبلا من أبي حسن\nكم حال فيض نداه يوم معضلة … وبأسه بين من يرجوه والمحن !\nكأنني يوم جردت الرجاء له … عضبا أخذت به سيفا على الزمن\nفتى تريش جناح الجود راحته … حتى يخال بأن البخل لم يكن\nوتشتري نفسه المعروف بالثمن ال … غالي ولو أنها كانت من الثمن\nأمواله وعداه من مواهبه … وبأسه يطلبون الدهر بالإحن\nيقشع الفتن المسود جانبها … وماله من نداه الدهر في فتن\nإذا بدا لك مر في كتائبهم … لم يحجب الموت عن روح ولا بدن\nكم في العلى لهم والمجد من بدع … إذا تصفحت اختيرت على السنن\nقوم إذا هطلت جودا أكفهم … علمت أن الندى مذ كان في اليمن"},{"id":"diwan-abutammam:150","bookId":"diwan-abutammam","type":"poem","seq":150,"chapter":"البحر: خفيف تام","title":"لي حبيب عصيت فيه النصيحا","page":"","text":"لي حبيب عصيت فيه النصيحا … ليس سمحا ولابخيلا شحيحا\nكلما قلت قد رثى لسقامي … زاد قلبي بهجره تبريحا\nإن في الصدر والحشا حرقات … بت منها يا صاحبي مستريحا\nفأثبني من القطيعة بالوصل … وإلا فاردد فؤادي صحيحا"},{"id":"diwan-abutammam:151","bookId":"diwan-abutammam","type":"poem","seq":151,"chapter":"البحر: كامل تام","title":"لطمحت في الإبراق والإرعاد","page":"","text":"لطمحت في الإبراق والإرعاد … وغدا علي بسيل لومك غاد\nأنت الفتى كل الفتى لو أن ما … تسديه في التأنيب في الإسعاد\nلا تنكرن أن يشتكي ثقل الهوى … بدني فما أنا من بقية عاد\nكم وقعة لي في الهوى مشهورة … ما كنت فيها الحارث بن عباد\nرحل العزاء مع الرحيل ، كأنما … أخذت عهودها على ميعاد\nجاد الفراق بمن أضن بنأيه … بمسالك الإتهام والإنجاد\nوكأن أفئدة النوى مصدوعة … حتى تصدع بالفراق فؤادي\nفإذا فضضت من الليالي فرجة … خالفنها فسددنها ببعاد\nبل ذكرة طرقت فلما لم أبت … باتت تفكر في ضروب رقادي\nأغرت همومي فاستلبن فضولها … نومي ونمن على فضول وسادي\nوإلى جناب أبي المغيث تواهقت … خوص العيون موائر الأعضاد\nيلقين مكروه السرى بنظيره … من جده في النص والإسآد\nالآن جردت المدائح وانتهى … فيض القريض إلى عباب الوادي\nأضحت معاطن روضه ومياهه … وقفا على الرواد والوراد\nعذنا بموسى من زمان أنشرت … سطواته فرعون ذا الأوتاد\nجبل من المعروف معروف له … تقييد عادية الزمان العادي\nما لامرىء أسر القضاء رجاءه … إلا رجاؤك أوعطاؤك فادي\nوإذا المنون تخطمت صولاتها … عسفا بيوم توافق وطراد\nوضمائر الأبطال تقسم روعها … فيها ظهور ضمائر الأغماد\nوالخيل تستقي الرماح نحورها … مستكرها كعصارة الفرصاد\nأمتعت سيفك من يديك بضربة … لا تمتع الأرواح بالإجساد\nمن أبيض لبياض وجهك ضامن … حين الوجوه مشوبة بسواد\nقد كاد مضربه يجالد جفنه … لو لم تسكنه بيوم جلاد\nوالسيف مغف غير أن غراره … يقظ إذا هاد نحاه لهاد\nأحييت ثغر الجود منك بنائل … قد مات منه ثغر كل فساد\nجاهدت فيه المال عن حوبائه … والمال ليس جهاده كجهاد\nما للخطوب طغت علي كأنها … جهلت بأن نداك بالمرصاد\nولقد تراءتني بأمنع جنة … لما برزت لها وأنت عتادي\nمازلت أعلم أن شلوي ضائع … حتى جعلتك موئلي ومصادي\nسل مخبرات الشعر عني هل بلت … في قدح نار المجد مثل زنادي\nلم أبق حلبة منطق إلا وقد … سبقت سوابقها إليك جيادي\nأبقين في أعناق جودك جوهرا … أبقى من الأطواق في الأجياد\nوغدا تبين كيف غب مدائحي … إن ملن بي هممي إلى بغداد\nومفاوز المال يبعد شأوها … إن لم تكن جدواك فيها زادي\nومن العجائب شاعر قعدت به … هماته أوضاع عند جواد"},{"id":"diwan-abutammam:152","bookId":"diwan-abutammam","type":"poem","seq":152,"chapter":"البحر: بسيط تام","title":"أبا قدامة قد قدمت لي قدما","page":"","text":"أبا قدامة قد قدمت لي قدما … من المكارم صدقا غير ما مين\nضقنا بدينك فاحتجنا إلى الدين … مذ غبت عنا بوجه ساطع الزين\nوكنت عونا إذا دهر تخوننا … عينا علينا فأنت العون بالعين\nإن الجياد على علاتها صبر … ما إن تشكى الوجا في حاله الأين\nوالنصل يعمل إخلاصا بجوهره … لا باتكال على شحذ من القين"},{"id":"diwan-abutammam:153","bookId":"diwan-abutammam","type":"poem","seq":153,"chapter":"البحر: خفيف تام","title":"يا سمي الذي تبهل يدعو","page":"","text":"يا سمي الذي تبهل يدعو … ربه مخلصا له في قل اوحي\nوشبيه الذي استقلت به العي … ر عن الجب خاضعا كالطليح\nومكنى تتوق نفسي إليه … بالرسول الكريم بعد المسيح\nافصح اليوم ناظرا مستهام … نطقا عن ضمير قلب قريح"},{"id":"diwan-abutammam:154","bookId":"diwan-abutammam","type":"poem","seq":154,"chapter":"البحر: بسيط تام","title":"يقول في قومس صحبي وقد أخذت","page":"","text":"يقول في قومس صحبي وقد أخذت … بنا السرى وخطا المهرية القود\nأمطلع الشمس تنوي أن تؤم بنا … فقلت كلا ولكن مطلع الجود"},{"id":"diwan-abutammam:155","bookId":"diwan-abutammam","type":"poem","seq":155,"chapter":"البحر: وافر تام","title":"ليهنك يا سليل فقد هنتني","page":"","text":"ليهنك يا سليل فقد هنتني … بما عوفيت عافية هنيه\nيطول لك البقاء قرير عين … وتصرف عنك صائلة المنيه\nأرى الآمال ضاحكة الثنايا … تبسم عن عطاياك السنيه\nونور الشمس ما طلعت تباهي … بنور طلوع طلعتك البهيه\nبنيت بنية في المجد طالت … وطلت بطول مجدك في البنيه\nغنيت ببذل مالك في المعالي … فنفسك من إفادتها غنيه\nجنى لي فيك من ثمرات مدحي … لسان الشكر أبياتا جنيه\nوقد أهديتها لك وهي عندي … على الأيام من أزكى هديه"},{"id":"diwan-abutammam:156","bookId":"diwan-abutammam","type":"poem","seq":156,"chapter":"البحر: مجزوء الكامل","title":"أعطاك دمعك جهده","page":"","text":"أعطاك دمعك جهده … فشكا فؤادك وجده\nحملت نفسك في الهوى … ما لا تطيق فهده\nيا شامتا بي إذ رأى … هجر الحبيب وصده\nلا تشمتن فإنه … مولى يعذبث عبده"},{"id":"diwan-abutammam:157","bookId":"diwan-abutammam","type":"poem","seq":157,"chapter":"البحر: وافر تام","title":"أيا ويل الشجي من الخلي","page":"","text":"أيا ويل الشجي من الخلي … وبالي الربع من إحدى بلي\nوما للدار إلا كل سمح … بأدمعه وأضلعه سخي\nسنت عبراته الأطلال حتى … نزحن غروبها نزح الركي\nسقى الشرطان جزعك والثريا … ثراك بمسبل خضل روي\nفكم لي من هواء فيك صاف … غذي جوه وهوى وبي !\nوناضرة الصباحين اسبكرت … طلاع المرط في الدرع اليدي\nتشكى الأين من نصف سريع … إذا قامت ومن نصف بطي\nتعيرك مقلة نطفت ولكن … قصاراها على قلب بري\nسأشكر فرجة اللبب الرخي … ولين أخادع الدهر الأبي\nوإن لدي للحسن بن وهب … حباء مثل شؤبوب الحبي\nأقول لعثرة الأدب التي قد … أوت منه إلى فيح دفي\nأميلوا العيس تنفح في براها … إلى قمر الندامى والندي\nفقد جعل الإله لكم لسانا … عليا ذكره بأبي علي\nأغر إذا تمرغ في نداه … تمرغنا على كرم وطي\nلعمر بني أبي دينا وعمري … وعمر أبي وعمر بني عدي\nلقد جلى كتابك كل بث … جو وأصاب شاكلة الرمي\nفضضت ختامه فتبلجت لي … غرائبه عن الخبر الجلي\nوكان أغض في عيني وأندى … على كبدي من الزهر الجني\nوأحسن موقعا مني وعندي … من البشرى أتت بعد النعي\nوضمن صدره مالم تضمن … صدور الغنيات من الحلي\nفكائن فيه من مغنى خطير … وكائن فيه من لفظ بهي\nوكم أفصحت عن بر جليل … به ووأيت من وأي سني\nكتبت به بلا لفظ كريه … على أذن ولاخط قمي\nفأطلق من عقالي في الأماني … ومن عقل القوافي والمطي\nوفي رمضاء من رمضان تغلي … بهامة لا الحصور ولا التقي\nفيا ثلج الفؤاد وكان رضفا … ويا شبعي إذا يمضي وربي\nرسالة من تمتع بعد حين … ومتعنا من الأدب الرضي\nلئن غربتها في الأرض بكرا … لقد جليت على سمع كفي\nوإن تك من هداياك الصفايا … فرب هدية لك كالهدي\nبيان لم ترثه تراث دعوى … ولم تنبطه من حسي بكي\nعشوت على عداتك فيه حتى … خطوت به على أمل مضي\nفناهض بي من الأسفار وجها … مهاريه ضوامر كالحني\nفلست ترى أقل هوى ونفسا … وألزم للدنو من الدني\nنبت على خلائق منك بيض … كما نبت الحلي على الولي\nفمن جود تدفق سيله لي … على مطر ومن جود أتي\nومن جود له حولي صريف … بنابيه ومن عرف فتي\nومحدود الذريعة ساء ه ما … ترشح لي من السبب الحظي\nيدب إلي في شخص ضئيل … وينظر من شفا طرف خفي\nويتبع نعمتي بك عين ضغن … كما نظر اليتيم إلى الوصي\nرجاء أنه يوري بزندي … إليك وأنه يفري فريي\nوذاك له إذا العنقاء صارت … مرببة وشب ابن الخصي\nأرى الإخوان ماغيبت عنهم … بمقسط ذلك الشعب القصي\nومردود صفاؤهم عليهم … كما رد النكاح بلا ولي\nوهم ما دمت كوكبهم وساروا … بريحك في غدو أو عشي\nفحينئذ خلا بالقوس بار … وأفرغت الأداة على الكمي\nوإن لهم لإحسانا ولكن … جرى الوادي فطم على القري\nوهل من جاء بعد الفتح يسعى … كصاحب هجرتين مع النبي ؟ !"},{"id":"diwan-abutammam:158","bookId":"diwan-abutammam","type":"poem","seq":158,"chapter":"البحر: مجزوء الخفيف","title":"لا وورد بخده","page":"","text":"لا وورد بخده … واعتدال بقده\nلا تعشقتث غيره … لو براني بصده\nإن يكن أسقم الهوى … بعد تصحيح وده\nفعساه بعد التم … يرثي لعبده"},{"id":"diwan-abutammam:159","bookId":"diwan-abutammam","type":"poem","seq":159,"chapter":"البحر: كامل تام","title":"داع دعا بلسان هاد مرشد","page":"","text":"داع دعا بلسان هاد مرشد … فأجاب عزم هاجد في مرقد\nنادى وقد نشر الظلام سدوله … والنوم يحكم في عيون الرقد\nيا ذائد الهيم الخوامس وفها … عشرا واف بها حياض محمد\nيمددن للشرف المنيف صواديا … أعناقهن إلى حياض السؤدد\nوتنبهت فكر فبتن هواجسا … في قلب ذي سمر بها متهجد\nلما رأيتك يا محمد تصطفي … صفو المحامد من ثناء المجتدي\nسيرت فيك مدائحي فتركتها … غررا تروح بها الرواة وتغتدي\nمالي إذا ما رضت فيك غربية … جاءت مجيء نجيبة في مقود !\nما ذاك إلا أن زندك لم يكن … في كف قادحه بزند مصلد\nصدقت مدحي فيك حين رعيتني … لتحرمي بالسيد المتشهد\nولجأت منك إلى ابن ملك أنبأت … عنه خلائقه بطيب المحتد\nملك يجود ولا يؤامر آمرا … فيه ويحكم في جداه المجتدي\nويقول والشرف المنيف يحفه … لا خير في شرف إذا لم أحمد\nوأكون عند ظنون طلاب الندى … وأذب عن شرفي بما ملكت يدي\nيأبى لعرضي أن يكون مشعثا … جود وقاه بطارف وبمتلد\nولراحتيه ديمتان : قديمة … لي بالوداد وديمة بالعسجد\nكم من ضريك قد بسطت يمينه … بعد التحين في ثراء سرمد\nولرب حرب حائل لقحتها … ونتجتها من قبل حين المولد\nفإذا بعثت لناكثين عزيمة … عصفت رؤوسق من سيوف ركد\nإن الخلافة لوجزتك بموقف … جعلت مثالك قبلة للمسجد\nوسعت إليك جنودها حتى إذا … وافتك خر لديك كل مقلد\nوالله يشكر والخليفة موقفا … لك شائعا بالبذ صعب المشهد\nفي مأزق ضنك المكر مغصص … أزز المجال من القنا المتقصد\nنازلت فيه مفندا في دينه … لا بأسه فرآك غير مفند\nفعلوت هامته فطار فراشها … بشهاب موت في اليدين مجرد\nيافارس الإسلام أنت حميته … وكفيته كلب العدو المعتدي\nونصرته بكتائب صيرتها … نصبا لعورات العدو بمرصد\nأصبحت مفتاح الثغور وقفلها … وسداد ثلمتها التي لم تسدد\nأدركت فيه دم الشهيد وثاره … وفلجت فيه بشكر كل موحد\nضحكت له أكباد مكة ضحكها … في يوم بدر والعتاة الشهد\nأحييت للإسلام نجدة خالد … وفسحت فيه لمتهم ولمنجد\nلو أن هرثمة بن أعين في الورى … حي وعاين فضله لم يجحد\nأو شاهد الحرب الممر مذاقها … لرآه أقمع للعتاة العند\nوأجر للخيل المغيرة في السرى … وأذب منه باللسان وباليد\nأما الجياد فقد جرت فسبقتها … وشربت صفو زلالها في المورد\nغادرت طلحة في الغبار وحاتما … وأبان حسرى عن مداك الأبعد\nوطلعت في درج العلى حتى إذا … جئت النجوم نزلت فوق الفرقد\nفانعم فكنيتك التي كنيتها … فأل جرى لك بالسعادة فاسعد\nولقد وفدت إلى الخليفة وفدة … كانت على قدر بعد الأسعد\nزرت الخليفة زورة ميمونة … مذكورة قطعت رجاء الحسد\nيتنفسون فتنثني لهواتهم … من جمرة الحسد التي لم تبرد\nنفسوك فالتمسوا نداك فحاولوا … جبلا يزل صفيحه بالمصعد\nدرست صفائح كيدهم فكأنما … أذكرن أطلالا برقة ثمهد"},{"id":"diwan-abutammam:160","bookId":"diwan-abutammam","type":"poem","seq":160,"chapter":"البحر: متقارب تام","title":"نعاء إلى كل حي نعاء","page":"","text":"نعاء إلى كل حي نعاء … فتى العرب احتل ربع الفناء\nأصبنا جميعا بسهم النضال … فهلا أصبنا بسهم الغلاء ! !\nألا أيها الموت فجعتنا … بماء الحياة وماء الحياء\nفماذا حضرت به حاضرا … وماذا خبأت لاهل الخباء !\nنعاء نعاء شقيق الندى … إليه نعيا قليل الجداء\nوكانا جميعا شريكي عنان … رضيعي لبان خليلي صفاء\nعلى خالد بن يزيد بن مز … يد امر دموعا نجيعا بماء\nولا ترين البكا سبة … ألصق جوى بلهيب رواء\nفقد كثر الرزء قدر الدموع … وقد عظم الخطب شأن البكاء\nفباطنه ملجأ للأسى … وظاهره ميسم للوفاء\nمضى الملك الوائلي الذي … حلبنا به العيش وسع الإناء\nفأودى الندى ناضر العود وال … فتوة مغموسة في الفتاء\nفأضحت عليه العلى خشعا … وبيت السماحة ملقى الكفاء\nوقد كان مما يضيء السرير … والبهو يملأه بالبهاء\nالملك عن خالد والملوك … بقمع العدى وبنفي العداء\nألم يك أقتلهم للأسود … صبرا وأوهبهم للظباء ؟ !\nألم يجلب الخيل من بابل … شوازب مثل قداح السراء\nفمد على الثغر إعصارها … برأي حسام ونفس فضاء\nفلما تراءت عفاريته … سنا كوكب جاهلي السناء\nوقد سد مندوحة القاصعاء … منهم وأمسك بالنافقاء\nطوى أمرهم عنوة في يديه … طي السجل وطي الرداء\nأقروا لعمري بحكم السيوف … وكانت أحق بفضل القضاء\nوما بالولاية إقرارهم … ولكن أقروا له بالولاء\nأصبنا بكنز الغنى والإمام … أمسى مصابا بكنز الغناء\nوما إن أصيب براعي الرعية … لا بل أصيب براعي الرعاء\nيقول النطاسي إذ غيبت … عن الداء حيلته والدواء\nونبو المقيل به والمبيت … أقعصه واختلاف الهواء\nوقد كان لو رد غرب الحمام … شديد توق طويل احتماء\nمعرسه في ظلال السيوف … ومشربه من نجيع الدماء\nذرى المنبر الصعب من فرشه … ونار الوغا ناره للصلاء\nوما من لبوس سوى السابغات … ترقرق مثل متون الإضاء\nفهل كان مذ كان حتى مضى … حميدا له غير هذا الغذاء\nأذهل بن شيبان ذهل الفخار … وذهل النوال وذهل العلاء\nمضى خالد بن يزيد بن مز … يد قمر الليل شمس الضحاء\nوخلى مساعيه بينكم … فإياي فيها وسعي البطاء\nردوا الموت مرا ورود الرجال … وبكوا عليه بكاء النساء\nغليلي علي خالد خالد … وضيف همومي طويل الثواء\nفلم يخزني الصبر عنه ولا … تقنعت عارا بلؤم العزاء\nتذكرت خضرة ذاك الزمان … لديه وعمران ذاك الفناء\nوزواره للعطايا حضور … كأن حضورهم للعطاء\nوإذ علم مجلسه مورد … زلال لتلك العقول الظماء\nتحول السكينة دون الأذى … به والمروة دون المراء\nوإذ هو مطلق كبل المصيف … وإذ هو مفتاح قيد الشتاء\nلقد كان حظي غير الخسيس … من راحتيه وغير اللفاء\nوكنت أراه بعين الرئيس … وكان يراني بعين الإخاء\nألهفي على خالد لهفة … تكون أمامي وأخرى ورائي\nألهفي إذا ما ردى للردى … ألهفي إذا ما احتبى للحباء\nألحد حوى حية الملحدين … ولدن ثرى حال دون الثراء ؟ !\nجزت ملكا فيه ريا الجنوب … ورائحة المزن خير الجزاء\nفكم غيب الترب من سؤدد … وغال البلى من جميل البلاء !\nأبا جعفر ليعرك الزمان … عزا ويكسبك طول البقاء\nفما مزنك المرتجى بالجهام … ولاريحنا منك بالجربياء\nولا رجعت فيك تلك الظنون … حيارى ولا انسد شعب الرجاء\nوقد نكس الثغر فابعث له … صدور القنا في ابتغاء الشفاء\nفقد فات جدك جد الملوك … وعمر أبيك حديث الضياء\nولم يرض قبضته للحسام … ولا حمل عاتقه للرداء\nفما زال يفرع تلك العلى … مع النجم مرتديا بالعماء\nويصعد حتى لظن الجهول … أن له منزلا في السماء\nوقد جاءنا أن تلك الحروب … إذا حديت فالتوت بالحداء\nوعاودها جرب لم يزل … يعاود أسعافها بالهناء\nويمتح سجلا لها كالسجال … ودلوا إذا أفرغت كالدلاء\nومثل قوى حبل تلك الذراع … كان لزازا لذاك الرشاء\nفلا تخز أيامه الصالحات … وما قد بنى من جليل البناء\nفقد علم الله أن لن تحب … شيئا كحبك كنز الثناء"},{"id":"diwan-abutammam:161","bookId":"diwan-abutammam","type":"poem","seq":161,"chapter":"قصائد","title":"صد ومااحتسب الصدا","page":"","text":"صد ومااحتسب الصدا … لم يحفظ الميثاق والعهدا\nولا رعى ودي ولاحرمتي … ولم أزل أرعى له الودا\nيا قاتلي ظلما بسيف الهوى … إذ صرت عبدا فارحم العبدا\nقد والذي عذب قلبي بكم … قاسيت مذ فارقتني جهدا"},{"id":"diwan-abutammam:162","bookId":"diwan-abutammam","type":"poem","seq":162,"chapter":"البحر: كامل تام","title":"أجفان خوط البانة الأملود","page":"","text":"أجفان خوط البانة الأملود … مشغولة بك عن وصال هجود\nسكبت ذخيرة دمعة مصفرة … في وجنة محمرة التوريد\nفكأن وهي نظامها نظم وهي … من يارق وقلائد وعقود\nأذكت حميا وجدها حمة الأسى … فغدت بنار غير ذات خمود\nطلعت طلوع الشمس في طرف النوى … والشمس طالعة بطرف حسود\nوتأملت شبحي بعين أيدت … عمد الهوى في قلبي المعمود\nفنحرت حسن الصبر تحت الصدر عن … جيد بواضح نحرها والجيد\nحاشى لجمر حشاي أن يلقى الحشا … إلا بلفج مثل لفج وقود\nأضحى الذي بقته نيران الحشا … مني حبيسا في سبيل البيد\nأذراء أمطاء الغنى يضحكن عن … أذراء أمطاء المطايا القود\nفظللت حد الأرض تحت العزم في … وجناء تدني حد كل بعيد\nتحثو إذا حث العتاق الوخد في … غرر العتاق النقع بالتوحيد\nتعريسها خلل السر تقريبها … حتى أنخت بأحمد المحمود\nفحططت تحت غمامة مغمورة … بحيا بروق ضاحكا ورعود\nتلقاه بين الزائرين كأنه … قمر السماء يلوح بين سعود\nلو فاح عود في الندي وذكره … لعلا بطيب الذكر طيب العود\nولاه منصور سماح يمينه … ومضى فقيد المثل غير فقيد\nفيرى فناء المال أفضل ذخره … وخلود ذكر الحمد خير خلود\nيبدي أبوالحسن اللهى ويعيدها … فمؤملوه من اللهى في عيد\nحييت غرته بحسن مدائح … غر فحيا غرتي بالجود\nلو رام جلمودا بجانب صخرة … يوما لرضض جانب الجلمود\nوإذا الثغور استنصرته شبا القنا … أروى الشبا من ثغرة ووريد\nيستل إثر عدوها عزماته … فيعمها بالنصر والتأييد\nذو ناظر حدب وسمع عائر … نحو الطريد الصارخ المجهود\nتلقاه منفردا وتحسب أنه … من عزمه في عدة وعديد\nياأيها الملك المرجى والذي … قدحت به فطني نظام نشيدي\nأنا راجل ببلاد مرو راكب … في جودة الأشعار كل مجيد\nفأعز ذلة رجلتي بمهذب … حلو المخيل مقذذ مقدود\nذي كمتة أوشقرة أو حوة … أو دهمة فهم الفؤاد سديد\nتتنزه اللحظات في حركاته … كتنزهي في ظلك الممدود\nمتسربل بردا يفوق بوشيه … بين المواكب حسن وشي برود\nفإذا بدا في مشهد قامت له … نبلاء صدر المحفل المشهود\nيجد السرور الراكب الغادي به … كسروره بالفارس المولود\nإن سابقته الخيل في ميدانها … قذفت إليه الخيل بالإقليد\nفيروح بين مؤبيه مخالفا … متعصبا بعصابة التسويد\nومشيعوده معوذوه بكل ما … عرفوه من عوذ من التحميد\nيتعشقون نضارة في وجهه … عضق الفتى وجه الفتاة الرود\nأغضى عليك جفون شكرك إنها … ثقلت علي لجودك الموجود\nإني اعتصمت بطول طودك إنه … طود يقوم مقام طود حديد\nلا يهتدي صرف الزمان إلى امرىء … متصرف بفنائك المعهود"},{"id":"diwan-abutammam:163","bookId":"diwan-abutammam","type":"poem","seq":163,"chapter":"البحر: كامل تام","title":"أمحمد بن سعيد ادخر الأسى","page":"","text":"أمحمد بن سعيد ادخر الأسى … فيها وراء الحر يوم ظمائه\nأنت الذي لا تعذل الدنيا إذا … ما النائبات صفحن عن حوبائه\nلو كان يغنى حازم عن واعظ … كنت الغني بخزمه وذكائه\nلست الفتى إن لم تعر مدامعا … من مائها والوجد بعد بمائه\nوإذا رأيت أسى امرئ أو صبره … يوما فقد عاينت صورة رائه\nإني أرى ترب المروءة باكيا … فأكاد أبكي معظما لبكائه\nحق على أهل التيقظ والحجى … وقضاء طب عالم بقضائه\nألا يعزى جاذع بحميمه … حتى يعزى أولا بعزائه"},{"id":"diwan-abutammam:164","bookId":"diwan-abutammam","type":"poem","seq":164,"chapter":"البحر: خفيف تام","title":"أنا في لوعة وحزن شديد","page":"","text":"أنا في لوعة وحزن شديد … ليس عندي للوعة من مزيد\nبأبي شادن تنسمت من عي … نيه يوم الخميس ريح الصدود\nصار ذنبي كذنب آدم يا عمر … رو ، فأخرجت من جنان الخلود\nأناأفدي ساجي الجفون يسمى … ويكنى ببعض عبد الحميد"},{"id":"diwan-abutammam:165","bookId":"diwan-abutammam","type":"poem","seq":165,"chapter":"البحر: كامل تام","title":"عن فشاقك طائر غريد","page":"","text":"عن فشاقك طائر غريد … لما ترنم والغصون تميد\nساق على ساق دعا قمرية … فدعت تقاسمه الهوى وتصيد\nإلفان في ظل الغصون تألفا … والتف بينهما هوى معقود\nيتطعمان بريق هذا هذه … مجعا وذاك بريق تلك معيد\nيا طائران تمتعا هنيتما … وعما الصباح فإنني مجهود\nآه لوقع البيي يابن محمد … بين المحب على المحب شديد\nأبكي وقد سمت البروق مضيئة … من كل أقطار السماء رعود\nواهتز ريعان الشباب فأشرقت … لتهلل الشجر القرى والبيد\nومضت طواويس العراق فأشرقت … أذناب مشرقة وهن حفود\nيرفلن أمثال العذارى طوفا … حول الدوار وقد تجانى العيد\nإني سأنثر من لساني لؤلؤا … يرد العراق نظامه معقود\nحتى يحل من المهلب منزلا … للمجد في غرفاته تشييد\nرفع الخلافة راية فتقاصرت … عنها الرجال وحازها داود\nالسيد العتكي غير مدافع … إذ ليس سؤدد سيد موجود\nنقرت باسمك في الظلام مسدرا … داود إنك في الفعال حميد\nقد قيل : أين تريد ، قلت : أخا الندى … وأبا سليمان الأغر أريد\nفافتح بجودك قفل دهري إنه … قفل وجود يديك لي إقليد\nفالجود حي ما حييت وإن تمت … غاضت مناهله ومات الجود"},{"id":"diwan-abutammam:166","bookId":"diwan-abutammam","type":"poem","seq":166,"chapter":"البحر: طويل","title":"هو الدهر لا يشوي وهن المصائب","page":"","text":"هو الدهر لا يشوي وهن المصائب … وأكثر آمال الرجال كواذب\nفيا غالبا لاغالب لرزية … بل الموت لاشك الذي هو غالب\nوقلت أخي ، قالوا أخ ذو قرابة ؟ … فقلت ولكن الشكول أقارب\nنسيبي في عزم ورأي ومذهب … وإن باعدتنا في الأصول المناسب\nكأن لم يقل يوما كأن فتنثني … إلى قوله الأسماع وهي رواغب\nولم يصدع النادي بلفظة فيصل … سنانية في صفحتيها التجارب\nولم أتسقط ريب دهري برأيه … فلم يجتمع لي رأيه والنوائب\nمضى صاحبي واستخلف البث والأسى … \nعبجت لصبري بعده وهو ميت … وكنت امرءا أبكي دما وهو غائب\nعلى أنها الأيام قد صرن كلها … عجائب حتى ليس فيها عجائب !"},{"id":"diwan-abutammam:167","bookId":"diwan-abutammam","type":"poem","seq":167,"chapter":"البحر: سريع","title":"وفاتن الألحاظ والخد","page":"","text":"وفاتن الألحاظ والخد … معتدل القامة والقد\nصيرني عبدا له حسنه … والطرفث قد صيره عبدي\nقال وعيني منه في عينه … راتعة في جنة الخلد\nطرفك زان قلتث دمعي اذا … بجلده أكثر من حد\nواحمر حتى كدت أن لا أرى … وجنته من كثرة الورد\nالحسن والطيب إذا استجمعا … عبدان عندي لأبي عبد"},{"id":"diwan-abutammam:168","bookId":"diwan-abutammam","type":"poem","seq":168,"chapter":"البحر: كامل تام","title":"حل الأمير محل رفد الرافد","page":"","text":"حل الأمير محل رفد الرافد … ومبيح طارف ماله والتالد\nلله درك من كريم ماجد … سهل الخليقة في المكارم واحد\nالدهر يسمح بالتي تهب الغنى … لمؤمل من صادر أو وارد\nفعلام أصبح من نداك بمعزل … وسواي تلحظه بعين الوالد\nكم للأمير محمد من شاكر … في العالمين وكم له من حامد\nاليأس ألزمني محل القاعد … إذ ليس جدي في الجدود بصاعد\nما لي حرمت لديك حظوة خالد … أوز لست حرمة من خالد ؟\nعوز الرجال أقام منة خالد … والصيف نفق سوق برد البارد\nشخصان أفاكان قيلهما الخنا … حلا لديك محل عمرو الزاهد !"},{"id":"diwan-abutammam:169","bookId":"diwan-abutammam","type":"poem","seq":169,"chapter":"البحر: خفيف تام","title":"ريب دهر أصم دون العتاب","page":"","text":"ريب دهر أصم دون العتاب … مرصد بالأوجال والأوصاب\nجف در الدنيا فقد أصبحت تك … تال أرواحنا بغير حساب\nلو بدت سافرا أهينت ولكن … شعف الخلق حسنها في النقاب\nإن ريب الزمان يحسن أن يه … دي الرزايا إلى ذوي الأحساب\nفلهذا يجف بعد اخضرار … قبل روض الوهاد روض الروابي\nلم تدر عينه عن الحمس حتى … ضعضعت ركن حمير الأرباب\nبطشت منهم بلؤلؤة الغوا … ص حسنا ودمية المحراب\nبالصريح الصريح والأروع الأر … وع منهم وباللباب اللباب\nذهبت محمد الغر من أيا … مك الواضحات أي ذهاب !\nعبس اللهد والثرى منك وجها … غير ما عابس ولا قطاب\nأطفأ اللحد والثرى لبك المس … رج في وقت ظلمة الألباب\nوتبدلت منزلا ظاهر الجد … ب يسمى مقطع الأسباب\nمنزلا موحشا وإن كان مع … مورا بحل الصديق والأحباب\nيا شهابا خبا لآل عبيد الل … ه أعزز بفقد هذا الشهاب !\nزهرة غضة تفتق عنها ال … مجد في منبت أنيق الجناب\nخلق كالمدام أو كرضاب المس … ك أو كالعبير أو كالملاب\nوحيا ناهيك في غير عي … وصبا مشرق بغير تصاب\nأنزلته الأيام عن ظهرها من … بعد إثبات رجله في الركاب\nحين سامى الشباب واغتدت الدن … يا عليه مفتوحة الأبواب\nوحكى الصارم المحلى سوى أن … حلاه جواهر الآداب\nوهو غض الآراء والحزم خرق … ثم غض النوال غض الشباب\nقصدت نحوه المنية حتى … وهبت حسن وجهه للتراب"},{"id":"diwan-abutammam:170","bookId":"diwan-abutammam","type":"poem","seq":170,"chapter":"البحر: بسيط تام","title":"رأيت في النوم أن الصلح قد فسدا","page":"","text":"رأيت في النوم أن الصلح قد فسدا … أن مولاي بعد القرب قد بعدا\nلم لم أمت حزنا لم لم أمت أسفا … لم لم أمت جزعا لم لم أمت كمدا !\nقد كدت احلف لولا أن ذا سرف … ألا أذوق مناما بعدها أبدا\nأصبحت من زفرات لا أقوم بها … أشكوالرقاد إذاغيري شكاالسهدا"},{"id":"diwan-abutammam:171","bookId":"diwan-abutammam","type":"poem","seq":171,"chapter":"البحر: وافر تام","title":"نوار في صواحبها نوار","page":"","text":"نوار في صواحبها نوار … كما فاجاك سرب أو صوار\nتكذب حاسد فنأت قلوب … أطاعت واشيا ونأت ديار\nقفا نعط المنازل من عيون … لها في الشوق أحساء غزار\nعفت آياتهن وأي ربع … يكون له على الزمن الخيار !\nأثاف كالخدود لطمن حزنا … ونؤي مثلما انفصم السوار\nوكانت لوعة ثم اطمأنت … كذاك لكل سائل قرار\nمضى الأملاك فانقرضوا وأمست … سراة ملوكنا وهم تجار\nوقوف في ظلال الذم تحمى … دراهمها لا يحمى الذمار\nفلو ذهبت سنات الدهر عنه … وألقي عن مناكبه الدثار\nلعدل قسمة الأرزاق فينا … ولكن دهرنا هذا حمار !\nسيبتعث الركاب وراكبيها … فتى كالسيف هجعته غرار\nأطل على كلى الآفاق حتى … كأن الأرض في عينيه دار\nيقول الحاسدون إذا انصرفنا … لقد قطعوا طريقا أوأغاروا\nنؤم أبا الحسين وكان قدما … فتى أعمار موعده قصار\nله خلق نهى القرآن عنه … وذاك عطاؤه السرف البدار\nولم يك منك إضرار ولكن … تمادت في سجتها البحار\nيطيب لجوده ثمر الأماني … وتروى عنده الهمم الحرار\nرفعت كواعب الأشعار فيه … كما رفعت لناظرها المنار\nحليم والحفيظة منه خيم … وأي النار ليس لها شرار ؟\nتحن عداته إثر التقاضي … وتنتج مثلما نتج العشار\nأرى الداليتين على جفاء … لديك وكل واحدة نضار\nإذا ما شعر قوم كان ليلا … تبلجتا كما انشق النهار\nوإن كانت قصائدهم جدوبا … تلونتا كما ازدوج البهار\nأغرتهما وغيرهما محلى … بجودك والقوافي قد تغار\nوغيرك يلبس المعروف خلفا … ويأخذ ، من مواعده الصفار\nرأيت صنائعا معكت فأمست … ذبائح والمطال لها شفار\nوكان المطل في بدء وعود … دخانا للضنيعة وهي نار\nنسيب البخل مذ كانا وإلا … يكن نسب فبينهما جوار\nلذلك قيل بعض المنع أدنى … إلى كرم وبعض الجود عار\nفدع ذكر الضياع فبي شماس … إذا ذكرت وبي عنها نفار\nومالي ضيعة إلا المطايا … وشعر لا يباع ولا يعار\nوما أنا والعقار ولست منه … على ثقة وجودك لي عقار"},{"id":"diwan-abutammam:172","bookId":"diwan-abutammam","type":"poem","seq":172,"chapter":"البحر: سريع","title":"أي ندى بين الثرى والحبوب","page":"","text":"أي ندى بين الثرى والحبوب … وسؤدد لدن ورأي صليب !\nياابن أبي ربعي استقبلت … من يومك الدنيا بيوم عصيب\nشق جيوبا من رجال لو … اسطاعوا لشقوا ما وراء الجيوب\nكنت على البعد قريبا فقد … صرت على قربك غير القريب\nراحت وفود الأرض عن قبره … فارغة الأيدي ملاء القلوب\nقد علمت مارزئت إنما … يعرف فقد الشمس بعد الغروب\nإذا البعيد الوطن انتابه … حل إلى نهي وجزع خصيب\nأدنته أيدي العيس من ساحة … كأنها مسقط رأس الغريب\nأظلمت الآمال من بعده … وعريت من كل حسن وطيب\nكانت خدودا صقلت برهة … فاليوم صارت مألفا للشحوب\nكم حاجة صارت ركوبا به … ولم تكن من قبله بالركوب !\nحل عقاليها كما أطلقت … من عقد المزنة ريح الجنوب\nإذا تيممناه في مطلب … كان قليبا أو رشاء القليب\nونعمة منه تسربلتها … كأنها طرة ثوب قشيب\nمن اللواتي إن ونى شاكر … قامت لمسديها مقام الخطيب\nمتى تنخ ترحل بتفضيله … أو غاب يوما حضرت بالمغيب\nفما لنا اليوم ولا للعلى … من بعده غير الأسى والنحيب"},{"id":"diwan-abutammam:173","bookId":"diwan-abutammam","type":"poem","seq":173,"chapter":"البحر: منسرح","title":"بلغت بي فوق غاية الكمد","page":"","text":"بلغت بي فوق غاية الكمد … أبكيت عيني آخر الأبد\nواكبدي يوشك الرقيب بأن … يمنعني أن أقول واكبدي\nلست ألوم الحساد يا أحسن … س لإجماعهم على حسدي\nكيف ألوم الحسود فيك وقد … رأى هلال السماء طوع يدي ؟"},{"id":"diwan-abutammam:174","bookId":"diwan-abutammam","type":"poem","seq":174,"chapter":"البحر: سريع","title":"قل للأمير الاريحي الذي","page":"","text":"قل للأمير الاريحي الذي … كفاه للبادي وللحاضر\nلتجزك الأيام مندوحة … ونضرة من عودي الناضر\nأشكر نعمى منك مشكورة … وكافر النعماء كالكافر\nموهبا لم تك إلا لمن … نصابه في منصب وافر\nلازلت من شكري في حلة … لابسها ذو سلب فاخر\nيقول من تقرع أسماعه … كم ترك الأول للآخر\nلي صاحب قد كان لي مؤنسا … ومألفا في الزمن الغابر\nيحتلب الدهر أفاويقه … ويخلط الحلو مع الحازر\nحتى إذا روضي تغنى به … ذبانه في مونق زاهر\nألقح بالعزم أمانيه … بعد اعتناق الهمة العاقر\nتحمل منه العيس أعجوبة … تجدد السخري للساخر\nذا ثروة يطلب من سائل … ومفحما يأخذ من شاعر !\nفصادفت مالي بإقباله … منية من أمل عاثر\nفشارك المقمور فيه ولا … تكن شريك الرجل القامر\nفرفدك الزائر مجد ولا … كرفدك الزائر للزائر"},{"id":"diwan-abutammam:175","bookId":"diwan-abutammam","type":"poem","seq":175,"chapter":"البحر: خفيف تام","title":"دأب عيني البكاء والحزن دابي","page":"","text":"دأب عيني البكاء والحزن دابي … فاتركيني وقيت ما بي لما بي\nسأجزي بقاء أيام عمري … بين بثي وعبرتي واكتئابي\nفيك يا أحمد بن هارون خصت … ثم عمت رزيئتي ومصابي\nفجعتني الأيام فيك فأنسي … في اختلالي وعصمتي في اضطرابي\nفجعتني الأيام بالصادق النط … ق فتى المكرمات والآداب\nبخليل دون الأخلاء لا بل … صاحبي المصطفى على أصحابي\nشمري يحتل من سلفي مر … وان في الأكرمين والصياب\nأفلما تسربل المجد واج … تاب من الحمد أيما مجتاب\nوتراءته أعين الناظريه … قمرا باهرا ورئبال غاب\nوعلا عارضيه ماء الندى الجا … ري وماء الحجى وماء الشباب\nأرسلت نحوه المنية عينا … قطعت منه أوثق الأسباب"},{"id":"diwan-abutammam:176","bookId":"diwan-abutammam","type":"poem","seq":176,"chapter":"البحر: سريع","title":"وفى البكا بالعهد اذ لم يكن","page":"","text":"وفى البكا بالعهد اذ لم يكن … للصبر ميثاق ولا عهد\nنغصت حسن النرجس الغض مذ … \n … يجتمع النرجس والورد"},{"id":"diwan-abutammam:177","bookId":"diwan-abutammam","type":"poem","seq":177,"chapter":"البحر: طويل","title":"محمد إني بعدها لمذمم","page":"","text":"محمد إني بعدها لمذمم … إذا ما لساني خانني فيك أوشكري\nلئن بقيت لي فيك آثار منطق … لقد بقيت ثار كفيك في دهري\nلقيت صروف الدهر دوني تابعا … لأمر العلى فاخترت شكري على عذري\nفأوليتني في النائبات صنائعا … كأن أياديها فجرن من\nخلائق لوكانت من الشعر سمجت … بدائعها ما استحسن الناس من شعري\nفعلمتني أن ألبس الحمد أهله … وذكرتني ما قد نسيت من الشكر"},{"id":"diwan-abutammam:178","bookId":"diwan-abutammam","type":"poem","seq":178,"chapter":"البحر: طويل","title":"جفوف البلى أسرعت في الغصن الرطب","page":"","text":"جفوف البلى أسرعت في الغصن الرطب … وخطب الردى والموت أبرحت من خطب\nلقد شرقت في الشرق بالموت غادة … تعوضت منها غربة الدار في الغرب\nوألبسني ثوبا من الحزن والأسى … هلال عليه نسج ثوب من الترب\nأقول وقد قالوا استراحت بموتها … من الكرب روح الموت شر من الكرب\nلقد نزلت ضنكا من اللحد والثرى … ولو كان رحب الذرع ماكان بالرحب\nوكنت أرجي القرب وهي بعيدة … فقد نقلت بعدي عن البعد والقرب\nلها منزل تحت الثرى وعهدتها … لها منزل بين الجوانح والقلب"},{"id":"diwan-abutammam:179","bookId":"diwan-abutammam","type":"poem","seq":179,"chapter":"البحر: خفيف تام","title":"خلس البين أحمد بن يزيد","page":"","text":"خلس البين أحمد بن يزيد … ليس فعل الأيام بالمحمود\nونأى الهجر بالذي لا أسمي … فأنا اليوم في القريب البعيد\nففراق أصابني من فراق … وفراق أصابني من صدود\nليس من كان غائبا فقدته … العين غيبا الكشاهد المفقود"},{"id":"diwan-abutammam:180","bookId":"diwan-abutammam","type":"poem","seq":180,"chapter":"البحر: كامل تام","title":"لا أنت أنت ولا الديار ديار","page":"","text":"لا أنت أنت ولا الديار ديار … خف الهوى وتولت الأوطار\nكانت مجاورة الطلول وأهلها … زمنا عذاب الورد فهي بحار\nأيام تدمي عينه تلك الدمى … فيها وتقمر لبه الأقمار\nإذ لا صدوف ولا كنود اسماهما … كالمعنيين ولا نوار نوار\nبيض فهن إذا رمقن سوافرا … صور وهن إذا رمقن صوار\nفي حيث يمتهن الحديث لذي الصبا … وتحصن الأسرار والأسرار\nإذ في القتادة وهي أبخل أيكة … ثمر وإذ عود الزمان نضار\nقد صرحت عن محضها الأخبار … واستبشرت بفتوحك الأمصار\nخبر جلا صدأ القلوب ضياؤه … إذ لاح أن الصدق منه نهار\nلولا جلاد أبي سعيد لم يزل … للثغر صدر ما عليه صدار\nقدت الجياد كأنهن أجادل … بقرى درولية لها أوكار\nحتى التوى من نقع قسطلها على … حيطان قسطنطينة الإعصار\nأوقدت من دون الخليج لأهلها … نارا لها خلف الخليج شرار\nإلا تكن حصرت فقد أضحى لها … من خوف قارعة الحصار حصار\nلو طاوعتك الخيل لم تقفل بها … والقفل فيه شبا ولا مسمار\nلما لقوك تواكلوك وأعذروا … هربا ، فلم ينفعهم الإعذار\nفهناك نار وغى تشب وهاهنا … جيش له لجب وثم مغار\nخشعوا لصولتك التي هي عندهم … كالموت يأتي ليس فيه عار\nلما فصلت من الدروب إليهم … بعرمرم للأرض منه خوار\nإن يبتكر ترشده أعلام الصوى … أو يسر ليلا فالنجوم منار\nفالحمة البيضاء ميعاد لهم … والقفل حتم والخليج شعار\nعلموا بأن الغزو كان كمثله … غزوا وأن الغزو منك بوار\nفالمشي همس والنداء إشارة … خوف انتقامك والحديث سرار\nإلا تنل منويل أطراف القنا … أو تثن عنه البيض وهي حرار\nفلقد تمنى أن كل مدينة … جبل أصم وكل حصن غار\nإلا تفر فقد أقمت وقد رأت … عيناك قدر الحرب كيف تفار\nفي حيث تستمع الهرير إذا علا … وترى عجاج الموت حين يثار\nفانظر بعين شجاعة فلتعلمن … أن المقام بحيث فرار\nلما أتتك فلولهم أمددتهم … بسوابق العبرات وهي غزار\nوضربت أمثال الذليل وقد ترى … أن غير ذاك النقص والإمرار\nالصبر أجمل والقضاء مسلط … فارضوا به والشر فيه خيار\nهيهات جاذبك الأعنة باسل … يعطي الأسنة كل ما تختار\nفمضى لو أن النار دونك خاضها … بالسيف إلا أن تكون النار\nحتى يؤوب الحق وهو المشتفي … منكم وما للدين فيكم ثار\nلله در أبي سعيد إنه … للضيف محض ليس فيه سمار\nلما حللت الثغر أصبح عاليا … للروم من ذاك الجوار جوار\nواستيقنوا إذ جاش بحرك وارتقى … ذاك الزئير وعز ذاك الزار\nأن لست نعم الجار للسنن الأولى … إلا إذا ما كنت بئس الجار\nيقظ يخاف المشركون شذاته … متواضع يعنو له الجبار\nذلل ركائبه إذا ما استأخرت … أسفاره فهمومه أسفار\nيسري إذا سرت الهموم كأنه … نجم الدجى ويغير حين يغار\nسمقت به أعراقه في معشر … قطب الوغى نصب لهم ودوار\nلا يأسفون إذا هم سمنت لهم … أحسابهم أن تهزل الأعمار\nمتبهم في غرسه أنصاره … عند النزال كأنهم أنصار\nلفظ لأخلاق التجار وإنهم … لغدا بما ادخروا له لتجار\nومجربون سقاهم من بأسه … فإذا لقوا فكأنهم أغمار\nعكف بجذل للطعان لقاؤه … خطر إذا خطر القنا الخطار\nوالبيض تعلم أن دينا لم يضع … مذ سلهن ولا أضيع ذمار\nوإذا القسي العوج طارت نبلها … سوم الجراد يسيح حين يطار\nضمنت له أعجاسها وتكفلت … أوتارها أن تنقض الأوتار\nفدعوا الطريق بني الطريق لعالم … أنى يقاد الجحفل الجرار\nلو أن أيديكم طوال قصرت … عنه فكيف تكون وهي قصار\nهو كوكب الإسلام أية ظلمة … يخرق فمخ الكفر فيها رار\nغادرت أرضهم بخيلك في الوغى … وكأن أمنعها لها مضمار\nوأقمت فيها وادعا متمهلا … حتى ظننا أنها لك دار\nبالملك عنك رضا وجابر عظمه … أرض وبالدنيا عليك قرار\nوأرى الرياض حواملا ومطافلا … مذ كنت فيها والسحاب عشار\nأيامنا مصقولة أطرافها … بك والليالي كلها أسحار\nتندى عفاتك للعفاة وتغتدي … رفقا إلى زوارك الزوار\nهممي معلقة عليك رقابها … مغلولة إن الوفاء إسار\nومودتي لك لا تعار بلى إذا … ما كان تامور الفؤاد يعار\nوالناس غيرك ما تغير حبوتي … لفراقهم هل أنجدوا أو غاروا\nولذاك شعري فيك قد سمعوا به … سحر وأشعاري لهم أشعار\nفاسلم ولا ينفك يحظوك الردى … فينا وتسقط دونك الأقدار"},{"id":"diwan-abutammam:181","bookId":"diwan-abutammam","type":"poem","seq":181,"chapter":"البحر: وافر تام","title":"أعيدي النوح معولة أعيدي","page":"","text":"أعيدي النوح معولة أعيدي … وزيدي من بكائك ثم زيدي\nوقومي حاسرا في حاسرات … خوامش للنحور وللخدود\nهو الخطب الذي ابتدع الرزايا … وقال لأعين الثقلين جودي\nألا رزئت خراسان فتاها … غداة ثوى عمير بن الوليد\nألا رزئت بمسؤول منيل … ألا رزئت بمتلاف مفيد\nألا إن الندى والجود حلا … بحيث حللت من حفر الصعيد\nبنفسي أنت من ملك رمته … منيته بسهم ردى سديد\nتجلت غمرة الهيجاء عنه … خضيب الوجه من دمه الجسيد\nفيا بحر المنون ذهبت منه … ببحر الجود في السنة الصلود\nويا أسد المنون فرست منه … غداة فرسته أسد الأسود\nأبالبطل النجيد فرست منه … نعم وبقاتل البطل النجيد\nترآى للطعان وقد تراءت … وجوه الموت من حمر وسود\nفلم يكن المقنع فيه رأسا … خلا أن قد تقنع بالحديد\nفيا لك وقعة جللا أعارت … أسى وصبابة جلد الجليد\nويا لك ساحة أهدت غليلا … إلى أكبادنا أبد الأبيد\nوإن أميرنا لم يأل نصحا … وعدلا فيالرعايا والجنود\nأفاض نوال راحته لديهم … وسامح بالطريف وبالتليد\nوأصحر دونهم للموت حتى … سقاه الموت من مقر هبيد\nوما ظفروا به حتى قراهم … قشاعم أنسر وضباع بيد\nبطعن في نحورهم مريد … وضرب في رؤوسهم عنيد\nفيا يوم الثلثاء اصطبحنا … غداة منك هائلة الورود\nويايوم الثلثاء اعتمدنا … بفقد فيك للسند العميد\nفكم أسخنت منا من عيون … وكم أعثرت فينا من جدود\nفما زجرت طيورك عن سنيح … ولا طلعت نجومك بالسعود\nألا يا أيها الملك المردى … رداء الموت في جدث خديد\nحضرت فناء بابك فاعتراني … شجى بين المخنق والوريد\nرأيت به مطايا مهملات … وأفراسا صوافن بالوصيد\nوكن عتاد إما فك عان … وإما قتل طاغية عنود\nرأيت مؤمليك غدت عليهم … عواد أصعدتهم في كؤود\nوأضحت عند غيرك في هبوط … حظوظ كن عندك في صعود\nوكلهم أعد إلياس وقفا … عليك ونص راحلة القعود\nواصبحت الوفود إليك وقفا … على ألا مفاد لمستفيد\nلقد سخنت عيون الجود لما … نويت وأقصدت غرر القصيد"},{"id":"diwan-abutammam:182","bookId":"diwan-abutammam","type":"poem","seq":182,"chapter":"البحر: سريع","title":"لا آكل التفاح دهري ولو","page":"","text":"لا آكل التفاح دهري ولو … جنيته لي من جنان الخلود\nوالله لا أتركه للقلى … لكنني أتركه للخدود"},{"id":"diwan-abutammam:183","bookId":"diwan-abutammam","type":"poem","seq":183,"chapter":"البحر: سريع","title":"يامن به يفتخر الفخر","page":"","text":"يامن به يفتخر الفخر … ومن به يبتهج الشعر\nماطلبي للإذن أن شاقني … شمس من الإنس ولا بدر\nبلى كتاب أخرس ناطق … أنطق منه طيه النشر\nفانتشرت حين بدا طيه … سرائر يكتمها الجهر\nجاء نذير الحزن في بطنه … بحادث أظهره الظهر\nفانهل في أسطره أسطر … للدمع سطر فوقه سطر\nفمن بالإذن على نازح … عن أهله ساعته دهر\nفقد صدقت الظن في كل ما … رجوته إذ كذب القطر"},{"id":"diwan-abutammam:184","bookId":"diwan-abutammam","type":"poem","seq":184,"chapter":"البحر: كامل تام","title":"يادهر قدك وقلما يغني قدي","page":"","text":"يادهر قدك وقلما يغني قدي … وأراك عشر الظمء مر المورد\nولقد أحيط بنا ولم نك صورة … بك واستعد لنا ولما نولد\nيادهر أية زهرة للمجد لم … تجفف وأية أيكة لم تخضد !\nأترعت للعنقاء في أشعافها … كأسا تدفق بالذعاف الأسود\nقد كان قرم كاسمه قرما وما … ولدت نساء بني أبيه كأحمد\nنجما هدى هذاك نجم الجدي إن … حار الدليل وذاك نجم الفرقد\nهذا سنان زاغبي في الوغى … وكأنما هذا ذباب مهند\nوجبين هذا كالشهاب جلا الدجى … عنه وهذا كالشهاب الموقد\nولنعم درعا الحي في يوميهما … كانا ونعم الذخر كانا للغد\nلم يشهدا نجوى ولاحشا لظى … حرب تسعر بالقنا المتقصد\nإلا رأينا ذا على تلك الرحا … قطبا وذا مصباح ذاك المشهد\nرزئت بنو عمرو بن عامر الذرى … بهما وصوح نبت واديها الندى\nوكذا المنايا ما يطأن بمسيم … إلا على أعناق أهل السؤدد\nولئن أصيبوا إن تلك لغيضة … لم تخل من ليث هنالك ملبد\nما دام ذاك المعدن الزاكي الثرى … في جزعنا لم نلتفت للعسجد\nتلك المصائب مشويات كلها … إلا مصيبة حجوة بن محمد\nولقد أصاب غليلها من لم يصب … ولصيرت فقدا لمن لم يفقد\nطامن حشاك أبا الحباب فإنها … نوب تروح على الأنام وتغتدي\nفلقد أفاق متمم عن مالك … وسلا لبيد قبله عن أربد\nفلئن صبرت لأنت كوكب معشر … صبروا وإن تجزع فغير مفند\nهذي المعونة باللسان ولو أرى … عين الحمام لقد أعنتك باليد"},{"id":"diwan-abutammam:185","bookId":"diwan-abutammam","type":"poem","seq":185,"chapter":"البحر: كامل تام","title":"غطت يداك علي في لحدي","page":"","text":"غطت يداك علي في لحدي … وبقيت ما مد المدى بعدي\nورزقت منك العطف ما حملت … عيني الدموع ودام لي وجدي\nنفسي بكتماني معلقة … بين النوى ومخافة الصد"},{"id":"diwan-abutammam:186","bookId":"diwan-abutammam","type":"poem","seq":186,"chapter":"البحر: بسيط تام","title":"يا هذه أقصري ما هذه بشر","page":"","text":"يا هذه أقصري ما هذه بشر … ولا الخرائد من أترابها الأخر\nخرجن في خضرة كالروض ليس لها … إلا الحلي على أعناقها زهر\nبدرة حفها من حولها درر … أرضى غرامي فيها دمعي الدرر\nريم أبت أن يريم الحزن لي جلدا … والعين عين بماء الشوق تبتدر\nصب الشباب عليها وهو مقتبل … ماء من الحسن ما في صفوه كدر\nلولا العيون وتفاح الخدود إذا … ما كان يحسد أعمى من له بصر\nحييت من طلل لم تبق لي طللا … إلا وفيه أسى ترشيحه الذكر\nقالوا أتبكي على رسم فقلت لهم : … من فاته العين هدى شوقه الأثر\nإن الكرام كثير في البلاد وإن … قلوا كما غيرهم قل وإن كثروا\nلا يدهمنك من دهمائهم عدد … فإن جلهم بل كلهم بقر\nوكلما أمست الأخطار بينهم … هلكى تبين من أمسى له خطر\nلو لم تصادف شيات البهم أكثر ما … في الخيل لم تحمد الأوضاح والغرر\nنعم الفتى عمر في كل نائبة … نابت وقلت له ' نعم الفتى عمر\nيعطي ويحمد من يأتيه يحمده … فشكره عوض وماله هدر\nمجرد سيف رأي من عزيمته … للدهر صيقله الإطراق والفكر\nعضبا إذا سله في وجه نائبة … جاءت إليه بنات الدهر تعتذر\nوسائل عن أبي حفص فقلت له … أمسك عنانك عه إنه القدر\nهو الهمام هو الصاب المريح هو ال … حتف الوحي هو الصمصامة الذكر\nفتى تراه فتنفي العسر غرته … يمنا وينبع من أسرارها اليسر\nفدى له مقشعر حين تسأله … خوف السؤال كأن في جلده وبر\nأنى ترى عاطلا منحلي مكرم ة … وكل يوم ترى في مالك الغير !\nلله در بني عبد العزيز فكم … أردوا عزيز عدى في خده صعر\n … حتى لقد ظن قوم أنها سور\nيا ليت شعري من هاتا مآثره … ماذا الذي ببلوغ النجم ينتظر\nبالشعر طول إذا اصطكت قصائده … في معشر وبه عن معشر قصر\nسافر بطرفك في أقصى مكارمنا … إن لم يكن لك في تأسيسها سفر\nهل أورق المجد إلا في بني أدد … \nلولا أحاديث بقتها مآثرنا … من الندى والردى لم يعجب السمر"},{"id":"diwan-abutammam:187","bookId":"diwan-abutammam","type":"poem","seq":187,"chapter":"البحر: طويل","title":"لا يشمت الأعداء بالموت إننا","page":"","text":"لا يشمت الأعداء بالموت إننا … سنخلي لهم من عرضة الموت موردا\nولا تحسبن الموت عارا فإننا … رأينا المنايا قد أصبن محمدا\nولا يحسب الأعداء أن مصيبتي … أكلت لهم مني لسانا ولا يدا\nتتابع في عام بني وإخوتي … فأصبحت إن لم يخلف الله واحدا"},{"id":"diwan-abutammam:188","bookId":"diwan-abutammam","type":"poem","seq":188,"chapter":"البحر: كامل تام","title":"رقت حواشي الدهر فهي تمرمر","page":"","text":"رقت حواشي الدهر فهي تمرمر … وغدا الثرى في حليه يتكسر\nنزلت مقدمة المصيف حميدة … ويد الشتاء جديدة لا تكفر\nلولا الذي غرس الشتاء بكفه … لاقى المصيف هشائما لاتثمر\nكم ليلة آسى البلاد بنفسه … فيها ويوم وبله مثعنجر\nمطر يذوب الصحو منه وبعده … صحو يكاد من الغضارة يمطر\nغيثان فالأنواء غيث ظاهر … لك وجهه والصحو غيث مضمر\nوندى إذا ادهنت به لمم الثرى … خلت السحاب أتاه وهو معذر\nأربيعنا في تسع عشرة حجة … حقا لهنك للربيع الأزهر\nما كانت الأيام تسلب بهجة … لو أن حسن الروض كان يعمر\nأولا ترى الأشياء إن هي غيرت … سمجت وحسن الأرض حين تغير\nيا صاحبي تقصيا نظريكما … تريا وجوه الأرض كيف تصور\nتريا نهارا مشمسا قد شابه … زهر الربا فكأنما هو مقمر\nدنيا معاش للورى حتى إذا … جلي الربيع فإنما هي منظر\nأضحت تصوغ بطونها لظهورها … نورا تكاد له القلوب تنور\nمن كل زاهرة ترقرق بالندى … فكأنها عين عليه تحدر\nتبدو ويحجبها الجميم كأنها … عذراء تبدو تارة وتخفر\nحتى غدت وهداتها ونجادها … فئتين في خلع الربيع تبختر\nمصفرة محمرة فكأنها … عصب تيمن في الوغا وتمضر\nمن فاقع غض النبات كأنه … در يشقق قبل ثم يزعفر\nأو ساطع في حمرة فكأن ما … يدنو إليه من الهواء معصفر\nصنع الذي لولا بدائع صنعه … ماعاد أصفر ، بعد إذ هو أخضر\nخلق أطل من الربيع كأنه … خلق الإمام وهديه المتيسر\nفي الأرض من عدل الإمام وجوده … ومن النبات الغض سرج تزهر\nتنسى الرياض وما يروض فعله … أبدا على مر الليالي يذكر\nإن الخليفة حين يظلم حادث … عين الهدى وله الخلافة محجر\nكثرت به حركاتها ولقد ترى … من فترة وكأنها تتفكر\nما زلت أعلم أن عقدة أمرها … في كفه مذ خليت تتخير\nسكن الزمان فلا يد مذمومة … للحادثات ولا سوام يذعر\nنظم البلاد فأصبحت وكأنها … عقد كأن العدل فيه جوهر\nلم يبق مبدى موحش إلا ارتوى … من ذكره فكأنما هو محضر\nملك يضل الفخر في أيامه … ويقل في نفحاته ما يكثر\nفليعسرن على الليالي بعده … أن يبتلى بصروفهن المعسر"},{"id":"diwan-abutammam:189","bookId":"diwan-abutammam","type":"poem","seq":189,"chapter":"البحر: طويل","title":"أألله إني خالد بعد خالد","page":"","text":"أألله إني خالد بعد خالد … وناس سراج المجد نجم المحامد !\nوقد ترعت إثفية العرب التي … بها صدعت مابين تلك الجلامد\nألا غرب دمع ناصر لي على الأسى … ألا حر شعر في الغليل مساعدي\nفلم تكرم العينان إن لم تسامحا … ولاطاب فرع الشعر إن لم يساعد\nلتبك القوافي شجوها بعد خالد … بكاء مضلات السماح نواشد\nلكانت عذاراها إذا هي أبرزت … لدى خالد مثل العذارى النواهد\nوكانت لصيد الوحش منها حلاوة … على قلبه ليست لصيد الأوابد\nوكان يرى سم الكلام كأنما … يقشب أحيانا بسم الأساود\nتقلص ظل العرف في كل بلدة … وأطفىء في الدنيا سراج القصائد\nفيا عي مرحول إليه وراحل … وخجلة موفود إليه ووافد\nوياماجدا أوفى به الموت نذره … فأشعر روعا كل أروع ماجد !\nغدا يمنع المعروف بعدك دره … وتعذر غدران الأكف الروافد\nويا شائما برقا خدوعا وسامعا … لراعدة دجالة في الرواعد\nأقم ثم حط الرحل والظن إنه … مضت قبلة الأسفار منء بعد خالد\nتكفأ متن الأرض يوم تعطلت … من الجبل المنهد تحت الفدافد\nفللثغر لون قاتم بعد منظر … أنيق وجو سائل غير راكد\nلأبرحت يا عام المصائب بعدما … دعتك بنو الآمال عام الفوائد !\nلقد نهس الدهر القبائل بعده … بناب حديد يقطر السم عاند\nفجلل قحطا آل قحطان وانثنت … نزار بمنزور من العيش جاحد\nعلى أي عرنين غلبنا ومارن … وأية كف فارقتنا وساعد !\nكأنا فقدنا ألف ألف مدجج … على ألف ألف مقرب لا مباعد\nفيا وحشة الدنيا وكانت أنيسة … ووحدة من فيها لمصرع واحد !\nمضت خيلاء الخيل وانصرف الردى … بأنفس نفس من معد ووالد\nفأين شفاء الثغر أين إذا القنا … خطرن على عضو من الملك فاسد ؟\nوأين الجلاد الهبر إذ ليس سيد … يقي جلدة الأحساب إن لم يجالد ؟\nومن يجعل السلطان حبل وريده … ومن ينظم الأطراف نظم القلائد ؟\nومن لم يكن ينفك يغبق سيفه … دما عاندا من نحر ليث معاند ؟\nبنفسي من خطتء ربيعة لحده … ولا زال مهتز الربي غير هامد\nأقام به من حي بكر بن وائل … هني الندى مخضر إثر المواعد\nفماذا حوت أكفانه من شمائل … مناهل أعداد عذاب الموارد !\nخلائق كانت كالثغور تخرمت … وكان عليها واقفا كالمجاهد\nفكم غال ذاك الترب لي ولمعشري … وللناس طرا من طريف وتالد !\nأشيبان لا ذاك الهلال بطالع … علينا ولا ذاك الغمام بعائد\nأشيبان ماجدي ولاجد كاشح … ولاجد شيء يوم ولى بصاعد\nأشيبان عمت نارها من مصيبة … فما يشتكى وجد إلى غير واجد\nلإن أقرحت عيني صديق وصاحب … لقد زعزعت ركني عدو وحاسد\nلئن هي أهدت للأقارب ترحة … لقد جللت تربا خدود الأباعد\nفما جانب الدنيا بسهل ولا الضحى … بطلق ولاماء الحياة ببارد\nبلى وأبي إن الأمير محمدا … لقطب الرحى مصباح تلك المشاهد\nحمدت الليالي إذ حمت سرحنا به … ولست لها في غير ذاك بحامد\nعليه دليل من يزيد وخالد … ونوران لاحا من نجار وشاهد\nمن المكرمين الخيل فيهم ولم يكن … ليكرمها إلا كرام المحاتد\nأخو الحرب يكسوها نجيعا كأنما … متون رباها منه مثل المجاسد\nإذا شب نارا أقعدت كل قائم … وقام لها من خوفه كل قاعد\nفقل لملوك السيسجان ومن غدا … بأران أو جرزان غير مناشد\nألا القوا مقاليد البلاد وهل لها … رتاج فيلقي أهلها بالمقالد ؟ !\nولا يغوكم شيطان حرب فإنه … مع السيف يدمى نصله غير مارد\nولا تفترق أعناقكم إن حولها … ردينية يجمعن هام الشوارد\nوما كثرت في بلدة قصد القنا … فتقلع إلا عن رقاب قواصد"},{"id":"diwan-abutammam:190","bookId":"diwan-abutammam","type":"poem","seq":190,"chapter":"البحر: سريع","title":"ولي من الدنياهوى واحد","page":"","text":"ولي من الدنياهوى واحد … يا رب فاصفح لي عن الواحد\nلا تتركني فيه يا ذا العلى … احدوثة الصادر والوارد\nيا رب إن فارقته بعد ما … أصرعني للشامت الحاسد\nفألحق الروح وجثمانه … بوهدة المحتفر اللاحد"},{"id":"diwan-abutammam:191","bookId":"diwan-abutammam","type":"poem","seq":191,"chapter":"البحر: كامل تام","title":"الحق أبلج والسيوف عوار","page":"","text":"الحق أبلج والسيوف عوار … فحذار من أسد العرين حذار\nملك غدا جار الخلافة منكم … والله قد أوصى بحفظ الجار\nيارب فتنة أمة قد بزها … جبارها في طاعة الجبار\nجالت بخيذر جولة المقدار … فأحله الطغيان دار بوار\nكم نعمة لله كانت عنده … فكأنها في غربة وإسار\nكسيت سبائب لومه فتضاءلت … كتضاؤل الحسناء في الأطمار\nموتورة طلب الإله بثأرها … وكفى برب الثأر مدرك ثار\nصادى أمير المؤمنين بزبرج … في طيه حمة الشجاع الضاري\nمكرا بنى ركنيه ، إلا أنه … وطد الأساس على شفير هار\nحتى إذا ما الله شق ضميره … عن مستكن الكفر والإصرار\nونحا لهذا الدين شفرته انثنى … والحق منه قانئ الأظفار\nهذا النبي وكان صفوة ربه … من بين باد في الأنام وقار\nقد خص من أهل النفاق عصابة … وهم أشد أذى من الكفار\nواختار من سعد لعين بني أبي … سرح لوحي الله غير خيار\nحتى استضاء بشعلة السور التي … رفعت له سجفا عن الأسرار\nوالهاشميون استقلت عيرهم … من كربلاء بأثقل الأوتار\nفشفاهم المختار منه ولم يكن … في دينه المختار بالمختار\nحتى إذا انكشفت سرائره اغتدوا … منه براء السمع والأبصار\nما كان لولا فحش غدر خيذر … ليكون في الإسلام عام فجار\nما زال سر الكفر بين ضلوعه … حتى اصطلى سر الزناد الواري\nنارا يساور جسمه من حرها … لهب كما عصفرت شق إزار\nطارت لها شعل يهدم لفحها … أركانه هدما بغير غبار\nمشبوبة رفعت لأعظم مشرك … ما كان يرفع ضوءها للساري\nصلى لها حيا وكان وقودها … ميتا ويدخلها مع الفجار\nفصلن منه كل مجمع مفصل … وفعل فاقرة بكل فقار\nوكذاك أهل النار في الدنيا هم … يوم القيامة جل أهل النار\nيا مشهدا صدرت بفرحته إلى … أمصارها القصوى بنو الأمصار\nرمقوا أعالي جذعه فكأنما … وجدوا الهلال عشية الإفطار\nواستنشأوا منه قتارا نشره … من عنبر ذفر ومسك داري\nوتحدثوا عن هلكه كحديث من … بالبدو عن متتابع الأمطار\nوتباشروا كتباشر الحرمين في … قحم السنين بأرخص الأسعار\nكانت شماتة شامت عارا فقد … صارت به تنضو ثياب العار\nقد كان بوأه الخليفة جانبا … من قلبه حرما على الأقدار\nفسقاه ماء الخفض غير مصرد … وأنامه في الأمن غير غرار\nورأى به مالم يكن يوما رأى … عمرو بن شأس قبله بعرار\nفإذا ابن كافرة يسر بكفره … وجدا كوجد فرزدق بنوار\nوإذا تذكره بكاه كما بكى … كعب زمان رثى أبا المغوار\nدلت زخارفه الخليفة أنه … ما كل عود ناضر بنضار\nيا قابضا يد آل عادلا … أتبع يمينا منهم بيسار\nألحق جبينا داميا رملته … بقفا ، وصدرا خائنا بصدار\nواعلم بأنك إنما تلقيهم … في بعض ما حفروا من الآبار\nلو لم يكد للسامري قبيله … ما خار عجلهم بغير خوار\nوثمود لو لم يدهنوا في ربهم … لم تدم ناقته بسيف قدار\nولقد شفى الأحشاء من برحائها … أن صار بابك جار مازيار\nثانيه في كبد السماء ولم يكن … لاثنين ثان إذ هما في الغار\nوكأنما انتبذا لكيما يطويا … عن ناطس خبرا من الأخبار\nسود الثياب كأنما نسجت لهم … أيدي السموم مدارعا من قار\nبكروا وأسروا في متون ضوامر … قيدت لهم من مربط النجار\nلا يبرحون ومن رآهم خالهم … أبدا على سفر من الأسفار\nكادوا النبوة والهدى ، فتقطعت … أعناقهم في ذلك المضمار\nجهلوا ، فلم يستكثروا من طاعة … معروفة بعمارة الأعمار\nفاشدد بهارون الخلافة إنه … سكن لوحشتها ودار قرار\nبفتى بني العباس والقمر الذي … حفته أنجم يعرب ونزار\nكرم العمومة والخؤولة مجه … سلفا قريش فيه والأنصار\nهو نوء يمن فيهم وسعادة … وسراج ليل فيهم ونهار\nفاقمع شياطين النفاق بمهتد … ترضى البرية هديه والباري\nليسير في الآفاق سيرة رأفة … ويسوسها بسكينة ووقار\nفالصين منظوم بأندلس إلى … حيطان رومية فملك ذمار\nولقد علمت بأن ذلك معصم … ما كنت تتركه بغير سوار\nفالأرض دار أقفرت مالم يكن … من هاشم رب لتلك الدار\nسور القران الغر فيكم أنزلت … ولكم تصاغ محاسن الأشعار"},{"id":"diwan-abutammam:192","bookId":"diwan-abutammam","type":"poem","seq":192,"chapter":"البحر: بسيط تام","title":"لو صحح الدمع لي أو ناصح الكمد","page":"","text":"لو صحح الدمع لي أو ناصح الكمد … لقلما صحباني الروح والجسد\nخان الصفاء أخ كان الزمان له … أخا فلم يتخون جسمه الكمد\nتساقط الدمع أدنى مابليت به … في الحب إذ لم تساقط مهجة ويد\nلا والذي ارتكت تطوي الفجاج له … سفائن البر في خد الثرى تخد\nلأنفدن أسى إذ لم أمت أسفا … أو ينفد العمر بي أو ينفد الأبد\nعني إليك فإني عنك في شغل … لي منه يوم يبكي مهجتي وغد\nوإن بجرية نابت جأرت لها … إلى ذرى جلدي فاستوهل الجلد\nهي النوائب فاشجي أو فعي عظة … فإنها فرص أثمارها رشد\nهبي تري قلقا من تحته أرق … يحدوهما كمد يحنو له الجسد\nصماء سم العدى في جنبها ضرب … وشرب كأس الردى في فمها شهد\nهناك أم النهى لم تود من حزن … ولم تجد لبني الدنيا بما تجد\nلو يعلم الناس علمي بالزمان وما … عاثت يداه لما ربوا ولا ولدوا\nلايبعد الله ملحودا أقام به … شخص الحجى وسقاه الواحد الصمد\nياصاحب القبر دعوى غير مثئب … إن قال أودى الندى والبدر والأسد\nبات الثرى بأخي جذلان مبتهجا … وبت يحكم في أجفاني السهد\nلهفي عليك ومالهفي بمجدية … مالم يزرك بنفسي حر ما أجد\nأنسى أبا الفضل يعفو الترب أحسنه … دوني ودلو الردى في مائه يرد ؟ !\nويل لأمك أقصر إنه حدث … لم يعتقد مثله قلب ولا جلد\nعاق الزمان رضيع الجود لم يقه … أهل ولم يفده مال ولاولد\nحين ارتوى الماء وافترت شبيبته … عن مضحك للمعالي ثغره برد\nوقيل أحمدها بل قيل أمجدها … بل قيل أنجدها إن فرت النجد\nرود الشباب كنصل السيف لاجعد … في راحتيه ولافي عوده أود\nسقى الحبيس ومحبوسا ببرزخه … من السمي كفيت الودق يطرد\nبحيث حل أبو صقر فودعه … صفو الحياة ومن لذاتها الرغد\nبحيث حل فقيد المجد مغتربا … ومورثا حسرات ليس تفتقد"},{"id":"diwan-abutammam:193","bookId":"diwan-abutammam","type":"poem","seq":193,"chapter":"قصائد","title":"فرد جمال سليل نور","page":"","text":"فرد جمال سليل نور … به استقلت يد السرور\nتجول في رونقي جمال … من خده مقلة البصير\nلم يعرفوا مثله جمالا … جل عن المثل والنظير"},{"id":"diwan-abutammam:194","bookId":"diwan-abutammam","type":"poem","seq":194,"chapter":"البحر: كامل تام","title":"أفنى وليلي ليس يفنى آخره","page":"","text":"أفنى وليلي ليس يفنى آخره … هاتا موارده فأين مصادره ؟\nنامت عيون الشامتين تيقنا … أن ليس يهجع والهموم تسامره\nأسر الفراق عزاءه ونأى الذي … قد كان يستحييه إذ يستاسره\nلا شيء ضائر عاشق ، فإذا نأى … عنه الحبيب فكل شيء ضائره\nيا أيهاذا السائلي أنا شارح … لك غائبي حتى كأنك حاضره\nإني ونصرا والرضا بجواره … ك\nما إن يخاف الخذل من أيامه … أحد تيقن أن نصرا ناصره\nيفدي أبا العباس من لم يفده … من لائميه جذمه وعناصره\nمستنفر للمادحين ، كأنما … آتيه يمدحه أتاه يفاخره\nماذا ترى فيمن رآك لمدحه … أهلا وصارت في يديك مصايره\nقد كابر الأحداث حتى كذبت … عنه ولكن القضاء يكابره\nمر دهره بالكف عن جنباته … فالدهر يفعل صاغرا ما تأمره\nلاتنس من لم ينس مدحك والمنى … تحت الدجى يزعمن أنك ذاكره\nأبكر فقد بكرت عليك بمدحه … غرر القصائد خير أمر باكره\nلاقاك أوله بأول شعره … فأهب بأوله يكن لك آخره\nلاشيء أحسن من ثنائي سائرا … ونداك في أفق البلاد يسايره\nوإذا الفتى المأمول أنجح عقله … في نفسه ونداه أنجح شاعره"},{"id":"diwan-abutammam:195","bookId":"diwan-abutammam","type":"poem","seq":195,"chapter":"البحر: طويل","title":"كذا فليجل الخطب وليفدح الأمر","page":"","text":"كذا فليجل الخطب وليفدح الأمر … فليس لعين لم يفض ماؤها عذر\nتوفيت الآمال بعد محمد … وأصبح في شغل عن السفر السفر\nوما كان إلا مال من قل ماله … وذخرا لمن أمسى وليس له ذخر\nوما كان يدري مجتدي جود كفه … إذا ما استهلت أنه خلق العسر\nألا في سبيل الله من علطت له … فجاج سبيل الله وانثغر الثغر\nفتى كلما فاضت عيون قبيلة … دما ضحكت عنه الأحاديث والذكر\nفتى مات بين الضرب والطعن ميتة … تقوم مقام النصر إذ فاته النصر\nوما مات حتى مات مضرب سيفه … من الضرب واعتلت عليه القنا السمر\nوقد كان فوت الموت سهلا فرده … إليه الحفاظ المر والخلق الوعر\nونفس تعاف العار حتى كأنه … هو الكفر يوم الروع أو دونه الكفر\nفأثبت في مستنقع الموت رجله … وقال لها من تحت أخمصك الحشر\nغدا غدوة والحمد نسج ردائه … فلم ينصرف إلا وأكفانه الأجر\nتردى ثياب الموت حمرا فما أتى … لها الليل إلا وهي من سندس خضر\nكأن بني نبهان يوم وفاته … نجوم سماء خر من بينها البدر\nيعزون عن ثاو ت عزى به العلى … ويبكي عليه الجود والبأس والشعر\nوأني لهم صبر عليه وقد مضى … إلى الموت حتى استشهدوا هو والصبر !\nفتى كان عذب الروح لامن غضاضة … ولكن كبرا أن يقال به كبر !\nفتى سلبته الخيل وهو حمى لها … وبزته نار الحرب وهو لها جمر\nوقد كانت البيض المآثير في الوغى … بواتر فهي الآن من بعده بتر\nأمن بعد طي الحادثات محمدا … يكون لأثواب الندى أبدا نشر ؟ !\nإذا شجرات العرف جذت أصولها … ففي أي فرع يوجد الورق النضر ؟\nلئن أبغض الدهر الخؤون لفقده … لعهدي به ممن يحب له الدهر\nلئن غدرت في الروع أيامه به … لما زالت الأيام شيمتها الغدر\nلئن ألبست فيه المصيبة طيء … لما عريت منها تميم ولا بكر\nكذلك ما ننفك نفقد هالكا … يشاركنا في فقده البدو والحضر\nسقى الغيث غيثا وارت الأرض سخصه … وإن لم يكن فيه سحاب ولا قطر\nوكيف احتمالي للسحاب صنيعة … بإسقائها قبرا وفي لحده\nمضى طاهر الأثواب لم تبق روضة … غداة ثوى إلا اشتهت أنها قبر\nثوى في الثرى من كان يحيا به الثرى … ويغمر صرف الدهر نائله الغمر\nعليك سلام الله وقفا فإنني … رأيت الكريم الحر ليس له عمر"},{"id":"diwan-abutammam:196","bookId":"diwan-abutammam","type":"poem","seq":196,"chapter":"البحر: خفيف تام","title":"ياعليلا حشا الجوانح نارا","page":"","text":"ياعليلا حشا الجوانح نارا … كان لي فيك حافظ الجار جارا\nمعدن الحسن والملاحة قد … بح للسقم معدنا وقرارا\nإن وجه الحمى لوجه صفيق … حين تسطو به نهارا جهارا\nلم تشن وجهه المليح ولكن … جعلت ورد وجنتيه بهارا"},{"id":"diwan-abutammam:197","bookId":"diwan-abutammam","type":"poem","seq":197,"chapter":"البحر: طويل","title":"شجا في الحشى ترداده ليس يفتر","page":"","text":"شجا في الحشى ترداده ليس يفتر … به صمن آمالي وإني لمفطر\nحلفت بمستن المنى تسترشه … سحابة كف بالرغائب تمطر\nإذا درجت فيه الصبا كفكفت لها … وقام يباريها أبو الفضل جعفر\nبسيب كأن السيف من ثر نؤيه … وأندية منها ندى النوء يعصر\nلقد زينت الدنيا بأيام ماجد … به الملك يبهى والمفاخر تفخر\nفتى من يديه البأس يضحك والندى … وفي سرجه بدر وليث غضنفر\nبه ائتلفت آمال وافدة المنى … وقامت لديه جمة تتشكر\nأبا الفضل إني يوم جئتك مادحا … رأيت وجوه الجود والنجح تزهر\nوأيقنت أني فالج غمر زاخر … تثوب إليه بالسماحة أبحر\nفلا شيء أمضى من رجائك في الندى … ولا شيء أبقى من ثناء يحبر\nوماتنصر الأسياف نصر مديحة … لها عند أبواب الخلائف محضر\nإذا ما انطوى عنها اللئيم بسمعه … يكون لها عند الأكارم منشر\nلها بين أبواب الملوك مزامر … من الذكر لم تنفخ ولا تتزمر\nحوت راحتاه الباس والجود والندى … ونال الحجا فالجهل حيران أزور\nفلا يدع الإنجاز يملك أمره … ويقدمه في الجود مطل مؤخر\nإليك بها عذراء زفت كأنها … عروس عليها حليها يتكسر\nتزف إليكم يابن نصر كأنها … حليلة كسرى يوم آواه قيصر\nأبا الفضل إن الشعر مما يميته … إباء الفتى والمجد يحيا ويقبر"},{"id":"diwan-abutammam:198","bookId":"diwan-abutammam","type":"poem","seq":198,"chapter":"البحر: طويل","title":"عزاء فلم يخلد حوي ولاعمرو","page":"","text":"عزاء فلم يخلد حوي ولاعمرو … وهل أحد يبقى وإن بسط العمر ؟\nسيأكلنا الدهر الذي غال من نرى … ولا تنقضي الأشياء أو يؤكل الدهر\nوأكثر حالات ابن آدم خلقة … يضل إذا فكرت في كنهها الفكر\nفيفرح بالشيء المعار بقاؤه … ويحزن لما صار وهو له ذخر !\nعليك بثوب الصبر إذ فيه ملبس … فإن ابنك المحمود بعد ابنك الصبر\nوما أوحش الرحمن ساحة عبده … إذا عاين الجلى ومؤنسه الأجر"},{"id":"diwan-abutammam:199","bookId":"diwan-abutammam","type":"poem","seq":199,"chapter":"البحر: سريع","title":"وقهوة كوكبها يزهر","page":"","text":"وقهوة كوكبها يزهر … يسطع منها المسك والعنبر\nوردية يحثها شادن … كأنها من خده تعصر\nما زال قلبي مذ تعلقته … أعمى من الهجران ما يبصر\nمهفهف لم يبتسم ضاحكا … مذ كان الاكسد الجوهر\nبحبه يقبرني قابري … مسد مماتي وبه أنشر"},{"id":"diwan-abutammam:200","bookId":"diwan-abutammam","type":"poem","seq":200,"chapter":"البحر: طويل","title":"أأحمد إن الحاسدين كثير","page":"","text":"أأحمد إن الحاسدين كثير … ومالك إن عد الكرام نظير\nحللت محلا فاضلا متقدما … من المجد والفخر القديم فخور\nفكل قوي أو غني فإنه … إليك ولو نال السماء فقير\nإليك تناهى المجد من كل وجهة … يصير فما يعدوك حين تصير\nوبدر إياد أنت لا ينكرونه … كذاك إياد للأنام بدور\nفما من ندى إلا إليك محله … ولا رفقة إلا إليك تسير\nتجنبت أن تدعى الأمير تواضعا … وأنت لمن يدعى الأمير أمير"},{"id":"diwan-abutammam:201","bookId":"diwan-abutammam","type":"poem","seq":201,"chapter":"البحر: وافر تام","title":"كفاني من حوادث كل دهر","page":"","text":"كفاني من حوادث كل دهر … بإسحق بن إبراهيم جارا\nسيكفيني الحوادث مصعبي … كأن جبينه قمر أنارا\nعلى ثقة وأنت لذاك أهل … أخذت بحبل ذمتك اختيارا\nبإسحق بن إبراهيم أضحت … سماء الجود تنهمر انهمارا\nفتى بنواله في كل قوم … أقام لكل مكرمة نجارا\nعقدت بحبله حبلي فأضحت … قواه لا أخاف لها انبتارا\nلكم نعم غواد ساريات … علي مننتم فيها مرارا\nشكرتكم بها سرا وجهرا … وأنجد فيكم مدحي وغارا\nنفضلكم على الأقوام إنا … رأينا الملك حل بكم وسارا\nلقد عمت فضولكم وخصت … ذوي يمن كما سلبت نزارا\nتخيرك الإمام على رجال … لأمته فما حرم الخيارا\nوليت المسلمين فلم تضيع … أمورهم الصغار ولا الكبارا\nبراك الله من كرم وجود … وألبسك المهابة والوقارا\nإذا ما كان جارك مصعبيا … فلا ضيرا تخاف ولا افتتارا"},{"id":"diwan-abutammam:202","bookId":"diwan-abutammam","type":"poem","seq":202,"chapter":"البحر: بسيط تام","title":"سهرت فيك فلم أجحد يد السهر","page":"","text":"سهرت فيك فلم أجحد يد السهر … وطال فكري ولاعتب على الفكر\nنادمت ذكرك والظلماء عاكفة … فكان ياسيدي أحلى من السمر\nفإن ترى عبرتي والشوق يسفحها … لما التفت إلى شيء من المطر\nيا من إذا قلت يا من لا نظير له … في حسنه قيل لي يا أصدق البشر\nما إن أرى وجهك المكنون جوهره … ياأملح الناس إلا نسخة القمر"},{"id":"diwan-abutammam:203","bookId":"diwan-abutammam","type":"poem","seq":203,"chapter":"البحر: بسيط تام","title":"يا وارث الملك إن الملك محتبس","page":"","text":"يا وارث الملك إن الملك محتبس … وقف عليك إلى أن تنشر الصور\nلم يذكر الجود إلا خضت واديه … ولا انتضي السيف إلا خافك القدر\nما ضر من أصبح المأمون سائسه … أن لم يسسه أبو بكر ولا عمر\nوما على الأرض والمأمون يملكها … أن لا تضيء لنا شمس ولا قمر"},{"id":"diwan-abutammam:204","bookId":"diwan-abutammam","type":"poem","seq":204,"chapter":"البحر: خفيف تام","title":"يا سمي النبي في سورة الج","page":"","text":"يا سمي النبي في سورة الج … ن ويا ثاني العزيز بمصر\nتركت ليلة الصراة بقلبي … جمر شوق احر من كل جمر\nباشر الماء فهو في رقة الصن … عة كالماء غير أن ليس يجري\nخمش الماء جلده الرطب حتى … خلته لابسا غلالة خمر"},{"id":"diwan-abutammam:205","bookId":"diwan-abutammam","type":"poem","seq":205,"chapter":"البحر: طويل","title":"أصم بك الناعي وإن كان أسمعا","page":"","text":"أصم بك الناعي وإن كان أسمعا … وأصبح مغنى الجود بعدك بلقعا\nللحد أبي نصر تحية مزنة … إذا هي حيت معمرا عاد ممرعا\nفلم ار يوما كان أشبه ساعة … بيومي من اليوم الذي فيه ودعا\nمصيف أفاض الحزن فيه جداولا … من الدمع حتى خلته عاد مربعا\nووالله لا تقضي العيون الذي له … عليها ولو صارت مع الدمع أدمعا\nفتى كان شربا للعفاة ومرتعا … فأصبح للهندية البيض مرتعا\nفتى كلما ارتاد الشجاع من الردى … مفرا غداة المأزق ارتاد مصرعا\nإذا ساء يوم في الكريهة منظرا … تصلاه علما أن سيحسن مسمعا\nفإن ترم عن عمر تدانى به المدى … فخانك حتى لم يجد فيك منزعا\nفما كنت إلا السيف لاقى ضريبة … فقطعها ثم انثنى فتقطعا !"},{"id":"diwan-abutammam:206","bookId":"diwan-abutammam","type":"poem","seq":206,"chapter":"البحر: منسرح","title":"هل أثر من ديارهم دعس","page":"","text":"هل أثر من ديارهم دعس … حيث تلاقى الأجراع والوعس\nمخبر السائر الرذية في ال … أطلال أين الجآذر اللعس\nلا تسألنها فليس يسمع جرس ال … قول إلا شخص له جرس\nولايراخي عذل المعنسة ال … خرقاء إلا الشملة العنس\nوراكد الهم كالزمانة وال … بيت إذا ما ألفته رمس\nنعم متاع الدنيا حباك به … أروع لا جيدر ولاجبس\nأصغر منها كأنه محة ال … بيضة ، صاف كأنه عجس\nهاديه جذع من الأراك وما … خلف الصلا منه صخرة جلس\nيكاد يجري الجادي من ماء عط … فيه ويجنى من متنه الورس\nهذب في جنسه ونال المدى … بنفسه فهو وحده جنس\nأحزر آباؤه الفضيلة مذ … تفرست في عروقها الفرس\nليس بديعا منه ولا عجبا … أن يطرق الماء ورده خمس\nيترك ما مر مذ قبيل به … كأن أدنى عهد به الأمس\nوهو إذا ما ناجاه فارسه … يفهم عنه ما يفهم الإنس\nوهو ولما تهبط ثنيته … لا الربع في جريه ولا السدس\nوهو إذا ما رمى بمقلته … كانت سخاما كأنها نقس\nوهو إذا ما أعرت غرته … عينيك لاحت كأنها برس\nضمخ من لونه فجاء كأن … قد كسفت في أديمه الشمس\nكل ثمين من الثواب به … غير ثنائي فإنه بخس\nشذب همي به صقيل ن ال … فتيان أقطار عرضه ملس\nسامي القذالين والجبين ، إذا … نكس من لؤم فعله النكس\nأبو علي أخلاقه زهر … غب سماء وروحه قدس\nأبيض قدت قد الشراك شرا … ك السبت بيني وبينه النفس\nللمجد مستشرف وللأدب ال … مجفو ترب وللندى حلس\nوحومة للخطاب فرجها وال … قوم عجم في مثلها خرس\nشك حشاها بخطبة عنن … كأنها منه طعنة خلس\nأروع لا من رياحه الحرجف ال … صر ولا من نجومه النحس\nيشتاقه من كماله غده … ويكثر الوجد نحوه الأمس\nردي لطرفي عن وجهه زمن … وساعتي من فراقه حرس\nأيامنا في ظلاله أبدا … فصل ربيع ودهرنا عرس\nلا كأناس قد أصبحوا صدأ ال … عيش كأن الدنيا بهم حبس\nالقرب منهم بعد من الروح وال … وحشة من مثلهم هي الأنس\nتلك خلال وقف عليك ابن وه … ب بن سعيد عتاقها حبس\nآبر حمد يرى الرجال هم … سر الثرى والعلى هي الغرس"},{"id":"diwan-abutammam:207","bookId":"diwan-abutammam","type":"poem","seq":207,"chapter":"البحر: كامل تام","title":"بأبي وغير أبي وذاك قليل","page":"","text":"بأبي وغير أبي وذاك قليل … ثاو عليه ثرى النباج مهيل\nخذلته أسرته كأن سراتهم … جهلوا بأن الخاذل المخذول\nأكال أشلاء الفوارس بالقنا … أضحى بهن وشلوه مأكول !\nكفي فقتل محمد لي شاهد … أن العزير مع القضاء ذليل\nإن يستضم بعد الإباء فإنه … قد يستضام المصعب المعقول\nمستحسن وجه الردى في معرك … وجه الحياة بحومتيه جميل\nأنسى أبا نصر نسيت إذن يدي … في حيث ينتصر الفتى وينيل !\nهيهات لا يأتي الزمان بمثله … إن الزمان بمثله لبخيل !\nما أنت بالمقتول صبرا إنما … أملي غداة نعيك المقتول\nللسيف بعدك حرقة وعويل … وعليك للمجد التليد غليل\nإن طال يومك في الوغى فلقد ترى … فيه ويوم الهام منك طويل\nفستذكر الخيل انصلاتك في السرى … والقفر معروف الردى مجهول\nوتفلل الأحساب بعدك والنهى … والبيض ملس ما بهن فلول\nمن ذا يحدث بالبقاء ضميره … هيهات أنت على الفناء دليل !\nيا ليت شعري بالمكارم كلها … ماذا وقد فقدت نداك تقول ؟\nكم مشهد قد جددته لك العلا … وكأنه بالأمس وهو محيل\nوكتيبة كتبت لها أرواحها … واليوم أحمر من دم مصقول\nماشك أثبتهم يقينا أنه … للموت في قبض النفوس رسول\nيا يوم قحطبة لقد أبقيت لي … حرقا أرى أيامها ستطول\nليث لو أن الليث قام مقامه … لانصاع وهو يراعة إجفيل\nلما رأى جمعا قليلا في الوغى … وأولو الحفاظ من القليل قليل\nلاقى الكريهة وهو مغمد روعه … فيها ولكن سيفه مسلول\nومشى إلى الموت الزوام كأنما … هو في محبته إليه خليل\nلم يود منه واحد لكنما … أودى به من أسودان قبيل\nأضحت عراص محمد ومحمد … وأخيهما وكأنهن طلول\nأبني حميد ليس أول ماعفا … بعد الأسود من الأسود الغيل\nما زال ذاك الصبر وهو عليكم … بالموت في ظل السيوف كفيل\nمستبسلون كأنما مهجاتهم … ليست لهم إلا غداة تسيل\nألفوا المنايا فالقتيل لديهم … من لاتجلي الحرب وهو قتيل\nإن كان ريب الدهر أثكلنيهم … فالدهر أيضا ميت مثكول"},{"id":"diwan-abutammam:208","bookId":"diwan-abutammam","type":"poem","seq":208,"chapter":"قصائد","title":"ثقيل ردف دقيق خصر","page":"","text":"ثقيل ردف دقيق خصر … شقيق شمس نتيج بدر\nبديع حسن رشيق قد … مليح خد نقي ثغر\nقضيب بان عليه بدر … مثال حسن عروس خدر\nياخصر قد كنت دا استتار … في الحب حتى هتكت ستري\nنمت دموعي على عذابي … اذ غاب عني جميل صبري"},{"id":"diwan-abutammam:209","bookId":"diwan-abutammam","type":"poem","seq":209,"chapter":"البحر: منسرح","title":"قالت وعي النساء كالخرس","page":"","text":"قالت وعي النساء كالخرس … وقد يصبن الفصوص في الخلس\nهل يرجعن غير جانب فرسا … ذو سبب في ربيعة الفرس\nكأنني قد وردت ساحتها … بمسمح في قياده سلس\nأحمر منها مثل السبيكة أو … أحوى به كاللمى أو اللعس\nأو أدهم فيه كمتة أمم … كأنه قطعة من الغلس\nمبتل متن وصهوتين إلى … حوافر صلب له ملس\nفهو لدى الروع والحلائب ذو … أعلى مندى وأسفل يبس\nيكبر أن يستحم في الحر والقر … م حميما يزيد في النجس\nمخلق وجهه على السبق تخلي … ق عروس الأبناء للعرس\nحر له سورة لدى الزجر والسو … ط وعبد العنان والمرس\nفهو يسر الرواض بالنزق السا … كن منه واللين والشرس\nصهصلق في الصهيل تحسبه … أشرج حلقومه على جرس\nتقتل عشرا من النعام به … بواحد الشد واحد النفس\nحلفت بالبيت ذي الملبين في ال … إحرام والحل قبل والحمس\nأن ابن طوق بن مالك ملك … مالك أمر المكارم الشمس\nخلائق فيه غضة جدد … ليست بمنهوكة ولا لبس\nلا برد أدنى ولا إزار على … مخزية تتقى ولا دنس\nمفترس ماله ولست ترى … فريسة عرضه لمفترس\nكأنني قد رأيت زلفته … عند إمام بقربه أنس\nتبنى المعالي في ظله وله … حظ من الملك غير مختلس\nفإن موسى وصلى على روحه الرب … م صلاة كثيرة القدس\nصار نبيا وعظم بغيته … في جذوة للصلاء أو قبس"},{"id":"diwan-abutammam:210","bookId":"diwan-abutammam","type":"poem","seq":210,"chapter":"البحر: طويل","title":"جوى ساور الأحشاء والقلب واغله","page":"","text":"جوى ساور الأحشاء والقلب واغله … ودمع يضيم العين والجفن هامله\nوفاجع موت لا عدوا يخافه … فيبقي ولا يبقي صديقا يجامله\nوأي أخي عزاء أو جبرية … ينابذه أو رام يناضله\nإذا ما جرى مجرى دم المرء حكمه … وبثت على طرق النفوس حبائله\nفلو شاء هذا الدهر أقصر شره … كما قصرت عنا لهاه ونائله\nسنشكوه إعلانا وسرا ونية … شكية من لا يستطيع يقاتله\nفمن مبلغ عني ربيعة أنه … تقشع طل الجود منها ووابله\nوأن الحجى منها استطارت صدوعه … وأن الندى منها أصيبت مقاتله ؟\nمضى للزيال القاسم الواهب اللهى … ولو لم يزايلنا لكنا نزايله\nولم يعلموا أن الزمان يريده … بفجع ولا أن المنايا تراسله\nفتى سيط حب المكرمات بلحمه … وخامره حق السماح وباطله\nفتى لم يذق سكر الشباب ولم تكن … تهب شمالا للصديق شمائله\nفتى جاءه مقداره واثنتا العلا … يداه وعشر المكرمات أنامله\nفتى ينفج الأقوام من طيب ذكره … ثناء كأن العنبر الورد شامله\nلقد فجعت عتابه وزهيره … وتغلبه أخرى الليالي ووائله\nوكان لهم غيثا وعلما فمعدم … فيسأله أو باحث فيسائله\nومبتدر المعروف تسري هباته … إليهم ولاتسري إليهم غوائله\nفتى لم تكن تغلي الحقود بصدره … وتغلي لأضياف الشتاء مراجله\nمليك لأملاك تضيف ضيوفه … ويرجى مرجيه ويسأل سائله\nطواه الردى طي الكتاب وغيبت … فضائله عن قومه وفواضله\nطوى شيما كانت تروح وتغتدي … وسائل من أعيت عليه وسائله\nفيا عارضا للعرف أقلع مزنه … ويا واديا للجود جفت مسائله\nألم ترني أنزفت عيني على أبي … محمد النجم المشرق آفله\nوأخضلتها فيه كما لو أتيته … طريد الليالي أخضلتني نوافله !\nولكنني أطري الحسام إذا مضى … وإن كان يوم الروع غيري حامله !\nوآسى على جيحان إذ غاض ماؤه … وإن كان ذودا غير ذودي ناهله\nعليك أبا كلثوم الصبر إنني … أرى الصبر أخراه تقى وأوائله\nتعادل وزنا كل شيء ولا أرى … سوى صحة التوحيد شيئا يعادله\nفأنت سنام للفخار وغارب … وصنواك منه منكباه وكاهله\nوليست أثافي القدر إلا ثلاثها … ولا الرمح إلا لهذماه وعامله"},{"id":"diwan-abutammam:211","bookId":"diwan-abutammam","type":"poem","seq":211,"chapter":"البحر: كامل تام","title":"ما في وقوفك ساعة من باس","page":"","text":"ما في وقوفك ساعة من باس … نقضي ذمام الأربع الأدراس\nفلعل عينك أن تعين بمائها … والدمع منه خاذل ومواس\nلايسعد المشتاق وسنان الهوى … يبس المدامع بارد الأنفاس\nإن المنازل ساورتها فرقة … أخلت من الآرام كل كناس\nمن كل ضاحكة الترائب أرهفت … إرهاف خوط البانة المياس\nبدر أطاعت فيك بادرة النوى … ولعا وشمس أولعت بشماس\nبكر إذا ابتسمت أراك وميضها … نور الأقاحي في ثرى ميعاس\nوإذا مشت تركت بصدرك ضعف ما … بحليها من كثرة الوسواس\nقالت وقد حم الفراق فكأسه … قد خولط الساقي بها والحاسي\nلاتنسين تلك العهود فإنما … سميت إنسانا لأنك ناسي\nإن الذي خلق الخلائق قاتها … أقواتها لتصرف الأحراس\nفالأرض معروف السماء قرى لها … وبنو الرجاء لهم بنو العباس\nالقوم ظل الله أسكن دينه … فيهم وهم جبل الملوك الراسي\nفي كل جوهرة فرند مشرق … وهم الفرند لهؤلاء الناس\nهدأت عل تأميل أحمد همتي … وأطاف تقليدي به وقياسي\nبالمجتبى والمصطفى والمسترى … للحمد والحالي به والكاسي\nوالحمد برد جمال اختالت به … غرر الفعال وليس برد لباس\nفرع نما من هاشم في تربة … كان الكفيء لها من الأغراس\nلا تهجر الأنواء منبتها ولا … قلب الثرى القاسي عليها قاسي\nوكأن بينهما رضاع الثدي من … فرط التصافي أو رضاع الكاس\nنور العرارة نوره ونسيمه … نشر الخزامى في اخضرار الآس\nأبليت هذا المجد أبعد غاية … فيه وأكرم شيمة ونحاس\nإقدام عمرو في سماحة حاتم … في حلم أحنف في ذكاء إياس\nلا تنكروا ضربي له من دونه … مثلا شرودا في الندى والباس\nفالله قد ضرب الأقل لنوره … مثلا من المشكاة والنبراس\nإن تحو خصل المجد في أنف الصبا … يابن الخليفة يا أبا العباس\nفلرب نار منكم قد أنتجت … في الليل من قبس من الأقباس\nولرب كفل في الخطوب تركته … لصعابها حلسا من الأحلاس\nأمددته في العدم والعدم الجوى … بالجود والجود الطبيب الآسي\nآنسته بالدهر حتى أنه … ليظنه عرسا من الأعراس\nغلب السرور على همومي بالذي … أظهرت من بري ومن إيناسي\nعدل المشيب على الشباب ولم يكن … من كبرة لكنه من ياس\nأثر المطالب في الفؤاد وإنما … أثر السنين ووسمها في الراس\nفالآن حين غرست في كرم الثرى … تلك المنى وبنيت فوق أساس"},{"id":"diwan-abutammam:212","bookId":"diwan-abutammam","type":"poem","seq":212,"chapter":"البحر: كامل تام","title":"مازالت الأيام تخبر سائلا","page":"","text":"مازالت الأيام تخبر سائلا … أن سوف تفجع مسهلا أو عاقلا\nإن المنون إذا استمر مريرها … كانت لها جنن الأنام مقاتلا\nفي كل يوم يعتبطن نفوسنا … عبط المنحب جلة وأفائلا\nما إن ترى شيئا لشيء محييا … حتى تلاقيه لآخر قاتلا\nمن ذاك أجهد أن لا أراه فلا أرى … حقا سوى الدنيا يسمى باطلا\nلله أية لوعة ظلنا بها … تركت بكيات العيون هواملا !\nمجد تأوب طارقا حتى إذا … قلنا أقام الدهر أصبح راحلا\nنجمان شاء الله ألا يطلعا … إلا ارتداد الطرف حتى يأفلا\nإن الفجيعة بالرياض نواضرا … لأجل منها بالرياض ذوابلا\nلو ينسآن لكان هذا غاربا … للمكرمات وكان هذا كاهلا\nلهفي على تلك الشواهد فيهما … لو أمهلت حتى تكون شمائلا\nلغدا سكونهما حجى وصباهما … حلما وتلك الأريحية نائلا\nولأعقب النجم المرذ بديمة … ولعاد ذاك الطل جودا وابلا\nإن الهلال إذا رأيت نموه … أيقنت أن سيكون بدرا كاملا\nقل للأمير وإن لقيت موقرا … منه بريب الحادثات حلاحلا\nإن تزز في طرفي نهار واحد … رزئين هاجا لوعة وبلابلا\nفالثقل ليس مضاعفا لمطية … إلا إذا ما كان وهما بازلا\nلاغرو إن فننان من عيدانه … لقيا حماما للبرية آكلا\nإن الأشاء إذا أصاب مشذب … منه اتمهل ذرى وأث أسافلا\nحقفان هالهما القضاء وغادرا … قللا لنا دون السماء قواعلا\nرضوى وقدس ويذبلا وعماية … ويرمرما ومتالعا ومواسلا\nالطاهرين وإخوة أنجبتهم … كالحوم وجه صادرا أو ناهلا\nشمخت خلالك أن يؤسيك امرؤ … أو أن تذكر ناسيا أو غافلا\nإلا مواعظ قادها لك سمحة … إسجاح لبك سامعا أو قائلا\nهل تكلف الأيدي بهز مهند … إلا إذا كان الحسام القاصلا"},{"id":"diwan-abutammam:213","bookId":"diwan-abutammam","type":"poem","seq":213,"chapter":"البحر: كامل تام","title":"من أين لي صبر على الهجر","page":"","text":"من أين لي صبر على الهجر … لو أن قلبي كان من صخر ؟\nويل لجسمي من دواعي الهوى … ويل معي يدخل في القبر\nلو كنت أرعى النجم تقوى لقد … أدرك طرفي ليلة القدر"},{"id":"diwan-abutammam:214","bookId":"diwan-abutammam","type":"poem","seq":214,"chapter":"البحر: بسيط تام","title":"أحيا حشاشة قلب كان مخلوسا","page":"","text":"أحيا حشاشة قلب كان مخلوسا … ورم بالصبر عقلا كان مألوسا\nسرى رداء الهوى في حين جدته … واها له منه مسرورا وملبوسا !\nلو تشهدين أقاسي الدمع منهمرا … والليل مرتتج الأبواب مطموسا\nإستنبت القلب من لوعاته شجرا … من الهموم فأجنته الوساويسا\nأهل الفراديس لم أعدد لذكركم … إلا رعى وسقى الله الفراديسا\nإذ لا نعطل منها منظرا أنقا … ومربعا بمها اللذات مأنوسا\nقد قلت لما اطلخم الأمر وانبعثت … عشواء تالية غبسا دهاريسا\nلي حرمة بك أمسى حق نازلها … وقفا عليك - فدتك النفس - محبوسا\nكم دعوة لي إذا مكروهة نزلت … واستفحل الخطب يا عياش ياعيسى\nلله أفعال عياش وشيمته … يزدنه كرما إن ساس أو سيسا\nما شاهد اللبس إلا كان متضحا … ولانأى الحق إلا كان ملبوسا\nفاضت سحائب من نعمائه فطمت … نعماه بالبؤس حتى اجتثت البوسا\nيحرسن بالبذل عرضا ما يزال من ال … آفات بالنفحات الغر محروسا\nفرع سما في سماء العز متخذا … أصلا ثوى في قرار المجد مغروسا\nليث ترى كل يوم تحت كلكله … ليثا من الإنس جهم الوجه مفروسا\nأهيس أليس مشاء إلى همم … تغرق العيس في آذيها الليسا\nنافس أهل العلى فاحتاز عقلهم … منهم فأصبح معطى الحق منفوسا\nتجري السعود له في كل نائبة … نابت وإن كان يوم البأس منحوسا\nله لواء ندى ما هز عامله … إلا أراك لواء البخل منكوسا\nمقابل في بني الأذواء منصبه … عيصا فعيصا وقدموسا فقدموسا\nالواردين حياض الموت متأقة … ثبا ثبا وكراديسا كراديسا\nوالمانعين حياض المجد إن دهمت … منع الضراغم آجاما وعريسا\nنموك قنعاس دهر حين يحزبه … أمر يشابه آباء قناعيسا\nوقدموا منك إن هم خاطبوا ذربا … ورادسوا حضرمي الصخر رديسا\nأشم أصيد تكوي الصيد غرته … كيا وأشوس يعشي الأعين الشوسا\nشامت بروقك آمالي بمصر ولو … أصبحت بالطوس لم استبعد الطوسا"},{"id":"diwan-abutammam:215","bookId":"diwan-abutammam","type":"poem","seq":215,"chapter":"البحر: طويل","title":"ذكرت محمدا بقتل محمد","page":"","text":"ذكرت محمدا بقتل محمد … وقحطبة ذكرا طويل البلابل\nوكان الأسى قد آل فيه إلى الحشا … فلما استجراه جرى في المفاصل\nكماء الغدير امتد بعد وقوعه … بما هاج من فيض التلاع القوابل\nثووا في الثرى من بعدما سربلوا العلا … ومن بعدما سموا نجوم المحافل\nمصارع لم تورث شنارا وإنها … ليرتع فيها شامت عند جاهل\nلعمرك ماكانوا ثلاثة أخوة … ولكنهم كانوا ثلاث قبائل"},{"id":"diwan-abutammam:216","bookId":"diwan-abutammam","type":"poem","seq":216,"chapter":"البحر: سريع","title":"معتمدا كالغصن الناضر","page":"","text":"معتمدا كالغصن الناضر … ابلج مثل القمر الزاهر\nجفونه ترشق أهل الهوى … باسهم من طرفه الفاتر\nقد قلتث لما لج في صده … إعطف على عبدك يا قابري\nإن لم تجد لي صحت بين الورى … ويلاه من ظبي بني عامر"},{"id":"diwan-abutammam:217","bookId":"diwan-abutammam","type":"poem","seq":217,"chapter":"البحر: كامل تام","title":"أقشيب ربعهم أراك دريسا","page":"","text":"أقشيب ربعهم أراك دريسا … وقرى ضيوفك لوعة ورسيسا\nولئن حبست على البلى لقد اغتدى … دمعي عليك إلى الممات حبيسا\nفكأن طسما قبل كانوا جيرة … بك والعماليق الألى وجديسا\nوأرى ربعك موحشات بعدها … قد كنت مألوف المحل أنيسا\nوبلاقعا حت كأن قطينها … حلفوا يمينا أخلقتك غموسا\nأترى الفراق يظن أني غافل … عنه وقد لمست يداه لميسا\nرود أصابتها النوى في خرد … كانت بدور دجنة وشموسا\nبيض تدور عيونهن إلى الصبا … فكأنهن بها يدرن كووسا\nوكأنما أهدى شقائقه إلى … وجناتهن بها أبو قابوسا\nقد أوتيت من كل شيء بهجة … وددا وحسنا في الصبا مغموسا\nلولا حداثتها وأني لا أرى … عرشا لها لظننتها بلقيسا\nإيها دمشق فقد حويت مكارما … بأبي المغيث وسؤددا قدموسا\nوأرى الزمان غدا عليك بوجهه … جذلان بساما وكان عبوسا\nقد بوركت تلك البطون وقدست … تلك الظهور بقربه تقديسا\nفصنيعة تسدى وخطب يعتلى … وعظيمة تكفى وجرح يوسى\nالآن أمست للنفاق وأصبحت … عورا عيون كن قبلك شوسا\nوتركت تلك الأرض ظلا سجسجا … من بعد ماكادت تكون وطيسا\nلم يشعروا حتى طلعت عليهم … بدرا يشق الظلمة الحنديسا\nما في النجوم سوى تعلة باطل … قدمت وأسس إفكها تأسيسا\nإن الملوك هم كواكبنا التي … تخفى وتطلع أسعدا ونحوسا\nفتن جلوت ظلامها من بعد ما … مدوا عيونا نحوها ورؤوسا\nحرب يكون الجيش فضل صبوحها … ويكون فضل عبوقها الكردوسا\nغرم امرىء من روحه فيها إذا … ذو السلم أغرم مطعما ولبوسا\nكم بين قوم إنما نفقاتهم … مال وقوم ينفقون نفوسا !\nسار ابن إبراهيم موسى سيرة … سكن الزمان لها وكان شموسا\nفأقر واسطة الشآم وأنشرت … كفاه جورا لم يزل مرموسا\nكانت مدينة عسقلان عروسها … فغدت بسيرته دمشق عروسا\nمن بعد ما صارت هنيدة صرمة … والبدرة النجلاء صارت كيسا\nفكأنهم بالعجل ضلوا حقبة … وكأن موسى إذ أتاهم موسى\nوستشكر النعمى التي صنعت ولا … نعم كنعمى أنقذت من بوسى\nألوى يذل الصعب إن هو ساسه … ويلين جانبه إذا ما سيسا\nولذاك كانوا لا يرأس منهم … من لم يجرب حزمه مرؤوسا\nمن لم يقد فيطير في خيشومه … رهج الخميس فلن يقود خميسا\nأعط الرياسة من يديك فلم تزل … من قبل أن تدعى الرئيس رئيسا\nماذا عسيت ومن أمامك حية … تقص الأسود ومن ورائك عيسى\nأسدان شدا من دمشق وذللا … من حمص أمنع بلدة عريسا\nتخذ القنا خيسا فإن طاغ طغى … نقلا إلى مغناه ذاك الخيسا\nأسق الرعية من بشاشتك التي … لو أنها ماء لكان مسوسا\nإن الطلاقة والندى خير لهم … من عفة جمست عليك جموسا\nلو أن أسباب العفاف بلا تقى … نفعت لقد نفعت إذا إبليسا\nهذي القوافي قد أتينك نزعا … تتجسم التهجير والتغليسا\nمن كل شاردة تغادر بعدها … حظ الرجال من القصيد خسيسا\nوجديدة المعنى إذا معنى التي … تشقى بها الأسماع كان لبيسا\nتلهو بعاجل حسنها وتعدها … علقا لأعجاز الزمان نفيسا\nمن دوحة الكلم التي لم تنفكك … يمسي عليك رصينها محبوسا\nكالنجم إن سافرت كان مواكبا … وإذا حططت الرحل كان جليسا\nإنا بعثنا الشعر نحوك مفردا … وإذا أذنت لنا بعثنا العيسا\nتبغي ذراك إذا آسنة قعضب … أردين عريف الوغى المريسا"},{"id":"diwan-abutammam:218","bookId":"diwan-abutammam","type":"poem","seq":218,"chapter":"البحر: بسيط تام","title":"لا تعذلي جارتي إنى لك العذل","page":"","text":"لا تعذلي جارتي إنى لك العذل … فلا شوى ما زريناه ولا جلل\nإحدى المصائب حلت في ديار بني … عمران ليست لها أخت ولا مثل\nألوى بتيجانهم يوم أتيح له … نحس وأثقب فيه ناره زحل\nألوى به وهو ملو بالقنا لتوا … ليها استواء وفي أعناقها ميل\nكان الذي ليس في معجومه خور … للعاجمين ولا في هديه خلل\nكان الذي يتقى ريب الزمان به … إذا الزمان بدت أنيابه العصل\nأحلنا الدهر في بطحاء مسهلة … لما تقوضت عنها أيها الجبل\nماكان أحسن حالات الأشاعر يا … يحيى بن عمران لو أنسي لك الأجل\nأي امرئ منك أثرى بين أعظمه … ثرى المقطم أو محلوده الرمل\nلايتبع المن ماجادت يداه به … ولا تحكم في معروفه العلل\nماقال كان إذا ما القوم أكذب ما … أطال من قولهم تقصير ما فعلوا\nيا موت حسبك إذ أقصدت مهجته … أولا فدونك لا حسب ولا بجل\nماحالنا يا أبا العباس بعدك هل … تنمى الفروع ويودي أصلها الأصل\nيا موت لو في وغى عاينته خلدت … عليه عوض دموع منك تنهمل\nالمشعل الحربض نارا وهي خامدة … والمستبيح حماها وهي تشتعل\nبكل يوم وغى تصدى الكمأة به … على يديه وتروى البيض والأسل\nيغشى الوغى بالقنا والخيل عابسة … والخيل لاعاجز فيها ولاوكل\nوالكاشف الكرب اللاتي يحف بها … إظلام أمر على البلدان ينسدل\nبمشهد ليس يثنيه به زلل … ومنطق ليس يعروه به خطل\nمستجمع لا يحل الريث عقدته … فيه ولا يمتطي إبلاغه العجل\nبحيث لا يضع الآراء موضعها … \nإذا الرجال رأوه وهو يفعل ما … أعياهم فعله قالوا كذا الرجل\nإما يدل منك بالموت العدى فبما … دارت عليهم بلا موت لك الدول\nأيام سيفك مشهور وبحرك مس … جور وقرنك مقصور له الطول\nإذ لابس الذلة المقطوع ذو رحم … قطعته وإذا الموصول من تصل\nجرعك الدهر كاس الصبر في لجج … للموت يغرق في آذيها الجبل\nموتا وقتلا كأن الدهر يظمأ ما … عاشوا وينقع ما ماتوا وماقتلوا\nياشاغل الدهر عنا ما لصولته … مذ صال فيك الردى إلا بنا شغل\nيا حلية المجد إن المجد عن عفر … بدا وحليته من بعدك العطل\nيا موئلا كان مأوى الآمات به … إذا ادلهمت بمكروهاتها العضل\nفأي معتمد يزكو به عمل … وأي منتظر يحيا به أمل\nلكن حسين وأمثال الحسين إاذ … ما الناس يوم حفاظ حصلوا قلل\nتنبي المواقف عنه أنه سند … ويخبر الروع عنه أنه بطل\nيعطي فيجزل أو يدعى فينزل أو … يؤتى لمحمل أعباء فيحتمل\nتظنه شيخه لولا شبيبته … والزرع ينبت فذا ثم يكتهل\nأضحى لنا بدلا منه تنوء به … والشبل من ليثه إما مضى بدل"},{"id":"diwan-abutammam:219","bookId":"diwan-abutammam","type":"poem","seq":219,"chapter":"البحر: طويل","title":"أبادرها بالشكر قبل وصالها","page":"","text":"أبادرها بالشكر قبل وصالها … وإن هجرت يوما طلبت لهاعذرا\nوأجعلها في الغدر عندي وفية … وإن زعمت أني لها مضمر غدرا\nأتاها بطيب أهلها فتضاحكت … وقالت أيبغي العطر ويحكم العطرا ؟\nأحاديثها در ودر كلامها … ولم أر درا قبله ينظم الدرا"},{"id":"diwan-abutammam:220","bookId":"diwan-abutammam","type":"poem","seq":220,"chapter":"البحر: سريع","title":"جرت له أسماء حبل الشموس","page":"","text":"جرت له أسماء حبل الشموس … والوصل والهجر نعيم وبوس\nولم تجد بالري ريا ولم … تلمس فؤادا يتمته لميس\nكواكب الدنيا السعود التي … بدلها دلت عليك النحوس\nأبا علي أنت وادي الندى ال … أحوى ومغنى المكرمات الأنيس\nالبيت حيث النجم والكف حي … ث الغيث في الأزمة والدار خيس\nيا بن رجاء أفدت نية … ركوبها مني خيم وسوس\nفامدد عناني بوأى ضلعه … تثبت والعذرة منه تنوس\nأقاتل الهم بإيجافه … فإن حرب الهم حرب ضروس\nإذا المذاكي خطبت نقعه … فحظها منه اللفاء الخسيس\nموضح ليس بذي رجلة … أشأم والأرجل منها بسوس\nوكل لون فليكن ما خلا ال … أشهب فالشهبة لون لبيس\nومجفر لم يصطلم كشحه … فالضمر المفرط فيها رسيس\nإن زار ميدانا سابقا … أو ناديا قام إليه الجلوس\nترى رزان القوم قد أسمحت … أعينهم في حسنه وهي شوس\nكأنما لاح لهم بارق … في المحل أو زفت إليهم عروس\nسام إذا اسعرضته زانه … أعلى رطيب وقرار يبيس\nفإن خدا يرتجل المشي فال … موكب في إحسانه والخميس\nكأنما خامره أولق … أو غازلت هامته الخندريس\nعوذه الحاسد بخلا به … ورفرفت خوفا عليه النفوس\nومثله ذو العن السبط قد … أمطيته والكفل المرمريس\nغادرته وهو على سؤؤد … وقف وفي سبل المعالي حبيس\nوحادث أخرق داويته … رداعه ذا هيئة دردبيس\nأخمدته والدهر من خطبه … كأنما أضرم فيه الوطيس\nحتى انثنى العسر إلى يسره … وانحت عن خديه ذاك العبوس\nلا طالبو جدواك أكدوا ولا … عافيك منهم لليالي فريس\nفاشدد على الحمد يدا إنه … إذا استحس العلق علق نفيس\nواغد على موشيه إنه … برد لعمري تصطفيه النفوس"},{"id":"diwan-abutammam:221","bookId":"diwan-abutammam","type":"poem","seq":221,"chapter":"البحر: طويل","title":"لنمنا وصرف الدهر ليس بنائم","page":"","text":"لنمنا وصرف الدهر ليس بنائم … خزمنا له قسرا بغير خزائم\nألست ترى ساعاته واقتسامها … نفوس بني الدنيا اقتسام الغنائم ؟\nليال إذا أنحت عليك عيونها … أرتك اعتبارا في عيون الأراقم\nشرقنا بذم الدهر يا سلم إنه … يسيء فما يألو وليس بظالم\nإذا فقد المفقود من آل مالك … تقطع قلبي رحمة للمكارم\nخليلي من بعد الأسى والجوى قفا … ولاتقفا فيض الدموع السواجم\nألما فهذا مصرع البأس والندى … وحسب البكا إن قلت مصرع هاشم\nألم تريا الأيام كيف فجعننا … به ثم قد شاركننا في المآتم ؟ !\nخطون إليه من نداه وبأسه … خلائق أوقى من ستور التمائم\nخلائق كالزغف المضاعف لم تكن … لتنفذها يوما شباه اللوائم\nولو عاش فينا بعض عيش فعاله … لأخلق أعمار النسور القشاعم\nرأى الدهر منه عثرة ماأقالها … وهل حازم يأوي لعثرة حازم\nلئن كان سيف الموت أسود صارما … لقد فل منه حد أبيض صارم\nأصاب امرءا كانت كرائم ماله … عليه إذا ما سيل غير كرائم\nجرى المجد مجرى النوم منه فلم يكن … بغير طعان أو سماح بحالم\nتبين في إشراقه وهو نائم … بأن الندى في روحه غير نائم\nفإن توه في الدنيا دعائم عمره … فما جوده فيها بواهي الدعائم\nإذا المرء لم تهدم علاه حياته … فليس لها الموت الجليل بهادم\nأهاشم صار الدمع ضربة لازم … وماكان لولا أنت ضربة لازم\nأهاشم للحيين فيك مصائب … دلوه جمعت كانت لبعض المواسم\nمساع تشظت في المواسم كلها … ولو جمعت كانت كبعض المواسم\nليومك عند الأزد يوم تخزعت … خزاعة منها في بطون التهائم\nوما يوم زرت اللحد يومك وحده … علينا ولكن يوم عمر ووحاتم\nفكم ملحد في يوم ذلك غانم … وكم منبر في يوم ذلك غارم !\nلئن عم ثكلا كل شيء مصابه … لقد خص أطراف السيوف الصوارم\nتسلبت الدنيا عليه فأصبحت … خلائقها مثل الفجاج القواتم\nوما نكبة فاتت به بعظيمة … ولكنها من أمهات العظائم\nبني مالك قد نبهت خامل الثرى … قبور لكم مستشرفات المعالم\nرواكد قيس الكف من متناول … وفيها على لاترتقى بالسلالم\nقضيتم حقوق الأرض منكم بأعظم … عظام قضت دهرا حقوق المقاوم\nخدعت لئن صدقت أن غيابة … تكشف إلا عن وجوه الهيائم\nرأيتهم ريش الجناح إذا ذوت … قوادم منها أيدت بقوادم\nإذا اختل ثغر المجد أضحى جلادهم … ونائلهم من حوله كالعواصم\nفلا تطلبوا أسيافهم في جفونها … فقد أسكنت بين الطلى والجماجم\nإذا ما رماح القوم في الروع أكرمت … مشاربها عاشوا كرام المطاعم"},{"id":"diwan-abutammam:222","bookId":"diwan-abutammam","type":"poem","seq":222,"chapter":"البحر: بسيط تام","title":"قد صنف الحسن في خديك جوهره","page":"","text":"قد صنف الحسن في خديك جوهره … وفيه قد خلف التفاح أحمره\nوكل حسن فمن عينيك أوله … مذ خط هاروت في عينيك عسكره\nوكان خدك دهرا مشرقا يققا … فمن تمكن فيه للحظ عصفره"},{"id":"diwan-abutammam:223","bookId":"diwan-abutammam","type":"poem","seq":223,"chapter":"البحر: بسيط تام","title":"أقرم بكر تباهي أيها الحفض","page":"","text":"أقرم بكر تباهي أيها الحفض … ونجمها أيهذا الهالك الحرض\nتنحي على صخرة صماء تحسبها … عضوا خلت به تبري وتنتحض\nفي شامتين هو الشري الجني لهم … والصاب والشرق المسموم والحرض\nمخامري حسد ما ضر غيرهم … كأنما هو في أبدانهم مرض\nلا يهنء العصبة المحمر أعينها … بثغر أران هذا الحادث العرض\nأضحى الشجا مستطيلا في حلوقهم … من بعد ما جاذبوه وهو معترض\nسهم الخليفة في الهيجا إذ سعرت … بالبيض والتفت الأحقاب والغرض\nبذلك السهم ذي النصلين قد حفزا … بريش نسرين يرمى ذلك الغرض\nظل من الله أضحى أمس منبسطا … به على الثغر فهو اليوم منقبض\nلخالد عوض في كل ناحية … منه ، وليس له من خالد عوض\nلم تنتقض عروة منه ولا سبب … لكن أمر بني الآمال ينتقض"},{"id":"diwan-abutammam:224","bookId":"diwan-abutammam","type":"poem","seq":224,"chapter":"البحر: بسيط تام","title":"محمد بن حميد أخلقت رممه","page":"","text":"محمد بن حميد أخلقت رممه … أريق ماء المعالي مذ أريق دمه\nتنبهت لبني نبهان يوم ثوى … يد الزمان فعاثت فيهم وفمه\nرأيته بنجاد السيف محتبيا … كالبدر حين جلت عن وجهه ظلمه\nفي روضة قد علا حافاتها زهر … علمت عند انتباهي أنها نعمه\nفقلت والدمع من حزن ومن فرح … يجري ومد فلأ الخدين منسجمه\nألم تمت ياشقيق النفس مذ زمن ؟ … فقال لي : لم يمت من لم يمت كرمه"},{"id":"diwan-abutammam:225","bookId":"diwan-abutammam","type":"poem","seq":225,"chapter":"البحر: خفيف تام","title":"وثناياك إنها إغريض","page":"","text":"وثناياك إنها إغريض … ولأل توم وبرق وميض\nوأقاح منور في بطاح … هزه في الصباح روض أريض\nوإرتكاض الكرى بعينيك في النو … م فنونا وما لعيني غموض\nلتكاءدتني غمار من الأحد … اث لم أدر أيهن أخوض\nأتأرتني الأيام بالنظر الشز … ر وكانت وطرفها لي غضيض\nكيف يضحي براس علياء مضح … وجناح السمو منه مهيض\nهمة تنطح النجوم وجد … آلف للحضيض فهو حضيض\nكم فتى ذل للزمان وقد ال … قى مقاليده إليه القبيض\nلوذعي يهلل المشرفي ال … عضب عنه والزاعبي النحيض\nوبساط كأنما الآل فيه … وعليه سحل الملاء الرخيض\nيصبح الداعري ذو الميعة المر … جم فيه كأنه مأبوض\nقد فضضنا من بيده خاتم الخو … ف وما كل خاتم مفضوض\nبالمهارى يجلن فيه وقد جا … لت على مسنماتهن الغروض\nجازعات سود المروراة ته … ديها وجوه لمكرماتك بيض\nسعم حث ركبهن أمان … فيك تترى حث القداح المفيض\nفاشمعلوا يلجلجون دؤوبا … مضغا للكلال فيها أنيض\nلن يهز التصريح للمجد والس … ؤدد من لم يهزه التعريض\nكل يوم يقضيه نوع … وعروض يتلوه فيك عروض\nوقواف قد ضج منها لما استع … مل فيها المرفوع والمخفوض\nالمديح الجزيل والشكر والفك … ر ومر العتاب والتحريض\nوحياة القريض إحياؤك الجو … د فإن مات الجود مات القريض\nكن طويل الندى عريضا فقد ساد … ثنائي فيك الطويل العريض\nإنما صادت البحور بحورا … إنها كلما استفيضت تفيض\nيامحب الإحسان في زمن أص … بح فيه الإحسان وهو بغيض\nقل لعا لابن عشرة ما له من … ها بشيء سوى نداك نهوض\nلاتكن لي ولن تكون كقوم … عودهم حين يعجمون رفيض\nعندهم محضر من البشر مبسو … ط لعاف ونائل مقبوض\nوأقل الأشياء محصول نفع … صحة القول والفعال مريض"},{"id":"diwan-abutammam:226","bookId":"diwan-abutammam","type":"poem","seq":226,"chapter":"البحر: خفيف تام","title":"رحم الله جعفرا فلقد كا","page":"","text":"رحم الله جعفرا فلقد كا … ن أبيا شهما وكان رحيما\nمثل الموت بين عينيه والذلم … فكلا رآه خطبا عظيما\nثم سارت به الحمية قدما … فأمات العدى ومات كريما"},{"id":"diwan-abutammam:227","bookId":"diwan-abutammam","type":"poem","seq":227,"chapter":"البحر: كامل تام","title":"هذا هواك وهذه آثاره","page":"","text":"هذا هواك وهذه آثاره … أما الؤاد فما يقر قراره\nيصل الأنين بزفرة موصولة … بغليل شوق ليس تطفا ناره\nودعا الدموع فأقبلت منهلة … شوقا وذاك قصارهاوقصاره\nمن طرف ممتنع الرقاد متيم … أرق سواء ليله ونهاره"},{"id":"diwan-abutammam:228","bookId":"diwan-abutammam","type":"poem","seq":228,"chapter":"البحر: طويل","title":"مهاة النقا لولا الشوى والمآبض","page":"","text":"مهاة النقا لولا الشوى والمآبض … وإن محض الإعراض لي منك ماحض\nرعت طرفها في هامة قد تنكرت … وصوح منها نبتها وهو بارض\nفصدت وعاضته أسى وصبابة … وما عائض منها وإن جل عائض\nفما صقل السيف اليماني لمشهد … كما صقلت بالأمس تلك العوارض\nولا كشف الليل النهار وقد بدا … كما كشفت تلك الشؤون الغوامض\nولاعملت خرقاء أوهت شعيبها … كما عملت تلك الدموع الفوائض\nوأخرى لحتني حين لم أمنع النوى … قيادي ولم ينقض زماعي ناقض\nأرادت بأن يحوي الرغيبات وادع … وهل يفرس الليث الطلى وهو رابض\nهي الحرة الوجناء وابن ملمة … وجأش على ما يحدث الدهر خافض\nإذا ما رأته العيس ظلت كأنما … عليها من الورد اليمامي نافض\nإليك سرى بالمدح قوم كأنهم … على المييس حيات اللصاب النضانض\nمعيدين ورد الحوض قد هدم البلى … نصائبه وانمح منه المراكض\nنشيم بروقا من نداك كأنها … وقد لاح أولاها عروق نوابض\nفما زلن يستشرين حتى كأنما … على أفق الدنيا سيوف روامض\nفلم تنصرم إلا وفي كل وهدة … ونشز لها واد من العرف فائض\nأخا الحرب كم ألحقتها وهي حائل … وأخرتها عن وقتها وهي ماخض\nإذا عرض رعديد تدنس في الوغى … فسيفك في الهيجا لعرضك راحض\nإذا كانت الأنفاس جمرا لدى الوغى … وضاقت ثياب القوم وهي فضافض\nبحيث القلوب الساكنات خوافق … وماء الوجوه الأريحيات غائض\nفأنت الذي تستيقظ الحرب باسمه … إذا جاض عن حد الأسنة جائض\nإذا قبض النقع العيون سما له … همام على جمر الحفيظة قابض\nوقد علم الحزم الذي أنت ربه … بأن لا يعي العظم الذي أنت هائض\nوقد علم القرن المساميك أنه … سيغرق في\nكما علم المستشعرون بأنهم … بطاء عن الشعر الذي أنا قارض\nكأني دينار ينادي ألا فتى … يبارز إذ ناديت من ذا يعارض\nفلا تنكروا ذل القوافي فقد رأى … محرمها أني لها الدهر رائض"},{"id":"diwan-abutammam:229","bookId":"diwan-abutammam","type":"poem","seq":229,"chapter":"البحر: بسيط تام","title":"اليوم أدرج زيد الخيل في كفن","page":"","text":"اليوم أدرج زيد الخيل في كفن … وانحل معقود دمع الأعين الهتن\nبني حميد لو ان الدهر متزع … لصد من ذكركم عن جانب خشن\nإن ينتخل حدثان الدهر أنفسكم … ويسلم الناس بين الحوض والعطن\nفالماء ليس عجيبا أن أعذبه … يفنى ويمتد عمر الآجن الأسن\nرزء على طيىء ألقى كلاكله … لابل على أدد لابل على اليمن\nلم يثكلوا ليث حرب مثل قحطبة … من بعد قحطبة في سالف الزمن\nإلا تكن صدرت عن منظر حسن … حرب ، فقد صدرت عن مسمع حسن\nنعم الفتى غير نكس في الجلاد ولا … لدن الفؤاد لدى وقع القنا اللدن\nحن إلى الموت حتى ظن جاهله … بأنه حن مشتاقا إلى وطن\nولى الحماة وأضحى عند سورته … مع الحمية كالمشدود في قرن\nرأى المنايا حبالات النفوس فلم … يسكن سوى الميتة العليا إلى سكن\nلو لم يمت بين أطراف الرماح إذا … لمات إذ لم يمت من شدة الحزن"},{"id":"diwan-abutammam:230","bookId":"diwan-abutammam","type":"poem","seq":230,"chapter":"البحر: خفيف تام","title":"إن يوم الفراق يوم عبوس","page":"","text":"إن يوم الفراق يوم عبوس … أي سيل تسيل منه النفوس\nلم أزل ابغض الخميس ولم … ر لماذا حتى دهاني الخميس\nبأبي من إذا رآها أبوها … شغفا قال ليت أنا مجوس"},{"id":"diwan-abutammam:231","bookId":"diwan-abutammam","type":"poem","seq":231,"chapter":"البحر: كامل تام","title":"أهلوك أضحوا شاخصا ومقوضا","page":"","text":"أهلوك أضحوا شاخصا ومقوضا … ومزمما يصف النوى ومغرضا\nإن يدج ليلك أنهم أموا اللوى … فلقد أضاء وهم على ذات الأضا\nبدلت من برق الثغور وبردها … برقا إذا ظعن الأحبة أومضا\nلو كان أبغض قلبه فيما مضى … أحد لكنت إذا لقلبي مبغضا\nقل الغضى لاشك في أوطانه … مما حشدت إليه من جمر الغضى\nما أنصف الزمن الذي بعث الهوى … فقضى عليك بلوعة ثم انقضى\nعندي من الأيام ما لو أنه … أضحى بشارب مرقد ما غمضا\nلا تطلبن الرزق بعد شماسه … فتروضه سبعا إذا ما غيضا\nما عوض الصبر امرؤ إلا رأى … ما فاته دون الذي قد عوضا\nيا أحمد ابن أبي داود دعوة … ذلت بشكرك لي وكانت ريضا\nلما انتضيتك للخطوب كفيتها … والسيف لا يكفيك حتى ينتضى\nما زلت أرقب تحت أفياء المنى … يوما بوجه مثل وجهك أبيضا\nكم محضر لم مرتضى لم تدخر … محموده عند الإمام المرتضى\nلولاك عز لقاؤه فيما بقي … أضعاف ما قد عزني فيما مضى\nقد كان صوح نبت كل قرارة … حتى تروح في نداك فروضا\nأوردتني العد الخسيف وقد أرى … أتبرض الثمد البكي تبرضا\nأما القريض فقد جذبت بضبعه … جذب الرشاء مصرحا ومعرضا\nأحببته إذ كان فيك محببا … وازددت حبا حين صار مبغضا\nأحييته وظننت أني لاأرى … شيئا يعود إلى الحياة وقد قضى\nوحملت عبء المجد معتمدا على … قدم وقاك أمينها أن تدحضا\nثقلا لو أن متالعا حمل اسمه … لا جسمه لم يستطع أن ينهضا\nقد كانت الحال اشتكت فأسوتها … أسوا أبى إمراره أن ينقضا\nما عذرها ألا تفيق ولم تزل … لمريضها بالمكرمات ممرضا\nكن كيف شئت فإن فيك خلائفا … أمسى إليهن الرجاء مفوضا\nفالمجد لا يرضى بأن ترضى بأن … يرضى امرؤ يرجوك إلا بالرضا"},{"id":"diwan-abutammam:232","bookId":"diwan-abutammam","type":"poem","seq":232,"chapter":"البحر: طويل","title":"ألم ترني خليت نفسي وشانها","page":"","text":"ألم ترني خليت نفسي وشانها … ولم أحفل الدنيا ولا حدثانها ؟\nلقد خوفتني النائبات صروفها … ولو أمنتني ما قبلت أمانها\nوكيف على نار الليالي معرسي … إذا كان شيب العارضين دخانها !\nأصبت بخود سوف أغبر بعدها … حليف أسى أبكى زمانا زمانها\nعنان من اللذات قد كان في يدي … فلما مضى الإلف استردت عنانها\nمنحت الدمى هجري فلا محسناتها … أود ولا يهوى فؤادي حسانها\nيقولون هل يبكي الفتى لخريدة … متى ما أراد اعتاض عشرا مكانها\nوهل يستعيض المرء من خمس كفه … ولو صاغ من حر اللجين بنانها"},{"id":"diwan-abutammam:233","bookId":"diwan-abutammam","type":"poem","seq":233,"chapter":"البحر: بسيط تام","title":"دعني وشرب الهوى ياشارب الكاس","page":"","text":"دعني وشرب الهوى ياشارب الكاس … فإنني للذي حسيته حاسي\nلا يوحشنك ما استعجبت من سقمي … فان منزله في أحسن الناس\nمن خلوتي فيه مبدا كل جائحة … وفكرتي منه مبدا كل وسواس\nمن قطع ألفاظه توصيل مهلكتي … ووصل ألفاظهش تقطيع أنفاسي\nرزقت رقة قلب منه نغصها … منغص من رقيب قلبه قاسي\nمتى أعيش بتأميل الرجاء اذا … م كان قطع رجائي من يدي ياسي"},{"id":"diwan-abutammam:234","bookId":"diwan-abutammam","type":"poem","seq":234,"chapter":"البحر: خفيف تام","title":"بدلت عبرة من الإيماض","page":"","text":"بدلت عبرة من الإيماض … يوم شدوا الرحال بالإغراض\nأعرضت برهة فلما أحست … بالنوى أعرضت عن الإعراض\nغصبتها نحيبها عزمات … غصبتني تصبري واغتماضي\nنظرت فالتفت منها إلى أح … لى سواد رأيته في بياض\nيوم ولت مريضة اللحظ والجف … ن وليست دموعها بمراض\nإن خيرا مما رأيت من الصف … ح عن النائبات والإغماض\nغربة تقتدي بغربة قيس ب … ن زهير والحارث بن مضاض\nغرضا نكبتين مافتلا رأ … يا فخافا عليه نكث انتقاض\nمن أبن البيوت أصبح في ثو … ب من العيش ليس بالفضفاض\nوالفتى من تعرقته الليالي … والفيافي كالحية النضناض\nصلتان أعداؤه حيث حلوا … في حديث من عزمه مستفاض\nكل يوم له بصرف الليالي … فتكة مثل فتكة البراض\nوإلى أحمد نقضت عرا العج … ز بوخذ السواهم الأنقاض\nفكأني لما حططت إليه الر … حل أطلقت حاجتي من إباض\nحل في البيت من إياد إذا عد … ت وفي المنصب الطوال الععراض\nمعشر أصبحوا حصون المعالي … ودروع الأحساب والأعراض\nبك عاد النضال دون المساعي … واهتدين النبال للأغراض\nوغدت أسهم القبائل أيقا … ظا وكانت قد نومت في الوفاض\nعادت المكرمات بزلا وكانت … أدخلت بينها بنات مخاض\nكم ظلام عن العلى قد تجلى … بك والمكرمات عنك رواض\nأي ذي سودد يناويك فيه … ظالما والندى بذلك قاض\nكم معان وشيتها فيك قد أم … ست وأصبحت ضرائرا للرياض\nبقواف هي البواقي على الده … ر ولكن أثمانهن مواض\nما أبالي بعد انبساطك بالمع … روف من كان منهم ذا انقباض\nأنت لي معقل من الدهر إن را … ب بريب أو حادث مضاض\nماشددت الأوذام في عقد الأك … راب حتى وردت ملء الحياض\nأنت أمضى من أن تصد عن الرم … ي إذا ما جددت في الإنباض\nوإذا المجد كان عوني على المر … ء تقاضيته بترك التقاضي"},{"id":"diwan-abutammam:235","bookId":"diwan-abutammam","type":"poem","seq":235,"chapter":"البحر: كامل تام","title":"كف الندى أضحت بغير بنانكف الندى أضحت بغير بنان","page":"","text":"كف الندى أضحت بغير بنانكف الندى أضحت بغير بنان … وقناته أمست بغير سنان\nجبل الجبال غدت عليه ملمة … تركته وهو مهدم الأركان\nأنعى عمير بن الوليد لغارة … بكر من الغارات أو لعوان\n … قولي وأنعى فارس الفرسان\nعثر الزمان ونائبات صروفه … بمقيلنا عثرات كل زمان\nلم يترك الحدثان يوم سطا به … أحدا نصول به على الحدثان\nقد كنت حشو الدرع ثم أراك قد … أصبحت حشو اللحد والأكفان\nشغلت قلوب الناس ثم عيونهم … مذ مت بالخفقان والهملان\nواستعذبوا الأحزان حتى إنهم … يتحاسدون مضاضة الأحزان\nمايرعوي أحد إلى أحد ولا … يشتاق إنسان إلى إنسان\nأأصاب منك الموت فرصة ساعة … فعدا عليك وأنتما أخوان ؟\nفمن الذي أبقى ليوم تكرم … ومن الذي أبقى ليوم طعان ؟\nمن يدفع الكرب العظام إذا التفت … في مأزق حلقات كل بطان ؟\nحمال مالو حل أصغره على … ثهلان لانهدت ذرى ثهلان"},{"id":"diwan-abutammam:236","bookId":"diwan-abutammam","type":"poem","seq":236,"chapter":"البحر: سريع","title":"ياشدنا صيغ من الشمس","page":"","text":"ياشدنا صيغ من الشمس … ته بالملاحات على الإنس\nفي كل يوم انت في صورة … غير التي كنت بها أمس\nتزداد طيبا كل يوم كما … يزداد غصن البان في الغرس\nوالله لولا الله لا غيره … وخوفي النار على نفسي\nصليت خمسا لك من هيبة … وازددت ثنتين على الخمس !"},{"id":"diwan-abutammam:237","bookId":"diwan-abutammam","type":"poem","seq":237,"chapter":"البحر: منسرح","title":"أقلق جفن العينين عن غمضه","page":"","text":"أقلق جفن العينين عن غمضه … وشد هذا الحشا على مضضه\nشجا بما عن للأمير أبي العبا … س أمسى نصبا لمعترضه\nلباسط الباع رحبه واجب الحق … م على العالمين مفترضه\nمن الألى نستجير من شرق الده … ر بهم إن ألم أو جرضه\nصاغهم ذو الجلال من جوهر المج … د وصاغ الأنام من عرضه\nإذا رموا عروة إليك فقد … أتيت حوض الأنام من فرضه\nسهم من الملك لا يضيعه … باديه حتى يهتز في غرضه\nصحته صحة الرجاء لنا … في حين ملتاثه ومنتقضه\nوإن يجد علة نعم بها … حتى ترانا نعاد من مرضه"},{"id":"diwan-abutammam:238","bookId":"diwan-abutammam","type":"poem","seq":238,"chapter":"البحر: بسيط تام","title":"إني أظن البلى لو كان يفهمه","page":"","text":"إني أظن البلى لو كان يفهمه … صد البلى عن بقايا وجهه الحسن\nيا مؤتة لم تدع ظرفا ولا أدبا … إلا حكمت به للحد والكفن\nلله ألحافظه والموت يكسرها … كأن أجفانه سكرى من الوسن\nيرد أنفاسه كرها وتعطفها … يد المنية عطف الريح للغصن\nيا هول ما أبصرت عيني وما سمعت … أذني فلا بقيت عيني ولا أذني\nلم يبق من بدني جزء علمت به … إلا وقد حله جزء من الحزن\nكان اللحاق به أولى وأحسن بي … من أن أعيش سقيم الروح والبدن"},{"id":"diwan-abutammam:239","bookId":"diwan-abutammam","type":"poem","seq":239,"chapter":"البحر: منسرح","title":"يامن تردى بحلة الشمس","page":"","text":"يامن تردى بحلة الشمس … ومن رماني بأسهم خمس\nبالطرف والثغر والسوالف والن … حر وشيئ يطيبث في اللمس\nهاأناذابالذنوب معترف … فهب لذلي جنايتي أمس\nوجد لمستمطر الجفون دما … شغلته عن صلاته الخمس\nسألتث عن وصفيك الصفات فما … نطقن إلا بألسن خرس"},{"id":"diwan-abutammam:240","bookId":"diwan-abutammam","type":"poem","seq":240,"chapter":"البحر: طويل","title":"أما إنه لولا الخليط المودع","page":"","text":"أما إنه لولا الخليط المودع … وربع عفا منه مصيف ومربع\nلردت على أعقابها أريحية … من الشوق واديها من الهم مترع\nلحقنا بأخراهم وقد حوم الهوى … قلوبا عهدنا طيرها وهي وقع\nفردت علينا الشمس والليل راغم … بشمس لهم من جانب الخدر تطلع\nنضا ضوء ها صبغ الدجنة فانطوى … لبهجتها ثوب السماء المجزع\nفوالله ما أدري أأحلام نائم … ألمت بنا أم كان في الركب يوشع\nوعهدي بها تحيي الهوى وتميته … وتشعب أعشار الفؤاد وتصدع\nوأقرع بالعتبى حميا عتابها … وقد تستقيد الراح حين تشعشع\nوتقفو إلى الجدوى بجدوى وإنما … يروقك بيت الشعر حين يصرع\nألم تر آرام الظباء كأنما … رأت بي سيد الرمل والصبح أدرع\nلئن جزع الوحشي منها لرؤيتي … لإنسيها من شيب رأسي أجزع\nغذا الهم مختطا بفودي خطة … طريق الردى منها إلى النفس مهيع\nهو الزور يجفى ، والمعاشر يجتوى … وذو الإلف يقلى ، والجديد يرقع\nله منظر في العين أبيض ناصع … ولكنه في القلب أسود أسفع\nونحن نزجيه على الكره والرضا … وأنف الفتى من وجهه وهو أجدع\nلقد ساسنا هذا الزمان سياسة … سدى لم يسسها قط عبد مجدع\nتروح علينا كل يوم وتغتدي … خطوب كأن الدهر منهن يصرع\nحلت نظف منها لنكس وذو النهى … يداف له سم من العيش منقعث\nفإن نك أهملنا فأضعف بسعينا … وإن نك أجبرنا ففيم نتعتع\nلقد آسف الأعداء مجد ابن يوسف … وذو النقص في الدنيا بذي الفضل مولع\nأخذت بحبل منه لما لويته … عل مرر الأيام ظلت تقطع\nهو السيل إن واجهته انقدت طوعه … وتقتاده من جانبيه فيتبع\nولم أر نفعا عند من ليس ضائرا … ولم أر ضرا عند من ليس ينفع\nيقول فيسمع ويمشي فيسرع … ويضرب في ذات الإله فيوجع\nممر له من نفسه بعض نفسه … وسائرها للحمد والأجر أجمع\nرأى البخل من كل فظيعا فعافه … على أنه منه أمر وأفظع\nوكل كسوف في الداراري شنعة … ولكنه في الشمس والبدر أشنع\nمعاد الورى بعد الممات وسيبه … معاد لنا قبل الممات ومرجع\nله تالد قد وقؤ الجود هامه … فقرت وكانت لاتزال تفزع\nإذا كانت النعمى سلوبا من امرئ … غدت من خليجي كفه ، وهي متبع\nوإن عثرت سود الليالي وبيضها … بوحدته ألفيتها وهي مجمع\nوإن خفرت أموال قوم أكفهم … من النيل والجدوى فكفاه مقطع\nويوم يظل العز يحفظ وسطه … بسمر العوالي والنفوس تضيع\nمصيف من الهيجا ومن حاجم الوغى … ولكنه من وابل الدم مربع\nعبوس كسا أبطاله كل قونس … يرى المرء منه وهو أفرع أنزع\nوأسمر محمر العوالي يومه … سنان بحبات القلوب ممتع\nمن اللاء يشربن النجيع من الكلى … غريضا ، ويروى غيرهن فينقع\nشققت إلى جباره حومة الوغى … وقنعته بالسيف وهو مقنع\nلدى سندبايا والهضاب وأرشق … وموقان والسمر اللذان تزعزع\nوأبرشتويم والكذاج وملتقى … سنابكها والخيل تردي وتمزع\nغدت ظلعا حسرى وغادر جدها … جدود أناس وهي حسرى وظلع\nهو الصنع إن يعجل فنفع وإن يرث … فللريث في بعض المواطن أسرع\nأظلتك آمالي وفي البطش قوم … وفي السهم تسديد وفي القوس منزع\nوإن الغنى لي إن لحظت مطالبي … من الشعر ، إلا في مديحك ، أطوع\nوإنك إن أهزلت في المحل لم تضع … ولم ترع إن أهزلت والروض ممرع\nرأيت رجائي فيك وحدك همة … ولكنه في سائر الناس مطمع\nوكم عاثر منا أخذت بضبعه … فأضحى له في قلة المجد مطلع\nفصار اسمه في النائبات مدافعا … وكان اسمه من قبل وهو مدفع\nوما السيف إلا زبرة لو تركته … على الخلقة الأولى لما كان يقطع\nفدونكها لولا ليان نسيبها … لظلت صلاب الصخر منها تصدع\nلها أخوات قبلها قد سمعتها … وإن لم تزع بي مدة فستسمع"},{"id":"diwan-abutammam:241","bookId":"diwan-abutammam","type":"poem","seq":241,"chapter":"البحر: كامل تام","title":"نفسي فداء محمد ووقاؤه","page":"","text":"نفسي فداء محمد ووقاؤه … وكذبت ما في العالمين فداؤه\nأزعمت أن يحكي طرفه … والقد غصن جال فيه ماؤه ؟\nأسكت فأين ضياؤه وبهاؤه … وكماله وذكاؤه وحياؤه\nلاتغن أسماء الملاحة والحجى … فيمن سواه فإنها أسماؤه\nعري المحب من الضنا فقميصه … طول التأوه والسقام رداؤه\nلو قيل سل تعط المنى كان المنى … أن لو رأى مولاه كيف بكاؤه\nأحبابه لم تفعلون بقلبه … ماليس يفعله به أعداؤه\nمطر من العبرات خدي أرضه … حتى الصباح ومقلتاي سماؤه"},{"id":"diwan-abutammam:242","bookId":"diwan-abutammam","type":"poem","seq":242,"chapter":"البحر: كامل تام","title":"يالابسا ثوب الملاحة أبله","page":"","text":"يالابسا ثوب الملاحة أبله … فلأنت أولى لابسيه بلبسه\nلم يعطك الله الذي أعطاكه … حتى استخف ببدره وبشمسه\nرشأ إذا ماكاد يطلق نفسه … في فتكه أمر الحياء بحبسه\nوأنا الذي اعطيته محض الهوى … وصميمه وأخذت عذرة أنسه\nفلئن جنيت ثماره وغرسته … ما كنت أول من جنى من غرسه\nمولاك يا مولاي صاحبث لوعة … في يومه وصبابة في أمسه\nدنف يجود بنفسه حتى لقد … أمسى ضعيفا أن يجود بنفسه !"},{"id":"diwan-abutammam:243","bookId":"diwan-abutammam","type":"poem","seq":243,"chapter":"البحر: وافر تام","title":"خذي عبرات عينك عن زماعي","page":"","text":"خذي عبرات عينك عن زماعي … وصوني ما أزلت من القناع\nأقلي قد أضاق بكاك ذرعي … وما ضاقت بنازلة ذراعي\nأآلفة النحيب كم افتراق … أظل فكان داعية اجتماع !\nوليست فرحة الأوبات إلا … لموقوف على ترح الوداع\nتوجع أن رأت جسمي نحيفا … كأن المجد يدرك بالصراع\nفتى النكبات من يأوي إذا ما … قطفن به إلى خلق وساع\nيثير عجاجة في كل ثغر … يهيم به عدي بن الرقاع\nأبن مع السباع القفر حتى … لخالته السباع من السباع\nفلب الحزم إن حاولت يوما … بأن تسطيع غير المستطاع\nفلم ترحل كناجية المهاري … ولم تركب همومك كالزماع\nبمهدي بن أصرم عاد عودي … إلى إيراقه وامتد باعي\nأطال يدي على الأيام حتى … جزيت صروفها صاعا بصاع\nإذا أكدت سوام الشعر أضحت … عطاياه وهن لها مراعي\nرياض لا يشذ العرف عنها … ولا تخلو من الهمم الرتاع\nسعى فاستنزل الشرف اقتدارا … ولولا السعي لم تكن المساعي\nأمهديا لحييت على نوال … لقد حكت الملام لغير واع\nأردت بحيث لاتعصى المعالي … بأن يعصى الندى وبأن تطاعي\nعميد الغوث إن نوب الليالي … سطت وقريعها عند القراع\nكثيرا ما تشوقه العوالي … وهمته إلى العلق المتاع\nكأن به غداة الروع وردا … وقد وصفت له نفس الشجاع\nلحسن الموت في كرم وتقوى … أحب إليه من حسن الدفاع\nونغمة معتف يرجوه أحلى … على أذنيه من نغم السماع\nجعلت الجود لألاء المساعي … وهل شمس تكون بلا شعاع\nوما في الأرض أعصى لامتناع … يسوق الذم من جود مطاع\nولم يحفظ مضاع المجد شيء … من الأشياء كالمال المضاع\nرعاك الله للمعروف إني … أراك لسرح مالك غير راعي\nفما في الأرض من شرف يفاع … سبقت به ولا خلق يفاع\nلعزمك مثل عزم السيل شدت … قواه بالمذانب والتلاع\nورأيك مثل رأي السيف صحت … مشورة حده عند المصاع\nفلو صورت نفسك لم تزدها … على ما فيك من كرم الطباع"},{"id":"diwan-abutammam:244","bookId":"diwan-abutammam","type":"poem","seq":244,"chapter":"البحر: كامل تام","title":"بيت قلبي من هواك على الطوى","page":"","text":"بيت قلبي من هواك على الطوى … ورحلت من بلد الصبابة والجوى\nلو لم يجرني الهجر منك بلطفه … والله لاستأمنت فيك إلى النوى\nلم ترع لي حرقا بقلبي قد مضت … لو لم يذدها الدمع عنه لاشتوى\nهيهات كنت من الحداثة والصبا … في غفلة إن الهوى ينسي الهوى"},{"id":"diwan-abutammam:245","bookId":"diwan-abutammam","type":"poem","seq":245,"chapter":"البحر: طويل","title":"بنفسي حبيب سوف يثكلني نفسي","page":"","text":"بنفسي حبيب سوف يثكلني نفسي … ويجعل جسمي تحفة اللحد والرمس\nجحدت الهوى ان كنت مذ جعل الهوى … محاسنه شمسي نظرت الى الشمس\nلقد ضاقت الدنيا علي بأسرها … بهجرانه حتى كأني في حبس\nأسكن قلبا هائما فيه مأتم … من الشوق إلا أن عيني في عرس"},{"id":"diwan-abutammam:246","bookId":"diwan-abutammam","type":"poem","seq":246,"chapter":"البحر: خفيف تام","title":"قد كسانا من كسوة الصيف خرق","page":"","text":"قد كسانا من كسوة الصيف خرق … مكتس من مكارم ومساع\nحلة سابرية ورداء … كسحا القيض أو رداء الشجاع\nكالسراب الرقراق في النعت إلا … أنه ليس مثله في الخداع\nقصبيا تسترجف الريح متنيه … ه بأمر من الهبوب مطاع\nرجفانا كأنه الدهر منه … كبد الصب أو حشا المرتاع\nلازما ما يليه تحسبه جز … ءا من المتنتين والأضلاع\nيطرد اليوم ذا الهجير ولو شب … به في حره بيوم الوداع\nخلعة من أغر أروع رحب الص … صدر رحب الفؤاد رحب الذراع\nسوف أكسوك ما يعفي عليها … من ثناء كالبرد برد الصناع\nحسن هاتيك في العيون وهذا … حسنه في القلوب والأسماع"},{"id":"diwan-abutammam:247","bookId":"diwan-abutammam","type":"poem","seq":247,"chapter":"البحر: خفيف تام","title":"بت سلم الجوى وحرب النعاس","page":"","text":"بت سلم الجوى وحرب النعاس … عرضة للزفير والأنفاس\nدائبا ليلتي أكف بكفي … كبدا حزها كحز المواسي\nفإذا حلت الهموم تأوهت … وناديت يا أبا العباس\nحزني منك لا أصابك معشار … الذي من هواك مر برأسي"},{"id":"diwan-abutammam:248","bookId":"diwan-abutammam","type":"poem","seq":248,"chapter":"البحر: منسرح","title":"أبو علي وسمي منتجعه","page":"","text":"أبو علي وسمي منتجعه … فاحلل بأعلى واديه أو جرعه\nواغد قريب الخيال والحس من … منظره تارة ومستمعه\nوحاسد لا يفيق قلت له … من صاب قول يدمي ومن سلعه\nلا تجزرن عرضك الأساود واس … تخف بأنف باد ، لمجتدعه\nلا يأمنن أخدعاك بادرة … من قدعه إن أمنت من قدعه\nإياك والغيل أن تطيف به … إني أخشى عليك من سبعه\nترى الهمام المحجوب حاشية … له وتلقى المتبوع من تبعه\nينزل في الكاهل المنيف من الأم … ر وهم تحت ذاك من زمعه\nيا رب يوم تلوح غرته … ساطع صبح المعروف منصدعه\nقد ذاب لي في يديك ذوب السنا … م الجعد حكمت الرضف في قمعه\nولم تغير وجهي عن الصبغة ال … أولى بمسفوع اللون ملتمعه\nلا بل هنيء الندى هنيء السدى … لم يتلوث راجيك في طمعه\nوقد أتاني الرسول بالملبس الفخ … م لصيف امرىء ومرتبعه\nمن شنع الخلعة الغريبة إن … م المجد مجد الرياش في شنعه\nلو أنها جللت أويسا لقد … أسرعت الكبرياء في ورعه\nرائق خز يلتذ ملمسه … سكب يدين الصبا لمدرعه\nوسر وشي كأن شعري أح … يانا نسيب العيون من بدعه\nكأن غض الحوذان والدم من … صائكه جاسدا ومن دفعه\nوالنور نور العرار أجري في … تسهيمه المجتلى على ينعه\nلا في ريام ولا قراه ولا … زبيده مثله ولا رمعه\nلايتخطاه الطرف من أحد … ينصف إلا صلى على صنعه\nتركتني سامي الجفون على … أزلم دهر بحسنها جذعه\nمعاود الكبر والسمو على … أعياده باذخا على جمعه\nوغابط في نداك قلت له … ورب قول قومت من ضلعه :\nنعت سيفا أغفلت قائمه … وظبي قف سهوت عن تلعه\nأنت أخونا وسيد ملك … نخلع ما نستزيد من خلعه\nفالبس به مثلها لمثلك من … فضفاض ثوب القريض متسعه\nصعب القوافي إلا لفارسه … أبي نسج العروض ممتنعه\nساحر نظم سحر البياض من ال … ألوان سائبه خبه خدعه\nكسوة ود أصبحت دون الورى … نجعته لا نقول من نجعه\nسبقت حتى اقتطعت قبلهم … ما شئت من تمه ومن قطعه\nوالشعر فرج ليست خصيصته … طول الليالي إلا لمفترعه"},{"id":"diwan-abutammam:249","bookId":"diwan-abutammam","type":"poem","seq":249,"chapter":"البحر: منسرح","title":"نأت به الدارعن أقاربه","page":"","text":"نأت به الدارعن أقاربه … فألقي الحبل فوق غاربه\nعاشت لمحبوبه ممانعة … مات عليها رجاء طالبه\nاتفق الحسن فيه واختلفت … مذاهب العقل في مذاهبه\nلم أر بدرا سواك معتدلا … به افتقار إلى كواكبه\nويلم صب رمى صعوبتكم … الأولى فلانت بلين جانبه\nألقاك في معجب أوائله … فما تفكرت في عواقبه\nومن يكن طيبا فلا عجب … أن يأكل الناس من أطايبه !"},{"id":"diwan-abutammam:250","bookId":"diwan-abutammam","type":"poem","seq":250,"chapter":"البحر: طويل","title":"غدا يتناءى صاحب كان لي انسا","page":"","text":"غدا يتناءى صاحب كان لي انسا … فلا مصبح لي في السرور ولا ممسا\nوتصبح أحزاني عليه كثيرة … ويصبح سعدي من مودته نحسا\nأخ لي لو أعطى المنى باسم فقده … بلا فقده كانت به ثمنا بخسا\nفلو أن نفسي الف نفس لما انثنت … يد البين أو تودي بآخرها نفسا"},{"id":"diwan-abutammam:251","bookId":"diwan-abutammam","type":"poem","seq":251,"chapter":"البحر: سريع","title":"ها إن هذا موقف الجازع","page":"","text":"ها إن هذا موقف الجازع … أقوى وسؤر الزمن الفاجع\nدار سقاها بعد سكانها … صرف النوى من سمه الناقع\nولا تلوما ذا الهوى إنها … ليست ببدع حنة النازع\nلو قيل ما كان مزورا بها … إذا لسر الربع بالرابع\nفاعتبرا واستعبرا ساعة … فالدمع قرن للجوى الرادع\nأخلت رباها كل سيفانة … تخلع قلب الملك الخالع\nيصبح في الحب لها ضارعا … من ليس عند السيف بالضارع\nرود إذا جردت في حسنها … فكرك دلتك على الصانع\nنوح صفا مذ عهد نوح له … شرب العلى في الحسب الفارع\nمطرد الآباء في نسبة … كالصبح في إشراقه الساطع\nمناسب تحسب من ضوئها … منازلا للقمر الطالع\nكالدلو والحوت وأشراطه … والبطن والنجم إلى البالع\nنوح بن عمرو بن حوي بن عم … رو بن حوي بن الفتى ماتع\nالسكسكي المجد كنديه … وأددي السؤدد الناصع\nللجدب في امواله مرتع … ومقنع في الخصب للقانع\nقد أشرقت في قومه منهم … ناصية تنأى عن السافع\nكم فارس فيهم إذا استصرخوا … مثل سنان الصعدة اللامع\nيكره صدر الرمح أو ينثني … وقد تروى من دم مائع\nبطعنة خرقاء تأتي على … حزامة المستلئم الدارع\nينفذ في الآجال أحكامه … أمر مطاع الأمر في طائع\nيخلى لها المأزق يوم الوغى … عن فرجة في الصف كالشارع\nإن حويا حاجتي فاقضها … ورد جأش المشفق الجازع\nفتى يمان كاليماني الذي … يعرم حراه على الوازع\nفي حليه النابي وفي جفنه … وفي مضاء الصارم القاطع\nيجاوز الخفض وأفياءه … إلى السرى والسفر الشاسع\nأدل بالقفر وأهدى له … من الدعيميص ومن رافع\nيعلم أن الداء مستحلس … تحت جمام الفرس الرائع\nوالطائر الطائر في شانه … يلوي بخط الطائر الواقع\nأخفق فاستقدم في همة … وغادر الرتعة للراتع\nترمي العلى منه بمستيقظ … لا فاتر الطرف ولا خاشع\nوإنما الفتك لذي لأمة … شبعان أو ذي كرم جائع\nأنشر له أحدوثة غضة … تصغي إليها أذن السامع\nإن يرفع السجف له اليوم ير … فعه غدا في المشهد البارع\nفرب مشفوع له لم يرم … حتى غدا يشفع للشافع\nإن أنت لم تنهض به صاعدا … في مستراد الزاهر اليانع\nحتى يرى معتدلا ظنه … بعد التياث الأمل الظالع\nأكدى الذي يعتده عدة … وضاع من يرجوه للضائع"},{"id":"diwan-abutammam:252","bookId":"diwan-abutammam","type":"poem","seq":252,"chapter":"البحر: سريع","title":"عبدك يدعو باسطا خمسه","page":"","text":"عبدك يدعو باسطا خمسه … مبتهلا يدعو فلا تنسه\nإن أنت لم تبك له رحمة … فلا تلمه إن بكى نفسه\nكم حسرة لي في الفؤاد الذي … أطلت في سجن الهوى حبسه\nعبد اذا استوحشته لم تجد … في الناس لو حفوا به أنسه"},{"id":"diwan-abutammam:253","bookId":"diwan-abutammam","type":"poem","seq":253,"chapter":"البحر: بسيط تام","title":"أما الرسوم فقد أذكرن ما سلفا","page":"","text":"أما الرسوم فقد أذكرن ما سلفا … فلا تكفن عن شأنيك أو يكفا\nلا عذر للصب أن يقنى الحياء ولا … للدمع بعد مضي الحي أن يقفا\nحتى يظل بماء سافح ودم … في الربع يحسب من عينيه قد رعفا\nوفي الخدور مها لو أنها شعرت … إذا ظغت فرحا أو أبلست أسفا\nلآلىء كالنجوم الزهر قد لبست … أبشارها صدف الإحسان لا الصدفا\nمن كل خود دعاها البين فابتكرت … بكرا ولكن غدا هجرانها نصفا\nلا أظلم النأي قد كانت خلائقها … من ، قبل وشك النوى عندي نوى قذفا\nغيداء جاد ولي الحسن سنتها … فصاغها بيديه روضة أنفا\nمصقولة سترت عنا ترائبها … قلبا برئيا يناغي ناظرا نطفا\nيضحي العذول على تأنيبه كلفا … بعذر من كان مشغوفا بها كلفا\nودع فؤادك توديع الفراق فما … أراه من سفر التوديع منصرفا\nيجاهد الشوق طورا ثم يجذبه … جهاده للقوافي في أبي دلفا\nبجوده انصاتت الأيام لابسة … شرخ الشباب وكانت جلة شرفا\nحتى لو ان الليالي صورت لغدت … أفعاله الغر في آذانها شنفا\nإذا علا طود مجد ظل في نصب … أو يعتلي من سواه ذروة شعفا\nفلو تكلم خلق لا لسان له … لقد دعته المعالي ملة طرفا\nجم التواضع والدنيا بسؤدده … تكاد تهتز من أطرافها صلفا\nقصد الخلائق إلا في وغى وندى … كلاهما سبة ما لم يكن سرفا\nتدعى عطاياه وفرا وهي إن شهرت … كانت فخارا لمن يعفوه مؤتنفا\nما زلت منتظرا أعجوبة عننا … حتى رأيت شؤالا يجتنى شرفا\nيقول قول الذي ليس الوفاء له … عزما وينجز إنجاز الذي حلفا\nرأى الحمام شقيق الخلف فاتفقا … في ناظريه وإن كانا قد اختلفا\nكلاهما رائح غاد يذل على … معروفه وعلى حوبائه ائتلفا\nولو يقال اقر حد السيف شرهما … ما شام حديه حتى يقتل الخلفا\nإن الخليفة والأفشين قد علما … من اشتفى لهما من بابك وشفى\nفي يوم أرشق والهيجاء قد رشقت … من المنية رشقا وابلا قصفا\nفكان شخصك في أغفالها علما … وكان رأيك في ظلمائها سدفا\nنضوته دلفيا من كنانته … فأصبحت فوزة العقبى له هدفا\nبه بسطت الخطا فاسحنفرت رتكا … إلى الجلاد وكانت قبله قطفا\nخطوا ترى الصارم الهندي منتصرا … به من المارن الخطي منتصفا\nذمرت جمع الهدى فانقض منصلتا … وكان في حلقات الرعب قد رسفا\nومر بابك مر العيشش منجذما … محلوليا دمه المعسول لو رشفا\nحيران يحسب سجف النقع من دهش … طودا يحاذر أن ينقض أو جرفا\nظل القنا يستقي من صفه مهجا … إما ثمادا وإما ثرة خسفا\nمن مشرق دمه في وجهه ، بطل ، … وواهل دمه للرعب قد نزفا\nفذاك قد سقيت منه القنا جرعا … وذاك قد سقيت منه القنا نطفا\nمثقفات سلبن الروم زرقتها … والعرب سمرتها والعاشق القضفا\nما إن رأيت سواما قبلها هملا … يرعى فيهدي إليه رعيه عجفا !\nورب يوم كأيام تركت به … متن القناة ومتن القرن منقصفا\nأزرت آبرشتويما والقنا قصد … غيابة الموت والمقورة الشسفا\nلما رأوك وإياها ململمة … يظل منها جبين الدهر منكسفا\nولوا وأغشيتهم شما غطارفة … لغمرة الموت كشافين لا كشفا\nقد نبذوا الحجف المحبوك من زؤد … وصيروا هامهم بل صيرت حجفا\nأغشيت بارقة الأغماد أرؤسهم … ضربا طلخفا ينسي الجانف الجنفا\nبرق إذا برق غيث بات مختطفا … للطرف أصبح للأعناق مختطفا\nبالبيض قد أنفت إن الحسام إذا … هجيرة حرضته ساعة أنفا\nكتبت أوجههم مشقا ونمنمة … ضربا وطعنا يقات الهام والصلفا\nكتابة لا تني مقروءة أبدا … وما خططت بها لاما ولا ألفا\nفإن ألظوا بإنكار فقد تركت … وجوههم بالذي أوليتها صحفا\nوغيضة الموت أعني البذ قدت لها … عرمرما لحزون الأرض معتسفا\nكانت هي الوسط الممنوع فاستلبت … ما حولها الخيل حتى أصبحت طرفا\nوظل بالظفر الأفشين مرتديا … وبات بابكها بالذل ملتحفا\nأعطى بكلتا يديه حين قيل له … هذا أبو دلف العجلي قد دلفا\nتركت أجفانه مغضوضة أبدا … ذلا تمكن من عينيه ، لا وطفا\nيا رب مكرمة تجفى ، إذا نزلت … قد عرفت في ذراك البر واللطفا\nلو لم تفت مسن المجد مذ زمن … بالجود والبأس كان المجد قد خرفا\nنامت همومي عني حين قلت لها … حسبي أبو دلف ، حسبي به وكفى"},{"id":"diwan-abutammam:254","bookId":"diwan-abutammam","type":"poem","seq":254,"chapter":"البحر: مديد تام","title":"نفس يحتثه نفس","page":"","text":"نفس يحتثه نفس … ودموع ليس تحتبس\nومغان للكرى دثر … عطل من عهده درس\nشهرت ما كنت اكتمه … ناطقات بالهوى خرس"},{"id":"diwan-abutammam:255","bookId":"diwan-abutammam","type":"poem","seq":255,"chapter":"البحر: كامل تام","title":"أطلالهم سلبت دماها الهيفا","page":"","text":"أطلالهم سلبت دماها الهيفا … واستبدلت وحشا بهن عكوفا\nيا منزلا أعطى الحوادث حكمها … لا مطل في عدة ولا تسويفا\nأرسى بناديك الندى وتنفست … نفسا بعقوتك الرياح ضعيفا\nشعف الغمام بعرصتيك وربما … روت رباك الهائم المشعوفا\nولئن ثوى بك ملقيا أجرامه … ضيف الخطوب لقد أصاب مضيفا\nوهي الحوادث لم تزل نكباتها … يألفن ربع المنزل المألوفا\nخلفت بعقوتك السنون وطالما … كانت بنات الدهر عنك خلوفا\nأيام لا تسطو بأهلك نكبة … إلا تراجع صرفها مصروفا\nوإذا رمتك الحادثات بلحظة … ردت ظباؤك طرفها مطروفا\nمن كل مطعمة الهوى جعلت لها … منا مودات القلوب وقوفا\nورفيقة اللحظات يعقب رفقها … بطشا بمغتر القلوب عنيفا\nجزن الصفات روادفا وسوالفا … ومحاجرا ونواظرا وأنوفا\nكن البدور الطالعات فأوسعت … عنا أفولا للنوى وكسوفا\nآرام حي أنزفتهم نية … تركتك من خمر الفراق نزيفا\nكانوا برود زمانهم فتصدعوا … فكأنما لبس الزمان الصوفا\nخلق الزمان الفدم عاد ظريفا … كان الممنع أخدعا وصليفا\nعاقدت جود أبي سعيد إنه … بدن الرجاء به وكان نحيفا\nوعززت بالسبع الذي بزئيره … أمست وأصبحت الضغور غريفا\nقطب الخشونة والليان بنفسه … فغدا جليلا في القلوب لطيفا\nفإذا مشى يمشي الدفقى أو سرى … وصل السرى أو سار سار وجيفا\nهزته معضلة الأمور وهزها … وأخيف في ذات الإله وخيفا\nيقظان أحصدت التجارب حزمه … شزرا وثقف عزمه تثقيفا\nواستل من آرائه الشعل التي … لو أنهن طبعن كن سيوفا\nكهل الأناة فتى الشذاة إذا غدا … للحرب كان القشعم الغطريفا\nوأخو الفعال إذا الفتى كل الفتى … في الباس والمعروف كان خليفا\nكم من وساع الجود عندي في الندى … لما جرى وجريت كان قطوفا\nأحسنتما صفدي ، ولكن كنت لي … مثل الربيع حيا وكان خريفا\nوكلاكما اقتعدض العلى فركبتها … في الذروة العليا وجاء رديفا\nإن غاض ماء المزن فضت وإن قست … كبد الزمان علي كنت رؤوفا\nوإذا خلائقهم نبت أو أجدبت … أنشأت تمهد لي خلائق ريفا\nومواهبا مطلوبة ملحوقة … تذر الشريف بفضلها مشروفا\nتكفي بها نهل البلاء وعله … عند السؤال مصارعا وحتوفا\nاسمع ، أقامت في ديارك نعمة … خضراء ناضرة ترف رفيفا\nريا إذا النعم انتقلن تخيمت … وإذا نفرن غدت عليك ألوفا\nأنا ذو كساك محبة لا خلة … حبر القصائد فوفت تفويفا\nمتنخل حلاك نظم بدائع … صارت لآذان الملوك شنوفا\nواف إذا الإحسان قنع لم يزل … وجه الصنيعة عنده مكشوفا\nوإذا غدا المعروف مجهولا غدا … معروف كفك عندهث معروفا\nهذا إلى قدم الذمام بك الذي … لو أنه ولد لكان وصيفا\nوحشا تحرقه النصيحة والهوى … لو أنه وقت لكان مصيفا\nومقيل صدر فيك باق روعه … لو أنه ثغر لكان مخوفا\nولئن أطلت مدائحي لبنائل … لك ليس محدودا ولا موصوفا\nخفضت عني الدهر بعد ملمة … تركت لنابيه علي صريفا\nجدوى أصيل العلم أن سيمضه … \nعمري عظم الدين جهمي الندى … ينفي القوى ويثبت التكليفا\nسأقول قولة ناصح لك ينتحي … قلبا نقيا في رضاك نظيفا\nلك هضبة الحلم التي لو وازنت … أجأ إذا ثقلت وكان خفيفا\nوحلاوة الشيم التي لو مازجت … خلقض الزمان الفدم عاد ظريفا\nوأراك في أرض الأعادي غازيا … ما تستفيق يبوسة وجفوفا\nإن كان بالورع ابتنى القوم العلى … أو بالتقى صار الشريف شريفا\nفعلام قدم وهو زان عامر … وأميط علقمة وكان عفيفا ؟ !\nوبنى المكارم حاتم في شركه … وسواه يهدمها وكان حنيفا ؟ !"},{"id":"diwan-abutammam:256","bookId":"diwan-abutammam","type":"poem","seq":256,"chapter":"قصائد","title":"خالس طرفا عل دهش","page":"","text":"خالس طرفا عل دهش … ناظر من طرف منجمش\nقد رمى قلبي بلحظته … سهم عينيه فلم يطش\nنقشت كف الملاحة في … وجنتيه اظرف النقش\nعطشي يروى بقبلته … فمتى ريي من العطش ؟ !"},{"id":"diwan-abutammam:257","bookId":"diwan-abutammam","type":"poem","seq":257,"chapter":"البحر: كامل تام","title":"قولا لإبراهيم والفضل الذي","page":"","text":"قولا لإبراهيم والفضل الذي … سكنت مودته جنوب شغافي\nمنع الزيارة والوصال سحائب … شم الغوارب جأبة الأكتاف\nظلمت بني الحاج المهم وأنصفت … عرض البسيطة أيما إنصاف\nفأتت بمنفعة الرياض وضرها … أهل المنازل ألسن الوصاف\nوعلمت ما لقي المزور إذا همت … من ممطر ذفر وطين خفاف\nفجفوتكم وعلمت في أمثالها … أن الوصول هو القطوع الجافي\nلما استقلت ثرة أخلافها … ملمومة الأرجاء والأكناف\nشهدت لها الأثراء أجمع إنها … من مزنة لكريمة الأطراف\nما ينقضي منها النتاج ببلدة … حتى يسر له لقاح كشاف\nكم أهدت الخضراء في أحمالها … للأرض من تحف ومن ألطاف\nفكأنني بالروض قد أجلى لها … عن حلة من وشيه أفواف\nعن ثامر ضاف ونبت قرارة … واف ونور كالمراجل خاف\nوكأنني بالظاعنين وطية … تبكي لها الألاف للألاف\nوكأنني بالشدقمية وسطه … خضر اللهى والوظف والأخفاف\nإن الشتاء على جهامة وجهه … لهو المفيد طلاقة المصطاف\nوكأنما آثارها من مزنة … بالميث والوهدات والأخياف\nآثار أيدي آل مصعب التي … بسطت بلا من ولا إخلاف\nحتم عليك إذا حللت معانهم … إلا تراه عافيا من عاف\nوكأنهم في برهم وحفائهم … بالمجتدي الأضياف للأضياف"},{"id":"diwan-abutammam:258","bookId":"diwan-abutammam","type":"poem","seq":258,"chapter":"البحر: بسيط تام","title":"صبرت عنك بصبر غير مغلوب","page":"","text":"صبرت عنك بصبر غير مغلوب … ودمع عين على الخدين مسكوب\nصيرتني مستقرا للهوى وطنا … للحزن يا مستقر الحسن والطيب\nلئن جحدتك مالاقيت فيك فقد … صحت شهود تباريحي وتعذيبي"},{"id":"diwan-abutammam:259","bookId":"diwan-abutammam","type":"poem","seq":259,"chapter":"البحر: طويل","title":"أما والذي أعطاك بطشا وقوة","page":"","text":"أما والذي أعطاك بطشا وقوة … علي وأزرى بي وضعف من بطشي\nلقد خلق الله الهوى لك خالصا … ومكنه في الصدر مني بلا غش\nسل الليل عني هل أذوق رقاده … وهل لضلوعي مستقر على فرشي\nعناء بمن لو قال للشمس أاقبلي … للبته أو جاءت على رغمها تمشي\nقضيب من الريحان في غير لونه … وأم رشا في غير اكراعها الخمش"},{"id":"diwan-abutammam:260","bookId":"diwan-abutammam","type":"poem","seq":260,"chapter":"البحر: كامل تام","title":"دنف بكى آيات ربع مدنف","page":"","text":"دنف بكى آيات ربع مدنف … لولا نسيم ترابها لم يعرف\nطابت لأقدام وطئن ترابها … فنفحن نشر لطيمة مع قرقف\nأرج أقام من الأحبة في الثرى … وصرى أريقت بالدموع الذرف\nأخذ البلى آياتها فرمى بها … بيد البوارح في وجوه الصفصف\nوحدي وقفت ولم أقل من عبرة … وقفت حشاي بها لحادينا قف\nوحسدت ما غادرت فيها من بلى … وبلوتها بوميض طرف موسف\nوظللت ألحف في السؤال رسومها … والمنع من تحف السؤال الملحف\nفلنؤيها في القلب نوي شفه … وله بظاعنها وبالمتخلف\nوكأنما استسقى لهن محمد … فرسومهن من الحيا في زخرف\nسأل السماك فجادها بحيائه … منه بوبل ذي وميض أوطف\nمتعانق الحوذان تنشره الصبا … خضلا وتطويه كطي الرفرف\nوثوى الربيع بها فليس يقله … عنها نئيح سموم قيظ معصف\nحملت رجاي إليك بنت حديقة … غلباء لم تلقح لفحل مقرف\nنتجت وقد حوت الهنيدة وابتنت … في شطرها وتبوعت في النيف\nفأتت محلي وهي حمل بناتها … تسري بقائمتي خريق حرجف\nفاعتامها ذو خبرة بفحولها … ندس بجبلة خلقها متلطف\nحتى إذا تمت فلم يعجزه من … أشلائها مذخورة المتلهف\nصارت إلي بجؤجؤ ذي ميعة … قدم تدف به وعجز مصرف\nتنسل في لجج حكت أغمارها … فعل المحمد في الزمان المجحف\nثم اجتنت شلوي فصرت جنينها … متمكنا بقرار بطن مسدف\nفمتى تعثر بالرفاق ذكرته … فيمر تحتي قطع ليل أغضف\nفأجاءها بعد المخاض طلوقها … بمراهق السنين كهل أهيف\nعوجاء تستلب الزمام وتحتذي … عوجا يجدن لها استلاب النفنف\nأشرت بطى الشي في أثباجها … فهوت كثعبان الصفا المتخوف\nأمتك والشيطان يزهب ظلها … فأتتك وهي تفوق حلم الأحنف\nمن كان يقصد في نصيحته لها … فمحمد في النصح عين المسرف\nأوريت زندي رأفة وتألق … فتقصدا بالنازع المتعسف\nنال الردى وحوى الغنى بمحمد … عند الخليفة مذنبون ومعتف\nفي الله ينجز وعده ووعيده … للمعتفين وللعنود المترف\nسكنت أحشاء الرعية في حشا … قلب ذكي عن لسان مرهف\nلم يبلغ القلم الذي يجدي به … في الله ألفا مرهف ومثقف\nبأكف أبدال إذا أموا بها … ملمومة عملوا بما في المصحف\nتستل خائنة العيون بمقلة … تحوي ضمائرها ولما تطرف"},{"id":"diwan-abutammam:261","bookId":"diwan-abutammam","type":"poem","seq":261,"chapter":"البحر: مجزوء الكامل","title":"لباك عبدك مخلصا","page":"","text":"لباك عبدك مخلصا … وبكى دما عدد الحصى\nعبدا أطاعك قلبه … ليس المطيع كمن عصى\nأغرت محاسنك السقا … م به فعم وخصصا\nرام التخلص من هو … اك فما أطاق تخلصا"},{"id":"diwan-abutammam:262","bookId":"diwan-abutammam","type":"poem","seq":262,"chapter":"البحر: بسيط تام","title":"أغنيت عني غناء الماء في الشرق","page":"","text":"أغنيت عني غناء الماء في الشرق … وكنت منشيء وبل العارض الغدق\nجددت لي أملا كانت رواتعه … عواكفا قبلها في مطلب خلق\nلو كان خيم أبي يعقوب في حجر … صلد لفاض بماء منه منبعق\nما من جميل من الدنبا ولا حسن … إلا وأكثره في ذلك الخلق\nيا منة لك لولا ما أخففها … به من الشكر لم تحمل ولم تطق\nبالله أدفع عني حق فادحها … فإنني خائف منها على عنقي"},{"id":"diwan-abutammam:263","bookId":"diwan-abutammam","type":"poem","seq":263,"chapter":"البحر: خفيف تام","title":"لي لا كان من هواك خلاص","page":"","text":"لي لا كان من هواك خلاص … وبجسمي ولا بك الانتقاص\nدونك السوء بي وهذا فؤادي … فأذبه كما يذاب الرصاص\nلم أعرضت إذ تقنصت لحظا … منك سرا وأنت لي قناص !"},{"id":"diwan-abutammam:264","bookId":"diwan-abutammam","type":"poem","seq":264,"chapter":"البحر: بسيط تام","title":"قد شرد الصبح هذا الليل عن أفقه","page":"","text":"قد شرد الصبح هذا الليل عن أفقه … وسوغ الدهر ما قد كان من شرقه\nسيقت إلى الخلق في النيروز عافية … بها شفاهم جديد الدهر من خلقه\nيا رب مصطبح بالبث مغتبق … صحا ومشتجر ليلا ومرتفقه\nلما اكتسى القاسم البرد الأنيق غدا … إلى السرور فأعداه على حرقه\nالله عافاه من كرب ومن وصب … كاد السماح يذوق الموت من فرقه\nلم يبق ذو كرم إلا وجامعة … ثقيلة قد حناها الدهر في عنقه\nأجناك من ثمرات البر أينعها … رب كساك الأثيث النضر من ورقه\nحتى يقال لقد أضحى أبو دلف … وخلقه قد طغى حسنا على خلقه"},{"id":"diwan-abutammam:265","bookId":"diwan-abutammam","type":"poem","seq":265,"chapter":"البحر: سريع","title":"سالب عيني لذة الغمض","page":"","text":"سالب عيني لذة الغمض … ومبكيا بعضي على بعضي\nوقاتلي ظلما بإعراضه … ولحظه بالنظر المغضي\nإياك تستضعف ذا فاقة … جرت عليه بالذي تقضي\nمن يحسد الأرض لإشفاقه … موطئ نعليك من الأرض"},{"id":"diwan-abutammam:266","bookId":"diwan-abutammam","type":"poem","seq":266,"chapter":"البحر: منسرح","title":"كانت صروف الزمان من فرقك","page":"","text":"كانت صروف الزمان من فرقك … واكتن أهل الإعدام في ورقك\nما السبق إلا سبق يحاز على … جواد قوم لم يجر في طلقك\nيا دهر قوم أخدعيك فقد … أضججت هذا الأنام من خرقك\nسائل لياليك فهي عالمة … أي كريم أرسفن في حلقك\nاقبض يدا عن أبي الحسين تجد … جديده عائدا على خلقك\nكم لوعة للندى وكم قلق … للمجد والمكرمات في قلقك\nألبسك الله ثوب عافية … في نومك المعترى وفي أرقك\nيخرج من جسمك السقام كما … أخرج ذم الفعال من عنقك\nيسح سحا عليك حتى يرى … خلقك فيها أصح من خلقك"},{"id":"diwan-abutammam:267","bookId":"diwan-abutammam","type":"poem","seq":267,"chapter":"البحر: كامل تام","title":"ومضمخ بالمسك في وجناته","page":"","text":"ومضمخ بالمسك في وجناته … حسن الشمائل ساحر الألفاظ\nأبدا ترى الآثار في وجناته … مما يجريها من الألحاظ\nوتراه سائر دهره متبسما … فإذا رآني مر كالمغتاظ\nفي القلب مني والجوانح والحشا … من حبه حر كحر شواظ"},{"id":"diwan-abutammam:268","bookId":"diwan-abutammam","type":"poem","seq":268,"chapter":"البحر: كامل تام","title":"يا برق طالع منزلا بالأبرق","page":"","text":"يا برق طالع منزلا بالأبرق … واحد السحاب له حداء الأينق\nدمن لوت عزم الفؤاد ومزقت … فيها دموع العين كل ممزق\nلا شوق ما لم تصل وجدا بالتي … تأبى وصالك كالآباء المحرق\nيغلي إذا لم يضطرم ويرى إذا … لم يحتدم ، ويغص إن لم يشرق\nتأبى مع التصريد إلا نائلا … إلا يكن ماء قراحا يمذق\nنزرا كما استكرهت عائر نفحة … من فارة المسك التي لم تفتق\nما مقرب يختال في أشطانه … ملآن من صلف به وتلهوق\nبحوافر حفر وصلب صلب … وأشاعر شعر وخلق أخلق\nوبشعلة نبذ كأن قليلها … في صهوتيه بدء شيب المفرق\nذو أولق تحت العجاج وإنما … من صحة إفراط ذاك الأولق\nتغرى العيون به ويفلق شاعر … في نعته عفوا وليس بمفلق\nبمصعد من حسنه ومصوب … ومجمع في خلقه ومفرق\nصلتان يبسط إن ردى أو إن عدا … في الأرض باعا منه ليس بضيق\nوتطرق الغلواء منه إذا عدا … والكبرياء له بغير مطرق\nأهدى كناز جده فيما مضى … للمثل واستصفى أباه ليلبق\nمسود شطر مثل ما اسود الدجى … مبيض شطر كابيضاض المهرق\nقد سالت الأوضاح سيل قرارة … فيه فمفترق عليه وملتقي\nوكأن فارسه يصرف إذ بدا … في منته إبن الصباح الأبلق\nصافي الأديم كأنما ألبسته … من سندس بردا ومن إستبرق\nإمليسه إمليده لو علقت … في صهوتيه العين لم تتعل ق\nيرقى وما هو بالسليم ويغتدي … دون السلاح سلاح أروع مملق\nفي مطلب أو مهرب أو رغبة … أو رهبة أو موكب أو فيلق\nأمطاكه الحسن بن وهب إنه … داني ثرى اليد من رجاء المملق\nيحصى مع الأنواء فيض يمينه … ويعد من حسنات أهل المشرق\nيستنزل الأمل البعيد ببشره … بشر الخميلة بالربيع المغذق\nوكذا السحائب قلما تدعو إلى … معروفها الرواد إن لم تبرق\nمجلي قتام الوجه يذهل إن بدا … لك في الندي عن الشباب المونق\nلو كان سيفا ما استبت لنصله … متنا لفرط فرنده والرونق\nثبت البيان إذا تحير قائل … أضحى شكالا للسان المطلق\nلم يتبع شنع اللغات ولا مشى … رسف المقيد في حدود المنطق\nفي هذه قسم الكلام وهذه … كالسور مضروبا له والخندق\nيجني جناة النحل من أعلى الربا … زهرا ويشرع في الغدير المتأق\nأنف البلاغة لا كمن هو حائر … متلدد في الموتع المتعرق\nعير تفرق إن حداها غيره … ومتى يسقها وادعا تستوسق\nتنشق في ظلم المعاني إن دجت … منه تباشير الكلام المشرق\nألبس سليمان الغنى وافتح له … بابا إزاء الخفض ليس بمغلق\nواقرب إليه فإن أحرى المزن أن … يروي الثرى ما كان غير محلق\nعتقت وسيلته وأية قيمة … للتبعي العضب إن لم يعتق\nوتخط بزته فربت خلة … في درج ثوب اللابس المتنوق\nشنعاء بين المركب الهملاج قد … كمنت وبين الطيلسان المطبق"},{"id":"diwan-abutammam:269","bookId":"diwan-abutammam","type":"poem","seq":269,"chapter":"البحر: كامل تام","title":"بأبي وإن حسنت له بأبي","page":"","text":"بأبي وإن حسنت له بأبي … من ليس يعرف غير ما أربي\nقرطست عشرا في مودته … في مثلها من سرعة الطلب\nولقد أراني لو وقفت يدي … شهرين أرمي الأرض لم أصب"},{"id":"diwan-abutammam:270","bookId":"diwan-abutammam","type":"poem","seq":270,"chapter":"البحر: سريع","title":"إجعل لعيني في الكرى حظا","page":"","text":"إجعل لعيني في الكرى حظا … ولا تكن لي مالكا فظا\nأما لعيني بك من حرمة … إذ أعملت في حسنك اللحظا\nألزمتني ذنبا فعاقبتني … من قبل أن تسمع لي لفظا"},{"id":"diwan-abutammam:271","bookId":"diwan-abutammam","type":"poem","seq":271,"chapter":"البحر: وافر تام","title":"ذريني منك سافحة المآقي","page":"","text":"ذريني منك سافحة المآقي … ومن سرعان عبرتك المراق\nوتخويفي نوى عرضت وطالت … فبعد الغاي من حظ العتاق\nوقرب أنت تلك ، فإن هما … عراني باشتجار وارتفاق\nقلائص ما يقيها حد همي … ولا سيفي غداة الهم واق\nمتى ما تستمحها السير تترع … لنا سجل الذميل إلى العراقي\nتهون علي أوبتها عجافا … إذا انصرفت بآمال مناق\nسلام ترجف الأحشاء منه … على الحسن بن وهب والعراق\nعلى البلد الحبيب إلي غورا … ونجدا والفتى الحلو المذاق\nنميل إلى شمائل منه ميث … قليلات لأماعز والبراق\nوهل لملمة دهياء خرت … على تلك الخلائق من خلاق\nليالي نحن في وسنات عيش … كأن الدهر منها في وثاق\nوأياما لنا وله لدانا … عرينا من حواشيها الرقاق\nنصب على التقارب والتداني … ويسقينا بكاس الشوق ساق\nكأن العهد عن عفر لدينا … وإن كان التلاقي عن تلاق\nسأسقي الركب من ذكراه صرفا … وممزوجا من الكلم البواقي\nشرابا عظمه للشرب شرب … وسائره ارتفاق للرفاق\nوتبرد بيننا أبدا قواف … وشيك الفوت منها للحاق\nإذا ما قيدت رتكت وليست … إذا ما أطلقت ذات انطلاق\nعلى أقرابها وعلى ذراها … لطائم من مديح واشتياق\nمضاعفة الصبابة مستبين … على صفحاتها أثر الفراق"},{"id":"diwan-abutammam:272","bookId":"diwan-abutammam","type":"poem","seq":272,"chapter":"البحر: خفيف تام","title":"وبديع الجمال يضحك عن اضوا","page":"","text":"وبديع الجمال يضحك عن اضوا … ئه البدر عند بدء الطلوع\nما اجتلته عين التجمل إلا … رجعت منه عن جمال بديع\nكل ما منظر رأيت من الحس … ن ففيه منه جميع جميع\nغير أن العيون تجني بايدي … اللحظ من وجنتيه زهر الربيع"},{"id":"diwan-abutammam:273","bookId":"diwan-abutammam","type":"poem","seq":273,"chapter":"البحر: خفيف تام","title":"ما عهدنا كذا نحيب المشوق","page":"","text":"ما عهدنا كذا نحيب المشوق … كيف والدمع آية المعشوق\nفأقلا التعنيف إن غراما … أن يكون الرفيق غير رفيق\nواستمحيا الجفون درة دمع … في دموع الفراق غير لصيق\nإن من عق والديه لملعو … ن ومن عق منزلا بالعقيق\nفقفا العيس ملقيات المثاني … في محل الأنيق مغنى الأنيق\nإن يكن رث من أناس بهم كا … ن يداوى شوقي ويسلس ريقي\nهم أماتوا صبري وهم فرقوا نف … \nإن في خيمهم لمطعمة الحج … لين والمتن متن خوط وريق\nوهي لا عقد ودها ساعة البي … ن ولا عقد خصرها بوثيق\nوكأن الجريال يجري بماء الد … ر في خدها وماء العقيق\nوهي كالطبية النوار ولكن … ربما أمكنت جناة السحوق\nرميت من أبي سعيد صفاة ال … \nباالأسيل الغطريف والذهب الإب … ريز فينا والأروع الغرنيق\nفي كماة يكسون نسج السلوقي … وتغدو بهم كلاب سلوق\nيتساقون في الوغى كأس موت … وهي موصولة بكأس رحيق\nوطئت هامة الضواحي إلى أن … أخذت حقها من الفيدوق\nألهبتها السياط حتى إذا استن … ت بإطلاقها على الناطلوق\nسنها شزبا فلما استباحت … بالقبلات كل سهب ونيق\nسار مستقدما إلى البأس يزجي … رهجا باسقا إلى الإبسيق\nناصحا للمليك والملك القا … ئم والملك غير نصح مذيق\nوقديما ما استنبطت طاعة الخا … لق إلا من طاعة المخلوق\nثم ألقى على درولية البر … ك محلا باليمن والتوفيق\nفحوى سوقها وغادر فيها … سوق موت طمت على كل سوق\nفهم هاربون بين حريق الس … يف صلتا وبين نار احريق\nواجدا بالخليج ما لم يجد قط … بما شان لا ولا بالرزيق\nلم يعقه بعد المقادير عنه … غير ستر من البلاد رقيق\nولو أن الجياد لم تعصه كا … ن لديه غير البعيد السحيق\nوقعة زعزعت مدينة قسطن … طين حتى ارتجت بسور فروق\nووحق القنا عليه يمينا … هي أمضى من الحسام الفتيق\nأن لو أن الذراع شدت قواها … عضد أو أعين سهم بفوق\nما رأى قفلها كما زعموا قف … لا ولا\nغير ضنك الضلوع في ساعة الرو … ع ولا ضيق غداة المضيق\nذاهب الصوت ساعة الأمر والنه … ي إذا قل ثم هدر الفنيق\nكم أسير من سرهم وقتيل … رادع الثوب من دم كالخلوق\nيستغيث البطريق جهلا وهل تط … لب إلا مبطرق البطريق !\nوأخيذ رأى المنية حتى … قال بالصدق وهو غير صدوق\nقام بالحق يخطب الخلق والأش … قى لعمري بالحق غير حقيق\nناصح وهو غير جد نصيح … مشفق وهو غير جد شفيق\n … بر بالدين تحت ذاك العقوق\nفقدى نفسه بكل شوار … وصهيل في أرضه وتهيق\nمن متاع الملك الذي يمتع العي … ن به ثم من رقيق الرقيق\nلم تبعهم منهم كبارا ولا صد … عت حب القلوب بالتفريق\nثم ناهضت في الغلول رجالا … ورجالا بالضرب والتحريق\nفرق ما بينهم وبين ذوي الإش … راك كالفرق بين نوك وموق\nأي شيء إلا الأماني بين ال … كفر لو فكروا وبين الفسوق\nوبوادي عقرقس لم تعرد … عن رسيم إلى الوغى وعنيق\nجأر الدين واستغاث بك الإس … لام للنصر مستغاث الغريق\nيوم بكر بن وائل بقضات … دون يوم المحمر الزنديق\nيوم حلق اللمات ذاك وهذا ال … يوم في الروم يوم حلق الحلوق\nأطعم السيف نصفهم ورمى النص … ف برأي صافي النجار عريق\nوأصاخوا كأنما كان يرمي … هم بذاك التدبير من منجنيق\nفورب البيت العتيق لقد طح … طحت منهم ركن الضلال العتيق\nسرقوهم من السيوف ومن سم … ر العوالي ليالي الساروق\nكرمت غزوتاك بالأمس والخي … ل دقاق والخطب غير دقيق\nحين لا جلدة السماء بخضرا … ء ولا وجه شتوة بطليق\nأورثت صاغرى صغارا ورغما … وقضت أو قضى قبيل الشروق\nكم أفاءت من أرض قر من قر … ة عين وربرب مرموق\nثم أبت وأنت خوف الغمام ال … غط ذو فكرة وقلب خفوق\nلا تبالي بوارق البيض والسم … \nتشنأ الغيث وهو حق حبيب … رب حزم في بغضة الموموق\nلم تخوف ضر العدو ولا بغ … يا ولكن تخاف ضر الصديق\nإن أيامك الحسان من الرو … م لحمر الصبوح حمر الغبوق\nمعلمات كأنها بالدم المه … \nفإليكم بني الضغائن عن سا … كن بين السماك والعيوق\nالنقي الولادة الطيب التر … بة والمستنير مسرى العروق\nلا يجوز الأمور صفحا ولا ير … قل إلا على سواء الطريق\nفتناهوا إن الخليق من القو … م لذاك الفعال غير خليق\nملكت ماله المعالي فما تل … قاه إلا فريسة للحقوق\nيقظ وهو أكثر الناس إغضا … ء على نائل له مسروق\nأنا ولهان في ودادك ما عش … ت ونشوان فيك غير مفيق\nراحتي في الثناء ما بقيت لي … \nفاغن بالنعمة التي هي كالحو … راء لا فارك ولا بعلوق\nبعلها يأمن النشوز عليها … وهي في معقل من التطليق"},{"id":"diwan-abutammam:274","bookId":"diwan-abutammam","type":"poem","seq":274,"chapter":"البحر: مجزوء الخفيف","title":"حسرات عواطف","page":"","text":"حسرات عواطف … وسقام موالف\nوفؤاد معذب … ودموع ذوارف\nوقريب المزارلك … نه لا يساعف\nنصب عيني خيال وجه … هك بالشوق واقف\nأين ما كنت سيدي … طاف بي منك طائف"},{"id":"diwan-abutammam:275","bookId":"diwan-abutammam","type":"poem","seq":275,"chapter":"البحر: خفيف تام","title":"أيها البرق بت بأعلى البراق","page":"","text":"أيها البرق بت بأعلى البراق … واغد فيها بوابل غيداق\nوتعلم بأنه ما لأنوا … ئك إن لم تروها من خلاق\nدمن طالما التقت أدمع المز … نث عليها وأدمع العشاق\nشرقات الأطلال بالماء من تل … ك العزالي ملثة والمآقي\nحفظ الله حيث يمم إسما … عيل وليسقه من الغيث ساق\nقد سقتني الأيام من يدها سم … ما لفقدي له بكأس دهاق\nولعلي أدال منها بلا عه … د ولا ذمة ولا ميثاق\nفأجازي يوم الرحيل ولا تد … ركني رقة ليوم الفراق\nيا أبا القاسم المقسم ما بي … ن شغافي مثاله والصفاق\nلو تطلعت في ودادي إذا فا … جاك بين الحشا وبين التراقي\nوشجت بيننا الأخوة إن ال … ود عرق زاك من الأعراق\nذاك خل جهدت جهدي فلم أح … ص انتفاعي بفهمه وارتفاقي\nلو ترى ذبه هنالك دوني … لم تلمني في حب أهل العراق\nما تمليت مثل ذاك الحجا المع … رق في الحلم والسجايا العتاق\nمع ما قد طويت من سائر النا … س وما قد نشرت في الآفاق\nوعذاب لو أنها أطمعت زا … دت على الشهد بسطة في المذاق\nناعمات الأطراف لو أنها تل … بس أغنت عن الملاء الرقاق\nجدد كلما غدا يوم فخر … بعضهم في خلافة الأخلاق\nيهجر الهجر والمقابح علما … أن شتم الأعراض عار باق\nفإذا القوم ألجئوه إلى ذا … لك ألفوا لسانه في وثاق\nخالص الود والهوى في زمان … مدر الودث فيه غير النفاق\nووجدت الإخوان رزقا أغر الوج … ه من بين هذه الأرزاق\nقد دنت حلقتا خناقي فراخى … بأياديه عقد ذاك الخناق\nهم شليل ونثرة حين لفت … في غداة الهياج ساق بساق\nلو رأوا كوكب المنايا لظلوا … نحوها مهطعين بالأعناق\nوتلاد ولم أرثه وكنز … ليس من عسجد ولا أوراق"},{"id":"diwan-abutammam:276","bookId":"diwan-abutammam","type":"poem","seq":276,"chapter":"البحر: كامل تام","title":"قرب الحيا وانهل ذاك البارق","page":"","text":"قرب الحيا وانهل ذاك البارق … والحاجة العشراء بعدك فارق\nإيه أبا زيد فذرعك واسع … ونداك فياح ومجدك باسق\nقد لان أكثر ما تريد وبعضه … خشن وإني بالنجاح لواثق\nفي الروض قراص وفي سيل الربا … كدر وفي بعض الغيوث صواعق\nزوجت أمري بالسعود فأصبحت … منه النحوس النكد وهي طوالق\nومغارب الإخفاق أضحت بالذي … أولى من الإنجاح وهي مشارق\nفأتته مأربتي فأدرك شأوها … قرم بعائرة المكارم لاحق\nما أول السامين بالعالي ولا … كل الجياد دفعن قبل سوابق\nفأتت عوانا ثيبا ما سرني … بمكانها مني الكعاب العاتق\nومن الرزية أن شكري صامت … عما فعلت وأن برك ناطق\nوأخف ما جشم امرؤ وسعى له … يوما لذي النعمى الثناء الصادق\nأأرى الصنيعة منك ثم أسرها … إني إذا ليد الكرام لسارق"},{"id":"diwan-abutammam:277","bookId":"diwan-abutammam","type":"poem","seq":277,"chapter":"قصائد","title":"يا قضيبا لا يدانيه م","page":"","text":"يا قضيبا لا يدانيه م … من الإنس قضيب\nفوقه البان ومن تح … ت تثنيه كثيب\nوغزالا كلما مر … تمنته القلوب\nذهبي الخد يث … نيه من الريح الهبوب\nما لمسناه ولكن … كاد من لحظ يذوب !"},{"id":"diwan-abutammam:278","bookId":"diwan-abutammam","type":"poem","seq":278,"chapter":"البحر: منسرح","title":"لم أر شيئا من الفراق اذا","page":"","text":"لم أر شيئا من الفراق اذا … كان أخو البين عاشقا كلفا\nأصعب من وقفة المشيع للحبم … ب يريد الوداع منصرفا\nماأنفع القرب للمحب وإن … أعرض عنه حبيبه وجفا\nأي محب تم السرور له … "},{"id":"diwan-abutammam:279","bookId":"diwan-abutammam","type":"poem","seq":279,"chapter":"البحر: رمل تام","title":"إن يكن في الأرض شيء حسن","page":"","text":"إن يكن في الأرض شيء حسن … فهو في دور بني عبد الملك\nما يبالون إذا ما أفضلوا … ما بقي من مالهم أو ما هلك\nعقلت ألسنهم عن قول لا … فهي لا تعرف إلا هو لك\nمنهم موسى جواد ماجد … لايرى مالم يهب مما ملك\nزينوا الأرض كما قد زينت … بنجوم الليل آفاق الفلك"},{"id":"diwan-abutammam:280","bookId":"diwan-abutammam","type":"poem","seq":280,"chapter":"البحر: طويل","title":"قعقلي هذاصرت أحدوثة الركب","page":"","text":"قعقلي هذاصرت أحدوثة الركب … وقد كنت في سلم فأصبحت في حرب\nلعمرو مع الرمضاء والنار تلتظي … أرق وأحفى منك في ساعة الكرب\nمتى أتبغى النصف من قلب صاحب … إذا لم يكن قلبي شفيقا على قلبي ؟ !\nفمن مات من حب فإني ميت … لئن دام ذا من شدة البغض للحب"},{"id":"diwan-abutammam:281","bookId":"diwan-abutammam","type":"poem","seq":281,"chapter":"البحر: مجزوء الخفيف","title":"خمشتني بكفها","page":"","text":"خمشتني بكفها … وأشارت بطرفها\nفتأملت وجهها … فاتقتني بكفها\nليت بصفي على الف … راش لحافا لنصفها\nفأنال الذي أري … د على رغم أنفها"},{"id":"diwan-abutammam:282","bookId":"diwan-abutammam","type":"poem","seq":282,"chapter":"البحر: طويل","title":"قرى دارهم مني الدموع السوافك","page":"","text":"قرى دارهم مني الدموع السوافك … وإن عاد صبحي بعدهم وهو حالك\nوإن بكرت في ظعنهم وحدوجهم … زيانب من أحبابنا وعواتك\nسقت ربعهم لا بل سقت منتواهم … من الأرض أخلاف السحاب الحواشك\nوألبسهم عصب الربيع ووشيه … ويمنته نبت الندى المتلاحك\nإذا غازل الروض الغزالة نشرت … زرابي في أكنافهم ودرانك\nإذا الغيث سدى نسجه خلت أنه … مضت حقبة حرس له وهو حائك\nألكني إلى حي الأراقم إنه … من الطائر الأحشاء تهدى المآلك\nكلوا الصبر غضا واشربوه فإنكم … أثرتم بعير الظلم والظلم بارك\nأتاكم سليل الغاب في صدر سيفه … سنا لدجى الإظلام والظلم هاتك\nإذا سيل سد العذر عن صلب ماله … وإن هم لم تسدر عليه المسالك\nركوب لأثباج المتالف عالم … بأن المعالي دونهن المهالك\nألح وماحكتم وللقدر التقى … غريمان في الهيجا ملح وماحك\nهو الحارث الناعي بجيرا وإن يدن … له فهو إشفاقا زهير ومالك\nرقاحي حرب طالما انقلبت له … قساطل يوم الروع وهي سبائك\nومستنبط في كل يوم من الغنى … قليبا رشاآها القنا والسنابك\nمطل على الآجال حتى كأنه … لصرف المنايا في النفوس مشارك\nفما تترك الأيام من هو آخذ … ولا تأخذ الأيام من هو تارك\nصفوح إذا لم يثلم الصفح حزمه … وذو تدرإ بالفاتك الخرق فاتك\nربيب ملوك أرضعته ثديها … وسمع تربته الرجال الصعالك\nولو لم يكفكف خيله عركتكم … بأثقالها عرك الأديم المعارك\nولولا تقاه عاد قيضا مفلقا … بأدحيه بيض الخدور الترائك\nولا صطفيت شول فظلت شواردا … قروم عشار ما لهن مبارك\nإذا للبستم عار دهر كأنما … لياليه من بين الليالي عوارك\nولاجتذبت فرش من الأمن تحتكم … هي المثل في لين بها والأرائك\nولكن أبى أن يستباح بكفه … سنامكم في قومكم وهو تامك\nوأن تصبحوا تحت الأظل وأنتم … غوارب حيي تغلب والحوارك\nفتنجذم الأسباب وهي مغارة … وتنقطع الأرحام وهي شوابك\nفلا تكفرن الصامتي محمدا … آيادي شفعا سيبها متادرك\nأهب لكم ريح الصفاء جنائبا … رخاء وكانت وهي نكب سواهك\nفرد القنا ظمآن عنكم وأغمدت … على حرها بيض السيوف البواتك\nوآب على سعد السعود برحله … عتاق المذاكي والقلاص الرواتك\nغدا وكأن اليوم من حسن وجهه … وقد لاح بين البيض والبيض ضاحك\nحياتك للدنيا حياة ظليلة … وفقدك للدنيا فناء مواشك\nمتى يأتك المقدار ولا تدع هالكا … ولكن زمان غال مثلك هالك"},{"id":"diwan-abutammam:283","bookId":"diwan-abutammam","type":"poem","seq":283,"chapter":"البحر: طويل","title":"تبدلت الفا إذ تبدلت لي ألفا","page":"","text":"تبدلت الفا إذ تبدلت لي ألفا … وقد خانني فيك الزمان وما أوفى\nوجرعت نفسي من إخائك سلوة … على الرغم مني جرعة مرة صرفا\nمللت فما تعدو الملال شجية … تعودتها لا تستطيع لها صرفا\nرميت بحظي منك في أبعد المدى … وأسلمته للريح تنسفه نسفا\nووالله مازالت لوامع بارق … من الغدر في أجفان عينيك لا تخفى\nفأقسم لو أيقنت أن ملالة … لعيني تسمو لم أدر لهما طرفا"},{"id":"diwan-abutammam:284","bookId":"diwan-abutammam","type":"poem","seq":284,"chapter":"البحر: بسيط تام","title":"هارون يا خير من يرجى","page":"","text":"هارون يا خير من يرجى … لم يطع الله من عصاكا\nلو كان بعد النبي وحي … إلى ولي لكنت ذاكا"},{"id":"diwan-abutammam:285","bookId":"diwan-abutammam","type":"poem","seq":285,"chapter":"البحر: مجزوء الكامل","title":"نأي وشيك وانطلاق","page":"","text":"نأي وشيك وانطلاق … وغليل شوق واحتراق\nبأبي هوى ودعته … تاهت بصحبته الرفاق\nبدر يضيء لعاشقيه … ه وما يطيف به المحاق\nوتمرهت وتشعثت … جزعا لغيبته العراق\nالموت عندي والفراق … ق كلاهما ما لا يطاق\nيتعاونان على النفوس … فذا الحمام وذا السياق\nلو لم يكن هذا كذا … ما قيل موت أو فراق"},{"id":"diwan-abutammam:286","bookId":"diwan-abutammam","type":"poem","seq":286,"chapter":"البحر: خفيف تام","title":"لك علم بعبرتي واشتياقي","page":"","text":"لك علم بعبرتي واشتياقي … والذي بي من لوعة واحتراق\nولك الظرف والملاحة والحسن … ن وطيب الأردان والأخلاق\nوقبيح بان تعرض جسمي … ما أرى من مصارع العشاق\nفعلام الصدود في غير جرم … والصدود الفراق قبل الفراق"},{"id":"diwan-abutammam:287","bookId":"diwan-abutammam","type":"poem","seq":287,"chapter":"البحر: خفيف تام","title":"مات ذاك الجوى وذاك الحريق","page":"","text":"مات ذاك الجوى وذاك الحريق … ورثى لي ظبي علي شفيق\nوجرى النومث من جفوني مجرى … الدمع واستأنس الفؤاد المشوق\nرفق الدهر لي بمولاي والدهر … اذا شاء بالقلوب رفيق\nفبحقي وحرمتي لاتسبوا الده … ر ظلما فإنه لي صديق"},{"id":"diwan-abutammam:288","bookId":"diwan-abutammam","type":"poem","seq":288,"chapter":"البحر: منسرح","title":"يصدني عن كلامك الشفق","page":"","text":"يصدني عن كلامك الشفق … فالرسل بيني وبينك الحدق\nحديثنا في الضمير متفق … وأمرنا في الجميع مفترق\nتوحي بأسرارنا حواجبنا … وأعين بالوصال ترتشق"},{"id":"diwan-abutammam:289","bookId":"diwan-abutammam","type":"poem","seq":289,"chapter":"البحر: كامل تام","title":"ولله لو تلقى الذي ألقى","page":"","text":"ولله لو تلقى الذي ألقى … لحرجت أن تتجاوز الحقا\nبي فوق ما تلقى بواحدها … أم تراه لجنبها ملقى\nتبكي لنمهوش تنيبه … صل فما يرجى ولا يرقى\nفارحم شقيا في هواك فما … يبغي وإن أعتقته عتقا"},{"id":"diwan-abutammam:290","bookId":"diwan-abutammam","type":"poem","seq":290,"chapter":"البحر: سريع","title":"دعا أبي اللحظ خداكا","page":"","text":"دعا أبي اللحظ خداكا … وامترت الأعين عيناكا\nما زلت أرجوك كما لم تزل … يا سيدي مذ كنت أخشاكا\nوالله لو أعطى المنى لم أرد … إلاستلاما بفمي فاكا\nقد بعدت همة من راح أو … أصبح يوما يتمناكا"},{"id":"diwan-abutammam:291","bookId":"diwan-abutammam","type":"poem","seq":291,"chapter":"البحر: خفيف تام","title":"لهف نفسي علي لا بك عليكا","page":"","text":"لهف نفسي علي لا بك عليكا … أن تجول العيون في خديكا\nوعزيز علي أن تجتني الأب … صار زهر الربيع من وجنتيكا\nأنت وقف على القلوب بما أص … بحت تهوى وهن وقف عليكا\nلا قضى الله لي وصالك إن كن … ت أراني أشتاق إلا إليكا\nجرحتك العيون باللحظ حتى … صرت أخشى عليك من عينيكا"},{"id":"diwan-abutammam:292","bookId":"diwan-abutammam","type":"poem","seq":292,"chapter":"قصائد","title":"إن حزني علي لا بل عليكا","page":"","text":"إن حزني علي لا بل عليكا … بل على مهجة تسيل لديكا\nأنت تزهى بصورة غدت الأبص … ارمن حسنها وراحت عليكا\nلعن الله مقلة جعل … الأمرث إليها ففارقت وجنتيكا\nبأبي لفظك المليح الذي قد … ترك السمع وهو طوع يديكا\nإن قلبي عليك في كل وصل … وصدود أرق من خديكا\nنم فإن لم أنم كراي كراكا … شاهد منك أن ذاك كذاكا\nطال ضري تفديك نفسي - وقلت … نفس مثلي عن أن تكون فداكا !\nفي سبيل الهوى فؤادي وما آ … ي عليه لكن على ذكراكا\nذهبت مقلتاي بالدم والدم … ما فراق الدنيا أبالي ولكن\nلست ابكي ذهاب عيني لعيني … غير أني أبكي لأن لا أراكا"},{"id":"diwan-abutammam:293","bookId":"diwan-abutammam","type":"poem","seq":293,"chapter":"البحر: خفيف تام","title":"يا أبا جعفر اقر لك الحس","page":"","text":"يا أبا جعفر اقر لك الحس … وحلت جيوشه في ذراكا\nياأباجعفرخلقت بديعا … فاق حسن الوجوه حسن قفاكا\nياأباجعفر هل النأي ينجي … منك هيهات بل يزيد هلاكا\nياأباجعفر أنلني وصالا … يجزك الله إن فعلت - جزاكا"},{"id":"diwan-abutammam:294","bookId":"diwan-abutammam","type":"poem","seq":294,"chapter":"البحر: خفيف تام","title":"راحتي في البكاء حتى أراكا","page":"","text":"راحتي في البكاء حتى أراكا … إن لي منك شاغلا عن سواكا\nتعس الهجر والذي شأنه … ر من الناس كلهم حاشاكا\nأرشدني إلى رضاك فإني … لست أدري ما حيلتي في رضاكا !\nوإذا قيل من تحب تخطا … لساني وأنت في القلب ذاكا"},{"id":"diwan-abutammam:295","bookId":"diwan-abutammam","type":"poem","seq":295,"chapter":"البحر: وافر تام","title":"عريت من الهوى وبرئت منه","page":"","text":"عريت من الهوى وبرئت منه … لئن أنا لم أعاقب مقلتيكا\nبعثتك رائدا فسرقت منه … محاسنه بلحظة ناظريكا\nوجئت تقول لم أره وهذي … محاسنه تلوح بوجنتيكا\nفإن تك يا رسول كتمتنيه … لقد ظهرت محاسنه عليكا"},{"id":"diwan-abutammam:296","bookId":"diwan-abutammam","type":"poem","seq":296,"chapter":"البحر: مجزوء الخفيف","title":"ملك جار إذ ملك","page":"","text":"ملك جار إذ ملك … ليس يرثي لمن هلك\nهتكت ستر سلوتي … كف حبيك فانهتك\nيا مليكا اذا بكى … عبده في الهوى ضحك !\nلي من الحزن مثل ما … من بديع الجمال لك !"},{"id":"diwan-abutammam:297","bookId":"diwan-abutammam","type":"poem","seq":297,"chapter":"البحر: سريع","title":"آنسني من بعدك الوجد","page":"","text":"آنسني من بعدك الوجد … وعبرة تطرق أو تغدو\n … بنت فطرفي منه مرتد\nلم يجمعاقط لعيني وقد … يجتمع النرجس والورد ؟"},{"id":"diwan-abutammam:298","bookId":"diwan-abutammam","type":"poem","seq":298,"chapter":"البحر: خفيف تام","title":"وجد الحاسدون فينا مقالا","page":"","text":"وجد الحاسدون فينا مقالا … فوقوا أسهما لنا ونبالا\nعجبوا أن قانصا بث في الآ … فاق أشراكه فصاد غزالا\nملأ عيني ملاحة وجمالا … وفؤادي مهابة وجلالا\nفاعذلوا فيه كيف شئتم وقولوا … قد كفى الله المؤمنين القتالا"},{"id":"diwan-abutammam:299","bookId":"diwan-abutammam","type":"poem","seq":299,"chapter":"قصائد","title":"ظبي بيته بورده في خده","page":"","text":"ظبي بيته بورده في خده … خد عليه غلائل من ورده\nما كنت أحسب أن لي مستمتعا … في قربه حتى بليت ببعده\nلاشيء أحسن منه ليلة وصلنا … وقد اتخذت مخدة من خده\nوفمي على فمه يسامر ريقه … ويدي تنزه في حدائق جلده"},{"id":"diwan-abutammam:300","bookId":"diwan-abutammam","type":"poem","seq":300,"chapter":"البحر: سريع","title":"كم يتمادى ليلي الأطول","page":"","text":"كم يتمادى ليلي الأطول … كم يتبارى دمعي المسبل !\nيا طول هجر ماله آخر … منك لعتب ما له أول\nيا غافلا عني ما لي أرى … طرفك عن قتلي لا يغفل\nأراك لا تنفك ذا فزعة … في النوم من كثرة ما نقتل"},{"id":"diwan-abutammam:301","bookId":"diwan-abutammam","type":"poem","seq":301,"chapter":"البحر: خفيف تام","title":"شد ما استنزلتك من ربعك الأظ","page":"","text":"شد ما استنزلتك من ربعك الأظ … عان حتى استهل دمع الغزال\nأي حسن في الذاهبين تولى … وجمال على ظهور الجمال\nودلال مخيم في ذرى الخيم … وحجل معذب في الحجال\nومها من مها الخدور وأجال … ظباء يسرعن في الآجال\nعادك الزور ليلة الرمل من … رملة بين الحمى وبين المطال\nنم فما زارك الخيال ولكنك … رت طيف الخيال"},{"id":"diwan-abutammam:302","bookId":"diwan-abutammam","type":"poem","seq":302,"chapter":"البحر: مخلع البسيط","title":"فرد جمال سليل نور","page":"","text":"فرد جمال سليل نور … به استقلت يد السرور"},{"id":"diwan-abutammam:303","bookId":"diwan-abutammam","type":"poem","seq":303,"chapter":"البحر: خفيف تام","title":"إستزارته فكرتي في المنام","page":"","text":"إستزارته فكرتي في المنام … فأتاني في خيفة واكتتام\nالليالي أحفى بقلبي إذا ما … جرعته النوى من الأيام\nيا لها ليلة تنزهت الأرواح … واح فيها سرا من الأجسام !\nمجلس لم يكن لنا فيه عيب … غير أنا في دعوة الأحلام"},{"id":"diwan-abutammam:304","bookId":"diwan-abutammam","type":"poem","seq":304,"chapter":"البحر: هزج","title":"شبيه الخد بالتفا","page":"","text":"شبيه الخد بالتفا … ح والريقة بالخمر\nبديع الحسن قد ألف … من شمس ومن بدر\nله وجه إذا أبصر … ته ناجاك عن عذر\nتعالى الله ما تقد … حه عيناه في صدري"},{"id":"diwan-abutammam:305","bookId":"diwan-abutammam","type":"poem","seq":305,"chapter":"البحر: خفيف تام","title":"الهوى ظالم وأنت ظلوم","page":"","text":"الهوى ظالم وأنت ظلوم … كيف يقوى عليكما المظلوم\nللهوى جرأة ومنك صدود … ليس لي منكما محب رحيم\nقد براني الهوى ودله عقلي … حل بي منكما البلاء العظيم\nإنما يعرف السهاد وطول اللي … ل من كان حبله المصروم"},{"id":"diwan-abutammam:306","bookId":"diwan-abutammam","type":"poem","seq":306,"chapter":"البحر: منسرح","title":"ظنك فيما أسر ه حكم","page":"","text":"ظنك فيما أسر ه حكم … أرضى به لي وطرفك الفهم\nكيف سلوي ولست ترحمني … ليس بهذا تجاور النعم\nأمنت قلبي على هواك فما … قلبي على ما ائتمنت متهم\nأظهرت من لوعة الهوى جزعا … والصبر إلا عن الهوى كرم"},{"id":"diwan-abutammam:307","bookId":"diwan-abutammam","type":"poem","seq":307,"chapter":"البحر: مجزوء الكامل","title":"وافى الحبيب الزائر","page":"","text":"وافى الحبيب الزائر … طلع الهلال الباهر\nوغزير دمعي مهتد … فيه وقلبي حائر\nلي عبرة في الخد سا … ئرة وبيت سائر\nفلو اكتحلت بوجهه … والطرف منه فاتر\nوبوجنتيه بدائع … للجلنار ضرائر\nلرأيت حتف موارد … ليست لهن مصادر"},{"id":"diwan-abutammam:308","bookId":"diwan-abutammam","type":"poem","seq":308,"chapter":"البحر: خفيف تام","title":"ياسمي النبي حين يسمى","page":"","text":"ياسمي النبي حين يسمى … والذي خص بالجمال وعما\nوالذي هم خصره بانبتات … فثناه الحشى فكاد ولما\nلست أنسى مقالة لي سرا … أحسن الحب ما يكون معمى\nحفظ الله لي صحيح هواه … وكفاني من حبه ما أهما !"},{"id":"diwan-abutammam:309","bookId":"diwan-abutammam","type":"poem","seq":309,"chapter":"البحر: طويل","title":"رقادك يا طرفي عليك حرام","page":"","text":"رقادك يا طرفي عليك حرام … فخل دموعا فيضهن سجام\nففي الدمع إطفاء لنار صبابة … لها بين اثناء الضلوع ضرام\nويا كبدي الحرى التي قد تصدعت … من الوجد ذوبي ما عليك ملام\nقضيت ذماما للهوى كان واجبا … علي ولي أيضا عليه ذمام\nويا وجه من ذلت وجوه أعزة … له وسطا عزا فليس يرام\nأجر مستجيرا في الهوى بك باسطا … إليك يديه والعيون نيام"},{"id":"diwan-abutammam:310","bookId":"diwan-abutammam","type":"poem","seq":310,"chapter":"البحر: خفيف تام","title":"يا غزالا قطاف وجنته الور","page":"","text":"يا غزالا قطاف وجنته الور … د ودر بفيه در نثير\nلا وقد يهتز كالغصن الغض … إذا ارتج فيه ردف وثير\nلا سألت الخلاص منك وإن كن … ت بلاء الهوى علي تثير"},{"id":"diwan-abutammam:311","bookId":"diwan-abutammam","type":"poem","seq":311,"chapter":"البحر: منسرح","title":"حبك بين الحشا مقيم","page":"","text":"حبك بين الحشا مقيم … يا أيها الشادن الرخيم\nأما وخد علاه ورد … أبدع في طيبه النعيم\nلقد تمكنت من فؤاد … اسقمه طرفك السقيم"},{"id":"diwan-abutammam:312","bookId":"diwan-abutammam","type":"poem","seq":312,"chapter":"البحر: مجتث","title":"الدهر يوم ويوم","page":"","text":"الدهر يوم ويوم … والعيش عذر ولوم\nفاقصر لما تشتهيه … ولا يكن منك حوم\nلا تصغين لقبيح … يقوله فيك قوم\nوأهيف كمنى النف … ليس يغليه سوم\nوسنان في مقلتيه … نوم وما ثم نوم\nفطري عليه وقد كا … ن قبله لي صوم"},{"id":"diwan-abutammam:313","bookId":"diwan-abutammam","type":"poem","seq":313,"chapter":"البحر: مجزوء الرجز","title":"أصداغه ألف ولام","page":"","text":"أصداغه ألف ولام … في طرفه سيف حسام\nوكلامه در هوى … لما تخونه النظام\nلم ينتقص في حسنه … فله الكمالة والتمام"},{"id":"diwan-abutammam:314","bookId":"diwan-abutammam","type":"poem","seq":314,"chapter":"البحر: خفيف تام","title":"لا تصدي فالصد أمر عظيم","page":"","text":"لا تصدي فالصد أمر عظيم … وارحمي فالاله بر رحيم\nأمن العدل أن قلبك سال … والهوى ثابت بقبي مقيم\nثم ألحقت بي الإساءة والظل … وغيري هو المسي الظلوم\nما اجترمنا اليك جرما ولكن … حب هذا الزمان ليس يدوم"},{"id":"diwan-abutammam:315","bookId":"diwan-abutammam","type":"poem","seq":315,"chapter":"البحر: كامل تام","title":"أغمد عن المهجات سيف الناظر","page":"","text":"أغمد عن المهجات سيف الناظر … فلقد فترن من اللحاظ الفاتر\nكيف اعتدلت مع اعتدال الغصن في … حركاته وفعلت فعل الجائر\nوعلمت إثم السحر حين ذممته … وأراك متخذا أداة الساحر\nيا شاعرا في طرفه وبهائه … وجماله عذبت قلب الشاعر !"},{"id":"diwan-abutammam:316","bookId":"diwan-abutammam","type":"poem","seq":316,"chapter":"البحر: كامل تام","title":"عنت له سكن فهام بذكرها","page":"","text":"عنت له سكن فهام بذكرها … أي الدموع وقد بدت لم يجرها !\nبيضاء يحسب شعرها من وجهها … لما بدا أو وجهها من شعرها\nمتفنن في الظرف باطن صدرها … متفنن في الحسن ظاهر صدرها\nتعطيك منطقها فتعلم أنه … لجنى عذوبته يمر بثغرها\nوأظن حبل وصالها لمحبها … أوهى وأضعف قوة من خصرها"},{"id":"diwan-abutammam:317","bookId":"diwan-abutammam","type":"poem","seq":317,"chapter":"البحر: رمل تام","title":"أنت في حل فزدني سقما","page":"","text":"أنت في حل فزدني سقما … أفن صبري واجعل الدمع دما\nوارض لي الموت بهجريك فإن … لم أمت شوقا فزدني ألما\nمحنة العاشق ذل في الهوى … وإذا استودع سرا كتما\nليس منا من شكلى علته … من شكا ظلم حبيب ظلما !"},{"id":"diwan-abutammam:318","bookId":"diwan-abutammam","type":"poem","seq":318,"chapter":"البحر: طويل","title":"إذا راح مشهور المحاسن أو غدا","page":"","text":"إذا راح مشهور المحاسن أو غدا … بلين على لحظ العيون الغوامز\nفمن لم تفز عيناه منه بنظرة … فليس بخير في الحياة بفائز\nإذا ما انتضى سيف الملاحة طرفه … ونادى قلوب القوم هل من مبارز\nعجزت فألقى السلم قلبي لطرفه … على أنه عن غيره غير عاجز"},{"id":"diwan-abutammam:319","bookId":"diwan-abutammam","type":"poem","seq":319,"chapter":"البحر: وافر تام","title":"تناء بدؤه ذنب التداني","page":"","text":"تناء بدؤه ذنب التداني … من المسروق من حور الجنان\nبخديه دقائقث لو تراها … إذا لسألت عنها في المعاني\nتساكتنا وقلبانا جميعا … بألفاظ الهوى يتكلمان\nوحاربناغليل الشوق حتى … نزلنا صاغرين على الأمان"},{"id":"diwan-abutammam:320","bookId":"diwan-abutammam","type":"poem","seq":320,"chapter":"البحر: مديد تام","title":"لو تراه يا أبا الحسن","page":"","text":"لو تراه يا أبا الحسن … قمرا أوفى على غصن\nقمرا ألقت جواهره … في فؤادي جوهر الحزن\nكل جزء من محاسنه … فيه أجزاء من الفتن\nلي في تركيبه بدع … شغلت قلبي عن السنن\nبأبي الأنصار من نفر … نصروا سقمي على بدني !"},{"id":"diwan-abutammam:321","bookId":"diwan-abutammam","type":"poem","seq":321,"chapter":"البحر: خفيف تام","title":"يا جفونا سواهرا اعدمتها","page":"","text":"يا جفونا سواهرا اعدمتها … لذة النوم والرقاد جفون\nأين منك الدما فقد نفد الدم … عث الذي يمتريه منك الحزين\nبلي الجسم لكن الشوق حي … ليس يبلى وليس تبلى الشجون\nإن لله في العباد منايا … سلطتها على القلوب العيون !"},{"id":"diwan-abutammam:322","bookId":"diwan-abutammam","type":"poem","seq":322,"chapter":"البحر: طويل","title":"ومحتكم في الخمص طورا وفي البدن","page":"","text":"ومحتكم في الخمص طورا وفي البدن … فقد دق في حقف وقد جل عن غصن\nبتدى فأبدى لي الجوى من صدوده … وأسنى عطيات الفؤاد من الحزن\nوقد سود الديوان بعض ثيابه … وأحسن ما تستوضح الشمس في الدجن\nفلاقته أبيات تناسب وجهه … ندبت لها فكري وأخدمتها ذهني\nفأغضبته أن قلت يا أحسن الورى … وكاد بأن يفضي إلى الشتم واللعن\nإذا غاظ وصف الناس بالحسن أهله … فلم لم يخرق ثوبه يوسف الحسن ؟"},{"id":"diwan-abutammam:323","bookId":"diwan-abutammam","type":"poem","seq":323,"chapter":"البحر: طويل","title":"لعمري لئن قرت بقربك أعين","page":"","text":"لعمري لئن قرت بقربك أعين … لقد سخنت بالبين منك عيون\nفسرأوأقم وقف عليك محبتي … مكانك من قلبي عليك مصون\nوإني لأخشى إن تراقت أموره … رغما ونطلبث صرف الدهر بالإحن"},{"id":"diwan-abutammam:324","bookId":"diwan-abutammam","type":"poem","seq":324,"chapter":"البحر: منسرح","title":"الحسن جزء من وجهك الحسن","page":"","text":"الحسن جزء من وجهك الحسن … يا قمرا موفيا على غصن\nإن كنت في الحسن واحدا فأنا … يا واحد الحسن واحد الحزن\nكل سقام تراه في أحد … فذاك فرع والأصل في بدني\nكوائن الحب قبل كونك في … أفئدة العاشقين لم تكن"},{"id":"diwan-abutammam:325","bookId":"diwan-abutammam","type":"poem","seq":325,"chapter":"البحر: وافر تام","title":"فديت محمدا من كل سو","page":"","text":"فديت محمدا من كل سو … يحاذر في رواح أو غدو\nأيا قمر السماء سفات حتى … كأنك قد ضجرت من العلو\nرأيتك من محبك ذا بعاد … وممن لا يحبك ذا دنو\nفلو أن الصبا حملتك ما إن … سيسبقني الغداة إلى السلو\nوحسبك حسرة لك من صديق … رأيت زمامه بيدي عدو"},{"id":"diwan-abutammam:326","bookId":"diwan-abutammam","type":"poem","seq":326,"chapter":"البحر: سريع","title":"رق له إن كنت مولاه","page":"","text":"رق له إن كنت مولاه … وارحم فقد أشمت أعداه\nويل له إن دام هذا به … من حرق تفلق أحشاه\nيا غصن بان ناعما قده … فوق نقا يهتز أعلاه\nمنعت عيني لذيذ الكرى … أحسن كما حسنك الله !"},{"id":"diwan-abutammam:327","bookId":"diwan-abutammam","type":"poem","seq":327,"chapter":"البحر: مجزوء الوافر","title":"لها وأعارني ولها","page":"","text":"لها وأعارني ولها … وأبصر ذلتي فزها\nلهث وجه يعز به … ولي حرق أذل لها\nدقيق محاسن وصلت … محاسن وجنتيه بها\nألاحظ حسن وجنتيه … فتجرحني وأجرحها !"},{"id":"diwan-abutammam:328","bookId":"diwan-abutammam","type":"poem","seq":328,"chapter":"البحر: طويل","title":"منحتك ودا كان طفلا فقد نشا","page":"","text":"منحتك ودا كان طفلا فقد نشا … وأبديت لي جسما من الود موحشا\nأرى ثمر الحسن الذي قد غرسته … على سقف أعواد التجني معرشا\nولي يا خلي الصدر من لوعة الهوى … حشا لست أدري جمرة هي أم حشا\nفداو سقاما منه في الجسم فاشيا … كما الحسن في ساحات وجهك قد فشا\nفأقسم لو تبدو لعين مرقش … لأذهلت عن أسماء حقا مرقشا"},{"id":"diwan-abutammam:329","bookId":"diwan-abutammam","type":"poem","seq":329,"chapter":"البحر: بسيط تام","title":"","page":"","text":" … أشهى إلي من الدنيا وما فيها\nحمراء في صفرة علت بغالية … كأنما قطفت من خد مهديها\nجاءت بها قينة من عند غانية … نفسي من السقم والأحزان تفديها\nلو كنت ميتا ونادتني بنغمتها … لكنت للشوق من لحدي ألبيها"},{"id":"diwan-abutammam:330","bookId":"diwan-abutammam","type":"poem","seq":330,"chapter":"البحر: وافر تام","title":"أيا من لا يرق لعاشقيه","page":"","text":"أيا من لا يرق لعاشقيه … ومن مزج الصدود لنا بتيه\nومن سجد الجمال له خضوعا … وعم الحسن منه من يليه\nسليل الشمس أنت فدتك نفسي … وهل لسليل شمس من شبيه\nكملت ملاحة وفضلت ظرفا … فأنت مهذب لا عيب فيه"},{"id":"diwan-abutammam:331","bookId":"diwan-abutammam","type":"poem","seq":331,"chapter":"البحر: وافر تام","title":"تحمل من حياتي في يديه","page":"","text":"تحمل من حياتي في يديه … فيا أسفي ويا شوقي إليه !\nتعالى الله يا طوبى لعين … تمتع طرفها في وجنتيه\nأظن البين كان يريد فجعي … به إذ صار يحسدني عليه\nسأبكي ما أطاع الدمع عيني … محاسنه وفترة مقلتيه"},{"id":"diwan-abutammam:332","bookId":"diwan-abutammam","type":"poem","seq":332,"chapter":"البحر: بسيط تام","title":"نشرت فيك رسيسا كنت أطويه","page":"","text":"نشرت فيك رسيسا كنت أطويه … وأظهرت لوعتي ما كنت أخفيه\nإن كان وجهك لي تترى محاسنه … فإن فعلك بي تترى مساويه\nمرتجة في تهاديه أسافله … مهتزة في تثنيه أعاليه\nتاهت على صورة الأشياء صورته … حتى إذا كملت تاهت على التيه\nما استجمعت فرق الحسن التي افترقت … عن يوسف الحسن حتى استجمعت فيه"},{"id":"diwan-abutammam:333","bookId":"diwan-abutammam","type":"poem","seq":333,"chapter":"البحر: كامل تام","title":"لو كنت عندي أمس وهو معانقي","page":"","text":"لو كنت عندي أمس وهو معانقي … ومدامعي تجري على خديه\nقد ارتوت من عبرتي وجناته … وتنزهت شفتاي من شفتيه\nلرأيت بكاء يهون على الهوى … وتهون تخلية الدموع عليه\nورأيت أحسن من بكائي قوله … هذا الفتى متعنت عينيه !"},{"id":"diwan-abutammam:334","bookId":"diwan-abutammam","type":"poem","seq":334,"chapter":"البحر: كامل تام","title":"برعت محاسنه فجل بها","page":"","text":"برعت محاسنه فجل بها … من أن يقوم بوصفه لفظ\nنطق الجمال بعذر عاشقه … للعاذلات فأخرس الوعظ\nلم تبتذل منه النفوس سوى … ما نال من وجناته اللحظ\nماضر من تمت محاسنه … لو كان رق فؤاده الفظ"},{"id":"diwan-abutammam:335","bookId":"diwan-abutammam","type":"poem","seq":335,"chapter":"البحر: بسيط تام","title":"ظني به حسن لولا تجنيه","page":"","text":"ظني به حسن لولا تجنيه … وأنه ليس يرعى حق وديه\nلم يلهني عنه ما ألهاه بل عذبت … عندي الصبابة إذ جرعتها فيه\nعفت محاسنه عندي إساءته … حتى لقد حسنت عندي مساويه\nهذا محبك أدمى الشوق مهجته … فكيف تنكر أن تدمى مآقيه !"},{"id":"diwan-abutammam:336","bookId":"diwan-abutammam","type":"poem","seq":336,"chapter":"البحر: بسيط تام","title":"عنت فأعرض عن تعريضها أربي","page":"","text":"عنت فأعرض عن تعريضها أربي … يا هذه اعذري في هذه النكب\nإليك ويلك عمن كان ممتلئا … ويلا عليك وويحا غير منقضب\nفي صدره من هموم يعتلجن به … وساوس فرك للخرد العرب\nرد اتداد الليالي غرب أدمعه … فذاب هما وجمد العين لم يذب\nلا أن خلفك للذات مطلعا … لكن دونك موت اللهو والطرب\nوحادثات أعاجيب خسا وزكا … ما الدهر في فعله إلا أبو العجب\nيغلبن قوم الكماة المعلمين بها … ويستقدن لفرسان على القصب\nفما عدمت بها لا جاحدا عدما … صبرا يقوم مقام الكشف للكرب\nما يحسم العقل والدنيا تساس يه … مايحسم الصبر في الأحداث والنوب\nالصبر كاس وبطن الكف عارية … والعقل عار إذا لم يكس بالنشب\nما أضيع العقل إن لم يرع ضيعته … وفر واي رحى دارت بلا قطب\nنشبت في لجج الدنيا فأثكلني … مالي وأبت بعرض غير مؤتشب\nكم ذقت في الدهر من عسر ومن يسر … وفي بني الدهر من رأس ومن ذنب\nأغضي إذا صرفه لم تغض أعينه … عني وأرضى إذا ما لج في الغضب\nوإن بليت بجد من حزونته … سهلته فكأني منه في لعب\nمقصر خطرات الهم في بدني … علما بأني ما قصرت في الطلب\nبأي وخد قلاص واجتياب فلا … أدراك رزق إذاما كان في الهرب\nماذا علي إذا لم يزل وتري … في الرمي ان زلن أغراضي فلم أصب\nفي كل يوم أظافيري مفللة … تستنبط الصفر لي من معدن الذهب\nما كنت كالسائل الأيام مختبطا … عن ليلة القدر في شعبان أو رجب\nبل سافع بنواصي الأمر مشتمل … على قواصيه في بدء وفي عقب\nما زلت أرمي بآمالي مراميها … لم يخلق العرض مني سوء مطلبي\nبغربة كاغتراب الجود ان برقت … بأوبة ودقت بالخلف والكذب\nإذا عنيت لشأو قلت إني قد … أدركته أدركتني حرفة الأدب !\nوخيبة نبعت من غيبة شسعت … بأنحس طلعت في كل مضطرب\nما آب من آب لم يظفر ببغيته … ولم يغب طالب للنجح لم يخب !"},{"id":"diwan-abutammam:337","bookId":"diwan-abutammam","type":"poem","seq":337,"chapter":"البحر: وافر تام","title":"","page":"","text":" … وخدناه الكآبة والنحيب\nوما تبقى على إدمان هذا … ولا هاتا العيون ولا القلوب\nعلى أن الغريب إذا استمرت … به مرر النوى آسى الغريب\nونعم مسكن البرجاء - حلت … به فأقامت - الدمع السكوب\nوكم عدوية من سر عمر و … لها حسب إذا انتسبت حسيب\nلها من طيء أم حصان … نجيبة معشر وأب نجيب\nتنى أن يعود لها حبيب … منى شططا وأين لها حبيب\nولو بصرت به لرأت حريصا … بماء الدهر حليته الشحوب\nكنصل السيف عري من كساه … وفلت من مضاربه الخطوب\nزعيمق بالغنى أو ندب نوح … حواقلة وأصبية ترامت\nفأصبح حيث لا نقع لصاد … ولا نشب يلوذ بهش حريب\nبمصر وأي مأربة بمصر … وقد شعبت كابرها شعوب"},{"id":"diwan-abutammam:338","bookId":"diwan-abutammam","type":"poem","seq":338,"chapter":"البحر: كامل تام","title":"طلبته أيام وطالب مثلها","page":"","text":"طلبته أيام وطالب مثلها … أخرى فأصبح طالبا مطلوبا\nهي عزمة للسيف إلا أنها … جعلت لاسباب الزمان قصوبا\nخطبت خطوب الدهر منه خطة … نتجت عليه تجاربا ونكوبا\nصرمت حبال الدهر منه صريمة … تركت النائبات وجيبا\nولربما أشكته نكبة حادث … نكأت بباطن صفحتيه ندوبا\nلا أنه خذلته أسباب الغنى … أو راح من سلب الزمان سليبا\nلكنه عجب وليس بمعجب … أن شام من حكم الزمان عجيبا\nيوما بمنقطع الشروق مقامه … ويقيم يوما بالغروب غريبا\nلا كانت الآمال يكفل نجحها … كرم يريك تجهما وقطوبا"},{"id":"diwan-abutammam:339","bookId":"diwan-abutammam","type":"poem","seq":339,"chapter":"البحر: رجز تام","title":"لما رأيت الأمر أمرا جدا","page":"","text":"لما رأيت الأمر أمرا جدا … ولم أجد من القيام بدا\nلبست جلد نمر معتدا … وجلد ضرغام يقد قدا\nجمعت جمع العرب الأشدا … جمعا يلد الظالم الأشدا\nيهد أركان الجبال هدا … كان تميم لأبينا عبدا\nأسود نضاخ المقد جعدا … ونحن كنا للتبي جندا\nيوم بزاخات وردن وردا … وعد لي بدرا وعد أحدا\nوطيءق قد ألبستني بردا … حتى فخرت فهزمت العبدا"},{"id":"diwan-abutammam:340","bookId":"diwan-abutammam","type":"poem","seq":340,"chapter":"البحر: طويل","title":"تصدت وحبل البين مستحصد شزر","page":"","text":"تصدت وحبل البين مستحصد شزر … وقد سهل التوديع ما وعر الهجر\nبكته بما أبكته أيام صدرها … خليء وما يخلو له من جوى صدر\nوقالت أتنسى البدر ، قلت تجلدا … إذا الشمس لم تغرب فلا طلع البدر\nفأبدت جمانا من دموع نظامها … على الصدر إلا أن صائغها الشفر\nوما الدمع ثان عزمتي ولو أنها … سقى خدها من كل عين لها نهر\nجمعت شعاع الرأي ثم وسمته … بحزم له في كل مظلمة فجر\nوصارعت عن مصر رجائي ولم يكن … ليصرع عزمي غير ما صرعت مصر\nوطحطت سدا سد يأجوج دونه … من الهم لم يفرغ على زبره قطر\nبذعلبة ألوى بوافر نحضها … فتى وافر الأخلاق ليس له وفر\nفكم مهمه قفر تعشقت متنه … على متنها والبر من آله بحر\nوما الققر بالبيد القواء بل التي … نبت بي وفيها ساكنوها هي القفر !\nومن قامر الأيام عن ثمراتها … فأحج به أن ينجلي ولها القمر\nفإن كان ذنبي أن أحسن مطلبي … أساء ففي سوء القضاء لي الغدر\nقضاء الذي ما زال في يده الغنى … ثنى غرب آمالي وفي يدي الفقر\nرضيت وهل أرضى إذا كان مسخطي … من الأمر ما فيه رضا من له الأمر !\nفأشجيت أيامي بصبر حلون لي … عواقبه والصبر مثل اسمه صبر\nأبى لي بحر الغوث أن أرأم التي … أسب بها والنجر يشبهه النجر\nوهل خاب من جذماه في ضنء طيىء … عدي العديين القلمس أو عمرو\nلنا غرر زيدية أددية … إذا نجمت ذلت لها الأنجم الزهر\nلنا جوهر لو خالط الأرض أصبحت … وبطنانها منه وظهرانها تبر\nجديلة والغوث اللذين إليهما … صغت أذن للمجد ليس بها وقر\nمقاماتنا وقف على الحلم والحجى … فأمردنا كهل وأشيبنا حبر\nألنا الأكف بالعطاء فجاوزت … مدى اللين الا أن أعراضنا صخر\nكأن عطايانا يناسبن من أتى … ولا نسب يدنيه منا ولا صهر\nاذا زينة الدنيا من المال أعرضت … فأزين منها عندنا الحمد والشكر\nوكور اليتامى في السنين فمن نبا … بفرخ له وكر فنحن له وكر\nأبى قدرنا في الجود إلا نباهة … فليس لمال عندنا أبدا قدر\nليسحج بجود من أراد فإنه … عوان لهذا الناس وهو لنا بكر\nجرى حاتم في حلبة منه لو جرى … بها القطر شأوا قيل أيهما القطر !\nفتى ذخر الدنيا أناس فلم يزل … لها باذلا فانظر لمن بقي الذخر !\nفمن شاء فليفخر بما شاء من ندى … فليس لحي غيرنا ذلك الفخر\nجمعنا العلى بالجود بعد افتراقها … إلينا كما الأيام يجمعها الشهر\nبنجدتنا ألقت بنجد بعاعها … سحاب المنايا وهي مظلمة كدر\nبكل كمي نحره غرض القنا … إذا اضطرم الأحشاءث وانتفخ السحر\nيشيعه أبناء موت إلى الوغى … يشيعهم صبر يشيعه نصر\nكماة إذا ظل الكماة بمعرك … وأرماحهم حمر وألوانهم صفر\nبخيل لزيد الخيل فيها فوارس … اذا نطقوا في مشهد خرس الدهر\nعلى كل طرف يحسر الطرف سابح … وسابحة لكن سباحتها الحضر\nطوى بطنها الإسآد حتى لو أنه … بدا لك ما شككت في أنهث ظهر\nضبيبية ما إن تحدث أنفسا … بما خلفها مادام قدامها وتر\nفإن ذمت الأعداء سوء صباحها … فليس يؤدي شكرها الذئب والنسر\nبها عرفت أقدارها بعد جهلها … بأقدارها قيس بن عيلان والفزر\nوتغلب لاقت غالبا كل غالب … وبكر فألفت حربنا بازلا بكر\nوأنت خبير كيف أبقت أسودنا … بني أسد إن كان ينفعك الخبر\nوقسمتنا الضيزى بنجد وأهلها … لنا خطوة في أرضها ولهم فتر\nمساع يضل الشعر في كنه وصفها … فما يهتدي إلا لأصغرها الشعر"},{"id":"diwan-abutammam:341","bookId":"diwan-abutammam","type":"poem","seq":341,"chapter":"البحر: طويل","title":"ألا صنع البين الذي هو صانع","page":"","text":"ألا صنع البين الذي هو صانع … فإن تك مجزاعا فما البين جازع\nهو الربيع من اسماء والعام رابع … له بلوى خبت فهل أنت رابع\nألا إن صبري من عزائي بلاقع … عشية شاقتني الديار البلاقع\nكأن السحاب الغر غيبن تحتها … حبيبا فما ترقا لهن مدامع\nربى شفعت ريح الصبا لرياضها … إلى الغيث حتى جادها وهو هامع\nفوجه الضحى غدوا لهن مضاحك … وجنبث الندى ليلا لهن مضاجع\nكساك من الأنوار أصفر فاقع … وابيض نصاع وأحمر ساطع\nلئن كان أمسى شمل وحشيك جامعا … لقد كان لي شمل بأنسك جامع\nأسيء على الدهر الثناء فقد قضى … علي بجور صرفه المتتابع\nأيرضخنا رضخ النوى وهو مصمت … ويأكلنا أكل الدبى وهو جائع\nوإني إذا ألقى بربعي رحله … لأذعره في سربه وهو راتع\nأبو منزل الهم الذي لو بغى القرى … لدى حاتم لم يقره وهو طائع\nاذا شرعت فيه الليالي بنكبة … تمزقن عنه وهو بالصبر دارع\nوان أقدمت يوما عليه رزية … تلقى شباها وهو بالصبر دارع\nله همم ما إن تزال سيوفها … قواطع لو كانت لهن مقاطع\nألا إن نفس الشعر ماتت وإن يكن … عداها حمام الموت فهي تنازع\nسأبكي القوافي بالقوافي فإنها … عليها - ولم تظلم بذاك - جوازع\nأراعي مظلات المروءة مهمل … وحافظ أيام المكارم ضائع !\nوعاو عوى والمجد بيني وبينه … له حاجز دوني وركن مدافع\nترقت مناه طود عز لو ارتقت … به الريح فترا لانثنت وهي ظالع\nأنا ابن الذين استرضع الجود فيهم … وسمي فيهم وهو كهل ويافع\nسما بي أوس في السماء وحاتم … وزيد القنا والأثرمان ورافع\nوكان إياس ما اياس وعارف … وحارثة أوفى الورى والأصابع\nنجوم طواليع جبال فوارع … غيوث هواميع سيول دوافع\nمضوا وكأن المكرمات لديهم … لكثرة ما أوصوا بهن شرائع\nفأي يد في المحل مدت فلم يكن … جنوب فيول ما لهن مضاجع\nهم استودعو المعروف محفوظ مالنا … فضاع وما ضاعت لدينا الودائع\nبهاليل لو عاينت فضل أكفهم … لأيقنت أن الرزق في الأرض واسع\nإذا خفقت بالبذل أرواح جودهم … حداها الندى واستنشقتها المطامع\nرياح كريح العنبر الغض في الندى … ولكنها يوم اللقاء زعازع\nإذا طيىء لم تطو منشور بأسها … فأنف الذي يهدي لها السخط جادع\nهي السم ما ينفك في كل بلدة … تسيل به أرماحهم وهو ناقع\nأصارت لهم أرض العدو قطائعا … نفوس لحد المرهفات قطائع\nبكل فتى ما شاب منروع وقعة … ولكنه قد شبن منه الوقائع\nاذا ماأغاروا فاحتووا مال معشر … أغارت عليهم فاحتوته الصنائع\nفتعطي الذي تعطيهم الخيل والقنا … أكف لا رث المكرمات موانع\nهم قوموا درء الشآم وأيقظوا … بنجد عيون الحرب وهي هواجع\nيمدون بالبيض القواطع أيديا … وهن سواء والسيوف القواطع\nإذا أسروا لم يأسر البأس عفوهم … ولم يمس عان فنهم وهو كانع\nإذا أطلقوا عنه جوامع غله … تيقن أن المن أيضا جوامع\nوإن صارعوا في مفخر قام دونهم … وخلفهم بالجد جد مصارع\nعلوا بجنوب موجدات كأنها … جنوب قبول ما لهن مضاجع\nكشفت قناع الشعر عن حر وجهه … وطيرته عن وكره وهو واقع\nبعز يراها من يراها بسمعه … فيدنو إليها ذو الحجى وهو شاسع\nيود ودادا أن أعضاء جسمه … إذا أنشدت شوقا إليها مسامع"},{"id":"diwan-abutammam:342","bookId":"diwan-abutammam","type":"poem","seq":342,"chapter":"البحر: طويل","title":"","page":"","text":" … وأنت غدا فيها تموت وتقبر ؟\nتلقح آمالا وترجو نتاجها … وعمرك مما قد ترجيه أقصر !\nتحوم على إدراك ماقد كفيته … وتقبل بالآمال فيه وتدبر\nوهذا صباح اليوم ينعاك ضوؤه … وليلته تنعاك إن كنت تشعر\nورزقك لا يعدوك إما معجل … على حالة يوما وإما مؤخر\nولا حول محتال ولا وجه مذهب … ولا قدر مزجيه إلا المقدر\nلقد قدر الأرزاق من ليس عادلا … عن العدل بين الخلق فيما يقدر\nفلا تأمن الدنيا وإن هي أقبلت … عليك فما زالت تخون وتغدر\nفما نم فيها الصفو يوما لأهله … ولا الرفق إلا ريثما يتغير\nوما لاح نجم لا ولا ذر شارق … على الخلق إلا حبل عمرك يقصر\nتطهر وألحق ذنبك اليوم توبة … لعلك منه إن تطهرت تطهر\nوشمر فقد أبدى لك الموت وجهه … وليس ينال الفوز إلا المشمر\nفهذي الليالي مؤذناتك بالبلى … تروح وأيام كذلك تبكر\nواخلص لدين الله صدرا ونية … فإن الذي تخفيه يوما سيظهر\nوقد يستر الإنسان باللفظ فعله … فيظهر عنه الطرف ما كان يستر\nتذكر وفكر في الذي أنت صائر … إليه غذا إن كنت ممن يفكر\nفلا بد يوما أن تصير لحفرة … بأثنائها تطوى إلى يوم تنشر"},{"id":"diwan-abutammam:343","bookId":"diwan-abutammam","type":"poem","seq":343,"chapter":"البحر: طويل","title":"أرى ألفات قد خططن على راسي","page":"","text":"أرى ألفات قد خططن على راسي … بأقلام شيب في مهارق أنقاس\nفإن تسأليني من يخط حروفها … فكف الليالي تستمد بأنفاسي\nجرت في قلوب الغانيات لشيبتي … قشعريرة من بعد لين وإيناس\nوقد أمس من وصل الكواعب آيسا … فآخر آمال العباد إلى اليأس"},{"id":"diwan-abutammam:344","bookId":"diwan-abutammam","type":"poem","seq":344,"chapter":"البحر: طويل","title":"ألم يأن تركي لا علي ولا ليا","page":"","text":"ألم يأن تركي لا علي ولا ليا … وعزمي على ما فيه اصلاح حاليا\nوقد نال مني الشيب وابيض مفرقي … وغالت سوادي شهبة في قذاليا\nوحالت بي الحالات عما عهدتها … بكر الليالي والليالي ما هيا\nأصوت بالدنيا وليست تجيبني … أحاولث أن ابقى وكيف بقائيا\nوما تبرح الأيام تحذف مدتي … بعد حساب لا كعد حسابيا\nلتمحو آثاري وتخلق جدتي … وتخلي من ربعي بكره مكانيا\nكما فعلت قبلي بطسم وجرهم … وآل ثمود بعد عاد بن عاديا\nوأبقى صريعا بين أهلي جنازة … ويحوي ذوو الميراث خالص ماليا\nأقول لنفسي حين مالت بصغوها … إلى خطرات قد نتجن أمانيا\nأليس الليالي غاصباتي بمهجتي … كما غصبت قبلي القرون الخواليا\nومسكنتي لحدا لدى حفرة بها … يطول إلى أخرى الليالي ثوائيا ؟\nكما أسكنت حاما وساما ويافثا … ونوحا ومن أمسى بمكة ثاويا\nفقد أنست بالموت نفسي لأنني … رأيت المنايا يخترمن حياتيا\nفيا ليتني من بعد موتي ومبعثى … أكون رفاتا لا علي ولا ليا\nأخاف إلهي ثم أرجو نواله … ولكن خوفي قاهر لرجائيا\nولولا رجائي واتكالي على الذي … توحد لي بالصنع كهلا وناشيا\nلما ساغ لي عذب من الماء بارد … ولا طاب لي عيش ولا زلت باكيا\nوأدخر التقوى بمجهود طاقتي … واركب في رشدي خلاف هوائيا\nعلى إثر ما قد كان مني صبابة … ليالي فيها كنت لله عاصيا\nفإني جدير أن أخاف وأتقي … وإن كنت لم أشرك بذي العرش ثانيا"},{"id":"diwan-abutammam:345","bookId":"diwan-abutammam","type":"poem","seq":345,"chapter":"قصائد","title":"البين جرعني نقيع الحنظل","page":"","text":"البين جرعني نقيع الحنظل … والبين أثكلني وإن لم أثكل\nما حسرتي أن كدت أقضي إنما … حسرات نفسي أنني لم أفعل\nنقل فؤدك حيث شئت من الهوى … ما الحب إلا للحبيب الأول\nكم منزل في الأرض يألفه الفتى … وحنينه أبدا لأول منزل"},{"id":"diwan-abutammam:346","bookId":"diwan-abutammam","type":"poem","seq":346,"chapter":"قصائد","title":"زائر زارني فهاج خيالا","page":"","text":"زائر زارني فهاج خيالا … كنت لولاه أسوأ الناس حالا\nفتمتعت من غزال وحاشى … ذلك الشخص أن يكون غزالا\nكيف أرجو لقاء ساكن بغدا … د بمصر لقد رجوت ضلالا ؟ !\nمثلته المنى لعيني وفكري … ولقلبي حتى قبلت المحالا\nما أراني أزال نصب خيال … طارق أو يصير جسمي خيالا !"},{"id":"diwan-abutammam:347","bookId":"diwan-abutammam","type":"poem","seq":347,"chapter":"قصائد","title":"أغار عليك من قبلي","page":"","text":"أغار عليك من قبلي … وإن أعطيتني أملي\nوأشفق أن أرى خدي … ك نصب مواقع المقل"},{"id":"diwan-abutammam:348","bookId":"diwan-abutammam","type":"poem","seq":348,"chapter":"البحر: كامل تام","title":"متطلب بصدوده قتلي","page":"","text":"متطلب بصدوده قتلي … فرد المحاسن وجهه شغلي\nألحاظه في الخلق مسرعة … فيما يريد كسرعة النبل"},{"id":"diwan-abutammam:349","bookId":"diwan-abutammam","type":"poem","seq":349,"chapter":"البحر: سريع","title":"معتدل لم يعتدل عدله","page":"","text":"معتدل لم يعتدل عدله … في عاشق طال به خبله\nأطرفه أحسن أم ظرفه … أو وجهه أحسن أم عقله ؟\nأنظر فما عاينت في غيه … من حسن فهو له كله\nلو قيل للحسن تمنى المنى … إذن تمنى أنه مثله\nأي خصال حازها سيدي … لو لم يكدر صفوها مطله ؟ !"},{"id":"diwan-abutammam:350","bookId":"diwan-abutammam","type":"poem","seq":350,"chapter":"قصائد","title":"بؤس قلبي كيف ذلا","page":"","text":"بؤس قلبي كيف ذلا … صار للسقم محلا ؟ !\nلم أكن أخشى الذي كا … ن وقد كنت مخلى\nذبت حتى ما أرى لي … في مراة الشمس ظلا\nصفح الله لمن يظ … لمني عما استحلا !"},{"id":"diwan-abutammam:351","bookId":"diwan-abutammam","type":"poem","seq":351,"chapter":"البحر: مخلع البسيط","title":"يا سقم الجفن من حبيبي","page":"","text":"يا سقم الجفن من حبيبي … ألبسني حلة السقام !\nكم قتلت لحظتاك ظلما … من عاشق القلب مستهام !\nيا من بعنيه لي غرام … قرب من مهجتي حمامي\nقد رويت من دمي فحسبي … من صائب النبل والسهام !"},{"id":"diwan-abutammam:352","bookId":"diwan-abutammam","type":"poem","seq":352,"chapter":"البحر: طويل","title":"يترجم طرفي عن لساني بسره","page":"","text":"يترجم طرفي عن لساني بسره … فيظهر من وجدي الذي كنت أكتم\nأليس عجيبا أن بيتا يضمني … وإياك لا نخلو ولا نتكلم ؟ !\nإشارة أفواه وغمز حواجب … وتكسير أبصار وطرف يسلم\nوألسننا ممنوعة من مرادنا … وأبصارنا عنا تجيب وتفهم !"},{"id":"diwan-abutammam:353","bookId":"diwan-abutammam","type":"poem","seq":353,"chapter":"البحر: خفيف تام","title":"كيف بعدي لا ذقتم البين أنتم","page":"","text":"كيف بعدي لا ذقتم البين أنتم … خبروني مذ بنت عنكم وبنتم !\nأعلى ما عهدت أم غيرتكم … نكبات الدهر الخؤون فخنتم\nيا منى النفس إن قلبي وإن با … ن بي البين عندكم حيث كنتم"},{"id":"diwan-abutammam:354","bookId":"diwan-abutammam","type":"poem","seq":354,"chapter":"البحر: طويل","title":"سلام على من لا يرد سلامي","page":"","text":"سلام على من لا يرد سلامي … ومن لا يراني موضعا لكلام\nوماذا عليه أن يجيب مسلما … ليس يقضى بالسلام ذمامي"},{"id":"diwan-abutammam:355","bookId":"diwan-abutammam","type":"poem","seq":355,"chapter":"البحر: بسيط تام","title":"أعطيت من نفحات الحسن أسناها","page":"","text":"أعطيت من نفحات الحسن أسناها … وفقت من نفحات الطيب أذكاها\nفالحسن مطرح والطيب مفتضح … والحور أصبحت بعد الله موالاها\nمن كان لم ير شمسا من سنا بشر … فإننا بعلي قد رأيناها"},{"id":"diwan-abutammam:356","bookId":"diwan-abutammam","type":"poem","seq":356,"chapter":"البحر: وافر تام","title":"إذا جاريت في خلق دنيئا","page":"","text":"إذا جاريت في خلق دنيئا … فأنت ومن تجاريه سواء\nرأيت الحر يجتنب المخازي … ويحميه عن الغدر الوفاء\nوما من شدة إلا سيأتي … لها من بعد شدتها رخاء\nلقد جربت هذا الدهر حتى … أفادتني التجارب والعناء\nإذا ما رأس أهل البيت ولى … بدا لهم من الناس الجفاء\nيعيش المرء ما استحيى بخير … ويبقى العود ما بقي اللحاء\nفلا والله ما في العيش خير … ولا الدنيا إذا ذهب الحياء\nإذا لم تخش عاقبة الليالي … ولم تستحي فافعل ما تشاء\nلئيم الفعل من قوم كرام … له من بينهم أبدا عواء"},{"id":"diwan-abutammam:357","bookId":"diwan-abutammam","type":"poem","seq":357,"chapter":"البحر: كامل تام","title":"أعتيب يا ابن الفعلة اللخناء","page":"","text":"أعتيب يا ابن الفعلة اللخناء … أأمنت من بذخي ومن غلوائي ؟\nفبحرمة الغرمول في استك إنه … قسم له حق على البغاء\nدعواك في كلب أعم فضيحة … وأخص أم دعواك في الشعراء ؟\nعجبا لصياد الهجاء بعرضه … وحر امه أبدا على الإعراء ؟ !\nما شعره كفأ لشعري فليمت … غيظا ولا الخلقي من أكفائي\nأنى يفوت مخالبي في بلدة … أرضي بها مبسوطة وسمائي\nوكهول كهلان وحيا حمير … كالسيل قدامي معا وورائي\nفألاك أعمامي الذين تعمموا … بالمكرمات وهذه آبائي !"},{"id":"diwan-abutammam:358","bookId":"diwan-abutammam","type":"poem","seq":358,"chapter":"البحر: كامل تام","title":"نبئت عتبة شاعر الغوغاء","page":"","text":"نبئت عتبة شاعر الغوغاء … قد ضج من عودي ومن إبدائي\nلما غضبت على القريض هجوته … وجعلت خلقته هجاء هجائي\nما كان جهلك تاركا لك غيه … حتى تكون دجاجة الرقاء\nحلمي عن الحلماء غير مكدر … والحتف في سفهي على السفهاء\nأضعف بمن أمسى وأصبح أمره … تبعا لأمر الدودة الشعراء !\nإني لأعجب من أناس صوروا … صور الرجال لهم فروج نساء !\nالله يعلم أنها لمصيبة … نزلت ولا سيما على الشعراء\nما الشمس أعجب حين تطلع للورى … غربية من شاعر بغاء\nإن كنت لست بمنته عن بذلها … فأنا أحق بها من الغرباء !"},{"id":"diwan-abutammam:359","bookId":"diwan-abutammam","type":"poem","seq":359,"chapter":"البحر: خفيف تام","title":"قل لعبدون أين ذاك الحياء","page":"","text":"قل لعبدون أين ذاك الحياء … إن داء المجون داء عياء !\nطالما كنت قبل عندي منيعا … ومصونا كما يصان الرداء\nثم كشحتني على غير جرم … فأنا والمباركي سواء\nقال لي الناصحون وهو مقال : … ذم من كان خاملا إطراء\nصدقوا ، في الهجاء رفعة أقوا … م طغام فليس عندي هجاء"},{"id":"diwan-abutammam:360","bookId":"diwan-abutammam","type":"poem","seq":360,"chapter":"البحر: وافر تام","title":"أعتبة أجبن الثقلين عتبا","page":"","text":"أعتبة أجبن الثقلين عتبا … بجهلك صرت للمكروه نصبا\nرميت بمن لو أن الجن ترمى … به لتنهبتها الإنس نهبا\nفإنك إن تساجلني تجدني … لرأسك جندلا ولفيك تربا\nتجد صلا تخال بكل عضو … له من شدة الحركات قلبا\nأخا الفلوات قد أحيا وأردى … ركابا في صحاصحها وركبا\nفكاد بأن يرى للشرق شرقا … وكاد بأن يرى للغرب غربا\nوأنت تدير قطب رحا عليا … ولم تر للرحا العلياء قطبا\nترى ظفرا بكل صراع قرن … إذا ما كنت أسفل منه جنبا\nثكلت قصائدي إن مر يوم … ولما أقض فيه منك نحبا\nوكنت إذن كأنت فإن مثلي … إذا ما كان مثلك كان كلبا"},{"id":"diwan-abutammam:361","bookId":"diwan-abutammam","type":"poem","seq":361,"chapter":"البحر: منسرح","title":"شعري ، أنى هربت في الطلب","page":"","text":"شعري ، أنى هربت في الطلب … ولو صعدت السماء في سبب\nيا ابن أبي عاصم ولا عاصم … ويلك من سطوتي ومن غضبي\nلو كنت من غرة الموالي إذن … لم تنث سوءا في غرة العرب\nأي كريم يرضى بشتم بني … عبد الكريم الجحاجح النجب\nأي مناد إلى الندى وإلى الهي … جاء ناداهم فلم يجب ؟\nأي فتى منهم أشاح فلم … يصب غداة الوغى ولم يصب ؟\nأي وليد رأى سيوفهم … في الحرب مشهورة فلم يشب ؟\nإن رمت تصديق ذاك يا أعور ال … دجال فالحظهم ولا تذب\nلن يهدم الناس ما بقواأ بدا … ما قد بنوه من ذلك الحسب\nألاك زهر النجوم ليس كمن … أمس دعيا في الشعر والنسب"},{"id":"diwan-abutammam:362","bookId":"diwan-abutammam","type":"poem","seq":362,"chapter":"البحر: خفيف تام","title":"من بنو عامر من ابن الحباب","page":"","text":"من بنو عامر من ابن الحباب … من بنو تغلب غداة الكلاب ؟\nمن طفيل من عامر ومن الحا … ث أم من عتيبة ابن شهاب !\nإنما الضيغم الهصور أبو الأش … بال مناع كل خيس وغاب\nمن غدت خيله على سرح شعري … وهو للحين راتع في كتابي\nغارة أسخنت عيون المعاني … واستحلت محارم الآداب\nلو ترى منطقي أسيرا لأصبح … ت أسيرا لعبرة واكتئاب\nيا عذارى الكلام صرتن من بع … دي سبايا تبعن في الأعراب !\nعبقات بالسمع تبدي وجوها … كوجوه الكواعب الأتراب\nقد جرى في متونهن من الإف … رند ماء نظير ماء الشباب\nإن ذمي محمد بن يزيد … في الذي ناله لغير صواب\nدعه يحظى لدى الأنام بشعري … وقصيدي فذاك أهون باب"},{"id":"diwan-abutammam:363","bookId":"diwan-abutammam","type":"poem","seq":363,"chapter":"البحر: طويل","title":"أما والذي غشى المبارك خزية","page":"","text":"أما والذي غشى المبارك خزية … يغني على الأيام ركب بها ركبا\nلقد ظل مقران يحك بعرضه … قوافي شعر لو تدبرها جربا\nإذا ما عصت من رامها وسما لها … أطاعت فتى عضبا يسوس حجا عضبا\nرجا أن ينجيه خساسة قدره … ولم يدر أن الليث يفترس الكلبا\nأمقران كم قرن لقيت بمشهد … فكان به رفعا وكنت به نصبا !\nتراه إذا ما جئته متهللا … إليك ومسرورا كأن قد رأى زبا\nغليظ مجاري فكره لو ضربته … على ما بدا لي منه لم يفهم الضربا\nإذا كان وجه المرء يبسا فإنه … يقاسي عجانا لا امتراء به رطبا"},{"id":"diwan-abutammam:364","bookId":"diwan-abutammam","type":"poem","seq":364,"chapter":"البحر: كامل تام","title":"فاض اللثام وغاضت الأحساب","page":"","text":"فاض اللثام وغاضت الأحساب … واجتثت العلياء والآداب\nفكأن يوم البعث فاجأهم فلا … أنساب بينهم ولا أسباب\nأمويس لا يغني اعتذارك طالبا … عفوي فما بعد العتاب عقاب\nهب من له شيء يريد حجابه … ما بال لا شيء عليه حجاب ؟ !\nما إن سمعت ولا أراني سامعا … أبدا بصحراء عليها باب ! !\nمن كان مفقود الحياء فوجهه … من غيربواب له بواب\nمازال وسواسي لعقلي خادعا … حتى رجا مطرا وليس سحاب\nما كنت أدري لا دريت - بأنه … يجري بأفنية البيوت سراب\nعجبا لقوم يسمعون مدائحي … لك لم يقولوا قم فأنت مصاب\nنبذوا بكذاب مسيلمة فقد … وهموا وجاروا بل أنا الكذاب\nهتكت ديني فاستترت بتوبة … فأناالمقر بذنبه التواب !"},{"id":"diwan-abutammam:365","bookId":"diwan-abutammam","type":"poem","seq":365,"chapter":"البحر: بسيط تام","title":"النار والعار والمكروه والعطب","page":"","text":"النار والعار والمكروه والعطب … والقتل والصلب والمران والخشب\nأحلى وأعذب من سيب تجود به … ولن تجود به يا كلب يا كلب !\nأشكيتموني فلما أن شكوتكم … غضبتم دام ذاك السخط والغضب\nبني لهيعة ما بالي وبالكم … وفي البلاد مناديح ومضطرب ؟\nلجاجة بي فيكم ليس يشبهها … إلا لجاجتكم في أنكم عرب !\nكذبتم ، ليس ينبو من له حسب … ومن له أدب عمن له أدب\nإني لذو عجب منه أكرره … فيكم ، وفي عجبي من لومكم عجب\nعياش مالك في أكرومة أرب … ولا لأكرومة في ساقط أرب\nيا أكثر الناس وعدا حشوه خلف … وأكثر الناس قولا كله كذب\nظللت تنتهب الدنيا وزخرفها … وظل عرضك عرض السوء ينتهب !"},{"id":"diwan-abutammam:366","bookId":"diwan-abutammam","type":"poem","seq":366,"chapter":"البحر: وافر تام","title":"أيوسف جئت بالعجب العجيب","page":"","text":"أيوسف جئت بالعجب العجيب … تركت الناس في شك مريب\nسمعت بكل داهية نآد … ولم أسمع بسراج أديب !\nأما لو أن جهلك كان علما … إذن لنفذت في علم الغيوب !\nوما لك بالغريب يد ولكن … تعاطيك الغريب هو الغريب\nفلو نبش المقابر عن زهير … لصرح بالعويل وبالنحيب\nمتى كانت قوافيه عيالا … على تفسير بقراط الطبيب ؟ !\nوكيف ولم يزل للشعر ماء … يرف عليه ريحان القلوب !\nتزحزح عن بعيد العقل حتى … توجه أن توجه في القريب\nأرى ظلميك إنصافا وعدلا … وذنبي فيك تكفير الذنوب !"},{"id":"diwan-abutammam:367","bookId":"diwan-abutammam","type":"poem","seq":367,"chapter":"البحر: كامل تام","title":"أنضيت في هذا الأنام تجاربي","page":"","text":"أنضيت في هذا الأنام تجاربي … وبلوتهم بمفحصات مذاهبي\nوذملت في الأيام حتى أسحتت … شطي سنامي وانتحت في غاربي\nمتجشما سبل المطامح طالبا … منها وفيها شأو رزق الغالب\nأمراي من خير وشر فاعلمي … طوقان في عنق القضاء الغالب\nلينل عدو من عدو إنما … يعفو ويصفح صاحب عن صاحب\nغاب الهجاء فآب فيك بديعه … فتهن يا موسى قدوم الغائب !\nلا تدهشني بالحجاب فإنني … فطن البديهة عالم بمواربي\nلاتكلفن وأرض وجهك صخرة … في غير منفعة مؤونة حاجب\nما كنت أول آخر في قدره … أثرى فقصر قدر حق واجب\nلا شاهدا أخزى لجاحد لؤمه … من أن تراه زاهدا في راغب\nخذ من غدي الجائي بخزيك ضعف ما … أعطيتني في صدر أمس الذاهب\nفلاتحفن السفر فيك بشرد … أنس يقمن مقام زاد الركب\nوزعمت أنك معطبي ومسلم … مني فأيري في حر أم الكاذب !"},{"id":"diwan-abutammam:368","bookId":"diwan-abutammam","type":"poem","seq":368,"chapter":"قصائد","title":"إمرأة مقران ماتت بعد ما شابا","page":"","text":"إمرأة مقران ماتت بعد ما شابا … فحست السلع الفتيان والصابا\nلم يبق خلق بباب الشام نعرفه … بالفتك مذ هلكت إلا وقد تابا ! !\nيا نكبة هشمت أنف السرور به … وميتة أبقت العزاب عزابا !"},{"id":"diwan-abutammam:369","bookId":"diwan-abutammam","type":"poem","seq":369,"chapter":"البحر: كامل تام","title":"صحبي قفوا مليتكم صحبا","page":"","text":"صحبي قفوا مليتكم صحبا … فاقضوا لنا من ربعها نحبا\nدار كأن يد الزمان بأن … واع البلى نشرت بها كتبا\nأين الأولى ؟ كانوا بعقوتها … والدهر يسكب ماء ه سكبا ؟\nإذ فيه كل خريدة فنق … عذر الفتى إن هام أو حبا\nفرغ الوشاح بها وقد ملأت … منها الشوى الخلخال والقلبا\nوإذا تهادت خلتها غصنا … لدنا تلاعبه الصبا رطبا\nنصبت له البلوى منعمة … جعلت لناظر عينه نصبا\nقصدت له قبل الفراق فما … أبقت له كبدا ولا قلبا\nقل للجلودي الذي يده … ذهبت بمال جنوده شعبا\nالله أعطاك الهزيمة إذ … جذبتك أسباب الردى جذبا\nلاقيت أبطالا تحث إلى … ضنك المقام شوازبا قبا\nفنزلت بين ظهورهم أشرا … فقروك ثم الطعن والضربا\nضيفا ولكن لا أقول له … أهلا بمثواه ولا رحبا\nفي حيث تلقى الرمح يشرع في … نطف الكلى والمرهف الغضبا\nوالخيل سانحة وبارحة … والموت يغشى الشرق والغربا\nوالبيض تلمع في أكفهم … رأد الضحى فتخالها شهبا\nثم انثنت عيناك قد رأتا … أمرا فأودعت الحشا رعبا\nوشغلت عن دبغ الجلود بما … نشر البلاء وجلل الخطبا\nوافتك خيل لو صبرت لها … لنهبن روحك في الوغا نهبا\nهيهات لما أن بصرت بهم … أغشوك ثوب الجهد والكربا\nوحسبتهم أسدا أساود أو … إبلا تصول قرومها جربا\nمن حي عدنان وأخوتهم … قحطان لا ميلا ولا نكبا\nورأيت مركب ما أردت بهم … صعبا ومغمز عودهم صلبا\nورميت طرفك ناظرا فرأى … في كل أرض موقدا حربا\nوعصمت بالليل البهيم وقد … ألقى عليك ظلامه حجبا\nفسريت تغشى البيد مجتزعا … بالعيس منها الحزم والسهبا\nوتركت جندك للقنا جزرا … والبيض تجذب هامهم جذبا\nقتلا وأسرا في الحديد معا … يتوقعون القتل والصلبا\nفأشكر أيادي ليلة سمحت … لك بالبقاء وركبها ركبا\nبل لا تؤدي شكرها أبدا … حتى تصيرها لكم ربا"},{"id":"diwan-abutammam:370","bookId":"diwan-abutammam","type":"poem","seq":370,"chapter":"البحر: سريع","title":"أول عدل منك فيما أرى","page":"","text":"أول عدل منك فيما أرى … أنك لا تقبل قول الكذب\nمدحتكم كذبا فجازيتني … بخلا لقد أنصفت يا مطلب"},{"id":"diwan-abutammam:371","bookId":"diwan-abutammam","type":"poem","seq":371,"chapter":"البحر: وافر تام","title":"أعبد الله دع لوا وليتا","page":"","text":"أعبد الله دع لوا وليتا … فقد أصبحت يا مسكين ميتا\nوكنت بخلتين تدل حتى … رميت من السماء كما رميتا\nبلين مرة وبقدر عون … فسود وجه عون وأطليتا\nفأنت اليوم في خزي عظيم … فكيف غدا تكون إذا التحيتا"},{"id":"diwan-abutammam:372","bookId":"diwan-abutammam","type":"poem","seq":372,"chapter":"البحر: كامل تام","title":"يا زوجة المسكين مقران التي","page":"","text":"يا زوجة المسكين مقران التي … عظمت على المتطرقين وفاتها\nخلت القبور بظبية عهدي بها … فيما يقال لذيذة خلواتها !\nتركت على المسكين عدة صبية … مثل الفراخ تخرمت أماتها\nلو كان أحصن بابه أو داره … قلت بنوها عنده وبناتها !\nإن البلاد إذا السيول تعاودت … ساحاتها غمر الفضاء نباتها !\nمتناوم إن زارها إخوانها … متيقظ إن زارها أخواتها !\nإمراته نفذت عليه أمورها … حتى ظننا أنه إمراتها !"},{"id":"diwan-abutammam:373","bookId":"diwan-abutammam","type":"poem","seq":373,"chapter":"البحر: كامل تام","title":"أمسك بل استمسك لوقع هياجي","page":"","text":"أمسك بل استمسك لوقع هياجي … فلتسأمن عذوبتي وأجاجي !\nدع ما مضى واستأنف العدد الذي … ضيعته يا محصي الأمواج\nفلقد أجمت عداوتي ممزوجة … ولأسعطنكها بغير مزاج\nيا ابن الخبيثة لا تعرض صخرة … صماء من مجدي بعرض زجاج\nأصبحت ني العقل فاصل بميسم … يبدي ألج الناس في الإنضاج\nما إن سمعت ولا أراني سامعا … حتى الممات بشاعر سراج\nمن كان توج رأسه فليوسف … شعب يقمن له مقام التاج\nحرن الزمان به فهملج كشحه … مس شركة في البغلة الهملاج\nللمرء في القرآن أربع نسوة … ولتلك أربعة من الأزواج !\nبيضاء في بيض يطفن بأسود … في سود غافق محصدي الأثباج\nما إن تزال لهم مراود ساسم … متغلغلات في مكاحل عاج !"},{"id":"diwan-abutammam:374","bookId":"diwan-abutammam","type":"poem","seq":374,"chapter":"البحر: وافر تام","title":"حجى لحمى البطالة مستبيح","page":"","text":"حجى لحمى البطالة مستبيح … وقدر للمكارم مستميح\nفلا قلب قريح قلبته … نوى قذف ولا جفن قريح\nولكن همة شطط وهم … به في المجد يغدو أو يروح\nسأعتب عتبة بمقفيات … سواء هن والصاب الجديح\nتبيت سوائرا وتظل تتلى … قصائدها كما تتلى الفتوح\nبنو عبد الكريم نجوم عز … ترى في طيء أبدا تلوح\nفلا حسب صحيح أنت فيه … فتكثرهم ولا عقل صحيح\nإذا كان الهجاء لهم ثوابا … فأخبرني لمن خلق المديح ؟\nأتبغض جوهر العرب المصفى … ولم يبغضهم مولى صريح\nوما لك حيلة فيهم فتجدي … عليك بلى تموت فتستريح"},{"id":"diwan-abutammam:375","bookId":"diwan-abutammam","type":"poem","seq":375,"chapter":"البحر: خفيف تام","title":"أي رأي وأي عقل صحيح","page":"","text":"أي رأي وأي عقل صحيح … لم يخوفك سانحي وبريحي ؟ !\nكذبت نفسك التي حدثت أنيم … أنمي رميتي وجريحي\nخلق الله لحية لك لو تح … لق لم يدر ماغلاء المسوح !\nوذراهافي الريح إن كنت ترجو … سير شعري في نعتها بالريح\nسار في التيه عقل من ظن أني … بالأماني يسير فيك مديحي\nياحرونا في البخل قد وأبي بخ … لك عوقبت بالأصم الجموح\nببعيدالمدى قريب المعاني … وثقيل الحجى خفيف الروح\nسجرت كفه بحور القوافي … لك عند التعريض والتصريح\nلحجى لست سالما من تعالي … ها ولو كنت في سفينة نوح"},{"id":"diwan-abutammam:376","bookId":"diwan-abutammam","type":"poem","seq":376,"chapter":"البحر: خفيف تام","title":"يا ابن تلك التي بحران لما","page":"","text":"يا ابن تلك التي بحران لما … نبتت أنبتت غصون السفاح\nلا تهولنك الكباش فقد أع … طيت ما شئت من أداة النطاح !\nجدت بالدبر والعجوز بقبل … فهنيئا ذهبتما بالسماح !\nبخ بخ لم يدان جودك يا أز … هر كعب ولا مباري الرياح\nكذت تدعى لو أن خلفك قدا … مك في الحرب يا حديا الرماح\nسوء ظني أجارني من هواه … فجعلت الطلاق قبل النكاح"},{"id":"diwan-abutammam:377","bookId":"diwan-abutammam","type":"poem","seq":377,"chapter":"البحر: بسيط تام","title":"قلبت أمري في بدء وفي عقب","page":"","text":"قلبت أمري في بدء وفي عقب … ورضت حالي في جور ومقتصد\nفما فتحت فمي إلا كعمت فمي … ولا مددت يدي إلا رددت يدي !\nلا ذنب لي غير ما سيرت من غرر … شرقا وغربا وما أحكمت من عقدي\nنشر يسير به شعر يهذبه … فكر يجول مجال الروح في الجسد\nساعات شكر غذاهن البقاء به … فهن أطول أعمارا من الأبد !\nإذا دجاها أحاطت بي أحطت بها … قلبا متى أسر في مصباحه يقد\nحضرمت دهري وأشكالي لكم وبكم … حتى بقيت كأني لست من أدد\nثم أطرحتم قراباتي وآصرتي … حتى توهمت أني من بني أسد !\nثم انصرفت إلى نفسي لأظأرها … على سواكم فلم تهشش إلى أحد\nومدح من ليس أهل المدح أحسبه … عضوا تفضل من قلبي ومن كبدي\nقوم إذا أعين الآمال جثنهم … رجعن مكتحلات عائر الرمد !\nفطلعة الشعر أقلى في عيونهم … وفي صدرهم من طلعة الأسد\nما إن ترى غير منشور على قدم … في الناطقين ومطوي على حسد\nقل قولة فيصلا تمضي حكومتها … في المنع إن عن لي منع أو الصفد\nيحصن بها سندي أو يمتنع عضدي … أو يدن لي أمدي أو يعتدل أودي\nأو التي طالما أفضت وعورتها … من الأمورإلى منهاجها الجدد\nإن كنت في المطل ذا صبر وذا جلد … فلست في الذم ذا صبر وذا جلد !\nفقل وراءك في سحق وفي بعد … فإنني فيك أهل السحق والبعد"},{"id":"diwan-abutammam:378","bookId":"diwan-abutammam","type":"poem","seq":378,"chapter":"البحر: بسيط تام","title":"نبئت عتبة يعوي كي أشاتمه","page":"","text":"نبئت عتبة يعوي كي أشاتمه … الله أكبر أنى استأسد النقد !\nما كنت أحسب أن الدهر يمهلني … حتى أرى أحدا يهجوه لا أحد !\nبحسب عتبة داء قد تضمنه … لو كان في أسد لم يفرس الأسد\nلو اعتدى أعوج يعدو به المرطى … أو لاحق لتمنى أنه وتد !\nلو كان يكره أن تبدو فضيحته … ما كان أكثر ما في شعره العمد\nفإن سمعت له نعت القنا عبثا … فقد أراد قنا ليست لها عقد !\nإني لأعجب ممن في حقيبته … من المني بحور كيف لا يلد ؟\nلو أن عشر الذي أمسى وظل به … بالعالمين من البلوى إذن فسدوا\nلا يدعون على الأعداء مجتهدا … إلا بأن يجدوا بعض الذي يجد !\nوقائل مالهم يغضون عنك إذا … أتأرت قلت له إني أنا الرمد\nأنا الحسام أنا الموت الزؤام أنا ال … نار الضرام أنا الضرغامة العبد"},{"id":"diwan-abutammam:379","bookId":"diwan-abutammam","type":"poem","seq":379,"chapter":"البحر: كامل تام","title":"الآن لما صار حوض الوارد","page":"","text":"الآن لما صار حوض الوارد … وغدا وأصبح عرضة للرائد\nدست إليه الحادثات تحية … فيها صلاح للغلام الفاسد ؟ !\nفاليوم عوض فرحة من ترحة … واليوم بدل راحما من حاسد\nجعل الكتابة للإجارة سترة … واعتل ثم أتى بعذر بارد\nفإذا تشاغل بالحديث فقل له … دع ذا أتعرف درب عبد الواحد ؟ !"},{"id":"diwan-abutammam:380","bookId":"diwan-abutammam","type":"poem","seq":380,"chapter":"البحر: كامل تام","title":"عياش يا ذا البخل والتصريد","page":"","text":"عياش يا ذا البخل والتصريد … وسلالة التضييق والتنكيد\nالبرد يقتل والكزاز بدون ما … أحكمته من شدة التبريد\nلؤم تدين بحلوه وبمره … فكأنه جزء من التوحيد\nليسودن يفاع وجهك منطقي … أضعاف ما سودت وجه قصيدي\nوليفضحنك في المحافل كلها … صدري كما فضحت يداك ورودي\nما كان خبرني القياس بباطل … عنكم ولكن جرت في التقليد !\nفطرحت في طمعي يدا أخرجتها … من طاعة التوفيق والتسديد\nورجوت نائلكم رجاءكم العلا … بتذكر العلجان واليعضيد\nونسيت سوء فعالكم نسيانكم … آساسكم في كورة البشرود !"},{"id":"diwan-abutammam:381","bookId":"diwan-abutammam","type":"poem","seq":381,"chapter":"البحر: كامل تام","title":"عياش زف إليك جهد جاهد","page":"","text":"عياش زف إليك جهد جاهد … واحتل ساحتك البلاء الراكد\nما اللؤم لؤما إن عداك لبانه … وعدوته ولهيعة لك والد !\nألف الهجاء فما يبالي عرضه … أهجاه ألف أم هجاه واحد\nسمجت بك الدنيا فما لك حامد … وسمجت بالدنيا فما لك حاسد !\nلأنكلنك أن تكون لشاعر … من بعدها غرضا وأصلك فاسد\nولأشهرن عليك شنع أوابد … يحسبن أسيافا وهن قصائد\nفيها لأعناق اللئام جوامع … تبقى وأعناق الكرام قلائد\nيلزمن عرض قفاك وسم خزاية … لم يخزها بأبي عيينة خالد\nوالله يعلم أن شعرا شابه … فيك الهجاء أو المديح لكاسد\nفالبس ثياب فضائح أسديتها … أشرا وألحمها أخوك البارد"},{"id":"diwan-abutammam:382","bookId":"diwan-abutammam","type":"poem","seq":382,"chapter":"البحر: مجتث","title":"أتيت يحيى وقد كا","page":"","text":"أتيت يحيى وقد كا … ن لي صديقا وودا\nفقلت ما بال هذا ال … فتى اشمأز وصدا ؟\nفارتد مني ارتدا … د الأسير عاين قدا\nفقال لي : ذو مزاح … يصير الهزل جدا\nكذا الكريم إذا ما … أراد أن يتغذى !"},{"id":"diwan-abutammam:383","bookId":"diwan-abutammam","type":"poem","seq":383,"chapter":"البحر: بسيط تام","title":"أفي تنظم قول الزور والفند","page":"","text":"أفي تنظم قول الزور والفند … وأنت أنزر من لا شيء في العدد ؟\nأشرجت قلبك من بغضي على حرق … أضر من حرقات الهجر في الجسد\nأنحفت جسمك حتى لو هممت بأن … ألهوا بصفعك يوما لم تجدك يدي !\nلا تنتسب قد حويت الفخر مجتمعا … والذكر إذ صرت منسوبا إلى حسدي\nأطلت روعك حتى صرت لي غرضا … قد يقدم العير من ذعر على الأسد !"},{"id":"diwan-abutammam:384","bookId":"diwan-abutammam","type":"poem","seq":384,"chapter":"البحر: سريع","title":"ما أنت إلا المثل السائر","page":"","text":"ما أنت إلا المثل السائر … يعرفه الجاهل والخابر\nفاكهة ضيع بستانها … فانتابها الوارد والصادر\nيا ساحر اللفظ على أن من … أغراك باللفظ هو الساحر !\nذئب فلاة كيده دارع … صادف ظبيا كيده حاسر\nإذا تذكرتك ذكرتني … قد ذل من ليس له ناصر !"},{"id":"diwan-abutammam:385","bookId":"diwan-abutammam","type":"poem","seq":385,"chapter":"البحر: كامل تام","title":"رحلت فغير دموعي الدرر","page":"","text":"رحلت فغير دموعي الدرر … ولغيري الأحزان والفكر\nلو تكشفون نقابها سبقت … منكم إلي ببينها البشر\nأنا مجمل لكم سماجتها … وجه ابن أعمش عندها قمر\nومبين لكم غثاثتها … لفظ ابن أعمش عندها سمر !"},{"id":"diwan-abutammam:386","bookId":"diwan-abutammam","type":"poem","seq":386,"chapter":"البحر: كامل تام","title":"أبو تماملا تعجلن عليك بعد نهار","page":"","text":"أبو تماملا تعجلن عليك بعد نهار … وغدا إليك تجهز الأشعار\nترك اللئيم ولم يمزق عرضه … نقص على الرجل الكريم وعار\nأشرعت في بحر الجهالة سادرا … والجهل في بعض الهنات عقار\nفاشرب فإنك سوف تعلم أنه … قدح يصيب العرض منه خمار\nغاداك مختار الكلام بشرد … عون القصيد حتوفها أبكار\nصخر يفيتك مسمعيك كليهما … حتى ترى أن الأذان سرار\nشعر مقيل السم فيه ولم يقع … قسط يديثه ولا أظفار\nغرر متى ماشئت كن شواهدي … أن لم يكن لك والد عطار\nلا تحسبن أني خففت لهفوة … والخفة الهفواء فيك وقار\nإثنان ليسا يؤمنان بحدة … أنا حين تحرق سخطتي والنار"},{"id":"diwan-abutammam:387","bookId":"diwan-abutammam","type":"poem","seq":387,"chapter":"البحر: كامل تام","title":"إني على ما نالني لصبور","page":"","text":"إني على ما نالني لصبور … وبغير حسن تجلد لجدير\nأعزز بعياش علي مغيبا … في غير حفرته الحجى والخير\nفكت أكف الموت غل قصائدي … مسه وضيغمها عليه يزير\nما زال غل الذم ثاني عطفه … حتى أتاه الموت وهو أسير\nمن بعد ما نزهت في سوآته … حسنات شعر بحرهن بحور\nوبقيت لولا أنني في طيىء … علم لقال الناس أنت جرير\nياعبرة الله التي من طرزها … نشأوا فكانا القرد والخنزير\nلو كان للجمل المجلل ريشة … ما شك خلق أنه سيطير\nوأرى نكيرا صد عنك ومنكرا … ظنا بأنك منكر ونكير\nوتضور القبر الذي أسكنته … حتى ظننا أنه المقبور"},{"id":"diwan-abutammam:388","bookId":"diwan-abutammam","type":"poem","seq":388,"chapter":"البحر: سريع","title":"لا سقيت أطلالك الداثره","page":"","text":"لا سقيت أطلالك الداثره … ولا انقضت عثرتك العاثره\nما حفرة واراك ملحودها … بنزرة الرجس ولا طاهره\nما قبلت شركك يوما ولا … كفرك إلا أنها كافره\nكرت على البخل بما ساءه … وناءه كرتك الخاسره\nأسهرت عين اللؤم منذ انطوت … عليك اثوابك بالساهره\nفيمن يشن الشعر غاراته … بعدك أو أمثاله السائره ؟\nقد كانت الدنيا شفت لوعتي … منك ولكن عذت بالآخره !\nيا أسد الموت تخلصته … من بين لحيي أسد القاصره\nأجارك المكروه من مثله … فاقرة نجتك من فاقره"},{"id":"diwan-abutammam:389","bookId":"diwan-abutammam","type":"poem","seq":389,"chapter":"البحر: بسيط تام","title":"يا أكرم الناس آباء ومفتخرا","page":"","text":"يا أكرم الناس آباء ومفتخرا … وألام الناس مبلوا ومختبرا"},{"id":"diwan-abutammam:390","bookId":"diwan-abutammam","type":"poem","seq":390,"chapter":"البحر: خفيف تام","title":"إن عبدون أرضه ممطوره","page":"","text":"إن عبدون أرضه ممطوره … فهي طوع نباتها وضروره\nسهل الأمر إذ توعر بالشع … ر فجاءت سهولة ووعوره\nأعمل النتف واطلى وقديما … كان صعبا أن تشعب القاروره\nلا تقاتل كتائب الشعر الأس … تود جهلا فإنها منصوره\nليس تغني شيئا ولو كنت قارو … ن الغنى واشتريت درب النوره"},{"id":"diwan-abutammam:391","bookId":"diwan-abutammam","type":"poem","seq":391,"chapter":"البحر: وافر تام","title":"مضى ما كان قبل من الدعاره","page":"","text":"مضى ما كان قبل من الدعاره … فبان وأطفئت تلك الحراره\nوأصبح وجهك المعشوق عفى … على ديباجه برد الإجاره\nوكان أرق وجه ثم أضحى … يكاد بأن ترص به الحجاره !\nوهل يبقى لثوب الصدق ماء … إذا أدمنت فيه على القصاره ؟\nتجرت بعين ظهرك مستعنا … بأثواب البطالة والخساره\nفأنت أحق خلق الله ألا … تضيع مع الكتابة والتجاره !"},{"id":"diwan-abutammam:392","bookId":"diwan-abutammam","type":"poem","seq":392,"chapter":"البحر: متقارب تام","title":"أعبدون قد صرت أحدوثة","page":"","text":"أعبدون قد صرت أحدوثة … يدون سائر أخبارها\nحبوت النصارى بها معلنا … لها غير كاتم أسرارها\nفقد أدركت بك في المسلمين … ما قد تقدم من ثارها\nرأيت فياشلهم لم تنل … بحد المواسي وإمرارها\nولم أدر أنك من قبلها … تحب السياط بأثمارها !"},{"id":"diwan-abutammam:393","bookId":"diwan-abutammam","type":"poem","seq":393,"chapter":"البحر: كامل تام","title":"أغزال قولي للغزال الأحور","page":"","text":"أغزال قولي للغزال الأحور … أضمرت غدرا ليس عنك بمضمر\nإذهب فلم أجزع عليك وربما … صبرت عنك حشاشة لم تصبر\nياواردا لجت به هفواته … ما كنت أول وارد لم يصدر\nظفرت بك الأيام بعد تمنع … ظفر الهموم بعاشق لم يظفر\nيا ليت شعري ضل عقلك كله … أم هذه أيام ثقب الجوهر ؟"},{"id":"diwan-abutammam:394","bookId":"diwan-abutammam","type":"poem","seq":394,"chapter":"البحر: بسيط تام","title":"صرد ونكد وزند أنت معذور","page":"","text":"صرد ونكد وزند أنت معذور … أسد الشرى ليس تنميها الخنازير\nهيهات خف إلى الغايات لاحقها … سبقا وأثقلك الحالوم والصير !\nإني بشتم امرىء أكدت خليقته … وكان باللؤم مشهورا لمعذور\nيا خلقة قد أمال الدهر أشطرها … لم يكفها من عقاب الله تغيير !\nلم يخطىء الرأي غيلان وشيعته … إن لم تكن أخطأت فيك المقادير\nأمن نسيم الهجاء انفل حدكم … فكيف لو قد علت تلك الأعاصير ؟\nأنظر إليهم كفانا الله أمرهم … أيد صخور وأعراض قوارير\nمجد تهدم حتى صار محكمه … نقضا ترم به الآطام والدور\nساحات سوء بحمد الله ميتة … فيها العلا حية فيها الزنانير !"},{"id":"diwan-abutammam:395","bookId":"diwan-abutammam","type":"poem","seq":395,"chapter":"البحر: رجز تام","title":"نعم الفتى ابن الأعمش الغث الذفر","page":"","text":"نعم الفتى ابن الأعمش الغث الذفر … لولا الحلاق والجنون والبخر\nكأنما أسنانه إذا كشر … حب من القرع مؤدر نخر\nيا حبذا أمك إمرأة البشر … وجزيت صالحة عن الكمر"},{"id":"diwan-abutammam:396","bookId":"diwan-abutammam","type":"poem","seq":396,"chapter":"البحر: كامل تام","title":"أيقنت حين نتفت أن ستكابر","page":"","text":"أيقنت حين نتفت أن ستكابر … وعلمت إذ بادلت أن ستؤاجر !\nأما النهار فأنت فيه كاتب … والليل أجمع أنت فيه تاجر !\nإن كنت تطمع أن قلبي هائم … بك أو تؤمل أنني لك ذاكر\nفأنا الذي يعطى استه من حاجة … وأبوك قوادي وأنت الشاعر !"},{"id":"diwan-abutammam:397","bookId":"diwan-abutammam","type":"poem","seq":397,"chapter":"البحر: متقارب تام","title":"أمقران يا ابن بنات العلوج","page":"","text":"أمقران يا ابن بنات العلوج … ونسل اليهود شرار البشر\nلقد صرت بين الورى عبرة … ركبت الهماليج بعد البقر\nوبدلت بالمر ذا ميعة … وما إن لسوطك فيه أثر\nيجر الخزوز وشيخ له … بنهر المبارك ما يستتر\nفقولا لمقران فيم المقام … وهذا حصادكم قد حضر ؟\nبع السيف ثم استجد منجلا … وأبدل بسوطك رفشا وسر\nإلى النار في غير حفظ الإله … غرقك الله يا منحدر !"},{"id":"diwan-abutammam:398","bookId":"diwan-abutammam","type":"poem","seq":398,"chapter":"البحر: وافر تام","title":"أعبد الله قم واقعد بهجري","page":"","text":"أعبد الله قم واقعد بهجري … فقد ألقيت من بالي وفكري\nوقد أخليت حبك من ضلوعي … وكان موشحا قلبي وصدري\nيموت مشايخ الكتاب هزلا … ورزقك أنت في الستين يجري !\nنفاقك في الخشونة عنك ينبي … بأنك تستطيل بحسن صبري\nسبقت مؤاجري بغداد جمعا … فقد أحرزت غاية كل فخر\nأولئك واجروا يوما بيوم … وأنت مؤاجر شهرا بشهر !"},{"id":"diwan-abutammam:399","bookId":"diwan-abutammam","type":"poem","seq":399,"chapter":"البحر: سريع","title":"نكست رأسي بين جلاسي","page":"","text":"نكست رأسي بين جلاسي … ونحن من ساق ومن حاسي\nكدت وأخطأت - بذكراك أن … أقتل بين الورد والآس\nيا كعب بذلا للعطايا ويا … أصفق وجها من أبي شاس\nما إن رأينا مثلها ضيعة … تكسب بالجود وبالباس\nأنسيت تأديبي وعهدي به … منك على العينين والراس !\nهذا لعمري يا أبا جعفر … جزاء من ربى بني الناس"},{"id":"diwan-abutammam:400","bookId":"diwan-abutammam","type":"poem","seq":400,"chapter":"البحر: سريع","title":"مقران يا متشعب الراس","page":"","text":"مقران يا متشعب الراس … لا تخل من هم ووسواس\nلا تقس قلبا وابك من لم يكن … على الكئيب الصب بالقاسي\nريحانة الفتيان قد أصبحت … رهن جبابين وأرماس\nوقل لها يا امرأتي هدني … فقدك بل يا امرأة الناس !"},{"id":"diwan-abutammam:401","bookId":"diwan-abutammam","type":"poem","seq":401,"chapter":"البحر: مجزوء الخفيف","title":"قد صحاالقلب بعدما","page":"","text":"قد صحاالقلب بعدما … قد يرى وهو منتشي\nلست من يلقي بوجه … للحديث المخدش\nلي من الصبر حاكم … في الهوى غير مرتشي\nكيف يصفو لك الهوى … يا سمي ابن الأعمش ؟\nيا سمي ابن سمحة … في غدو وفي عشي !"},{"id":"diwan-abutammam:402","bookId":"diwan-abutammam","type":"poem","seq":402,"chapter":"البحر: كامل تام","title":"بدلت بعد تأنس بتوحش","page":"","text":"بدلت بعد تأنس بتوحش … وأعرت سمعك من يبلغ أو يشي\nوزعمت أني ذاهل فمن الذي … يدعى خليفة عروة ومرقش\nلا مت إن كان الذي بلغته … حتى أرى في صورة ابن الأعمش !"},{"id":"diwan-abutammam:403","bookId":"diwan-abutammam","type":"poem","seq":403,"chapter":"البحر: سريع","title":"والله ابن الأعمش المبتلى","page":"","text":"والله ابن الأعمش المبتلى … في دبره بالخبث المحض\nلو يقدر المسكين مما به … لاستدخل الفيشة بالعرض\nأنت الذي يملك أضعاف ما … حواه قارون من البغض\nلتعلمن أن الردى كله … حتم على الراتع في عرضي\nلو فر شيء قط من شكله … فر إذن بعضك من بعض\nكونك في صلب أبينا آدم … هبطنا جمعا إلى الأرض !"},{"id":"diwan-abutammam:404","bookId":"diwan-abutammam","type":"poem","seq":404,"chapter":"البحر: كامل تام","title":"عثمان لا تلهج بذكر محمد","page":"","text":"عثمان لا تلهج بذكر محمد … ينهاك طول المجد عنه وعرضه\nيغتال بذلك كله إمساكه … ويفوت بسطك في المكارم قبضه\nفكأن عرضك في السهولة وجهه … وكأن وجهك في الحزونة عرضه"},{"id":"diwan-abutammam:405","bookId":"diwan-abutammam","type":"poem","seq":405,"chapter":"البحر: هزج","title":"أيا من أعرض الله","page":"","text":"أيا من أعرض الله … عن العالم من بغضه\nويا من بعضه يشه … د بالبغض على بعضه !\nويا أثقل خلق الل … ه من ماش على أرضه\nومن عاف مليك المو … ت واستقذر من قبضه"},{"id":"diwan-abutammam:406","bookId":"diwan-abutammam","type":"poem","seq":406,"chapter":"البحر: سريع","title":"ياعمرو قل للقمر الطالع","page":"","text":"ياعمرو قل للقمر الطالع … إتسع الخرق على الراقع !\nيا فتنة الناظر قد صرت في … فعلك هذا فتنة السامع\nهل أنت إلا رشأ خاذل … حل بمغنى أسد جائع ؟ !\nما كان في المخدع من أمركم … فإنه في المسجد الجامع !\nياطول فكري فيك من حامل … صحيفة مكسورة الطابع !"},{"id":"diwan-abutammam:407","bookId":"diwan-abutammam","type":"poem","seq":407,"chapter":"البحر: وافر تام","title":"أعتبة إن تطاولت الليالي","page":"","text":"أعتبة إن تطاولت الليالي … عليك فإن شعري سم ساعه\nوما وفد المشيب عليك إلا … بأخلاق الدناءة والوضاعه\nفأشهد ما جسرت علي إلا … وزيد الخيل عبدك في الشجاعه\nووجهك إذ قنعت به نديما … فأنت نسيج وحدك في القناعه\nفلو بدلته وجها إذن لم … أصل به نهارا في جماعه\nولكن قد رزقت به سلاحا … لو استعصيت ما أديت طاعه\nمناسب كلب قد قسمت فدعها … فليست مثل نسبتك المشاعه\nوروح منكبيك فقد أعيدا … حطاما من زحامك في قضاعه\nولا يغررك أوغاد تعاووا … لنصرك بالحلاق وبالرقاعه\nرأوني حيث كنت لهم عدوا … وأنت لهم شريك في الصناعه !"},{"id":"diwan-abutammam:408","bookId":"diwan-abutammam","type":"poem","seq":408,"chapter":"البحر: هزج","title":"سأهجو الوغد مقران","page":"","text":"سأهجو الوغد مقران … فلاغروولابدعا\nفتى ما إن تخلت ذا … ته من حية تسعى\nإذا ما جاعت الفيش … غدت في ذاته ترعى\nإذاماأدخلت كالبسر … فيه خرجت شمعا\nوألقاه بلطم يه … تك الأبصار والسمعا\nفإن لم يفهم الشع … ر سريعا فهم الصفعا !"},{"id":"diwan-abutammam:409","bookId":"diwan-abutammam","type":"poem","seq":409,"chapter":"البحر: كامل تام","title":"بسطت إلي بنانة أسروعا","page":"","text":"بسطت إلي بنانة أسروعا … تصف الفراق ومقلة ينبوعا\nكادت لعرفان النوى ألفاظها … من رقة الشكوى تكون دموعا\nبل صوت عاذلة عراني موهنا … عدل لعمرك لو عذلت سميعا\nأألوم من بخلت يداه واغتدى … للبخل تربا ، ساء ذاك صنيعا !\nآبى فأعصي العاذلين وأغتدي … في تالدي للسائلين مطيعا\nمتسربلا خلق المكارم إنها … جعلت لأعراض الكرام دروعا\nومحجب حاولته فوجدته … نجما على الركب العفاة شسوعا\nلما عدمت نواله أعدمته … شكري فرحنا معدمين جميعا !"},{"id":"diwan-abutammam:410","bookId":"diwan-abutammam","type":"poem","seq":410,"chapter":"البحر: متقارب تام","title":"ألم تك ريحانة الواصف","page":"","text":"ألم تك ريحانة الواصف … لمستظرف ولمستأنف ؟ !\nغريرا فآنس حالاته … إذا كان كالرشإ الخائف\nتنام مع الظهر من غرة … ومن خفر خشية الطائف ؟ !\nفبينا ضياؤك قد صانه … حياؤك إذ جئت بالجارف\nمسخت وكنت الطموح الجمو … ح في خلقة الكلبة الصارف"},{"id":"diwan-abutammam:411","bookId":"diwan-abutammam","type":"poem","seq":411,"chapter":"البحر: كامل تام","title":"الدار ناطقة وليست تنطق","page":"","text":"الدار ناطقة وليست تنطق … بدثورها أن الجديد سيخلق\nدمن تجمعت النوى في ربعها … وتفرقت فيها السحاب الفرق\nفترقرقت عيني مآقيها إلى … أن خلت مهجتي التي تترقرق\nيا سهم كيف يفيق من سكر الهوى … حران يصبح بالفراق ويغبق ؟ !\nما زال مشتمل الفؤاد على أسى … والبين مشتمل على من يعشق\nحكمت لأنفسها الليالي أنها … أبدا تفرقنا ولاتتفرق\nعمري لقد نصح الزمان وإنه … لمن العجائب ناصح لا يشفق !\nإن تلغ موعظة الحوادث بعدما … وضحت فكم من جوهر لا ينفق !\nإن العزاء وإن فتى حرم الغنى … رزق جزيل للذي لا يرزق !\nهمم الفتى في الأرض أغصان الغنى … غرست وليست كل عام تورق\nيا عتبة ابن أبي عصيم دعوة … شنعاء تصدم مسمعيك فتصعق\nأخرست إذ عاينتني حتى إذا … ما غبت عن بصري ظللت تشدق ؟ !\nوكذا اللئيم يقول إن نأت النوى … بعدوه ويحول ساعة يصدق\nعير رأى أسد العرين فهاله … حتى إذا ولى تولى ينهق !\nأو مثل راعي السوء أتلف ضأنه … ليلا وأصبح فوق نشز ينعق !\nهيهات غالك أن تنال مآثري … إست بها سعة وباع ضيق !\nوتنقل من معشر في معشر … فكأن أمك أو أباك الزئبق\nأإلى بني عبد الكريم تشاوست … عيناك ويلك خلف من تتفوق\nقوم تراهم حين يطرق معشر … يسمون للخطب الجليل فيطرق\nقوم إذا اسود الزمان توضحوا … فيه فغودر وهو منهم أبلق\nما زال في جرم بن عمرو منهم … مفتاح باب للندى لا يغلق\nما أنشئت للمكرمات سحابة … إلا ومن أيديهم تتدفق\nأنظر فحيث ترى السيوف لوامعا … أبدا ففوق رؤوسهم تتألق\nشوس إذا خفقت عقاب لوائهم … ظلت قلوب الموت منهم تخفق\nبله إذا لبسوا الحديد حسبتهم … لم يحسبوا أن المنية تخلق\nقل ما بدا لك يا ابن ترنا فالصدا … بمهذب العقيان لا يتعلق\nأفعشت حتى عبتهم قل لي متى … فرزنت سرعة ما أرى يا بيدق\nجدعا لأنف طيء إن فتها … ولوأن روحك بالسماك معلق\nإني أراك حلمت أنك سالم … من بطشهم ما كل رؤيا تصدق\nإياك يعني القائلون بقولهم … إن الشقي بكل حبل يخنق\nسر أين شئت من البلاد فإن لي … سورا عليك من الرجال يخندق\nوقبيلة يدع المتوج خوفهم … فكأنما الدنيا عليه مطبق\nوقصائدا تسري إليك كأنها … أحلام رعب أو خطوب طرق\nمن منهضاتك مقعداتك خائفا … مستوهلا حتى كأنك تطلق\nمن شاعر وقف الكلام ببابه … واكتن في كنفي ذراه المنطق\nقد ثقفت منه الشآم وسهلت … منه الحجاز ورققته المشرق"},{"id":"diwan-abutammam:412","bookId":"diwan-abutammam","type":"poem","seq":412,"chapter":"البحر: كامل تام","title":"أعلي يقدم عتبة المستحلق","page":"","text":"أعلي يقدم عتبة المستحلق … هيهات يطلب شأو من لا يلحق !\nكم خلق أير لم يكن لك ظالما … قد بات وهو بحلق جحرك يخفق !\nلو كنت تعلم يا مخنث طائلا … لعلمت أنك في هجائي أحمق\nفلتعلمن حر أم من وإهاب من … وقديم من وحديث من يتمزق !\nلججت في بحري فناك عجوزه … من كان في شك بأنك تغرق\nوالله لو ألصقت نفسك بالغرا … في كلب لاستيقنت أنك ملصق\nدع معشري لا معشر لك إنني … من خلفهم وأمامهم لك موبق\nكم نادمت أسيافنا أرماحهم … بين الجيوش على دم يترقرق\nعمي حدوك إلي أي عجيبة … أعمى دليل هدى وأخرس ينطق ؟\nقولوا فلستم ضائري وأنتم … نسل البغايا تكذبون وأصدق"},{"id":"diwan-abutammam:413","bookId":"diwan-abutammam","type":"poem","seq":413,"chapter":"البحر: منسرح","title":"لولم أكن مشبعا من الحمق","page":"","text":"لولم أكن مشبعا من الحمق … ما كنت ممن أود يا حلقي\nإياك أرضى يا ابن البغي لقد … بعد التقريب بالعنق\nإني لمستوجب من أجلك أن … تشد كلتا يدي في عنقي\nتنفر عمدا ولو قدرت إذن … حملتها للورى على طبق !\nمثل التي تنبش القبور ولا … تدنوا إلى ظلها من الفرق"},{"id":"diwan-abutammam:414","bookId":"diwan-abutammam","type":"poem","seq":414,"chapter":"البحر: خفيف تام","title":"يا هلالا غدا عليه المحاق","page":"","text":"يا هلالا غدا عليه المحاق … أين ذاك الضياء والإشراق ! !\nنال مني فيك التلاقي من الحر … قة مالم يكن ينال الفراق !\nبدل الدهر ثوب حسنك حتى … غاله بعد جدة إخلاق\nلم أزل عالما بأن ليس خلق … دام حلوا إلا وسوف يذاق !\nحجر الصبر والسلو على دم … عي ووجدي فاذهب فأنت الطلاق\nلم يسود وجه الوصال بوس … م الحب حتى تكشخن العشاق\nقد زعمنا أن السلو حظوظ … إذزعمتم أن الهوى أرزاق !"},{"id":"diwan-abutammam:415","bookId":"diwan-abutammam","type":"poem","seq":415,"chapter":"البحر: وافر تام","title":"دع ابن الأعمش المسكين تبكي","page":"","text":"دع ابن الأعمش المسكين تبكي … لداء ظل منه في وثاق !\nفصفرة وجهه من غير سقم … تنم عن الشقي بما يلاقي !\nلبئس الداء والداء استكفا … عليه من السماجة والحلاق\nكحلت بقبح صورته فأضحى … لها إنسان عيني في السياق\nمساو لو قسمن على الغواني … لما جهزن إلا بالطلاق\nقبحت وزدت فوق القبح حتى … كأنك قد خلقت من الفراق"},{"id":"diwan-abutammam:416","bookId":"diwan-abutammam","type":"poem","seq":416,"chapter":"البحر: خفيف تام","title":"ويك سلم للواحد الخلاق","page":"","text":"ويك سلم للواحد الخلاق … إن في الحلق قائدا للحلاق\nليس يغني إذا تتابع أمر الل … ه نتف ولا طلاء رقاق\nقد تذكرت منك بخلك عني … بكتاب يا أمول الأخلاق\nما كتاب المقطعات أسم … يه ولكنه كتاب صداق\nأيما حرة من الناس جادت … لخليل بالمهر بعد الطلاق ؟ !"},{"id":"diwan-abutammam:417","bookId":"diwan-abutammam","type":"poem","seq":417,"chapter":"البحر: كامل تام","title":"ماذا بدا لك إذ نقضت هواكا","page":"","text":"ماذا بدا لك إذ نقضت هواكا … وحلفت أني لا أشم قفاكا\nترضى العجائب ثم تغضب أنني … ناظرت في بعض الأمور أخاكا ! !\nمثل التي ضنت برد سلامها … وأباحت الأفخاذ والأوراكا !\nإن كان ذا من غيرة قد أضرمت … بالغيظ قلبك خاليا وحشاكا\nفاحلف بأن سواي لم يظفر بها … وعلي نذر إن لقيت سواكا\nفإذا أبيت فقد أبيت معالنا … فاعلم فديتك أن ذاك بذاكا"},{"id":"diwan-abutammam:418","bookId":"diwan-abutammam","type":"poem","seq":418,"chapter":"البحر: كامل تام","title":"متخمط في غمرة متهتك","page":"","text":"متخمط في غمرة متهتك … ما إن يبالي أي وجه يسلك !\nيكفيك خزيا أن عقلك دائبا … يبكي عليك وأن وجهك يضحك !\nلا تفتكن على الكؤوس بشربها … فهي التي إن مت قبلك تفتك\nكم بت تأخذها وبات منادم … لك وهو يأخذ منك ما لا يترك !\nأضبحت عنك لعظم جرمك ممسكا … وكذا إذا ذكر القضاة فأمسكوا"},{"id":"diwan-abutammam:419","bookId":"diwan-abutammam","type":"poem","seq":419,"chapter":"البحر: خفيف تام","title":"رغم أنفي من أن ترى مهتوكا","page":"","text":"رغم أنفي من أن ترى مهتوكا … أو أرى لي ما عشت فيك شريكا\nصرت مملوك كل من ترتجي فل … سا لديه وكنت قبل مليكا !\nأي شيء أنساك بعدي أيما … نك أني أبوك بعد أبيكا\nكنت ألحى مقران في الكشح حتى … كشحتني حوادث الدهر فيكا !"},{"id":"diwan-abutammam:420","bookId":"diwan-abutammam","type":"poem","seq":420,"chapter":"البحر: منسرح","title":"إقطع حبالي فقد برمت بكا","page":"","text":"إقطع حبالي فقد برمت بكا … وخلني حيث شئت من يدكا\nلا أشتهي أن تكون لي سكنا … حسبك ماكنت لي وكنت لكا !\nأنت كثير الألوان مشترك … فاطلب خليلا سواي مشتركا\nقد نلت منك الذي بخلت به … فلم أنل طائلا ولا دركا\nفاذهب إلى حيث شئت منطلقا … سال بك السيل حيثما سلكا\nومت حيا بلحية طلعت … عليك قد كنت قبلها ملكا\nإذا رأيت الغلام قد طلعت … بخده شعرة فقد هلكا !"},{"id":"diwan-abutammam:421","bookId":"diwan-abutammam","type":"poem","seq":421,"chapter":"البحر: كامل تام","title":"أمويس كيف رأيت نصب حبائلي","page":"","text":"أمويس كيف رأيت نصب حبائلي … أوليس ختلي فوق ختل الخاتل !\nأعملت فيك قصائدي ووسائلي … فحرمتني فلبئس أجر العامل !\nهذا جزائي إذ أدنس همتي … بك جاهلا وكذا جزاء الجاهل\nكم من لئم قد غزته قصائدي … ودأبن فيه فما ظفرن بطائل !\nلا خفف الرحمن عني إنني … أرتعت ظني في رياض الباطل !\nما أنسلت حواء أحمق لحية … من سائل يرجو الغنى من سائل !\nذاك الذي أحصى الشهور وعدها … طمعا لينتج سقبة من حائل !\nبهرتك شيمتك الشحاح زنادها … لما اجتثثتك في ارتقاء النائل !\nأحرزت من جدواك أكثر محرز … في ظاهر وأقله في حاصل\nما زلت أعلم أن بحرك ملحة … وازددت لما صرت نصب الساحل\nوكذاك من قصد اللئام بعاجل … في المدح سود وجهه في الآجل !"},{"id":"diwan-abutammam:422","bookId":"diwan-abutammam","type":"poem","seq":422,"chapter":"البحر: وافر تام","title":"كأني لم أبثكما دخيلي","page":"","text":"كأني لم أبثكما دخيلي … ولم تريا ولوعي من ذهولي\nوتركي مقلتي تحمى وتدمى … فتدمع في الحقوق وفي الفضول\nكلاني إن راحاتي تأتت … لقلبي في البكاء وفي العويل\nوبالإسكندرية رسم دار … عفت فعفوت من صبري وحولي\nذكرت به وفيه منسياتي … عزاي مسعرات لظى غليلي\nوما زالت تجد أسى وشوقا … له وعليه إخلاق الطلول\nفقدتك من زمان كل فقد … وغالت حادثاتك كل غول\nمحت نكباته سبل المعاني … وأطفأ ليله سرج العقول\nفما حيل الأريب بمدركات … عجائبه ولا فكر الأصيل\nفلو نشر الخليل له لعفت … رزاياه على فطن الخليل !\nأعياش ارع أو لا ترع حقي … وصل أو لا تصل أبدا وسيلي\nأراك ، ومن أراك الغي رشدا ، … ستلبس حلتي قال وقيل\nملاحم من لباب الشعر تنسي … قراة أبيك كتب أبي قبيل\nأمثلك يرتجى لولا تنائي … أموري والتياثي في حويلي ؟ !\nتوهم آجل الطمع المفيتي … تيقن عاجل اليأس المنيل\nرجاء حل من عرصات قلبي … محل البخل من قلب البخيل\nورأي هز حسن الظن حتى … جرى ماءاه في عرضي وطولي\nفأجدى موقفي بنداك جدوى … وقوف الصب بالطلل المحيل\nوأعكفت المنى في ذات صدري … عكوف اللحظ في الخد الأسيل\nوكنت أعز عزا من قنوع … تعوضه صفوح عن جهول\nفصرت أذل من معنى دقيق … به فقر إلى ذهن جليل\nفما أدري عماي عن ارتيادي … دهاني أم عماك عن الجميل\nمتى طابت جنى وزكت فروع … إذا كانت خبيثات الأصول !\nندبتك للجزيل وأنت لغو … ظلمتك لست من أهل الجزيل !\nكلا أبويك من يمن ولكن … كلا أبوي نوالك من سلول !\nرويدك إن جهلك سوف يجلو … لك الظلماء عن خزي طويل\nوأقلل إن كيدك حين تصلى … بنيراني أقل من القليل\nمرارات المقام عليك تعفو … وتذهب في حلاوات الرحيل\nسأظعن عالما أن ليس برء … لسقمي كالوسيج وكالذميل\nولو كانت يمينك ألف بحر … يفيض لكل بحر ألف نيل"},{"id":"diwan-abutammam:423","bookId":"diwan-abutammam","type":"poem","seq":423,"chapter":"البحر: كامل تام","title":"أنبئت عبد الله أصبح يعول","page":"","text":"أنبئت عبد الله أصبح يعول … إن الزمان بأهله متنقل !\nلما أطلى المسكين أسبل عبرة … والأطلاء الإلتحاء الأول !\nمستعمل نتفا ليرجع حسنه … بعد البلى والحسن لا يستعمل\nنتف العوارض غضة ما عذره … في نتف شعر الخد حين يسنبل !"},{"id":"diwan-abutammam:424","bookId":"diwan-abutammam","type":"poem","seq":424,"chapter":"البحر: وافر تام","title":"تعشقك الكبار يدل عندي","page":"","text":"تعشقك الكبار يدل عندي … على أن الرحا قلبت ثفالا\nوإلا فالصغار ألذ قربا … وأشهى إن أردت بهم فعالا\nمتى أبصرت لوطيا صحيحا … يحب بأن يصادفهم رجالا ؟ !\nثكلتك يا أخي إن كنت عندي … صحيح الأمر لو لكت البغالا !"},{"id":"diwan-abutammam:425","bookId":"diwan-abutammam","type":"poem","seq":425,"chapter":"البحر: طويل","title":"هل الله لو أشركت كان معذبي","page":"","text":"هل الله لو أشركت كان معذبي … بأكثر من أني لجاهك آمل ؟ !\nهلموا اعجبوا من أنبه الناس كلهم … ذريعته فيما يحاول خامل\nأيرضى بضعف في وسائله امرؤ … له حركات كلهن وسائل !"},{"id":"diwan-abutammam:426","bookId":"diwan-abutammam","type":"poem","seq":426,"chapter":"البحر: طويل","title":"ستعلم يا عياش إن كنت تعلم","page":"","text":"ستعلم يا عياش إن كنت تعلم … فتندم إن خلاك جهلك تندم\nأبى لك أن تأبى المخازي كلها … أب أندرهلي وجد معلم\nوقفت عليك الظن حتى كأنما … لديك الغنى أو ليس في الأرض درهم\nوكفكفت عنك الذم حتى كأنما … أجارك مجد أو كأني مفحم\nفلما بدا لي منك لؤم يحفه … حرمية يستن فيها التبظرم\nتركتك ما إن في أديمك ظاهر … ولا باطن إلا ولي فيه ميسم\nفأيسر من تسآلك العي والعمى … وأعذب من إحسانك القيح والدم"},{"id":"diwan-abutammam:427","bookId":"diwan-abutammam","type":"poem","seq":427,"chapter":"البحر: بسيط تام","title":"صدق أليته إن قال مجتهدا","page":"","text":"صدق أليته إن قال مجتهدا … ' لا والرغيف ' فذاك البر من قسمه !\nوإن هممت به فافتك بخبزته … فإن موقعها من لحمه ودمه !\nقد كان يعجبني لو أن غيرته … على جرادقه كانت على حرمه !"},{"id":"diwan-abutammam:428","bookId":"diwan-abutammam","type":"poem","seq":428,"chapter":"البحر: كامل تام","title":"الزنج أكرم منكم والروم","page":"","text":"الزنج أكرم منكم والروم … والحين أيمن منكم والشوم\nعياش إنك للئيم وإنني … مذ صرت موضع مطلبي للئيم\nالسحت أطيب من نوالك مطمعا … والمهل والغسلين والزقوم\nنجس تدبر أمره شيم له … شكس يدبر أمرهن اللوم\nومنازل لم يبق فيها ساحة … إلا وفيها سائل محروم\nعرصات سوء لم يكن لسيد … وطنا ولم يرتع بهن كريم\nلما بدا لي من صميمك ما بدا … بل لم يصب لك لا أصيب صميم\nجردت في ذميك خيل قصائد … حالت بك الدنيا وأنت مقيم\nألحقن بالجميز أصلك صاغرا … والشيح يضحك منك والقيصوم\nطبقات شحمك ليس يخفى أنها … لم يبنها آء ولا تنوم\nيا شاربا لبن اللقاح تعزيا … الصبر من يقنيه والحالوم ؟\nوالمدعي صوران منزل جده … قل لي لمن أهناس والفيوم ؟ !"},{"id":"diwan-abutammam:429","bookId":"diwan-abutammam","type":"poem","seq":429,"chapter":"البحر: وافر تام","title":"أتدري أي بارقة تشيم","page":"","text":"أتدري أي بارقة تشيم … ومهلكة إليها تستنيم\nإلام وكم يقيك أذاي صفح … ومجد عنك في غضبي حليم !\nكأنك لم تعود من سهادي … إذا ما عانق السنة النؤوم\nومن تقليب قلبي عن لساني … إذا باتت تقلبه الهموم\nفما أنت اللئيم إذن ولكن … زمان سدت فيه هو اللئيم\nأتطمع أن تعد كريم قوم … وبابك لا يطيف به كريم ؟ !\nكمن جعل الحضيض له مهادا … ويزعم أن إخوته النجوم\nحلفت بيوم أوب أبي سعيد … سعيدا إنه يوم عظيم\nفتى من أكثر الفتيان غرما … لعافيه وليس له غريم\nلنمت ونام عرضك والقوافي … سواخط لا تنام ولا تنيم\nيبيت يثيرها لك أفعوان … بلصب ما يبل له سليم\nيرى في كل واد أنت فيه … بلؤمك سائرا أبدا يهيم"},{"id":"diwan-abutammam:430","bookId":"diwan-abutammam","type":"poem","seq":430,"chapter":"البحر: بسيط تام","title":"ألان خليت الذؤبان في الغنم","page":"","text":"ألان خليت الذؤبان في الغنم … وصرت أضيع من لحم على وضم\nقد كنت تحكي حطيطا صالحا فغدت … فخذاك أكتب من كفيك بالقلم !\nوكنت أدعوك عبدالله قبل فقد … أصبحت أدعوك زيدا غير محتشم\nواجرت جودا بما قد كنت تمنعه … ما كل جود الفتى يدني من الكرم !\nإن أبل فيك بأن أصبحت منتهبا … فالمرء قد يبتلى في صالح الحرم"},{"id":"diwan-abutammam:431","bookId":"diwan-abutammam","type":"poem","seq":431,"chapter":"البحر: منسرح","title":"رب غليظ الطباع يغلظ عن","page":"","text":"رب غليظ الطباع يغلظ عن … رقة مثلي في لحمه ودمه\nنعمته نعمة إذا قدحت … لرفد حر ثنته عن هممه\nفصان وجهي عن عرفه وحمى … عرضي فيم ينتقصه من كرمه !\nفالحمد لله حين خلصني … منه سليم الأديم من نعمه"},{"id":"diwan-abutammam:432","bookId":"diwan-abutammam","type":"poem","seq":432,"chapter":"البحر: بسيط تام","title":"ألا ترى كيف يبلينا الجديدانألا ترى كيف يبلينا الجديدان","page":"","text":"ألا ترى كيف يبلينا الجديدانألا ترى كيف يبلينا الجديدان … وكيف نلعب في سر وإعلان ؟\nلا تركنن إلى الدنيا وزخرفها … فإن أوطانها ليست بأوطان\nوامهد لنفسك من قبل الممات ولا … يغررك كثرة أصحاب وإخوان\nلو أنهم نفعوا خلقا لحرمته … لدافعوا الموت عن إمراة معدان ؟ !"},{"id":"diwan-abutammam:433","bookId":"diwan-abutammam","type":"poem","seq":433,"chapter":"البحر: خفيف تام","title":"كشفتك الأيام يا إنسان","page":"","text":"كشفتك الأيام يا إنسان … لا يكن للذي أهنت الهوان !\nإن تكن قد فضضت بعدي فليست … بدعة أن يفلق الرمان !\nنشرتك الكفوف بعد عفاف … كنت تطوى في تحته وتصان\nأيها السابق المسامح في ال … لذات والقصف أين ذاك الحران ؟\nما تحداك رائض لك إلا … قلت بيني وبينك الميدان\nلم أشقى بكم ويسعد غيري … بهواكم حبي إذن كشخان ؟ !"},{"id":"diwan-abutammam:434","bookId":"diwan-abutammam","type":"poem","seq":434,"chapter":"البحر: بسيط تام","title":"وسابح هطل التعداء هتان","page":"","text":"وسابح هطل التعداء هتان … على الجراء أمين غير خوان\nأظمى الفصوص ولم تظمأ قوائمه … فخل عينيك في ظمآن ريان\nفلو تراه مشيحا والحصى فلق … تحت السنابك من مثنى ووحدان\nحلقت إن لم تثبت أن حافره … من صخر تدمر أو من وجه عثمان !"},{"id":"diwan-abutammam:435","bookId":"diwan-abutammam","type":"poem","seq":435,"chapter":"البحر: خفيف تام","title":"غاب والله أحمد فأصا","page":"","text":"غاب والله أحمد فأصا … بتني له قطعة من الأحزان\nوتخلفت بعده في أناس … ألبسوني صبرا على الحدثان\nما لنور الربيع في غير حسن … مالهم من تغير الألوان\nأنكرتهم نفسي وما ذلك الم … إنكار إلا من شدة العرفان\nوإساءات ذي الإساءة يذكر … نك يوما إحسان ذي الإحسان\nكثرة الصفر يمنة وشمالا … أضعفت في نفاسة العقيان !"},{"id":"diwan-abutammam:436","bookId":"diwan-abutammam","type":"poem","seq":436,"chapter":"قصائد","title":"أم ابن الأعمش فاعلموها فرتنا","page":"","text":"أم ابن الأعمش فاعلموها فرتنا … وما أسهل المعروف ثم وأمكنا !\nعجزاء يحسن إن أتاها خائف … وقد استجار بصدعها أن تحسنا\nلو أن غلمتها استحارت فضة … تمتار أو ذهبا لكانت معدنا\nلا تحسبن أني افتريت على التي … ولدتك لكني افتريت على الزنا"},{"id":"diwan-abutammam:437","bookId":"diwan-abutammam","type":"poem","seq":437,"chapter":"البحر: خفيف تام","title":"ليت شعري بأي وجهيك بالمص","page":"","text":"ليت شعري بأي وجهيك بالمص … ر غدا حين نلتقي تلقاني ؟\nأبوجه له طلاقة ذي الإح … سان أم وجه غير ذي إحسان ؟ !\nفلئن كنت محسنا ليسرم … نك في كل محضر أن تراني\nولئن كنت غير ذاك فما أن … ت علينا غدا بذي سلطان\nكل يوم آتيك في حاجة أب … ذل وجهي فيها معا ولساني\nثم لم أحظ منك في حاجة قط … بغير الإباء والحرمان !\nخلف أعور وحق رسول الله … يا سلم أنت من عثمان"},{"id":"diwan-abutammam:438","bookId":"diwan-abutammam","type":"poem","seq":438,"chapter":"البحر: بسيط تام","title":"لقد أقام على بغداد ناعيها","page":"","text":"لقد أقام على بغداد ناعيها … فليبكها لخراب الدهر باكيها\nكانت على ما بها والحرب موقدة … والنار تطفىء حسنا في نواحيها\nترجى لها عودة في الدهر صالحة … فالآن اضمر منها إلياس راجيها\nمثل العجوز التي ولت شبيبتها … وبان عنها كمال كان يحظيها\nلزت بها ضرة زهراء واضحة … كالشمس أحسن منها عند رائيها"},{"id":"diwan-abutammam:439","bookId":"diwan-abutammam","type":"poem","seq":439,"chapter":"البحر: كامل تام","title":"لا ترث لابن الأعمش الكشخان من","page":"","text":"لا ترث لابن الأعمش الكشخان من … رخص الإجازة والبغاء لديه\nأنظر إلى ابن الزانيين تجدهما … قرنين يصطرعان في عينيه\nقطع الطريق على فياش عجوزه … وأمال وفد النايكين إليه\nما فكرتي فيه ولكن فكرتي … في أير جياف يقوم عليه"},{"id":"diwan-abutammam:440","bookId":"diwan-abutammam","type":"poem","seq":440,"chapter":"البحر: وافر تام","title":"بأي نجوم وجهك يستضاء","page":"","text":"بأي نجوم وجهك يستضاء … أبا حسن وشيمتك الإباء ؟\nأتترك حاجتي غرض التواني … وأنت الدلو فيها والرشاء\nتألف آل إدريس بي بدر … فتسبيب العطاء هو العطاء\nوخذهم بالرقى إن المهاري … يهيجها على السير الحداء\nفإما جاز مني الشعر فيهم … وإما جاز منك الكيمياء !\nوقل للمرء عثمان مقالا … يضيق بلفظه البلد الفضاء !\nألم يهززك قول فتى يصلي … لما يثني عليك به الثناء !\nفتفعل ما يشاء المجد فيه … فإن المجد يفعل ما يشاء\nوأنت المرء تعشقه المعالي … ويحكم في مواهبه الرجاء\nفإنك لا تسر بيوم حمد … شهرت به ومالك لا يساء\nوإن المدح في الأقوام مالم … يشيع بالجزاء هو الهجاء"},{"id":"diwan-abutammam:441","bookId":"diwan-abutammam","type":"poem","seq":441,"chapter":"البحر: طويل","title":"أيا زينة الدنيا وجامع شملها","page":"","text":"أيا زينة الدنيا وجامع شملها … ومن عدله فيها تمام بهائها\nويا شمس أرضيها التي تم نورها … فباهت به الأرضون شمس بهائها\nعطاؤك لا يفنى ويستغرق المنى … ويبقي وجوه الراغبين بمائها\nترامتني الأبصار من كل جانب … كأني مريب بينها لإرتمائها\nولي عدة قد راث عني نجاحها … ومجدك أدنى رائد في اقتضائها\nشكوت وما الشكوى لنفسي عادة … ولكن تفيض النفس عند امتلائها\nومالي شفيع غير نفسك إنني … ثكلت من الدنيا على حسن وائها"},{"id":"diwan-abutammam:442","bookId":"diwan-abutammam","type":"poem","seq":442,"chapter":"البحر: طويل","title":"أبا دلف لم يبق طالب حاجة","page":"","text":"أبا دلف لم يبق طالب حاجة … من الناس غيري والمحل جديب\nيسرك أني أبت عنك مخيبا … ولم ير خلق من جداك يخيب ؟ !\nوأني صيرت الثناء مذمة … وقام بها في العالمين خطيب\nفكيف وأنت ضالماجد العلم الذي … لكل أناس من نداه نصيب ؟\nأقمت شهورا في فنائك خمسة … لقى حيث لا تهمي علي جنوب\nفإن نلت ما أملت فيك فإنني … جدير وإلا فالرحيل قريب"},{"id":"diwan-abutammam:443","bookId":"diwan-abutammam","type":"poem","seq":443,"chapter":"البحر: بسيط تام","title":"قل للأمير تجد للقول مضطربا","page":"","text":"قل للأمير تجد للقول مضطربا … وتلق في كنفيه السهل والرحبا\nفداء نعلك معطى حظ مكرمة … أصغى إلى المطل حتى باع ما وهبا !\nإني وإن كان قوم ما لهم سبت … إلا قضاء كفاهم دوني السببا\nلمضمر غلة في القلب يضرمها … أني سبقت وتعطي غيري القصبا\nإحفظ وسائل شعر فيك ما ذهبت … خواطف البرق إلا دون ما ذهبا\nيغدون مغتربات في البلاد فما … يزلن يؤنسن في الآفاق مغتربا\nفلا تضعها فما في الأرض أحسن من … نظم القوافي إذا ما صادفت حسبا\nإن أنت لم تك عدل الحق تنصفه … لم نرج بعدك خلقا ينص ف الأدبا"},{"id":"diwan-abutammam:444","bookId":"diwan-abutammam","type":"poem","seq":444,"chapter":"البحر: بسيط تام","title":"صبرا على المطل مالم يتله الكذب","page":"","text":"صبرا على المطل مالم يتله الكذب … فللخطوب إذا سامحتها عقب\nعلى المقادير لوم إن رميت به … من عادل وعلي السعي والطلب\nيا أيها الملك النائي برؤيته … وجوده لمرجي جوده كثب\nليس الحجاب بمقض عنك لي أملا … إن السماء ترجى حين تحتجب\nمادون بابك لي باب ألوذ به … ولا وراءك لي مثوى ومطلب\nيا خير من سمعت أذن به ورأت … عين ومن وردت أبوابه العرب\nأما السكوت فمطوي على عدة … وفي كلامك غر المال ينتهب !"},{"id":"diwan-abutammam:445","bookId":"diwan-abutammam","type":"poem","seq":445,"chapter":"البحر: خفيف تام","title":"ليس يدري إلا اللطيف الخبير","page":"","text":"ليس يدري إلا اللطيف الخبير … أي شيء تطوى عليه الصدور !\nويقولون إنك المرء بالغي … ب محام عن الصديق نصور\nفإذا جئت زائرا حجبت وج … هك عني كآبة وبسور\nفتطلق مع العناية إن البش … ر في أكثر الأمور بشير\nإن في البشر روضة فإذا كا … ن ببذل فروضة وغدير\nفاقسم اللحظ بيننا إن في اللح … ظ لعنوان ما يجن الضمير !"},{"id":"diwan-abutammam:446","bookId":"diwan-abutammam","type":"poem","seq":446,"chapter":"البحر: كامل تام","title":"صدفت لهيا قلبي المستهتر","page":"","text":"صدفت لهيا قلبي المستهتر … فبقيت نهب صبابة وتذكر\nغابت نجوم السعد يوم فراقها … وأساءت الأيام فيها محضري\nفي كل يوم في فؤادي وقعة … للشوق إلا أنها لم تذكر\nأرني حليفا للصبا جارى الصبا … في حلبة الأحزان لم يتفطر !\nأما الذي في جسمه فسل التي … هجرته وهو مواصل لم يهجر\nصفراء صفرة صحة قد ركبت … جثمانه في ثوب سقم أصفر\nقتلته سرا ثم قالت جهرة … قول الفرزدق لا بظبي أعفر\nنظرت إليه فما استنمت لحظها … حتى تمنت أنها لم تنظر\nورأت شحوبا رابها في جسمه … ماذا يريبك من جواد مضمر ؟ !\nغرض الحوادث ما تزال ملمة … ترميه عن شزن بأم حبوكر\nسدكت به الأقدار حتى إنها … لتكاد تفجأه بما لم يقدر\nما كف من حرب الزمان ورميه … بالصبر إلا أنه لم ينصر\nما إن يزال بجد حزم مقبل … متوطئا أعقاب رزق مدبر\nالعيش تعلم أن حوبا واتها … ريخ إذا بلغتك إن لم تنحر\nكم ظهر مرت مقفر جاوزته … فحللت ربعا منك ليس بمقفر\nبنداك يوسى كل جرح يعتلي … رأب الأساة بدردبيس قنطر\nجود كجود السيل إلا أن ذا … كدر وأن نداك غير مكدر\nالفطر والأضحى قد انسلخا ولي … أمل ببابك صائم لم يفطر !\nعام ولم ينتج نداك وإنما … تتوقع الحبلى لتسعة أشهر !\nجش لي ببخر واحد أغرقك في … مدح أجش له بسبعة أبحر\nقصر ببذلك عمر مطلك تحولي … حمدا يعمر عمر سبعة أنسر\nكم من كثير البذل قد جازيته … شكرا بأطيب من نداه وأكثر\nشر الأوائل والأواخر ذمة … لم تصطنع وصنيعة لم تشكر\nلا تغضبنك منهضاتي إنها … مدخورة لك في السقاء الأوفر\nأفديك مورق موعد لم يفدني … من قول باغ أنه لم يثمر\nقد كدت أن أنسى ظماء جوانحي … من بعد شقة موردي عن مصدري\nولئن أردت لأعذرنك مجملا … والعجز عندي عذر غير المعذر\nما إن أراني مادحا ومعاتبا … إلا وقد حررت فيك فحرر\nواعلم بأني اليوم غرس محامد … تزكو فتجنيها غدا في العسكر"},{"id":"diwan-abutammam:447","bookId":"diwan-abutammam","type":"poem","seq":447,"chapter":"البحر: كامل تام","title":"ضاحكن من أسف الشباب المدبر","page":"","text":"ضاحكن من أسف الشباب المدبر … وبكين من ضحكات شيب مقمر\nناوشن خيل عزيمتي بعزيمة … تركت بقلبي وقعة لم تنصر\nولقد بلون خلائقي فوجدنني … سمح اليدين ببذل ود مضمر\nيعجبن مني أن سمحت بمهجتي … وكذاك أعجب من سماحة جعفر\nملك إذا الحاجات لذن بحفوه … صافحن كف نواله المتيسر\nملك مفاتيح الردى بشماله … ويمينه إقليد قفل المعسر\nملك إذا ما الشعر حار ببلدة … كان الدليل لطرفه المتحير\nيا من يبشرني بأسباب الغنى … منه بشائر وجهه المستبشر\nإفخر بجودك دون فخرك إنما … جدواك تنشر عنك مالم تنشر\nإني انتجعتك يا أبا الفضل الذي … بالجود قرب موردي من مصدري\nعش سالما تبني العلا بيد الندى … حتى تكون مناوئا للمشيري\nإني أرى ثمر المدائح يانعا … وغصونها تهتز فوق العنصر\nلولاك لم أخلع عنان مدائحي … أبدا ولم أفتح رتاج تشكري\nولقلما عبيت خيل مدائحي … إلا رجعت بهن غير مظفر\nأولم يكن وطني بأرضك والهوى … بدمشق يرتع في ديار البحتري\nوأعوذ باسمك أن تكون كعارض … لا يرتجى وكنابت لم يثمر\nواعلم بأني لم أقم بك فاخرا … لك مادحا في مدحه لم أنذر"},{"id":"diwan-abutammam:448","bookId":"diwan-abutammam","type":"poem","seq":448,"chapter":"البحر: بسيط تام","title":"إما حججت فمقبول ومبرور","page":"","text":"إما حججت فمقبول ومبرور … موفر الحظ منك الذنب مغفور\nقضيت من حجة الإسلام واجبها … ثم انصرفت ومنك السعي مشكور\nإلا كتابا لنا قد كنت جدت به … فض الختام وفحوى لفظه زور\nفتب إلى الله من تحقيق باطله … فأنت إن تبت عند الله معذور !"},{"id":"diwan-abutammam:449","bookId":"diwan-abutammam","type":"poem","seq":449,"chapter":"البحر: بسيط تام","title":"أبا علي لصرف الدهر والغير","page":"","text":"أبا علي لصرف الدهر والغير … وللحوادث والأيام والعبر\nأذكرتني أمر داود وكنت فتى … مصرف القلب في الأهواء والفكر\nإن أنت لم تترك السير الحثيث إلى … جآذر الروم أعنقنا إلى الخزر !\nأعندك الشمس قد راقت محاسنها … وأنت مشتغل الأحشاء بالقمر !\nإن النفور له عندي مقر هوى … يحل مني محل السمع والبصر\nورب أمنع منه جانبا وحمى … أمسى وتكته مني على خطر\nجردت فيه جنود العزم فانكشفت … عنه غيابتها عن نيكة هدر\nسبحان من سبحته كل جارحة … ما فيك من طمحان الأير والنظر\nأنت المقيم فما تغدو رواحله … وأيره أبدا منه على سفر !"},{"id":"diwan-abutammam:450","bookId":"diwan-abutammam","type":"poem","seq":450,"chapter":"البحر: بسيط تام","title":"ذل السؤال شجى في الحلق معترض","page":"","text":"ذل السؤال شجى في الحلق معترض … من دونه شرق من خلفه جرض\nما ماء كفك إن جادت وإن بخلت … من ماء وجهي إذا أفنيته عوض\nأرى أمورك موطوآتها رمض … إذا سلكن وممهوراتها فضض\nإني بأيسر ما أدنيت منبسط … كما بأيسر ما أقصيت منقبض\nأجر الفراسة من قرني إلى قدمي … ومشها حيث لا عثر ولا دحض\nتنبئك أني لا هيابة ورع … عن الخطوب ولا جثامة حرض\nمن أشتكي وإلى من أعتزي وندى … من أجتدي كل أمري فيك منتقض\nمودة ذهبت أثمارها شبه … وهمة جوهر معروفها عرض\nأظن عندك أقواما وأحسبهم … لم يأتلوا في ما أعدوا وما ركضوا\nيرمونني بعيون حشوها شرر … نواطق عن قلوب حشوها مرض\nلولا صبابة عرضي وانتظار غد … والظم حتم علي الدهر مفترض\nلما فككت رقاب الشعر عن فكري … ولا رقابهم إلا وهم حيض !\nأصبحت يرمي نباهاتي بخامله … من كله لنبالي كلها غرض"},{"id":"diwan-abutammam:451","bookId":"diwan-abutammam","type":"poem","seq":451,"chapter":"البحر: خفيف تام","title":"وأخ أملى عليه اختلاط الد","page":"","text":"وأخ أملى عليه اختلاط الد … هر طول التقليب والتصريف\nأصحلته لي المروءة حتى … أفسدته استطالة المعروف\nبغضته الأيام مدحي فأعفى … شكري الجزل من نداه الطفيف !\nليس جدع الأنوف جدعا ولكن … بعض من نصطفيه جدع الأنوف ؟\nلو بأسد العريف نيطت عرى المن … لذلت رقاب أسد العريف !\nوطري في فجاءة الرد ما يع … لم من همة ونفس عزوف\nضئضئي من بني عدي بن عمر و … غير أني في مثلها من ثقيف\nلا تته إن أطال هزك مدحي … واعذرن لست بعدها من سيوفي !"},{"id":"diwan-abutammam:452","bookId":"diwan-abutammam","type":"poem","seq":452,"chapter":"قصائد","title":"نسج المشيب له لفاعا مغدفا","page":"","text":"نسج المشيب له لفاعا مغدفا … يققا فقنع مدرويه ونصفا\nنظر الزمان إليه قطع دونه … نظر الشقيق تحسرا وتلهفا\nما اسود حتى ابيض كالكرم الذي … لم يأن حتى جيء كيما يقطفا\nلما تفوفت الخطوب سوداها … ببياضها عبثت به فتفوفا\nما كان يخطر قبل ذا في فكره … في البدر قبل تمامه أن يكسفا\nيا ظبية الجزع الذي بمحجر … ترعى الكباث مصيفة والعلفا\nتقرؤ بأسفله ربولا غضة … وتقيل أعلاه كناسا أجوفا\nأتبعت قلبي لوعة كانت أسى … تبعت أماني منك كانت زخرفا\nكم من شماتة حاسد إن أنت لم … تخلف رجاء المرتجي أن تخلفا\nلا تنس تسعة أشهر أنضييتها … دأبا وأنضتني إليك ونيفا\nبقصائد لم يرو بحرك وردها … ولو الصفا وردت لفجرت الصفا !\nلله أي وسيلة في أول … أقوى ولكن آخرا ما أضعفا !\nإني أخاف بلحظتي عقباك أن … تدعى المطول وأن أسمى الملحفا\nقد كان أصغر همتي مستصغرا … عظم الربيع فصرت أرضى الصيفا\nهبت رياحك لي جنوبا سهوة … حتى إذا أورقت عادت حرجفا\nإن أنت لم تفضل ولم تر أنني … أهل له فأنا أرى أن تنصفا\nما عذر من كان النوال مطيعه … والطبع منه أن يراه تكلفا !\nأسرفت في منعي وعادتك التي … منعت عنانك أن تجود فتسرفا\nالله جارك أن تحول وأن يهي … ما سلف التأميل فيك وخلفا\nلا تصرفن نداك عمن لم يدع … للقول فيك إلى سواك تصرفا\nثقف فتي في الجود تلق قصائدا … لاقت أوابدهن فيك مثقفا\nلا ترض ذاك فتسخطن أوابدا … هزتك إلا أن تصيبك مرهفا\nأفن التظنن بالتيقن إنه … لم يفن ما أبقى الثناء المضعفا\nكم ماجد سمح تناول جوده … مطل فأصبح وجه نائله قفا !\nلم آل فيك تعسفا وتعجرفا … وتألقا وتلطفا وتظرفا\nوأراك تدفع حرمتي فلعلني … ثقلت غير مؤنب فأخففا !"},{"id":"diwan-abutammam:453","bookId":"diwan-abutammam","type":"poem","seq":453,"chapter":"البحر: خفيف تام","title":"نطقت مقلة الفتى الملهوف","page":"","text":"نطقت مقلة الفتى الملهوف … فتشكت بفيض دمع ذروف\nترجم الدمع في صحائف خدي … ه سطورا مؤلفات الحروف\nفلئن شطت الديار وغال الده … ر في آلف وفي مألوف\nوتبدلت بالبشاشة حزنا … بعد لهو في مربع ومصيف\nفعزائي بأن عرضي مصون … سائغ الورد والسماح حليفي\nثم علمي على حداثة سني … بصروف الدهور والتصريف\nراكب للأمور في حلبة الأيا … م للمنجيات أو للحتوف\nذو اعتداء على ثراء فتى الجو … د الشريف الفعال وابن الشريف\nليت شعري ماذا يريبك مني … ولقد فقت فطنة الفيلسوف\nانتهز فرصة تسرك مني … باصطناع الخيرات والمعروف\nأنا ذو منطق شريف لإعطا … ء منطق لمنع عفيف\nما أبالي إذا عنتك أموري … كيف أنحت علي أيدي الصروف"},{"id":"diwan-abutammam:454","bookId":"diwan-abutammam","type":"poem","seq":454,"chapter":"البحر: كامل تام","title":"وأخ بشعت بعرفه ومذاقه","page":"","text":"وأخ بشعت بعرفه ومذاقه … ومللت عنف قياده وسياقه\nفمنحته بعد الوصال قطيعة … شدت على الزفرات عقد نطاقه\nفاذهب فكم فارقت قبلك صاحبا … عاينت شخص الجور في حملاقه\nلو مت لم تعدل وفاتك بغتة … حلما يخوفني بيوم فراقه\nحشم الصديق عيونهم بحاثة … لصديقه عن صدقة ونفاقه\nفلينظرن المرء من غلمانه … فهم خلائقه على أخلاقه"},{"id":"diwan-abutammam:455","bookId":"diwan-abutammam","type":"poem","seq":455,"chapter":"البحر: كامل تام","title":"أجميل ما لك لا تجيب أخاكا","page":"","text":"أجميل ما لك لا تجيب أخاكا … ماذا الذي بالله أنت دهاكا !\nأغنى ظفرت به فإني في غنى … من نعمة الله التي أعطاكا\nبل لا نسيت - ولا ألومك - خلتي … ولئن فعلت لحادث أنساكا\nستلوم يوما سوء رأيك إنه … رأي غوي طالما أرداكا"},{"id":"diwan-abutammam:456","bookId":"diwan-abutammam","type":"poem","seq":456,"chapter":"البحر: وافر تام","title":"شهدت لقد لبست أبا سعيد","page":"","text":"شهدت لقد لبست أبا سعيد … مكارم تبهر الشرف الطوالا\nإذا حر الزمان حرت أيادي … نداه فغشت الدنيا ظلالا\nوإن نفس امرئ دقت رأينا … بعرصة جوده كرما جلالا\nوقاك الخطب قوم لم يمدوا … يمينا للفعال ولا شمالا\nأحين رفعت من نظري وعادت … حويلي في ذراك الرحب حالا ؟\nوحفت بي العشائر والأقاصي … عيالا لي وكنت لهم عيالا ؟\nفقد أصبحت أكثرهم عطاء … وقبلك كنت أكثرهم سؤالا\nإذا شفعوا إلي فلا خدودا … يقون من الهوان ولا نعالا\nأتعتع في الحوائج إن خفافا … غدوت بها عليك وإن ثقالا\nإذا ما الحاجة انبعثت يداها … جلعت المنع منك لها عقالا\nفأين قصائد لي فيك تأبى … وتأنف أن أهان وأن أذالا ؟\nمن السحر الحلال لمجتنيه … ولم أر قبلها سحرا حلالا\nفلا يكدر غديرك لي فإني … أمد إليك آمالا طوالا\nوفر جاهي عليك فإن جاها … إذا ما غب يوما صار مالا"},{"id":"diwan-abutammam:457","bookId":"diwan-abutammam","type":"poem","seq":457,"chapter":"البحر: خفيف تام","title":"قد عرفناه دلائل المنع أو ما","page":"","text":"قد عرفناه دلائل المنع أو ما … يشبه المنع باحتباس الرسول\nوافتضحنا عند الزبيب بما صحم … لديه من قبح وجه الشمول\nفاجأتنا كدراء لم تسب من تسم … نيم جريالها ولا سلسبيل\nمن عقار لا ريحها نفحة المس … ك ولا خدها بخد أسيل\nلا تهدى سبل العروق ولا تنسل … في مفصل بغير دليل\nوهي نزر لو أنها من دموع الصبم … لم تشف منه حر الغليل\nوكأن الأنامل اعتصرتها … بعد كد من ماء وجه البخيل !\nاحتسابا بذلتها أم تصدق … ت بها رحمة على ابن السبيل ؟ !\nقد كتبنا لك الأمان فما تس … ألها عمر ذا الزمان الطويل\nكم مغطى قد اختبرنا نداه … واعتبرنا كثيره بالقليل !"},{"id":"diwan-abutammam:458","bookId":"diwan-abutammam","type":"poem","seq":458,"chapter":"البحر: كامل تام","title":"عجب لعمرك أن وجهك معرض","page":"","text":"عجب لعمرك أن وجهك معرض … عني وأنت بوجه فعلك مقبل !\nبر بدأت به ودار بابها … للخلق مفتوح ووجهك مقفل\nأو لا ترى أن الطلاقة جنة … من سوء ما تجني الظنون ومعقل\nحلي الصنيعة أن يكون لربها … لفظ له زجل وطرف قلقل\nومودة مطوية منشورة … فيها إلى إنجاحها متعلل\nإن تعط وجها كاسفا من تحته … كرم وحلم خليقة لا تجهل\nفلرب سارية عليك مطيرة … قد جاد عارضها وما يتهلل !"},{"id":"diwan-abutammam:459","bookId":"diwan-abutammam","type":"poem","seq":459,"chapter":"البحر: طويل","title":"إني لأستحيي يقيني أن يرى","page":"","text":"إني لأستحيي يقيني أن يرى … لشكي في شيء عليه سبيل\nوما زال لي علم إذا ما نصصته … كثير بأن الظرف فيك قليل\nوإن يك عدا عن سواك إليك بي … رحيل فلي في الأرض عنك رحيل\nأبى الحزم لي مكثا بدار مضيعة … وعنس أبوها شدقم وجديل\nأبعد التي ما بعدها متلوم … عليك لحر قلت أنت جهول ؟ !\nسأقطع أرسان العتاب بمنطق … قصير عناء الفكر فيه طويل\nوإن امرءا ضنت يداه على امرىء … بنيل يد من غيره لبخيل"},{"id":"diwan-abutammam:460","bookId":"diwan-abutammam","type":"poem","seq":460,"chapter":"البحر: كامل تام","title":"إعلم وأنت المرء غير معلم","page":"","text":"إعلم وأنت المرء غير معلم … وافهم جعلت فداك غير مفهم\nإن اصطناع العرف مالم توله … مستكملا كالبرد مالم يعلم\nوالشكر ما لم تستتر بصنيعه … كالخط تقرأه وليس بمعجم\nوتفنني في القول إكثار وقد … أسرجت في كرم الفعال فألجم !"},{"id":"diwan-abutammam:461","bookId":"diwan-abutammam","type":"poem","seq":461,"chapter":"البحر: بسيط تام","title":"لا يحمد السجل حتى يحكم الوذم","page":"","text":"لا يحمد السجل حتى يحكم الوذم … ولا ترب بغير الواصل النعم\nوفي الجواهر أشباه مشاكلة … وليس تمتزج الأنوار والظلم\nورب خطب رمى إلفين فانصدعا … عن المودة والأسباب تلتئم\nيصور قلبيهما عهد يجدده … طول الزمان ولا يغتاله القدم\nذما العقوق وردا فضل حلمهما … وراجعا الوصل واستثناهما الكرم\nكنا وكنت على عهد مضى سلفا … وفي عواقب حال القاطع الندم\nلنا قريبان في قلبين ردهما … إلى الصفاء هوى باد ومكتتم\nحتى إذا لم نخف نقض الهوى وصفت … لنا المودة حتى ماؤها سجم\nونحن في كنفي حال مساعدة … كل على صبوة العشاق معتزم\nكوارد الخمس شهر القيظ جاد له … حسي ومد عليه ظله السلم\nالهتك عن حاجة ضيعت حرمتها … ولاية ودواعي النفس تتهم !\nأحين قمت من الأيام في كبد … كما أنار بنار الموقد العلم\nأنشبت نفسك في ظلماء مسدفة … وأفسدتك على إخوانك النعم !\nدنيا ولكنها دنيا ستنصرم … وآخر الحيوان الموت والهرم !"},{"id":"diwan-abutammam:462","bookId":"diwan-abutammam","type":"poem","seq":462,"chapter":"البحر: بسيط تام","title":"محمد بن سعيد أرعني أدنا","page":"","text":"محمد بن سعيد أرعني أدنا … فما بأذنك عن أكرومة صمم\nلم تسق بعد الهوى ماء على ظمأ … كماء فافية يسقيكها فهم\nمن كل بيت يكاد الميت يفهمه … حسنا ويحسده القرطاس والقلم\nمالي ومالك شبه حين أنشده … إلا زهير وقد أصغى له هرم\nبكل سالكة للفكر مالكة … كأنه مستهام أو به لمم\nلآل سهل أكف كلما اجتديت … فعلن في المحل مالاتفعل الديم\nقوم تراهم غيارى دون مجدهم … حتى كأن المعالي عندهم حرم\nإن الزمان انثنى عني بغمته … وصدر حسرته يغلي ويضطرم\nما زال يخضع مذ أورقت لي عدة … فكيف يصنع لو قد أثمرت نعم\nفأيقظ الفعل يقض القول نومته … وقد حكى سوء ظن أن ذا حلم !\nولا تقل قدم أزرى بحاجته … ليس العلا طللا يزري به القدم !"},{"id":"diwan-abutammam:463","bookId":"diwan-abutammam","type":"poem","seq":463,"chapter":"البحر: بسيط تام","title":"شعبي وشعب عبيد الله ملتئم","page":"","text":"شعبي وشعب عبيد الله ملتئم … وكيف يختلفان الساق والقدم\nصمصامتي اتهموني في صيانتها … هل كان عمرو على الصمصام يتهم\nسيفي الذي حده من جانبي أبدا … ناب ومن جانب القوم العدى خذم\nذقنا الصدود فلما اقتاد أرسننا … حنت حنين عجول بيننا الرحم\nسيعلم الهجر أنا من إساءته … وظلمه بالوصال العذب ننتقم\nأما الوجوه فكانت وهي عابسة … أما القلوب فكانت وهي تبتسم\nسعاية من رجال لا طباخ بهم … قالوا بما جهلوا فينا وما علموا\nسعوا فلما تلاقت وحشنا زعمت … أخلاقنا الغر فينا غير ما زعموا\nفأرزمت أنفس قد كن واحدة … لوالد واحد في أنفه شمم\nإنا خدمنا القلى جهلا بنا وعمى … فاليوم نحن جميعا للرضا خدم"},{"id":"diwan-abutammam:464","bookId":"diwan-abutammam","type":"poem","seq":464,"chapter":"البحر: طويل","title":"أبا القاسم أسلم في وفود من القسم","page":"","text":"أبا القاسم أسلم في وفود من القسم … ولا زال من حاربته دامي الكلم\nرأيتك ترعى الجود من كل وجهة … وتبني بناء المجد في خطة النجم\nوذا شيم سهلية حسنية … رئيسية صيغت من الجبر والحطم\nإذا نوبة نابت أدرت صروفها … على الضخم آراء لدى الحادث الضخم\nيداك لنا شهرا ربيع كلاهما … إذا جف أطراف البخيل من الأزم\nألذ مصافاة من الظل والضحى … وأكرم في اللأواء عودا من الكرم\nففيم تركت النصف في الود بعدما … رآه الورى خيرا من النصف في الحكم ؟\nأإياي جارى القوم في الشعر ضلة … وقد عاينوا تلك القلائد من نظمي !\nطلعت طلوع الشمس في كل تلعة … وأشرفت إشراف السماك على الخصم\nوما أنا بالغيران من دون جاره … إذ أنا لم اصبح غيورا على العلم\nلصيق فؤادي مذ ثلاثون حجة … وصيقل ذهني والمروح عن همي\nأبى ذاك صبر لا يقيل على الأذى … فواقا ونفس لا تمرغ في الظلم\nوإني إذا ما الحلم أحوج لاحيا … إلى سفه أفضلت فضلا على حلمي\nتظن ظنون السوء بي إن لقيتني … ولا وتري فيما كرهت ولا سهمي\nوتجزع من مزحي وترضى قصيدة … وقد أخرجت ألفاظها مخرج الشتم\nفإن تك أحيانا شديد شكيمة … فإنك تمحوها بما فيك من شكم\nوما خير حلم لم تشبه شراسة … وما خير لحم لا يكون على عظم\nوهل غير أخلاق كرام تكافأت … فمن خلق طلق ومن خلق جهم !\nنجوم فهذا للضياء إذا بدا … تجلى الدجى عنه وذلك للرجم\nفإن لم تطيبا لي جميعا فإنه … نهى عمر عن أكل أدمين في أدم !"},{"id":"diwan-abutammam:465","bookId":"diwan-abutammam","type":"poem","seq":465,"chapter":"البحر: كامل تام","title":"لولا القديم وحرمة مرعية","page":"","text":"لولا القديم وحرمة مرعية … لقطعت ما بيني وبين هشام\nلا حرمة الأدب القديم يحوطها … وأراه يجهل حرمة الإسلام\nفكأنما كانت مودتنا له … وإماؤنا حلما من الأحلام\nوتصرف الإخوان إن كشفتهم … ينسيك طول تصرف الأيام !"},{"id":"diwan-abutammam:466","bookId":"diwan-abutammam","type":"poem","seq":466,"chapter":"البحر: سريع","title":"رسولك الخطي يوم الوغى","page":"","text":"رسولك الخطي يوم الوغى … تردفه بالأبيض الصارم\nمن نام عن مكرمة عامدا … فلست عنها الدهر النائم\nلم ير في عترته مثله … أنصف للمظلوم من ظالم\nلكنه يمطل حقا مضى … به لي التسجيل من حاكم !"},{"id":"diwan-abutammam:467","bookId":"diwan-abutammam","type":"poem","seq":467,"chapter":"البحر: كامل تام","title":"ما ابيض وجه المرء في طلب العلى","page":"","text":"ما ابيض وجه المرء في طلب العلى … حتى يسود وجهه في البيد\nوصدقت إن الرزق يطلب أهله … لكن بحيلة متعب مكدود !"},{"id":"diwan-abutammam:468","bookId":"diwan-abutammam","type":"poem","seq":468,"chapter":"البحر: رجز تام","title":"وعاذل عذلته في عذله","page":"","text":"وعاذل عذلته في عذله … فظن أني جاهل من جهله\nما غبن المغبون مثل عقله … من لك يوما بأخيك كله ؟\nلبست ريعاني فدعني أبله … رأي ابن دهر غرقا في خبله\nأعلم منه بحداء إبله … قد لعبت أيدي النوى بشمله\nممتعا مضطلعا بحمله … منصلتا كالسيف عند سله\nمولودة همته من قبله … قد دان ذو الفضل له بفضله\nكالصاب من يذقه لا يستحله … إلا بأن يسكن تحت ظله\nمفيد جزل المال معطي جزله … يحويه من حرامه وحله\nويجعل النائل أدنى سبله … وبلد نائي المحل محله\nرميته من السرى بنبله … بيازل مقابل في بزله\nمثلي سرى في مثله بمثله … وملك في كبره ونبله\nوسوقة في قوله وفعله … بذلت مدحي فيه باغي بذله\nفحذ حبل أملي من أصله … من بعد ما استعبدني بمطله\nثم أتى معتذرا بجهله … ذا عنق في المجد لم يحله\nيعجب من تعجبي وبخله … يلحظني في جده وهزله\nلحظ الأسير حلقات كبله … حتى كأني جئته بعزله\nيا واحدا منفردا بعدله … ألبسته الغنى فلا تمله\nما أضيع الغمد بغير نصله … والشعر ما لم يك عند أهله !"},{"id":"diwan-abutammam:469","bookId":"diwan-abutammam","type":"poem","seq":469,"chapter":"البحر: طويل","title":"أفيكم فتى حي فيخبرني عني","page":"","text":"أفيكم فتى حي فيخبرني عني … بما شربت مشروبة الراح من ذهني\nبدور المظلمات إذا تنادوا … \nهي عزمة كالسيف إلا أنها … جعلت لأسباب الزمان قضوبا\nغدت وهي أولى من فؤادي بعزمتي … ورحت بما في الدن أولى من الدن\nلقد تركتني كأسها وحقيقتي … محال وحق من فعالي كالظن\nهي اختدعتني والغمام ولم أكن … بأول من أهدى التغافل للدجن\nيهد أركان الجبال هدا … \nإذا اشتعلت في الطاس والكاس نارها … صليت بها من راحتي ناعم لدن\nقرين الصبا في وجنتيه ملاحة … ذكرت بها أيام يوسف في الحسن\nإذا نحن أومأنا إليه أدارها … سلافا كماء الجفن وهي من الجفن\nتقلب روح المرء في كل وجهة … وتدخل منه حيث شاءت بلا إذن\nومسمعنا طفل الأنامل عنده … لنا كل نوع من قرى العين والأذن\nلنا وتر منه إذا ما استحثه … فصيح ولحن في أمان من اللحن\nوفي روضة نبتية صبغت لها … جداولها أنوارها صبغة الدهن\nظللنا بها في جنة غاب نحسها … تذكرنا جناتها جنة العدن\nنعمنا بها في بيت أروع ماجد … من القوم آب للدناءة والأفن\nفتى شق من عود المحامد عوده … كما اشتق له اسما من الحسن"},{"id":"diwan-abutammam:470","bookId":"diwan-abutammam","type":"poem","seq":470,"chapter":"البحر: طويل","title":"هل اجتمعت عليا معد ومذحج","page":"","text":"هل اجتمعت عليا معد ومذحج … بملتحم إلا ومنا أميرها ؟\nبل اليمن استعلت لدى كل موطن … وصار لطيء تاجها وسريرها\nمحرمة أكفال خيلي في الوغى … ومكلومة لباتها ونحورها\nحرام على أرماحنا طعن مدبر … وتندق بأسا في الصدور صدورها"},{"id":"diwan-abutammam:471","bookId":"diwan-abutammam","type":"poem","seq":471,"chapter":"البحر: بسيط تام","title":"إن كان غيرك الإسراء والنعم","page":"","text":"إن كان غيرك الإسراء والنعم … فلم يغيرني عن محتدي العدم\nإذا أناخ علي الدهر كلكله … قراه صبرا وعزما مني الكرم\nفإن علتني من أزمانه ظلم … صبرت نفسي حتى تكشف الظلم\nفكل هذا منحت الحادثات به … إني امرؤ ليس ترضى الضيم لي الهمم"},{"id":"diwan-abutammam:472","bookId":"diwan-abutammam","type":"poem","seq":472,"chapter":"البحر: وافر تام","title":"إذا ما شبت حسن الدي","page":"","text":"إذا ما شبت حسن الدي … ن منك بصالح الأدب\nفممن شئت كن فلقد … فلحت بأكرم النسب\nفنفسك قط أصلح ها … ودعني من قديم أب"},{"id":"diwan-abutammam:473","bookId":"diwan-abutammam","type":"poem","seq":473,"chapter":"البحر: طويل","title":"نحاول شيئا قد تولى فودعا","page":"","text":"نحاول شيئا قد تولى فودعا … وهيهات منه أن يعود فيرجعا\nخشنت على التأديب فهما ومنطقا … ولنت على الأيام ليتا وأخدعا\nوأقبلت الأيام ترتاد مصرعا … لجنبك فارتد إذ تيقنت مضجعا"}]};